var e=`translation`,t=`it`,n={book:`SRD 5.2.1 IT`,license:`cc-by-4.0`},r=`SRD 5.2.1`,i=JSON.parse(`{"background.acolyte":{"name":"Accolito","page":93,"equipmentNotes":{"item.book":"preghiere"}},"background.criminal":{"name":"Criminale","page":93},"background.soldier":{"name":"Soldato","page":93},"background.sage":{"name":"Sapiente","page":93,"equipmentNotes":{"item.book":"storia"}},"class.barbarian":{"name":"Barbaro","page":32,"classSpecialFeatures":{"class.barbarian.core-traits":{"name":"Tratti del barbaro","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche della tabella Tratti del barbaro.\\n- Ottiene i privilegi di 1º livello da barbaro, elencati nella tabella Privilegi del barbaro.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti della tabella Tratti del barbaro: Dado Vita, competenza nelle armi da guerra e negli scudi.\\n- Ottiene i privilegi di 1º livello da barbaro, elencati nella tabella Privilegi del barbaro.\\n"},"class.barbarian.subclass":{"name":"Sottoclasse del barbaro","description":"Livello 3: Sottoclasse del barbaro\\n\\nIl personaggio ottiene una sottoclasse del barbaro a scelta. La descrizione della sottoclasse Cammino del berserker segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da barbaro. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da barbaro attuale o a quelli inferiori.\\n"},"class.barbarian.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da barbaro.\\n"},"class.barbarian.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da barbaro.\\n"},"class.barbarian.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da barbaro.\\n"},"class.barbarian.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da barbaro.\\n"},"class.barbarian.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono dell'offensiva irresistibile."}}},"feature.barbarian.unarmored-defense":{"name":"Difesa senza armatura","description":"Se il barbaro non indossa un'armatura, la Classe Armatura base corrisponde a 10 più i modificatori di Destrezza e Costituzione. Un barbaro può usare uno scudo e ottenere comunque questo beneficio.","page":33},"feature.barbarian.weapon-mastery":{"name":"Padronanza d'armi","description":"Il barbaro è addestrato nell'uso delle armi, e per questo può avvalersi della proprietà di padronanza per due tipi di armi da mischia semplici o da guerra a sua scelta, come le asce bipenne e le asce. Ogni volta che termina un riposo lungo, può esercitarsi con le armi e cambiare una delle armi scelte.\\n\\nQuando si raggiungono determinati livelli da barbaro, si ottiene la capacità di utilizzare le proprietà di padronanza di più tipi di armi, come indicato nella colonna Padronanza d'armi della tabella Privilegi del barbaro.","page":33},"feature.barbarian.rage":{"name":"Ira","description":"Può infondere in se stesso un potere primordiale chiamato \\"ira\\", una forza che conferisce una potenza e una resistenza straordinarie. Può entrare in ira come azione bonus se non sta indossando un'armatura pesante.\\n\\nIl barbaro può entrare in ira il numero di volte indicato per il proprio livello da barbaro nella colonna Ire della tabella Privilegi del barbaro. Per quanto riguarda gli utilizzi consumati, ne recupera uno dopo aver completato un riposo breve e li recupera tutti dopo un riposo lungo.\\n\\nQuando è in atto, l'ira segue le regole indicate di seguito.\\n\\nResistenza ai danni. Un barbaro dispone di resistenza ai danni contundenti, perforanti e taglienti.\\n\\nDanni dell'ira. Quando effettua un attacco con un'arma o con un colpo senz'armi usando Forza, e infligge danni al bersaglio, il barbaro ottiene un bonus ai danni che aumenta man mano che sale di livello, come indicato nella colonna Danni dell'ira della tabella Privilegi del barbaro.\\n\\nVantaggio nella Forza. Il barbaro dispone di vantaggio alle prove di Forza e ai tiri salvezza su Forza.\\n\\nNiente concentrazione o incantesimi. Il barbaro non può mantenere la concentrazione e non può lanciare incantesimi.\\n\\n**Durata.** L'ira dura fino al termine del turno successivo del barbaro e termina anticipatamente se il barbaro indossa un'armatura pesante o è incapacitato. Se l'ira è ancora in atto nel suo turno successivo, è possibile prolungarla per un altro turno eseguendo una delle seguenti azioni:\\n\\n- Effettuando un tiro per colpire contro un nemico.\\n- Costringendo un nemico a effettuare un tiro salvezza.\\n- Effettuando un'azione bonus per prolungare l'ira.\\n\\nOgni volta che l'ira viene prolungata, dura fino alla fine del turno successivo del barbaro. Si può mantenere un'ira per un massimo di 10 minuti.","page":32},"feature.barbarian.reckless-attack":{"name":"Attacco irruento","description":"Il barbaro può ignorare ogni preoccupazione per la sua difesa e attaccare in preda a una maggiore ferocia. Quando effettua il primo tiro per colpire nel suo turno, può decidere di sferrare un attacco irruento. Così facendo, fino all'inizio del suo turno successivo, dispone di vantaggio ai tiri per colpire che usano Forza; tuttavia, anche i tiri per colpire contro il barbaro dispongono di vantaggio.","page":34},"feature.barbarian.danger-sense":{"name":"Percezione del pericolo","description":"Il barbaro ottiene una percezione prodigiosa di tutto ciò che nei paraggi non è come dovrebbe essere, cosa che lo agevola quando deve evitare i pericoli. Dispone di vantaggio nei tiri salvezza su Destrezza, a meno che non sia incapacitato.","page":33},"feature.barbarian.primal-knowledge":{"name":"Conoscenza primordiale","description":"Il barbaro acquisisce competenza in un'altra abilità a scelta dalla lista delle abilità disponibili per i barbari di 1º livello.\\n\\nInoltre, mentre l'ira è in atto, può incanalare il potere primordiale quando compie dei tentativi per la riuscita di determinate attività; ogni volta che effettua una prova di caratteristica utilizzando una delle seguenti abilità, può effettuarla come prova di Forza anche se normalmente usa una caratteristica diversa: Acrobazia, Intimidire, Percezione, Furtività o Sopravvivenza. Quando usa questa caratteristica, la Forza rappresenta il potere primordiale che scorre nel suo corpo, affinandone l'agilità, l'orientamento e i sensi.","page":33},"feature.barbarian.extra-attack":{"name":"Attacco extra","description":"Quando effettua l'azione di Attacco nel proprio turno, il barbaro può attaccare due volte anziché una.","page":33},"feature.barbarian.fast-movement":{"name":"Movimento veloce","description":"La velocità del barbaro aumenta di 3 metri, purché non indossi un'armatura pesante.","page":33},"feature.barbarian.feral-instinct":{"name":"Istinto ferino","description":"Gli istinti del barbaro sono talmente affinati da fornirgli vantaggio ai tiri per l'iniziativa.","page":33},"feature.barbarian.instinctive-pounce":{"name":"Balzo istintivo","description":"Come parte dell'azione bonus che il personaggio esegue per entrare in ira, può muoversi fino alla metà della sua velocità.","page":34},"feature.barbarian.brutal-strike":{"name":"Colpo brutale","description":"Usando Attacco irruento, nel proprio turno il personaggio può rinunciare a qualsiasi vantaggio su un tiro per colpire a scelta basato sulla Forza. Il tiro per colpire scelto non deve disporre di svantaggio. Se il tiro per colpire va a segno, il bersaglio subisce 1d10 di danni extra dello stesso tipo di danni inflitti dall'arma o dal colpo senz'armi, e il personaggio può causare uno degli effetti di Colpo brutale tra quelli elencati di seguito.\\n\\nColpo violento. Il bersaglio viene spinto a 4,5 metri di distanza dal personaggio. In seguito, il personaggio può muoversi fino alla metà della sua velocità in linea retta verso il bersaglio senza provocare attacchi di opportunità.\\n\\nColpo spaccaossa. La velocità del bersaglio viene ridotta di 4,5 metri fino all'inizio del turno successivo del barbaro. Un bersaglio può essere influenzato da un solo Colpo spaccaossa alla volta, quello più recente.","page":34},"feature.barbarian.relentless-rage":{"name":"Ira implacabile","description":"Grazie alla sua ira, il barbaro può continuare a combattere nonostante le ferite più gravi. Se scende a 0 punti ferita mentre è in preda all'ira e non è ucciso sul colpo, può effettuare un tiro salvezza su Costituzione con CD 10. Se lo supera, i punti ferita cambiano invece in un numero pari al doppio del livello da barbaro.\\n\\nOgni volta che utilizza questo privilegio dopo la prima, la CD aumenta di 5. Quando completa un riposo breve o lungo, la CD è ripristinata a 10.","page":34},"feature.barbarian.improved-brutal-strike":{"name":"Colpo brutale migliorato","description":"Il barbaro ha affinato nuovi metodi per attaccare furiosamente. I seguenti effetti si aggiungono alle opzioni di Colpo brutale.\\n\\nColpo sbalorditivo. Il bersaglio subisce svantaggio al prossimo tiro salvezza e non può effettuare attacchi di opportunità fino all'inizio del turno successivo del personaggio.\\n\\nColpo di scissione. Prima dell'inizio del turno successivo del barbaro, il prossimo tiro per colpire effettuato da un'altra creatura contro il bersaglio ottiene un bonus di +5 al tiro. Un tiro per colpire può ottenere un solo bonus Colpo di scissione.","page":34},"feature.barbarian.persistent-rage":{"name":"Ira persistente","description":"Quando effettua un tiro per l'iniziativa, il barbaro può recuperare tutti gli utilizzi di ira spesi. Dopo aver recuperato gli utilizzi di ira in questo modo, non può ripetere l'azione prima di aver completato un riposo lungo.\\n\\nInoltre, la sua ira è così feroce che ora dura 10 minuti senza che debba fare nulla per prolungarla a ogni round. L'ira termina anticipatamente se il personaggio è privo di sensi (e non semplicemente incapacitato) o indossa un'armatura pesante.","page":34},"feature.barbarian.improved-brutal-strike-enhanced":{"name":"Colpo brutale migliorato","description":"I danni extra del Colpo brutale aumentano a 2d10. Inoltre, il barbaro può utilizzare due diversi effetti del Colpo brutale quando usa questo privilegio.","page":34},"feature.barbarian.indomitable-might":{"name":"Potenza indomabile","description":"Se il totale di una prova di Forza o di un tiro salvezza su Forza del barbaro è inferiore al suo punteggio di Forza, il barbaro può usare quel punteggio al posto del totale.","page":34},"feature.barbarian.primal-champion":{"name":"Campione primordiale","description":"Il barbaro diventa un'incarnazione del potere primordiale. Il suo punteggio di Forza e Costituzione aumenta di 4, fino a un massimo di 25.","page":34},"subclass.barbarian.path-of-the-berserker":{"name":"Cammino del berserker","description":"Incanala l'ira in furia violenta\\n\\nL'ira dei barbari che percorrono il Cammino del berserker è diretta principalmente verso la violenza. È un cammino di furia indiscriminata in cui i barbari si esaltano nel caos della battaglia, lasciando che l'ira si impadronisca di loro e li renda più forti.","page":34},"feature.barbarian.path-of-the-berserker.frenzy":{"name":"Frenesia","description":"Se il personaggio usa Attacco irruento mentre è in preda all'ira, infligge danni extra al primo bersaglio che colpisce nel suo turno con un attacco basato sulla Forza. Per determinare i danni extra, il personaggio tira un numero di d6 pari al suo bonus Danni dell'ira e li somma. I danni sono dello stesso tipo dell'arma o del colpo senz'armi che il personaggio ha utilizzato per l'attacco.","page":34},"feature.barbarian.path-of-the-berserker.mindless-rage":{"name":"Ira incontenibile","description":"Il barbaro non può essere affascinato o spaventato mentre è in ira. Se è affascinato o spaventato quando entra in ira, quella condizione ha fine.","page":34},"feature.barbarian.path-of-the-berserker.retaliation":{"name":"Ritorsione","description":"Quando il barbaro subisce danni da una creatura che si trova entro 1,5 metri da sé, può usare la sua reazione per effettuare un attacco in mischia contro quella creatura, utilizzando un'arma o un colpo senz'armi.","page":34},"feature.barbarian.path-of-the-berserker.intimidating-presence":{"name":"Presenza intimidatoria","description":"Come azione bonus, il barbaro può incutere terrore con la sua presenza minacciosa e il suo potere primordiale. Quando lo fa, ogni creatura a scelta del personaggio in un'emanazione del raggio di 9 metri di cui il personaggio è il punto di origine deve effettuare un tiro salvezza su Saggezza (CD pari a 8 + il modificatore di Forza del barbaro + il bonus di competenza). Se lo fallisce, la creatura è spaventata per 1 minuto. Alla fine del turno di ogni creatura spaventata, la creatura ripete il tiro salvezza e, se lo supera, l'effetto svanisce.\\n\\nDopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo; può ignorare questo limite spendendo un utilizzo dell'ira (nessuna azione richiesta).","page":35},"class.bard":{"name":"Bardo","page":35,"classSpecialFeatures":{"class.bard.core-traits":{"name":"Tratti del bardo","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche della tabella Tratti del bardo.\\n- Ottiene i privilegi di 1º livello da bardo, elencati nella tabella Privilegi del bardo.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti della tabella Tratti del bardo: Dado Vita, competenza in un'abilità a scelta, competenza in uno strumento musicale a scelta e competenza nelle armature leggere.\\n- Ottiene i privilegi di 1º livello da bardo, elencati nella tabella Privilegi del bardo. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.bard.subclass":{"name":"Sottoclasse del bardo","description":"Livello 3: Sottoclasse del bardo\\n\\nIl personaggio ottiene una sottoclasse del bardo a scelta. La descrizione della sottoclasse Collegio della Sapienza segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da bardo. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da bardo attuale o a quelli inferiori.\\n"},"class.bard.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da bardo.\\n"},"class.bard.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da bardo.\\n"},"class.bard.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da bardo.\\n"},"class.bard.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da bardo.\\n"},"class.bard.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del richiamo degli incantesimi."}}},"feature.bard.bardic-inspiration":{"name":"Ispirazione bardica","description":"Un bardo può ispirare gli altri in maniera soprannaturale tramite le parole, la musica o la danza. Questa ispirazione è rappresentata dal dado di Ispirazione bardica, un d6.\\n\\nUtilizzare l'Ispirazione bardica. Come azione bonus, il bardo può ispirare un'altra creatura entro 18 metri da sé che può vederlo o sentirlo. Quella creatura ottiene uno dei suoi dadi di Ispirazione bardica. Una creatura può possedere un solo dado di Ispirazione bardica alla volta.\\n\\nUna volta entro l'ora successiva, quando fallisce una prova con d20, la creatura può tirare il dado di Ispirazione bardica e aggiungere il risultato al d20, trasformando potenzialmente il fallimento in un successo. Un dado di Ispirazione bardica viene speso quando viene tirato.\\n\\nNumero di utilizzi. Il bardo può conferire un dado di Ispirazione bardica un numero di volte pari al valore del suo modificatore di Carisma (minimo di una volta) e recuperare tutti gli utilizzi spesi quando completa un riposo lungo.\\n\\nAi livelli superiori. Il dado di Ispirazione bardica cambia quando si raggiungono determinati livelli da bardo, come indicato nella colonna Dado bardico della tabella Privilegi del bardo. Il dado diventa un d8 al 5º livello, un d10 al 10º livello e un d12 al 15º livello.","page":35},"feature.bard.spellcasting":{"name":"Incantesimi","description":"Il bardo impara a lanciare incantesimi attraverso le arti bardiche. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicare tali regole agli incantesimi da bardo, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Trucchetti.** Un bardo conosce due trucchetti a scelta tratti dalla lista degli incantesimi da bardo. Sono consigliati beffa crudele e luci danzanti.\\n\\nOgni volta che il personaggio ottiene un livello da bardo, può sostituire uno dei suoi trucchetti con un altro trucchetto a scelta dalla lista degli incantesimi da bardo.\\n\\nQuando il personaggio raggiunge il 4º e il 10º livello da bardo, impara un altro trucchetto a scelta dalla lista degli incantesimi da bardo, come indicato nella colonna Trucchetti della tabella Privilegi del bardo.\\n\\nSlot incantesimo. La tabella Privilegi del bardo mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\nIncantesimi preparati di 1º livello o superiore. Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, sceglie quattro incantesimi di 1º livello dalla lista degli incantesimi da bardo. Sono consigliati charme su persone, spruzzo colorato, sussurri dissonanti e parola guaritrice.\\n\\nIl numero di incantesimi nella lista aumenta man mano che si ottengono livelli da bardo, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del bardo. Ogni volta che il numero cresce, il bardo deve scegliere altri incantesimi dalla lista degli incantesimi da bardo finché il numero di incantesimi sulla sua lista non combacia con quello mostrato nella tabella. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di un bardo di 3º livello, la sua lista di incantesimi preparati può includere sei incantesimi di 1º e 2º livello in qualsiasi combinazione.\\n\\nSe un altro privilegio del bardo gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da bardo.\\n\\nCambiare gli incantesimi preparati. Quando ottiene un livello da bardo, il personaggio può sostituire un incantesimo sulla propria lista con un altro incantesimo da bardo di cui possiede degli slot.\\n\\nCaratteristica da incantatore. Carisma è la caratteristica da incantatore per gli incantesimi da bardo.\\n\\nFocus da incantatore. Un bardo può usare uno strumento musicale come focus da incantatore per i suoi incantesimi da bardo.","page":36},"feature.bard.expertise":{"name":"Maestria","description":"Il bardo ottiene Maestria (vedi \\"Glossario delle regole\\") in due abilità a scelta in cui ha competenza. Sono consigliate Intrattenere e Persuasione se il personaggio ha competenza in queste due.\\n\\nAl livello 9, il bardo ottiene Maestria in altre due abilità a scelta in cui ha competenza.","page":37},"feature.bard.jack-of-all-trades":{"name":"Factotum","description":"Il bardo può aggiungere metà del suo bonus di competenza (arrotondato per difetto) a qualsiasi prova di caratteristica effettuata che utilizzi competenza in un'abilità che non ha ancora appreso e che non utilizzi il suo bonus di competenza.\\n\\nPer esempio, se effettua una prova di Forza (Atletica) ed è privo di competenza in Atletica, può aggiungere metà del suo bonus di competenza alla prova.","page":37},"feature.bard.font-of-inspiration":{"name":"Fonte di ispirazione","resourceNames":{"bardic-inspiration":"Ispirazione bardica"},"description":"Il bardo recupera tutti i suoi utilizzi spesi di Ispirazione bardica quando completa un riposo breve o lungo.\\n\\nInoltre, può spendere uno slot incantesimo (nessuna azione richiesta) per recuperare un utilizzo speso di Ispirazione bardica.","page":37},"feature.bard.countercharm":{"name":"Controfascino","description":"Il bardo ottiene la capacità di usare note musicali o parole del potere per interferire negli effetti di influenza mentale. Se il bardo o una creatura entro 9 metri da lui fallisce un tiro salvezza contro un effetto che applica la condizione affascinato o spaventato, il bardo può usare una reazione per far sì che il tiro salvezza venga ripetuto e che il nuovo tiro disponga di vantaggio.","page":37},"feature.bard.magical-secrets":{"name":"Segreti magici","description":"Il bardo ha attinto ai segreti provenienti da una vasta gamma di tradizioni magiche. Ogni volta che il personaggio raggiunge un livello da bardo (incluso il livello attuale) e il numero di incantesimi preparati nella tabella Privilegi del bardo aumenta, il personaggio può scegliere un nuovo incantesimo preparato qualsiasi dalle liste degli incantesimi da bardo, chierico, druido e mago. Per il personaggio, gli incantesimi scelti contano come incantesimi da bardo (vedi la sezione di ciascuna classe per i rispettivi incantesimi). Inoltre, ogni volta che sostituisce un incantesimo preparato per la propria classe, può farlo con un incantesimo di queste liste.","page":37},"feature.bard.superior-inspiration":{"name":"Ispirazione superiore","description":"Quando il bardo tira per l'iniziativa, se ha meno di due utilizzi di Ispirazione bardica, li recupera finché non ne ha due.","page":38},"feature.bard.words-of-creation":{"name":"Parole della creazione","description":"Il bardo padroneggia due Parole della creazione: le parole della vita e della morte. Pertanto, gli incantesimi parola del potere guarire e parola del potere uccidere sono sempre considerati preparati. Quando lancia uno dei due incantesimi, il bardo può bersagliare una seconda creatura se questa si trova entro 3 metri dal primo bersaglio.","page":38},"subclass.bard.college-of-lore":{"name":"Collegio della Sapienza","description":"Scandaglia le profondità della conoscenza magica\\n\\nI bardi del Collegio della Sapienza accumulano incantesimi e segreti da varie fonti, come tomi accademici, riti mistici e racconti della tradizione contadina. I membri del collegio si riuniscono nelle biblioteche e nelle università per condividere la loro sapienza con gli altri. Si incontrano anche in occasione di feste popolari e ricevimenti di stato, dove possono denunciare casi di corruzione, smascherare bugie e farsi beffe dei più pomposi esponenti delle autorità.","page":40},"feature.bard.college-of-lore.bonus-proficiencies":{"name":"Competenze bonus","description":"Il bardo acquisisce competenza in tre abilità a scelta.","page":40},"feature.bard.college-of-lore.cutting-words":{"name":"Parole taglienti","description":"Il bardo impara a fare buon uso del suo ingegno per distrarre, confondere e fiaccare la determinazione e la competenza altrui in maniera soprannaturale.\\n\\nQuando una creatura che il bardo è in grado di vedere situata entro 18 metri da sé effettua un tiro per i danni, o supera una prova di caratteristica o un tiro per colpire, il bardo può usare una reazione per spendere un utilizzo di Ispirazione bardica; il bardo tira il dado di Ispirazione bardica e sottrae il numero ottenuto dal tiro della creatura, riducendo il danno o trasformando potenzialmente il successo in un fallimento.","page":40},"feature.bard.college-of-lore.magical-discoveries":{"name":"Scoperte magiche","description":"Il bardo apprende due incantesimi a scelta che possono far parte della lista degli incantesimi del chierico, del druido o del mago o di una loro combinazione (vedi la sezione di ciascuna classe per i rispettivi incantesimi). L'incantesimo scelto deve essere un trucchetto o un incantesimo per il quale il personaggio dispone di slot incantesimo, come indicato nella tabella Privilegi del bardo.\\n\\nGli incantesimi scelti sono sempre considerati preparati e ogni volta che il personaggio ottiene un livello da bardo può sostituire uno degli incantesimi con un altro che soddisfi questi requisiti.","page":40},"feature.bard.college-of-lore.peerless-skill":{"name":"Abilità impareggiabile","description":"Quando un bardo effettua una prova di caratteristica o un tiro per colpire e fallisce, può spendere un utilizzo di Ispirazione bardica; se lo fa, tira un dado di Ispirazione bardica e aggiunge il risultato ottenuto al d20, trasformando potenzialmente il fallimento in un successo. In caso di fallimento, l'Ispirazione bardica non viene consumata.","page":40},"class.cleric":{"name":"Chierico","page":41,"classSpecialFeatures":{"class.cleric.core-traits":{"name":"Tratti del chierico","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche della tabella Tratti del chierico.\\n- Ottiene i privilegi di 1º livello da chierico, elencati nella tabella Privilegi del chierico.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti della tabella Tratti del chierico: Dado Vita, competenza nelle armature leggere, medie e negli scudi.\\n- Ottiene i privilegi di 1º livello da chierico, elencati nella tabella Privilegi del chierico. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.cleric.subclass":{"name":"Sottoclasse del chierico","description":"Livello 3: Sottoclasse del chierico\\n\\nIl personaggio ottiene una sottoclasse del chierico a scelta. La descrizione della sottoclasse Dominio della Vita segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da chierico. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da chierico attuale o a quelli inferiori.\\n"},"class.cleric.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da chierico.\\n"},"class.cleric.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da chierico.\\n"},"class.cleric.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da chierico.\\n"},"class.cleric.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da chierico.\\n"},"class.cleric.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del fato."}}},"feature.cleric.divine-order":{"name":"Ordine divino","description":"Il chierico si dedica a uno dei seguenti ruoli sacri a scelta.\\n\\n**Protettore.** Addestrato a combattere, il chierico ha acquisito competenza con le armi da guerra e con le armature pesanti.\\n\\n**Taumaturgo.** Il chierico conosce un trucchetto extra dalla lista degli incantesimi da chierico. Inoltre, la connessione mistica con il divino gli conferisce un bonus alle prove di Intelligenza (Arcano o Religione). Il bonus è pari al suo modificatore di Saggezza (minimo di +1).","page":41},"feature.cleric.spellcasting":{"name":"Incantesimi","description":"Il chierico impara a lanciare incantesimi attraverso la preghiera e la meditazione. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicarle agli incantesimi del chierico, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Trucchetti.** Il chierico conosce tre trucchetti a scelta tratti dalla lista degli incantesimi da chierico. Sono consigliati guida, fiamma sacra e taumaturgia.\\n\\nOgni volta che il personaggio ottiene un livello da chierico, può sostituire uno dei suoi trucchetti con un altro trucchetto a scelta dalla lista degli incantesimi da chierico.\\n\\nQuando il personaggio raggiunge il 4º e il 10º livello da chierico, impara un altro trucchetto a scelta dalla lista degli incantesimi da chierico, come indicato nella colonna Trucchetti della tabella Privilegi del chierico.\\n\\nSlot incantesimo. La tabella Privilegi del chierico mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\nIncantesimi preparati di 1º livello o superiore. Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, sceglie quattro incantesimi di 1º livello dalla lista degli incantesimi da chierico. Sono consigliati benedizione, cura ferite, dardo tracciante e scudo della fede.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da chierico, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del chierico. Ogni volta che il numero cresce, il chierico deve scegliere altri incantesimi dalla lista degli incantesimi da chierico finché il numero di incantesimi sulla sua lista non combacia con quello mostrato nella tabella. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di un chierico di 3º livello, la sua lista di incantesimi preparati può includere sei incantesimi di 1º e 2º livello in qualsiasi combinazione.\\n\\nSe un altro privilegio del chierico gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da chierico.\\n\\nCambiare gli incantesimi preparati. Quando il chierico completa un riposo lungo, può modificare la sua lista di incantesimi preparati, sostituendo quelli che preferisce con altri incantesimi da chierico di cui possiede degli slot incantesimo.\\n\\nCaratteristica da incantatore. Saggezza è la caratteristica da incantatore usata per gli incantesimi da chierico.\\n\\nFocus da incantatore. Il chierico può usare un simbolo sacro come focus da incantatore per i suoi incantesimi da chierico.","page":41},"feature.cleric.channel-divinity":{"name":"Incanalare divinità","description":"Il chierico può incanalare l'energia divina direttamente dai Piani Esterni, usandola per alimentare gli effetti magici. Un chierico parte con due effetti: scintilla divina e scacciare non morti, ciascuno descritto di seguito. Ogni volta che il personaggio usa Incanalare divinità di questa classe, è possibile scegliere l'effetto desiderato della classe. Con livelli superiori da chierico si ottengono opzioni di effetto aggiuntive.\\n\\nIl chierico può usare Incanalare divinità due volte. Per quanto riguarda gli utilizzi consumati, ne recupera uno dopo aver completato un riposo breve e li recupera tutti dopo un riposo lungo. Quando il personaggio raggiunge determinati livelli da chierico, ottiene degli usi aggiuntivi, come mostrato nella colonna Incanalare divinità della tabella Privilegi del chierico.\\n\\nSe un effetto di Incanalare divinità richiede un tiro salvezza, la CD equivale alla CD del tiro salvezza sull'incantesimo del privilegio Incantesimi di questa classe.\\n\\nScintilla divina. Come azione di Magia, il chierico punta il simbolo sacro verso una creatura entro 9 metri e che si trova nel suo campo visivo e concentra l'energia divina su di essa. Poi, tira 1d8 e aggiunge il suo modificatore di Saggezza. Ripristina i punti ferita della creatura di un numero pari a quello del totale o costringe la creatura a effettuare un tiro salvezza su Costituzione. Se lo fallisce, la creatura subisce danni necrotici o radiosi (a scelta) pari al risultato del tiro. Se invece lo supera, subisce la metà di quei danni (arrotondati per difetto).\\n\\nIl personaggio tira un d8 aggiuntivo quando raggiunge il 7º (2d8), il 13º (3d8) e il 18º (4d8) livello da chierico.\\n\\nScacciare non morti. Come azione di Magia, il chierico brandisce il simbolo sacro e condanna le creature non morte. Ogni non morto a scelta entro 9 metri dal chierico deve effettuare un tiro salvezza su Saggezza. Se la creatura fallisce il tiro salvezza, è spaventata e incapacitata per 1 minuto. Per tutta la durata, la creatura cerca di allontanarsi il più possibile dal chierico durante i suoi turni. L'effetto termina anticipatamente se la creatura subisce danni, o se il chierico è incapacitato o morto.","page":42},"feature.cleric.sear-undead":{"name":"Bruciare i non morti","description":"Ogni volta che il chierico usa scacciare non morti, può tirare un numero di d8 pari al modificatore di Saggezza (minimo di 1d8) e sommarli. Ogni non morto che fallisce il tiro salvezza contro quell'utilizzo di scacciare non morti subisce danni radiosi pari alla somma dei tiri. I danni non interrompono l'effetto di Scacciare non morti.","page":43},"feature.cleric.blessed-strikes":{"name":"Colpi benedetti","description":"In battaglia, il chierico è permeato di potere divino e ottiene una delle seguenti opzioni a scelta (se ottiene entrambe le opzioni da una sottoclasse del chierico di un manuale più vecchio, usa solo l'opzione scelta per questo privilegio).\\n\\nColpo divino. Una volta per ogni suo turno, quando il chierico colpisce una creatura con un tiro per colpire usando un'arma, può far sì che il bersaglio subisca 1d8 danni necrotici o radiosi extra (a scelta).\\n\\nIncantesimi potenti. Il personaggio aggiunge il suo modificatore di Saggezza al danno che infligge con qualsiasi trucchetto da chierico.","page":43},"feature.cleric.divine-intervention":{"name":"Intervento divino","description":"Il chierico può invocare una divinità o un pantheon affinché intervenga a suo favore. Come azione di Magia, sceglie un incantesimo da chierico qualsiasi di 5º livello o inferiore che non richieda una reazione per essere lanciato. Come parte della stessa azione, il chierico lancia quell'incantesimo senza spendere uno slot incantesimo o senza avere bisogno di componenti materiali. Non può riutilizzare questo privilegio prima di aver completato un riposo lungo.","page":43},"feature.cleric.improved-blessed-strikes":{"name":"Colpi benedetti migliorati","description":"L'opzione scelta per i Colpi benedetti diventa più potente.\\n\\nColpo divino. I danni extra del Colpo divino aumentano a 2d8.\\n\\nIncantesimi potenti. Quando lancia un trucchetto da chierico infliggendo danni a una creatura, il chierico può infondere vitalità in se stesso o in un'altra creatura entro 18 metri da sé, concedendo un numero di punti ferita temporanei pari al doppio del suo modificatore di Saggezza.","page":43},"feature.cleric.greater-divine-intervention":{"name":"Intervento divino superiore","description":"Il chierico può invocare un intervento divino ancora più potente. Quando usa il privilegio Intervento divino, può scegliere desiderio tra gli incantesimi. Se lo fa, non può usare di nuovo Intervento divino finché non completa 2d4 riposi lunghi.","page":43},"subclass.cleric.life-domain":{"name":"Dominio della Vita","description":"Allevia le ferite del mondo\\n\\nIl Dominio della Vita si concentra sull'energia positiva che aiuta a sostenere ogni essere vivente del multiverso. I chierici che attingono a questo dominio sono maestri della guarigione e usano la forza vitale per curare molte ferite.\\n\\nL'esistenza stessa si basa sull'energia positiva associata a questo dominio, rendendolo adatto a pressoché qualsiasi tradizione religiosa. Questo dominio è associato in particolare alle divinità dell'agricoltura, agli dèi della guarigione o della resistenza e agli dèi della casa e della comunità. La magia di questo dominio viene cercata anche dagli ordini religiosi dei guaritori.","page":45},"feature.cleric.life-domain.disciple-of-life":{"name":"Discepolo della vita","description":"Quando un incantesimo lanciato dal chierico con uno slot incantesimo ripristina i punti ferita di una creatura, quella creatura recupera un ammontare di punti ferita aggiuntivi nel turno in cui l'incantesimo viene lanciato. I punti ferita aggiuntivi sono pari a 2 più il livello dello slot incantesimo.","page":45},"feature.cleric.life-domain.preserve-life":{"name":"Preservare vita","description":"Come azione di Magia, il chierico brandisce il suo simbolo sacro e spende un utilizzo di Incanalare divinità per evocare un flusso di energia curativa che può ripristinare un numero di punti ferita pari a cinque volte il suo livello da chierico. Il personaggio sceglie delle creature sanguinanti entro 9 metri da sé (incluso se stesso) e divide quei punti ferita tra loro. Questo privilegio può ripristinare un ammontare di punti ferita di una creatura che la riporti a non più della metà dei suoi punti ferita massimi.","page":45},"feature.cleric.life-domain.life-domain-spells":{"name":"Incantesimi del Dominio della Vita","description":"La connessione con questo dominio divino permette al chierico di avere sempre pronti alcuni incantesimi. Quando il chierico raggiunge un livello specificato nella tabella Incantesimi del Dominio della Vita, gli incantesimi lì elencati sono considerati come preparati.\\n\\n**Tabella: Incantesimi del Dominio della Vita**\\n\\n|Livello da chierico|Incantesimi preparati|\\n|---|---|\\n|3|Aiuto, benedizione, cura ferite e ristorare inferiore|\\n|5|Parola guaritrice di massa e rinascita|\\n|7|Aura di vita e interdizione alla morte|\\n|9|Ristorare superiore e cura ferite di massa|","page":45},"feature.cleric.life-domain.blessed-healer":{"name":"Guaritore benedetto","description":"Gli incantesimi curativi che il chierico lancia sugli altri guariscono anche il chierico stesso. Subito dopo aver lanciato un incantesimo con uno slot incantesimo che ripristina i punti ferita di una o più creature diverse da se stesso, il chierico recupera punti ferita pari a 2 più il livello dello slot incantesimo.","page":46},"feature.cleric.life-domain.supreme-healing":{"name":"Guarigione suprema","description":"Quando il chierico sta per lanciare normalmente uno o più dadi per ripristinare i punti ferita di una creatura con un incantesimo o con Incanalare divinità, anziché tirare quei dadi per la guarigione, usa il numero più alto possibile per ogni dado. Ad esempio, invece di ripristinare 2d6 punti ferita di una creatura con un incantesimo, un chierico ne ripristina 12.","page":46},"class.druid":{"name":"Druido","page":46,"classSpecialFeatures":{"class.druid.core-traits":{"name":"Tratti del druido","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche della tabella Tratti del druido.\\n- Ottiene i privilegi di 1º livello da druido, elencati nella tabella Privilegi del druido.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti della tabella Tratti del druido: Dado Vita e competenza nelle armature leggere e negli scudi.\\n- Ottiene i privilegi di 1º livello da druido, elencati nella tabella Privilegi del druido. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.druid.subclass":{"name":"Sottoclasse del druido","description":"Livello 3: Sottoclasse del druido\\n\\nIl personaggio ottiene una sottoclasse del druido a scelta. La descrizione della sottoclasse Circolo della Terra segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da druido. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da druido attuale o a quelli inferiori.\\n"},"class.druid.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da druido.\\n"},"class.druid.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da druido.\\n"},"class.druid.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da druido.\\n"},"class.druid.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da druido.\\n"},"class.druid.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del viaggio dimensionale."}}},"feature.druid.primal-order":{"name":"Ordine primordiale","description":"Il druido si dedica a uno dei seguenti ruoli sacri a scelta.\\n\\n**Mago.** Il druido conosce un trucchetto extra dalla lista degli incantesimi da druido. Inoltre, la connessione mistica con natura gli conferisce un bonus alle prove di Intelligenza (Arcano o Natura). Il bonus è pari al suo modificatore di Saggezza (bonus minimo di +1).\\n\\n**Custode.** Addestrato a combattere, il druido ha acquisito competenza con le armi da guerra e con le armature medie.","page":48},"feature.druid.druidic":{"name":"Druidico","description":"Un druido conosce il Druidico, la lingua segreta del suo ordine. Imparando questa lingua antica, ha sbloccato anche la magia della comunicazione con gli animali; l'incantesimo parlare con gli animali è sempre considerato preparato.\\n\\nIl druido può usare il Druidico per lasciare messaggi nascosti. Il druido e coloro che conoscono il Druidico sono in grado di individuare tali messaggi automaticamente. Altri possono notare la presenza di un messaggio superando una prova di Intelligenza (Indagare) con CD 15, ma non possono decifrarlo senza l'aiuto della magia.","page":48},"feature.druid.spellcasting":{"name":"Incantesimi","description":"Il druido ha imparato a lanciare incantesimi attraverso lo studio delle forze mistiche della natura. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicarle agli incantesimi del druido, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Trucchetti.** Un druido conosce due trucchetti a scelta tratti dalla lista degli incantesimi da druido. Sono consigliati artificio druidico e produrre fiamma.\\n\\nOgni volta che il personaggio ottiene un livello da druido, può sostituire uno dei suoi trucchetti con un altro trucchetto a scelta dalla lista degli incantesimi da druido.\\n\\nQuando il personaggio raggiunge il 4º e il 10º livello da druido, impara un altro trucchetto a scelta dalla lista degli incantesimi da druido, come indicato nella colonna Trucchetti della tabella Privilegi del druido.\\n\\nSlot incantesimo. La tabella Privilegi del druido mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\nIncantesimi preparati di 1º livello o superiore. Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, il personaggio sceglie quattro incantesimi di 1º livello dalla lista degli incantesimi da druido. Sono consigliati amicizia con gli animali, cura ferite, luminescenza e onda tonante.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da druido, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del druido. Ogni volta che il numero cresce, il druido deve scegliere altri incantesimi dalla lista degli incantesimi da druido finché il numero di incantesimi sulla sua lista non combacia con quello mostrato nella tabella. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di un druido di 3º livello, la sua lista di incantesimi preparati può includere sei incantesimi di 1º e 2º livello in qualsiasi combinazione.\\n\\nSe un altro privilegio del druido gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da druido.\\n\\nCambiare gli incantesimi preparati. Quando il druido completa un riposo lungo, può modificare la sua lista di incantesimi preparati, sostituendo quelli che preferisce con altri incantesimi da druido cui possiede degli slot incantesimo.\\n\\nCaratteristica da incantatore. Saggezza è la caratteristica da incantatore usata per gli incantesimi da druido.\\n\\nFocus da incantatore. Il druido può usare un focus druidico come focus da incantatore per i suoi incantesimi da druido.","page":46},"feature.druid.wild-companion":{"name":"Compagno selvatico","description":"Il druido può evocare in suo soccorso uno spirito della natura che assume una forma animale. Come azione di Magia, il druido può spendere uno slot incantesimo o un utilizzo di Forma selvatica per lanciare l'incantesimo trova famiglio senza l'ausilio di componenti materiali.\\n\\nUna volta lanciato l'incantesimo in questo modo, il famiglio evocato sarà un folletto e svanirà quando il druido avrà completato un riposo lungo.","page":49},"feature.druid.wild-shape":{"name":"Forma selvatica","description":"La forza della natura permette al druido di assumere la forma di un animale. Come azione bonus, il druido assume le sembianze di una bestia di cui ha appreso la forma per questo privilegio (vedi \\"Forme conosciute\\" di seguito). Rimane in quella forma per un numero di ore pari alla metà del livello da druido o finché non utilizza di nuovo Forma selvatica, o non è incapacitato o morto. Il druido può anche abbandonare la forma da animale anticipatamente come azione bonus.\\n\\n**Numero di utilizzi.** Il druido può utilizzare Forma selvatica due volte. Per quanto riguarda gli utilizzi consumati, ne recupera uno dopo aver completato un riposo breve e li recupera tutti dopo un riposo lungo.\\n\\nQuando il personaggio raggiunge determinati livelli da druido, ottiene degli usi aggiuntivi, come mostrato nella colonna Forma selvatica della tabella Privilegi del druido.\\n\\n**Forme conosciute.** Per questo privilegio, il druido conosce quattro forme bestiali scelte tra le schede delle statistiche delle bestie con un grado di sfida massimo pari a 1/4 e che siano prive di velocità di volo (vedi \\"Animali\\" nel capitolo \\"Mostri\\" per le schede delle statistiche). Sono consigliati il topo, il cavallo da galoppo, il ragno e il lupo. Al termine di un riposo lungo, il druido può sostituire una delle forme conosciute con un'altra.\\n\\nQuando il personaggio raggiunge determinati livelli da druido, il numero di forme conosciute e il grado di sfida massimo per queste forme aumenta, come indicato nella tabella Forme bestiali. Inoltre, a partire dall'8º livello, il druido può adottare una forma dotata di velocità di volo.\\n\\nQuando scegli le forme conosciute, puoi consultare altre fonti per trovare le bestie adeguate, sempre che il Game Master lo consenta.\\n\\n**Tabella: Forme bestiali**\\n\\n|Livello da druido|Forme conosciute|GS max|Velocità di volo|\\n|---|---|---|---|\\n|2|4|1/4|No|\\n|4|6|1/2|No|\\n|8|8|1|Sì|\\n\\n**Regole durante il mutamento della forma.** Mentre assume una determinata forma, il druido mantiene la sua personalità, i ricordi e la capacità di parlare. Si applicano le regole seguenti:\\n\\n- **Punti ferita temporanei.** Quando assume una Forma selvatica, il druido ottiene un numero di punti ferita temporanei pari al suo livello da druido.\\n\\n- **Statistiche di gioco.** Le statistiche di gioco del druido vengono sostituite dalle statistiche della bestia, ma il druido conserva il proprio tipo di creatura, i punti ferita, i Dadi Vita, i punteggi di Intelligenza, Saggezza e Carisma, i propri privilegi di classe, le proprie lingue e i propri talenti. Conserva inoltre tutte le sue abilità e competenze nei tiri salvezza, per le quali utilizza il suo bonus di competenza, oltre a ottenere quelle della creatura. Se la creatura possiede un'abilità o un modificatore del tiro salvezza superiori a quelli del druido, il personaggio usa la scheda delle statistiche della creatura anziché la propria.\\n\\n- **Non si possono lanciare incantesimi.** Il druido non può lanciare incantesimi, ma il mutamento della forma non interrompe la sua concentrazione e non interferisce con un incantesimo già lanciato.\\n\\n- **Oggetti.** La capacità di maneggiare gli oggetti è determinata dagli arti della forma bestiale e non dai propri. In più, un druido può scegliere se lasciare cadere l'equipaggiamento nel suo spazio, se tale equipaggiamento si fonde nella sua nuova forma o se indossarlo. L'equipaggiamento indossato funziona normalmente, ma spetta al GM decidere se è pratico o meno che la nuova forma indossi ogni determinato oggetto d'equipaggiamento, in base alla taglia e alla forma della creatura. L'equipaggiamento del druido non cambia per adattarsi alla nuova forma, e ogni oggetto di equipaggiamento che la nuova forma non può indossare deve cadere a terra o fondersi nella nuova forma del druido. L'equipaggiamento fuso alla nuova forma non ha alcun effetto finché il druido non abbandona quella forma.","page":48},"feature.druid.wild-resurgence":{"name":"Rinascita selvatica","description":"Una volta per ogni suo turno, se il druido ha consumato tutti i suoi utilizzi di Forma selvatica, può ripristinare un utilizzo spendendo uno slot incantesimo (nessuna azione richiesta).\\n\\nInoltre, può spendere un utilizzo di Forma selvatica (nessuna azione richiesta) per ottenere uno slot incantesimo di 1º livello, ma non potrà farlo di nuovo finché non completa un riposo lungo.","page":49},"feature.druid.elemental-fury":{"name":"Furia elementale","description":"La forza degli elementi scorre attraverso il druido, facendogli ottenere una delle seguenti opzioni a scelta.\\n\\nIncantesimi potenti. Il personaggio aggiunge il suo modificatore di Saggezza al danno che infligge con qualsiasi trucchetto da druido.\\n\\nColpo primordiale. Una volta per ogni suo turno, quando il druido colpisce una creatura con un tiro per colpire usando un'arma o un attacco della forma bestiale in Forma selvatica, può far sì che il bersaglio subisca 1d8 danni da freddo, fuoco, fulmine o tuono extra (a scelta).","page":49},"feature.druid.improved-elemental-fury":{"name":"Furia elementale migliorata","description":"L'opzione scelta per la Furia elementale diventa più potente, come descritto di seguito.\\n\\nIncantesimi potenti. Quando il personaggio lancia un trucchetto da druido con un raggio pari o superiore a 3 metri, la gittata dell'incantesimo aumenta di 90 metri.\\n\\nColpo primordiale. I danni extra del Colpo primordiale aumentano a 2d8.","page":49},"feature.druid.beast-spells":{"name":"Incantesimi bestiali","description":"Mentre utilizza Forma selvatica, il druido può lanciare incantesimi in forma bestiale, fatta eccezione per gli incantesimi che abbiano bisogno di componenti materiali con un costo specificato o che consumino la propria componente materiale.","page":49},"feature.druid.archdruid":{"name":"Arcidruido","resourceNames":{"nature-magician":"Mago della natura"},"description":"La vitalità della natura fiorisce costantemente all'interno del druido, concedendogli i seguenti benefici.\\n\\nForma selvatica sempreverde. Ogni volta che il druido tira per l'iniziativa e non ha utilizzi disponibili di Forma Selvatica, ne recupera uno.\\n\\nMago della natura. Il druido può convertire gli utilizzi di Forma selvatica in slot incantesimo (nessuna azione richiesta). Sceglie un numero di utilizzi di Forma selvatica non spesi e li converte in un singolo slot incantesimo; ogni utilizzo contribuisce a 2 livelli di incantesimo. Per esempio, se converte due utilizzi di Forma selvatica, ottiene uno slot incantesimo di 4º livello. Dopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.\\n\\nCorpo senza tempo. La magia primordiale che fluisce nel druido rallenta il suo invecchiamento. Per ogni 10 anni trascorsi, il corpo del druido invecchia soltanto di 1 anno.","page":49},"subclass.druid.circle-of-the-land":{"name":"Circolo della Terra","description":"Celebra la connessione con il mondo naturale\\n\\nIl Circolo della Terra è composto da mistici e sapienti che preservano i riti e le conoscenze dei tempi antichi. Questi druidi si incontrano all'interno di circoli sacri di alberi o monoliti, per rivelarsi in Druidico i segreti primordiali che hanno appreso. I più saggi membri del circolo presiedono come sommi sacerdoti delle comunità.","page":51},"feature.druid.circle-of-the-land.lands-aid":{"name":"Ausilio dalla terra","description":"Come azione di Magia, può spendere un utilizzo di Forma selvatica e scegliere un punto entro 18 metri da sé. Per un istante, in una sfera del raggio di 3 metri centrata su quel punto appaiono fiori che donano vitalità e spine che risucchiano la vita. Ogni creatura nella sfera a scelta del druido deve effettuare un tiro salvezza su Costituzione contro la CD del tiro salvezza sul suo incantesimo. La creatura subisce 2d6 danni necrotici in caso di fallimento, o la metà in caso di successo. Una creatura a scelta del druido in quell'area recupera 2d6 punti ferita.\\n\\nI danni e la guarigione del personaggio aumentano di 1d6 quando raggiunge il 10º (3d6) e il 14º (4d6) livello da druido.","page":52},"feature.druid.circle-of-the-land.spell-list":{"name":"Incantesimi del Circolo della Terra","description":"Al termine di un riposo lungo, il druido sceglie un tipo di terra: arida, polare, temperata o tropicale. Consulta la tabella qui di seguito corrispondente al tipo di terra scelto; gli incantesimi elencati per il livello da druido attuale e per i livelli inferiori si considerano preparati.\\n\\n**Tabella: Terra arida**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Dardo di fuoco, mani brucianti, sfocatura|\\n|5|Palla di fuoco|\\n|7|Inaridire|\\n|9|Muro di pietra|\\n\\n**Tabella: Terra polare**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Blocca persone, nube di nebbia, raggio di gelo|\\n|5|Tempesta di nevischio|\\n|7|Tempesta di ghiaccio|\\n|9|Cono di freddo|\\n\\n**Tabella: Terra temperata**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Passo velato, sonno e stretta folgorante|\\n|5|Fulmine|\\n|7|Libertà di movimento|\\n|9|Traslazione arborea|\\n\\n**Tabella: Terra tropicale**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Fiotto acido, raggio di infermità, ragnatela|\\n|5|Nube maleodorante|\\n|7|Metamorfosi|\\n|9|Piaga degli insetti|","page":51},"feature.druid.circle-of-the-land.natural-recovery":{"name":"Recupero naturale","resourceNames":{"natural-recovery":"Recupero naturale (incantesimo del Circolo)","natural-recovery-slots":"Recupero naturale (slot incantesimo)"},"description":"Il druido può lanciare uno degli incantesimi di 1º livello o superiore che ha preparato con il privilegio Incantesimi del Circolo senza spendere uno slot incantesimo; deve completare un riposo lungo prima di poterlo fare di nuovo.\\n\\nInoltre, quando completa un riposo breve, sceglie quali slot incantesimo spesi desidera recuperare. Questi slot incantesimo possono avere un livello totale pari o inferiore alla metà del livello da druido (arrotondato per eccesso) e nessuno slot può essere di livello superiore al 6º. Per esempio, se il personaggio è un druido di 6º livello, può recuperare slot incantesimo per un valore totale di tre livelli. Il druido può recuperare uno slot incantesimo di 3º livello, uno slot incantesimo di 2º livello e uno di 1º livello, o tre slot incantesimo di 1º livello. Dopo aver recuperato gli slot incantesimo con questo privilegio, il druido non può farlo di nuovo prima di aver completato un riposo lungo.","page":52},"feature.druid.circle-of-the-land.natures-ward":{"name":"Interdizione della Natura","description":"Il druido è immune alla condizione avvelenato ed è dotato di resistenza a un tipo di danno associato alla terra che ha scelto per il privilegio Incantesimi del Circolo, come indicato nella tabella Interdizione della Natura.\\n\\n**Interdizione della Natura**\\n\\n|Tipo di terra|Resistenza|Tipo di terra|Resistenza|\\n|---|---|---|---|\\n|Arida|Fuoco|Temperata|Fulmine|\\n|Polare|Freddo|Tropicale|Veleno|","page":52},"feature.druid.circle-of-the-land.natures-sanctuary":{"name":"Rifugio della Natura","description":"Come azione di Magia, il druido può spendere un utilizzo della sua Forma selvatica per far apparire alberi e viticci spettrali in un cubo con spigolo di 4,5 metri in un punto del terreno entro 36 metri da sé. La vegetazione permane per 1 minuto, o finché il druido non è incapacitato o morto. Mentre si trovano in quell'area, il druido e i suoi alleati ottengono mezza copertura, e gli alleati ottengono la resistenza conferita da Interdizione della Natura.\\n\\nCome azione bonus, il druido può muovere il cubo fino a 18 metri sul terreno entro 36 metri da sé.","page":52},"class.fighter":{"name":"Guerriero","page":53,"classSpecialFeatures":{"class.fighter.core-traits":{"name":"Tratti del guerriero","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche della tabella Tratti del guerriero.\\n- Ottiene i privilegi di 1º livello da guerriero, elencati nella tabella Privilegi del guerriero.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti della tabella Tratti del guerriero: Dado Vita, competenza nelle armi da guerra, nelle armature leggere, medie e negli scudi.\\n- Ottiene i privilegi di 1º livello da guerriero, elencati nella tabella Privilegi del guerriero.\\n"},"class.fighter.subclass":{"name":"Sottoclasse del guerriero","description":"Livello 3: Sottoclasse del guerriero\\n\\nIl personaggio ottiene una sottoclasse del guerriero a scelta. La descrizione della sottoclasse Campione segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da guerriero. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da guerriero attuale o a quelli inferiori.\\n"},"class.fighter.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente al 6º, all'8º, al 12º, al 14º e al 16º livello da guerriero.\\n"},"class.fighter.ability-score-improvement-6":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente al 6º, all'8º, al 12º, al 14º e al 16º livello da guerriero.\\n"},"class.fighter.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente al 6º, all'8º, al 12º, al 14º e al 16º livello da guerriero.\\n"},"class.fighter.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente al 6º, all'8º, al 12º, al 14º e al 16º livello da guerriero.\\n"},"class.fighter.ability-score-improvement-14":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente al 6º, all'8º, al 12º, al 14º e al 16º livello da guerriero.\\n"},"class.fighter.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente al 6º, all'8º, al 12º, al 14º e al 16º livello da guerriero.\\n"},"class.fighter.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono delle abilità di combattimento."}}},"feature.fighter.second-wind":{"name":"Recuperare energie","description":"Un guerriero possiede una riserva limitata di resistenza fisica e mentale a cui può attingere. Come azione bonus, può usarla per recuperare punti ferita pari a 1d10 più il suo livello da guerriero.\\n\\nPuò utilizzare questo privilegio due volte. Per quanto riguarda gli utilizzi consumati, ne recupera uno dopo aver completato un riposo breve e li recupera tutti dopo un riposo lungo.\\n\\nQuando il personaggio raggiunge determinati livelli da guerriero, ottiene più utilizzi di questo privilegio, come indicato nella colonna Recuperare energie della tabella Privilegi del guerriero.","page":54},"feature.fighter.fighting-style":{"name":"Stile di combattimento","description":"Il guerriero ha affinato le sue doti marziali e ottiene un talento Stile di combattimento a scelta (vedi capitolo \\"Talenti\\"). È consigliata la Difesa.\\n\\nOgni volta che il personaggio ottiene un livello da guerriero, può sostituire il talento scelto con un altro talento Stile di combattimento.","page":53},"feature.fighter.weapon-mastery":{"name":"Padronanza d'armi","description":"Il guerriero è addestrato nell'uso delle armi, e per questo può avvalersi della proprietà di padronanza per tre tipi di armi semplici o da guerra a sua scelta. Ogni volta che termina un riposo lungo, può esercitarsi con le armi e cambiare una delle armi scelte.\\n\\nQuando si raggiungono determinati livelli da guerriero, si ottiene la capacità di utilizzare le proprietà di padronanza di più tipi di armi, come indicato nella colonna Padronanza d'armi della tabella Privilegi del guerriero.","page":54},"feature.fighter.action-surge":{"name":"Azione impetuosa","description":"Il guerriero può spingersi oltre i suoi normali limiti per un istante. Nel suo turno, può effettuare un'azione aggiuntiva, fatta eccezione per l'azione di Magia.\\n\\nDopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo breve o lungo. A partire dal 17º livello, il guerriero può utilizzare questo privilegio due volte prima di un riposo, ma soltanto una volta nello stesso turno.","page":54},"feature.fighter.tactical-mind":{"name":"Mente tattica","description":"Il guerriero possiede una mente tattica sia sul campo di battaglia che fuori. Quando fallisce una prova di caratteristica, può spendere un utilizzo di Recuperare energie per spingersi verso il successo. Invece di recuperare punti ferita, il guerriero tira 1d10 e aggiunge il risultato alla prova di caratteristica, trasformandola potenzialmente in un successo. Se la prova fallisce di nuovo, questo utilizzo di Recuperare energie non viene speso.","page":54},"feature.fighter.extra-attack":{"name":"Attacco extra","description":"Quando effettua l'azione di Attacco nel proprio turno, il guerriero può attaccare due volte anziché una.","page":54},"feature.fighter.tactical-shift":{"name":"Spostamento tattico","description":"Ogni volta che il guerriero attiva Recuperare energie con un'azione bonus, può muoversi fino a metà della sua velocità senza provocare attacchi di opportunità.","page":54},"feature.fighter.indomitable":{"name":"Indomabile","description":"Se il personaggio fallisce un tiro salvezza, può ripetere il tiro con un bonus pari al suo livello da guerriero. Deve usare il nuovo risultato e non può riutilizzare questo privilegio prima di aver completato un riposo lungo.\\n\\nPrima di un riposo lungo, il personaggio può utilizzare questo privilegio due volte a partire dal 13º livello e tre volte a partire dal 17º livello.","page":54},"feature.fighter.tactical-master":{"name":"Signore delle tattiche","description":"Quando il guerriero attacca con un'arma di cui può utilizzare la proprietà di padronanza, per quell'attacco può sostituirla con le proprietà spinta, fiaccare o lentezza.","page":54},"feature.fighter.two-extra-attacks":{"name":"Due attacchi extra","description":"Quando effettua l'azione di attacco nel proprio turno, il guerriero può attaccare tre volte anziché una.","page":54},"feature.fighter.studied-attacks":{"name":"Attacchi studiati","description":"Il guerriero studia gli avversari e apprende da ogni attacco che effettua. Se effettua un tiro per colpire contro una creatura e manca il bersaglio, dispone di vantaggio sul tiro per colpire successivo che effettua contro quella creatura prima della fine del suo turno successivo.","page":54},"feature.fighter.three-extra-attacks":{"name":"Tre attacchi extra","description":"Quando effettua l'azione di attacco nel proprio turno, il guerriero può attaccare quattro volte anziché una.","page":54},"subclass.fighter.champion":{"name":"Campione","description":"Raggiungi l'eccellenza fisica nel combattimento\\n\\nIl campione si concentra sullo sviluppo delle abilità marziali in un'incessante ricerca della vittoria. Unisce un rigoroso addestramento a una condizione fisica eccellente per infliggere colpi devastanti, resistere ai pericoli e ottenere la gloria. Che si tratti di gare atletiche o di battaglie sanguinose, i campioni lottano per la corona del vincitore.","page":55},"feature.fighter.champion.improved-critical":{"name":"Critico migliorato","description":"I tiri per colpire con armi e con colpi senz'armi possono mettere a segno un colpo critico con un risultato di 19 o 20 al tiro del d20.","page":55},"feature.fighter.champion.remarkable-athlete":{"name":"Atleta straordinario","description":"Grazie alle sue doti atletiche, il guerriero dispone di vantaggio ai tiri per l'iniziativa e alle prove di Forza (Atletica).\\n\\nInoltre, subito dopo aver messo a segno un colpo critico, può muoversi fino a metà della propria velocità senza provocare attacchi di opportunità.","page":55},"feature.fighter.champion.additional-fighting-style":{"name":"Stile di combattimento aggiuntivo","description":"Il guerriero può scegliere un altro talento Stile di combattimento.","page":55},"feature.fighter.champion.heroic-warrior":{"name":"Guerriero eroico","description":"Il brivido della battaglia conduce il guerriero verso la vittoria. Durante il combattimento, può concedere a se stesso Ispirazione eroica ogni volta che inizia il turno senza di essa.","page":55},"feature.fighter.champion.superior-critical":{"name":"Critico superiore","description":"I tiri per colpire con armi e con colpi senz'armi possono mettere a segno un colpo critico con un risultato di 18–20 al tiro del d20.","page":55},"feature.fighter.champion.survivor":{"name":"Sopravvissuto","description":"Il guerriero giunge all'apice della sua resilienza in battaglia, ottenendo i seguenti benefici.\\n\\n**Sfuggire alla morte.** Dispone di vantaggio ai tiri salvezza contro morte. Inoltre, quando ottiene 18–20 a un tiro salvezza contro morte, possiede il beneficio di ottenere un 20.\\n\\n**Incoraggiamento eroico.** All'inizio di ogni suo turno, il guerriero recupera punti ferita pari a 5 più il suo modificatore di Costituzione se è sanguinante e possiede almeno 1 punto ferita.","page":55},"class.rogue":{"name":"Ladro","page":55,"classSpecialFeatures":{"class.rogue.core-traits":{"name":"Tratti del ladro","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutti i tratti nella tabella Tratti del ladro.\\n- Ottiene i privilegi di 1º livello da ladro, elencati nella tabella Privilegi del ladro.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti dalla tabella Tratti del ladro: Dado Vita, competenza in un'abilità a scelta dalla lista delle abilità del ladro, competenza negli arnesi da scasso e nelle armature leggere.\\n- Ottiene i privilegi di 1º livello da ladro, elencati nella tabella Privilegi del ladro.\\n"},"class.rogue.subclass":{"name":"Sottoclasse del ladro","description":"Livello 3: Sottoclasse del ladro\\n\\nIl personaggio ottiene una sottoclasse del ladro a scelta. La descrizione della sottoclasse Furfante segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da ladro. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da ladro attuale o a quelli inferiori.\\n"},"class.rogue.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 10º, al 12º e al 16º livello da ladro.\\n"},"class.rogue.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 10º, al 12º e al 16º livello da ladro.\\n"},"class.rogue.ability-score-improvement-10":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 10º, al 12º e al 16º livello da ladro.\\n"},"class.rogue.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 10º, al 12º e al 16º livello da ladro.\\n"},"class.rogue.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 10º, al 12º e al 16º livello da ladro.\\n"},"class.rogue.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono dello spirito notturno."}}},"feature.rogue.sneak-attack":{"name":"Attacco furtivo","description":"Il ladro sa come colpire con precisione sfruttando la distrazione di un avversario. Una volta per turno, può infliggere 1d6 danni extra a una creatura che colpisce con un tiro per colpire, se dispone di vantaggio al tiro e l'attacco è eseguito con un'arma accurata o a distanza. Il danno aggiuntivo è dello stesso tipo di quello dell'arma.\\n\\nNon è necessario avere vantaggio al tiro per colpire se almeno uno degli alleati si trova entro 1,5 metri dal bersaglio, l'alleato non è incapacitato e il ladro non dispone di svantaggio al tiro per colpire.\\n\\nIl danno extra aumenta man mano che il ladro sale di livello, come mostrato nella colonna Attacco furtivo della tabella Privilegi del ladro.","page":56},"feature.rogue.expertise":{"name":"Maestria","description":"Il ladro ottiene maestria in due abilità a scelta in cui ha competenza. Se il personaggio ha competenza in Rapidità di mano e Furtività, è consigliabile scegliere queste due.\\n\\nAl livello 6, il ladro ottiene maestria in altre due competenze nelle abilità a sua scelta.","page":55},"feature.rogue.weapon-mastery":{"name":"Padronanza d'armi","description":"Il ladro è addestrato nell'uso delle armi, e per questo può avvalersi della proprietà di padronanza per due tipi di armi a sua scelta in cui ha competenza, come i pugnali e gli archi corti.\\n\\nOgni volta che completa un riposo lungo, può cambiare il tipo di arma utilizzato. Per esempio, è possibile passare alle proprietà di padronanza per scimitarre e spade corte.","page":56},"feature.rogue.thieves-cant":{"name":"Gergo ladresco","description":"Il ladro ha appreso varie lingue nelle comunità in cui ha affinato le proprie competenze illecite. Per questo, conosce il Gergo ladresco e un'altra lingua a scelta, selezionabili dalle tabelle delle lingue al capitolo \\"Creazione del personaggio\\".","page":56},"feature.rogue.cunning-action":{"name":"Azione scaltra","description":"La prontezza di spirito e l'agilità ti consentono di muoverti e di agire in fretta. Per questo, durante il suo turno può eseguire una delle seguenti azioni come azione bonus: Scatto, Disimpegno o Nascondersi.","page":56},"feature.rogue.steady-aim":{"name":"Mira ferma","description":"Come azione bonus, il ladro ottiene un vantaggio al prossimo tiro per colpire durante il turno in corso. Può utilizzare questo privilegio solo se non si è mosso durante questo turno e, dopo averlo usato, la sua velocità è ridotta a 0 fino al termine del turno.","page":56},"feature.rogue.cunning-strike":{"name":"Colpo astuto","description":"Il ladro ha ideato modi più astuti di utilizzare il proprio Attacco furtivo. Quando infligge danni da Attacco furtivo, è possibile aggiungere uno dei seguenti effetti del Colpo astuto. Ogni effetto prevede un costo in dadi di danno dell'Attacco furtivo. Il dado da spendere viene rimosso prima del tiro e l'effetto entra in vigore subito dopo aver inflitto i danni dell'attacco. Per esempio, se si aggiunge il veleno, è necessario rimuovere 1d6 dai danni dell'Attacco furtivo prima di tirare.\\n\\nSe uno degli effetti di Colpo astuto richiede un tiro salvezza, la CD equivale a 8 più il modificatore di Destrezza e il bonus di competenza.\\n\\n**Inciampo (costo: 1d6).** Se il bersaglio è una creatura di taglia Grande o di dimensioni inferiori, deve superare un tiro salvezza su Destrezza, altrimenti cade a terra prona.\\n\\n**Ritirata (costo: 1d6).** Subito dopo l'attacco, il ladro può muoversi fino a metà della sua velocità senza provocare attacchi di opportunità.\\n\\n**Veleno (costo: 1d6).** Il ladro aggiunge una tossina al proprio attacco, costringendo il bersaglio a effettuare un tiro salvezza su Costituzione. Se lo fallisce, è avvelenato per 1 minuto. Alla fine di ogni suo turno, il bersaglio avvelenato ripete il tiro salvezza e, se lo supera, l'effetto svanisce.\\n\\nPer utilizzare questo effetto, è necessario avere con sé le sostanze da avvelenatore.","page":57},"feature.rogue.uncanny-dodge":{"name":"Schivata prodigiosa","description":"Quando viene colpito con un tiro per colpire da un attaccante nel suo campo visivo, il ladro può usare la sua reazione per dimezzare i danni subiti (arrotondati per difetto).","page":57},"feature.rogue.reliable-talent":{"name":"Dote affidabile","description":"Ogni volta che il ladro effettua una prova di caratteristica in un'abilità o uno strumento in cui ha competenza, può considerare un tiro di d20 dal 9 in giù come 10.","page":57},"feature.rogue.evasion":{"name":"Elusione","description":"Ora il ladro può schivare agilmente determinati pericoli. Quando è soggetto a un effetto che gli consente di effettuare un tiro salvezza su Destrezza per dimezzare i danni, non subisce alcun danno se lo supera, e soltanto la metà dei danni se lo fallisce. Il personaggio non può utilizzare questo privilegio se è incapacitato.","page":57},"feature.rogue.improved-cunning-strike":{"name":"Colpo astuto migliorato","description":"Il ladro può utilizzare fino a due effetti di Colpo astuto quando infligge danni da Attacco furtivo, pagando il relativo costo in dadi per ciascuno di essi.","page":57},"feature.rogue.devious-strikes":{"name":"Colpi infidi","description":"Il ladro ha scoperto nuovi modi più infidi di utilizzare il proprio Attacco furtivo. I seguenti effetti si aggiungono alle opzioni di Colpo astuto.\\n\\n**Atterramento (costo: 6d6).** Il bersaglio deve superare un tiro salvezza su Costituzione, altrimenti diventa privo di sensi per 1 minuto o finché non subisce dei danni. Dopodiché, ripete il tiro salvezza alla fine di ogni suo turno e, se lo supera, l'effetto svanisce.\\n\\n**Confusione (costo: 2d6).** Il bersaglio deve superare un tiro salvezza su Costituzione, altrimenti nel suo turno successivo potrà fare solo una delle seguenti azioni: muoversi o effettuare un'azione o un'azione bonus.\\n\\n**Rabbuio (costo: 3d6).** Il bersaglio deve superare un tiro salvezza su Destrezza, altrimenti è accecato fino al termine del proprio turno successivo.","page":57},"feature.rogue.slippery-mind":{"name":"Mente sfuggente","description":"La mente arguta del ladro è particolarmente difficile da controllare, per questo ottiene competenza nei tiri salvezza su Saggezza e Carisma.","page":57},"feature.rogue.elusive":{"name":"Inafferrabile","description":"Il ladro è talmente sfuggente che gli attaccanti riescono raramente ad avere il sopravvento su di lui. Nessun tiro per colpire può avere vantaggio contro il ladro, a meno che non sia incapacitato.","page":57},"feature.rogue.stroke-of-luck":{"name":"Colpo di fortuna","description":"Il ladro ha un'incredibile propensione per avere successo quando ne ha bisogno. Se fallisce una prova con d20, può trasformare il risultato in un 20.\\n\\nDopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo breve o lungo.","page":57},"subclass.rogue.thief":{"name":"Furfante","description":"Vai a caccia di tesori nei panni di un autentico avventuriero\\n\\nGrazie alle capacità da scassinatore, cacciatore di tesori ed esploratore, il personaggio ormai rappresenta l'avventuriero per antonomasia. Oltre a vantare agilità e furtività migliorate, ottiene abilità utili per addentrarsi in rovine inesplorate e acquisire il massimo beneficio dagli oggetti magici al loro interno.","page":57},"feature.rogue.thief.second-story-work":{"name":"Lavoro al secondo piano","description":"Grazie a un duro addestramento, riesci ad arrivare in luoghi particolarmente difficili da raggiungere, ottenendo i seguenti benefici.\\n\\n**Scalatore.** Il personaggio ottiene una velocità di scalata pari alla propria velocità.\\n\\n**Saltatore.** Il ladro può determinare la distanza dei suoi salti usando il modificatore di Destrezza anziché quello di Forza.","page":58},"feature.rogue.thief.fast-hands":{"name":"Mani veloci","description":"Come azione bonus, puoi scegliere una delle opzioni elencate di seguito.\\n\\n**Rapidità di mano.** Il ladro effettua una prova di Destrezza (Rapidità di mano) per scassinare una serratura, disattivare una trappola con gli arnesi da scasso o borseggiare qualcuno.\\n\\n**Usare un oggetto.** Puoi effettuare l'azione di Utilizzo o di Magia per utilizzare un oggetto magico che richiede una di quelle azioni.","page":58},"feature.rogue.thief.supreme-sneak":{"name":"Furtività suprema","description":"Il ladro ottiene la seguente opzione per il Colpo astuto.\\n\\n**Attacco nascosto (costo: 1d6).** Se il ladro è invisibile per via dell'azione Nascondersi, l'attacco non interrompe tale condizione se termina il turno dietro a tre quarti di copertura o a una copertura totale.","page":58},"feature.rogue.thief.use-magic-device":{"name":"Usare oggetto magico","description":"Il ladro ha imparato a trarre il massimo dall'utilizzo degli oggetti magici, ottenendo i seguenti benefici.\\n\\n**Cariche.** Quando il ladro usa la proprietà di un oggetto magico che ne consuma delle cariche, tira 1d6. Se il risultato è 6, la proprietà viene utilizzata senza consumare cariche.\\n\\n**Pergamene.** Il ladro può utilizzare qualunque pergamena magica sfruttando Intelligenza come caratteristica da incantatore. Se l'incantesimo è un trucchetto o un incantesimo di 1º livello, può lanciarlo senza effettuare alcuna prova. Invece, se la pergamena contiene un incantesimo di livello superiore, deve prima superare una prova di Intelligenza (Arcano) (CD 10 più il livello dell'incantesimo). Se la prova viene superata, lancerà l'incantesimo. In caso di fallimento, la pergamena si disintegra.\\n\\n**Sintonia.** Il ladro può entrare in sintonia con un massimo di quattro oggetti magici contemporaneamente.","page":58},"feature.rogue.thief.thiefs-reflexes":{"name":"Riflessi da furfante","description":"Il ladro è diventato abile nel tendere imboscate e sfuggire rapidamente alle situazioni di pericolo. Per questo, può effettuare due turni durante il primo round di ogni combattimento. Effettua il suo primo turno alla sua normale iniziativa e il secondo turno alla sua iniziativa meno 10.","page":58},"class.wizard":{"name":"Mago","page":59,"classSpecialFeatures":{"class.wizard.core-traits":{"name":"Tratti del mago","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche nella tabella Tratti del mago.\\n- Ottiene i privilegi di 1º livello da mago, elencati nella tabella Privilegi del mago.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene il Dado Vita dalla tabella Tratti del mago.\\n- Ottiene i privilegi di 1º livello da mago, elencati nella tabella Privilegi del mago. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.wizard.subclass":{"name":"Sottoclasse del mago","description":"Livello 3: Sottoclasse del mago\\n\\nIl personaggio ottiene una sottoclasse del mago a scelta. La descrizione della sottoclasse Invocatore segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da mago. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da mago attuale o a quelli inferiori.\\n"},"class.wizard.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da mago.\\n"},"class.wizard.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da mago.\\n"},"class.wizard.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da mago.\\n"},"class.wizard.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da mago.\\n"},"class.wizard.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del richiamo degli incantesimi."}}},"feature.wizard.arcane-recovery":{"name":"Recupero arcano","description":"Il mago può recuperare parte della sua energia magica studiando il libro degli incantesimi. Quando completa un riposo breve, sceglie quali slot incantesimo spesi desidera recuperare. Gli slot incantesimo possono avere un livello totale pari o inferiore alla metà del livello da mago (arrotondato per eccesso) e nessuno slot può essere di livello pari o superiore al 6º. Per esempio, se il mago è di 4º livello, può recuperare un massimo di due livelli di slot incantesimo, ripristinando o uno slot incantesimo di 2º livello o due di 1º livello.\\n\\nDopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.","page":60},"feature.wizard.ritual-adept":{"name":"Adepto dei rituali","description":"Il mago può lanciare qualsiasi incantesimo come rituale se quell'incantesimo possiede il descrittore rituale ed è presente nel suo libro degli incantesimi. Non è necessario che sia preparato, ma per poterlo lanciare in questo modo è necessario leggere il libro.","page":60},"feature.wizard.spellcasting":{"name":"Incantesimi","description":"In quanto studioso della magia arcana, il mago ha imparato a lanciare incantesimi. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicare tali regole agli incantesimi del mago, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Trucchetti.** Il mago conosce tre trucchetti a scelta. Sono consigliati luce, mano magica e raggio di gelo. Ogni volta che il personaggio completa un riposo lungo, puoi sostituire uno dei suoi trucchetti di questo privilegio con un altro trucchetto a scelta.\\n\\nDopo aver raggiunto il 4º e il 10º livello da mago, il personaggio apprende un altro trucchetto a scelta, come mostrato nella colonna Trucchetti della tabella Privilegi del mago.\\n\\n**Libro degli incantesimi.** Lo studio delle arti arcane da parte del mago ha raggiunto il suo apice con la creazione di un particolare tomo: il suo libro degli incantesimi. Si tratta di un oggetto minuscolo che pesa 1,5 chilogrammi, conta 100 pagine e può essere letto solo dal personaggio o da qualcuno che lanci identificare. L'aspetto e i materiali che compongono il libro sono a tua discrezione: potrebbe essere un tomo dal dorso dorato o una raccolta di pergamene tenute insieme con della corda.\\n\\nIl libro contiene gli incantesimi di 1º livello o superiore noti al personaggio. Inizia con sei incantesimi da mago di 1º livello a scelta. Sono consigliati individuazione del magico, caduta morbida, armatura magica, dardo incantato, sonno e onda tonante.\\n\\nOgni volta che il personaggio acquisisce un livello da mago dopo il 1º, puoi aggiungere due incantesimi da mago a scelta al libro degli incantesimi. Ognuno di essi deve essere di un livello di cui il mago possiede degli slot incantesimo, come indicato nella tabella Privilegi del mago. Gli incantesimi rappresentano il culmine delle ricerche arcane svolte regolarmente dal personaggio.\\n\\n**Slot incantesimo.** La tabella Privilegi del mago mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\n**Incantesimi preparati di 1º livello o superiore.** Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per farlo, devi scegliere quattro incantesimi dal suo libro degli incantesimi. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da mago, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del mago. Ogni volta che il numero cresce, il mago deve scegliere altri incantesimi finché il numero sulla lista non combacia con quello mostrato nella tabella Privilegi del mago. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di un mago di 3º livello, la sua lista di incantesimi preparati può includere sei incantesimi di 1º e 2º livello in qualsiasi combinazione presi dal suo libro degli incantesimi.\\n\\nSe un altro privilegio del mago gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da mago.\\n\\n**Cambiare gli incantesimi preparati.** Quando il mago completa un riposo lungo, può modificare la sua lista di incantesimi preparati, sostituendo quelli che preferisce con altri incantesimi inclusi nel suo libro.\\n\\n**Caratteristica da incantatore.** Intelligenza è la caratteristica da incantatore per gli incantesimi da mago.\\n\\n**Focus da incantatore.** Il mago può usare un focus arcano o il suo libro degli incantesimi come focus da incantatore per i propri incantesimi da mago.\\n\\n> **Ampliare e sostituire un libro degli incantesimi**\\n>\\n> Gli incantesimi che il mago aggiunge al proprio libro sono un riflesso degli studi magici che conduce. Tuttavia, durante le sue avventure potrebbe trovarne degli altri da aggiungere al suo repertorio. Per esempio, il personaggio potrebbe scoprirne uno su una pergamena magica e copiarlo nel proprio libro.\\n>\\n> **Copiare un incantesimo nel libro.** Quando il personaggio trova un incantesimo da mago di 1º livello o superiore, può aggiungerlo al proprio libro degli incantesimi se è di un livello che ne consente la preparazione e se c'è abbastanza tempo per copiarlo. Per ogni livello dell'incantesimo, la trascrizione richiede 2 ore e costa 50 mo. Dopodiché, il mago può preparare l'incantesimo come tutti gli altri già presenti nel proprio libro.\\n>\\n> **Copiare il libro.** Il mago può copiare un incantesimo dal proprio libro in un altro. Questo procedimento è simile alla copia di un nuovo incantesimo nel suo libro, ma è più rapido, dal momento che sa già come lanciarlo. Infatti, dovrà impiegare solo 1 ora e spendere 10 mo per ogni livello dell'incantesimo copiato.\\n>\\n> Se il mago perde il suo libro degli incantesimi, può usare la stessa procedura per trascrivere gli incantesimi che ha preparato in un nuovo libro degli incantesimi. Tuttavia, per completarlo dovrà trovarne di nuovi. Ecco perché molti maghi conservano sempre una copia di sicurezza del proprio libro degli incantesimi.","page":60},"feature.wizard.scholar":{"name":"Studioso","description":"Durante il suo studio della magia, il mago si è specializzato anche in un'altra disciplina. Scegli una delle seguenti abilità in cui il personaggio ha competenza: Arcano, Indagare, Medicina, Natura, Religione o Storia. Il mago possiederà maestria nell'abilità selezionata.","page":60},"feature.wizard.memorize-spell":{"name":"Memorizzare incantesimi","description":"Quando il mago completa un riposo breve, può studiare il proprio libro degli incantesimi e sostituire uno degli incantesimi da mago preparati di 1º livello o superiore con un altro di 1º livello o superiore dal libro.","page":61},"feature.wizard.spell-mastery":{"name":"Maestria negli incantesimi","description":"Il mago raggiunge una tale padronanza nell'uso di certi incantesimi da poterli lanciare a volontà. Dal suo libro degli incantesimi, sceglie un incantesimo di 1º livello e uno di 2º livello con il tempo di lancio di un'azione. Tali incantesimi sono sempre considerati come preparati. Inoltre, il mago può lanciarli al loro livello più basso senza spendere slot incantesimo. Per lanciarli a un livello superiore, deve invece spendere uno slot incantesimo.\\n\\nOgni volta che il mago completa un riposo lungo, può studiare il proprio libro e sostituire uno di quegli incantesimi con un altro pertinente dello stesso livello (preso dal libro).","page":61},"feature.wizard.signature-spells":{"name":"Incantesimi personali","description":"Il mago sceglie due incantesimi di 3º livello contenuti nel suo libro degli incantesimi come suoi incantesimi personali. Tali incantesimi sono sempre considerati come preparati. Inoltre, il mago può lanciarli una volta ciascuno al 3º livello senza spendere slot incantesimo. Quando lo fa, non può lanciarli di nuovo in questo modo finché non completa un riposo breve o lungo. Per lanciarli a un livello superiore, deve invece spendere uno slot incantesimo.","page":61},"subclass.wizard.evoker":{"name":"Invocatore","description":"Crea effetti elementali esplosivi\\n\\nUn invocatore concentra i suoi studi sulle magie che generano potenti effetti elementali come un freddo pungente, una fiamma incandescente, un rombo di tuono, un fulmine crepitante o un acido sfrigolante. Alcuni invocatori prestano servizio nelle forze militari come unità di artiglieria in grado di colpire gli eserciti nemici da lontano. Altri usano i loro poteri per proteggere il prossimo, mentre altri ancora li sfruttano per il proprio tornaconto personale.","page":64},"feature.wizard.evoker.evocation-savant":{"name":"Invocatore sapiente","description":"Scegli due incantesimi da mago della scuola di Invocazione che non siano di livello superiore al 2º, e aggiungili gratuitamente al libro degli incantesimi del mago.\\n\\nInoltre, ogni volta che il personaggio ottiene accesso a un nuovo livello di slot incantesimo in questa classe, puoi aggiungere gratuitamente al libro un ulteriore incantesimo da mago della scuola di Invocazione. L'incantesimo scelto deve essere di un livello di cui possiede degli slot incantesimo.","page":64},"feature.wizard.evoker.potent-cantrip":{"name":"Trucchetto potente","description":"I trucchetti del mago che infliggono danni possono influenzare perfino le creature che altrimenti eviterebbero il grosso dell'effetto. Quando il personaggio lancia un trucchetto contro una creatura e la manca con il tiro per colpire o questa supera il tiro salvezza contro il trucchetto, il bersaglio subisce metà dei danni (se applicabile), ma non gli vengono inflitti eventuali effetti aggiuntivi.","page":64},"feature.wizard.evoker.sculpt-spells":{"name":"Plasmare incantesimi","description":"Il mago è in grado di creare delle sacche di relativa sicurezza all'interno degli effetti delle sue invocazioni. Quando il mago lancia un incantesimo di Invocazione che influenza le altre creature nel suo campo visivo, può scegliere un numero di quelle creature pari a 1 più il livello dell'incantesimo. Le creature scelte superano automaticamente i loro tiri salvezza contro l'incantesimo e non subiscono alcun danno se normalmente subirebbero la metà dei danni in caso di tiro salvezza superato.","page":64},"feature.wizard.evoker.empowered-evocation":{"name":"Invocazione potente","description":"Quando il mago lancio un incantesimo della scuola di Invocazione, può aggiungere a un tiro per i danni il suo modificatore di Intelligenza.","page":65},"feature.wizard.evoker.overchannel":{"name":"Saturazione magica","description":"Il mago può aumentare il potere dei suoi incantesimi. Quando lancia un incantesimo con uno slot di livello da 1 a 5 che infligge danni, con quell'incantesimo può infliggere il massimo dei danni nel turno in cui lo lancia.\\n\\nLa prima volta che lo fa, il mago non subisce alcun effetto avverso. Se però utilizza questo privilegio di nuovo prima di avere completato un riposo lungo, subisce 2d12 danni necrotici per ogni livello dell'incantesimo in questione, subito dopo averlo lanciato. Questi danni ignorano le varie forme di resistenza e immunità.\\n\\nOgni volta che utilizza di nuovo questo privilegio prima di aver completato un riposo lungo, i danni necrotici per livello dell'incantesimo aumentano di 1d12.","page":65},"class.monk":{"name":"Monaco","page":66,"classSpecialFeatures":{"class.monk.core-traits":{"name":"Tratti del monaco","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche della tabella Tratti del monaco.\\n- Ottiene i privilegi di 1º livello da monaco, elencati nella tabella Privilegi del monaco.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene il tratto Dado Vita dalla tabella Tratti del monaco.\\n- Ottiene i privilegi di 1º livello da monaco, elencati nella tabella Privilegi del monaco.\\n"},"class.monk.subclass":{"name":"Sottoclasse del monaco","description":"Livello 3: Sottoclasse del monaco\\n\\nIl personaggio ottiene una sottoclasse del monaco a scelta. La descrizione della sottoclasse Guerriero della Mano Aperta segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da monaco. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da monaco attuale o a quelli inferiori.\\n"},"class.monk.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da monaco.\\n"},"class.monk.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da monaco.\\n"},"class.monk.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da monaco.\\n"},"class.monk.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da monaco.\\n"},"class.monk.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono dell'offensiva irresistibile."}}},"feature.monk.martial-arts":{"name":"Arti marziali","description":"Grazie alla sua perizia nelle arti marziali, un monaco padroneggia stili di combattimento che fanno uso di colpi senz'armi e delle seguenti armi da monaco:\\n\\n- Armi da mischia semplici\\n- Armi da mischia da guerra con la proprietà leggera\\n\\nUn monaco ottiene i benefici seguenti fintantoché è senz'armi o impugna soltanto armi da monaco, non indossa alcuna armatura e non impugna uno scudo:\\n\\n**Colpo senz'armi bonus.** Il monaco può effettuare un colpo senz'armi come azione bonus.\\n\\n**Dado di Arti marziali.** Un monaco può tirare 1d6 al posto dei normali danni del suo colpo senz'armi o della sua arma da monaco. Questo dado cambia man mano che il personaggio acquisisce altri livelli da monaco, come indicato nella colonna Arti marziali nella tabella Privilegi del monaco.\\n\\n**Attacchi destri.** Un monaco può usare il modificatore di Destrezza invece del modificatore di Forza per i tiri per colpire e i tiri per i danni dei suoi colpi senz'armi e delle sue armi da monaco. Inoltre, quando utilizza le opzioni di afferrare o spingere del suo colpo senz'armi, il monaco può utilizzare il suo modificatore di Destrezza invece del modificatore di Forza per determinare la CD del tiro salvezza.","page":66},"feature.monk.unarmored-defense":{"name":"Difesa senza armatura","description":"Se il personaggio non sta indossando un'armatura o impugnando uno scudo, la Classe Armatura base corrisponde a 10 più i modificatori di Destrezza e Saggezza.","page":67},"feature.monk.monks-focus":{"name":"Concentrazione da monaco","resourceNames":{"focus-points":"Punti concentrazione"},"description":"La concentrazione e l'addestramento marziale del monaco gli permettono di imbrigliare una fonte di energia straordinaria dentro di sé. Questa energia è rappresentata dai punti concentrazione. Il numero di punti posseduti è determinato dal livello da monaco, come indicato nella colonna Punti concentrazione nella tabella Privilegi del monaco.\\n\\nQuesti punti possono essere spesi per potenziare o alimentare alcuni privilegi del monaco. Inizialmente il monaco conosce tre di questi privilegi: Difesa paziente, Passo del vento e Raffica di colpi, descritti di seguito.\\n\\nQuando un monaco spende un punto concentrazione, quel punto non è più disponibile finché non completa un riposo breve o lungo, alla fine del quale il monaco recupera tutti i punti spesi.\\n\\nAlcune caratteristiche che utilizzano i punti concentrazione richiedono che il bersaglio effettui un tiro salvezza. La CD del tiro salvezza è pari a 8 più il modificatore di Saggezza e il bonus di competenza del monaco.\\n\\n**Raffica di colpi.** Il monaco può spendere 1 punto concentrazione per sferrare due colpi senz'armi come azione bonus.\\n\\n**Difesa paziente.** Il monaco può effettuare l'azione di Disimpegno come azione bonus. In alternativa, può spendere 1 punto concentrazione per effettuare le azioni di Disimpegno e Schivata come azione bonus.\\n\\n**Passo del vento.** Il monaco può utilizzare l'azione di Scatto come azione bonus. In alternativa, può spendere 1 punto concentrazione per effettuare le azioni di Disimpegno e Scatto come azione bonus; inoltre, la sua distanza di salto raddoppia per quel turno.","page":67},"feature.monk.unarmored-movement":{"name":"Movimento senza armatura","description":"La velocità del monaco aumenta di 3 metri, purché non indossi un'armatura o impugni uno scudo. Questo bonus aumenta man mano che il personaggio acquisisce altri livelli da monaco, come indicato nella tabella Privilegi del monaco.","page":67},"feature.monk.uncanny-metabolism":{"name":"Metabolismo straordinario","description":"Quando effettua un tiro per l'iniziativa, il monaco può recuperare tutti i punti concentrazione spesi. Quando lo fa, tira un dado di Arti marziali e recupera un numero di punti ferita pari al suo livello da monaco più il risultato ottenuto.\\n\\nDopo aver utilizzato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.","page":67},"feature.monk.deflect-attacks":{"name":"Devia attacchi","description":"Quando viene colpito da un tiro per colpire che include danni contundenti, perforanti o taglienti, il monaco può usare una reazione per ridurre i danni totali dell'attacco che ha subito. La riduzione è pari a 1d10 più il suo modificatore di Destrezza e il suo livello da monaco.\\n\\nSe i danni vengono ridotti a 0, il monaco può spendere 1 punto concentrazione per deviare parte della forza dell'attacco. Se lo fa, deve scegliere una creatura nel suo campo visivo entro 1,5 metri da sé se l'attacco era in mischia; se l'attacco era a distanza, deve scegliere una creatura nel suo campo visivo entro 18 metri da sé che non sia dietro copertura totale. Quella creatura deve superare un tiro salvezza su Destrezza o subire danni pari a due tiri del dado di Arti marziali più il modificatore di Destrezza del monaco. I danni sono dello stesso tipo di danni inflitti dall'attacco.","page":67},"feature.monk.stunning-strike":{"name":"Colpo stordente","description":"Una volta per turno, quando il monaco colpisce una creatura con un'arma da monaco o un colpo senz'armi, può spendere 1 punto concentrazione per tentare un colpo stordente. Il bersaglio deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, è stordito fino all'inizio del turno successivo del monaco. Se lo supera, la velocità del bersaglio è dimezzata fino all'inizio del turno successivo del monaco, e il prossimo tiro per colpire effettuato contro il bersaglio prima di allora dispone di vantaggio.","page":68},"feature.monk.slow-fall":{"name":"Caduta lenta","description":"Un monaco può usare la sua reazione quando cade per ridurre gli eventuali danni da caduta di un ammontare pari a cinque volte il suo livello da monaco.","page":68},"feature.monk.extra-attack":{"name":"Attacco extra","description":"Quando effettua l'azione di Attacco nel proprio turno, il monaco può attaccare due volte anziché una.","page":68},"feature.monk.empowered-strikes":{"name":"Colpi potenziati","description":"Ogni volta che il monaco infligge danni con un colpo senz'armi, il colpo può infliggere un tipo di danno a scelta tra Forza e il suo tipo di danno normale.","page":68},"feature.monk.evasion":{"name":"Elusione","description":"Quando è soggetto a un effetto che gli consente di effettuare un tiro salvezza su Destrezza per dimezzare i danni, non subisce alcun danno se lo supera, e soltanto la metà dei danni se lo fallisce.\\n\\nIl monaco non beneficia di questo privilegio se è incapacitato.","page":68},"feature.monk.acrobatic-movement":{"name":"Movimento acrobatico","description":"Se il personaggio non sta indossando un'armatura o impugnando uno scudo, ottiene la capacità di muoversi lungo le superfici verticali e sulle superfici liquide durante il suo turno senza cadere durante il movimento.","page":68},"feature.monk.heightened-focus":{"name":"Concentrazione superiore","description":"Difesa paziente, Passo del vento e Raffica di colpi ottengono i seguenti benefici.\\n\\n**Raffica di colpi.** Il monaco può spendere 1 punto concentrazione per usare Raffica di colpi ed infliggere tre colpi senz'armi anziché due.\\n\\n**Difesa paziente.** Quando il monaco spende un punto concentrazione per utilizzare Difesa paziente, ottiene un numero di punti ferita temporanei pari a due tiri del dado di Arti marziali.\\n\\n**Passo del vento.** Quando il monaco spende un punto concentrazione per utilizzare Passo del vento, può scegliere una creatura consenziente entro 1,5 metri da sé di taglia Grande o inferiore. Il monaco muove la creatura con sé fino al termine del suo turno. Questo movimento non provoca attacchi di opportunità.","page":68},"feature.monk.self-restoration":{"name":"Autorigenerazione","description":"Con la sola forza di volontà, il monaco può rimuovere le seguenti condizioni da se stesso al termine di ogni suo turno: affascinato, spaventato o avvelenato.\\n\\nInoltre, la rinuncia a cibo e bevande non comporta livelli di indebolimento.","page":68},"feature.monk.deflect-energy":{"name":"Deviare energia","description":"Ora il monaco può utilizzare il suo privilegio Devia attacchi contro gli attacchi che infliggono qualsiasi tipo di danno, non solo quelli contundenti, perforanti o taglienti.","page":68},"feature.monk.disciplined-survivor":{"name":"Esperto di sopravvivenza disciplinato","description":"La disciplina fisica e mentale del monaco gli conferisce competenza in tutti i tiri salvezza.\\n\\nInoltre, ogni volta che effettua un tiro salvezza e fallisce, può spendere 1 punto concentrazione per ripetere il tiro. Deve usare il nuovo risultato.","page":68},"feature.monk.perfect-focus":{"name":"Concentrazione perfetta","description":"Quando il monaco tira per l'iniziativa e non usa Metabolismo straordinario, può recuperare i punti concentrazione spesi fino ad averne 4, se ne ha 3 o meno.","page":68},"feature.monk.superior-defense":{"name":"Difesa superiore","description":"All'inizio del suo turno, il monaco può spendere 3 punti concentrazione per rafforzare se stesso contro i danni per 1 minuto o finché non è incapacitato. In quell'intervallo di tempo, ottiene resistenza a tutti i danni tranne a quelli da Forza.","page":68},"feature.monk.body-and-mind":{"name":"Corpo e mente","description":"La mente e il corpo del monaco hanno raggiunto nuove vette. I punteggi di Destrezza e Saggezza aumentano di 4, fino a un massimo di 25.","page":68},"subclass.monk.warrior-of-the-open-hand":{"name":"Guerriero della Mano Aperta","description":"Padroneggia le tecniche di combattimento senz'armi\\n\\nI Guerrieri della Mano Aperta sono i maestri del combattimento senz'armi. Apprendono tecniche speciali per spingere e sbilanciare i loro avversari e manipolano la propria energia per proteggersi dai danni.","page":68},"feature.monk.warrior-of-the-open-hand.open-hand-technique":{"name":"Tecnica della mano aperta","description":"Ogni volta che il monaco colpisce una creatura con un attacco concessogli dalla sua Raffica di colpi, può imporre a quel bersaglio uno degli effetti seguenti:\\n\\n**Disorientamento.** Il bersaglio non può effettuare attacchi di opportunità fino all'inizio del suo turno successivo.\\n\\n**Spinta.** Il bersaglio deve effettuare un tiro salvezza su Forza. Se lo fallisce, il monaco spinge il bersaglio via da sé fino a un massimo di 4,5 metri.\\n\\n**Rovesciamento.** Il bersaglio deve superare un tiro salvezza su Destrezza, altrimenti cade a terra prono.","page":69},"feature.monk.warrior-of-the-open-hand.wholeness-of-body":{"name":"Integrità del corpo","description":"Il monaco ottiene la capacità di curarsi. Come azione bonus, può tirare il dado di Arti marziali. In questo modo, recupera un numero di punti ferita pari al risultato ottenuto più il suo modificatore di Saggezza (minimo di 1 punto ferita recuperato).\\n\\nIl personaggio può utilizzare questo privilegio un numero di volte pari al valore del suo modificatore di Saggezza (minimo una volta) e recupera tutti gli utilizzi consumati quando completa un riposo lungo.","page":69},"feature.monk.warrior-of-the-open-hand.fleet-step":{"name":"Passo lesto","description":"Quando il monaco effettua un'azione bonus diversa da Passo del vento, può usare anche Passo del vento subito dopo l'azione bonus.","page":69},"feature.monk.warrior-of-the-open-hand.quivering-palm":{"name":"Palmo tremante","description":"Il monaco ottiene la capacità di scatenare vibrazioni letali nel corpo di un altro. Quando il monaco colpisce una creatura con un colpo senz'armi, può spendere 4 punti concentrazione per dare il via a queste vibrazioni impercettibili, che durano un numero di giorni pari al suo livello da monaco. Le vibrazioni sono innocue, a meno che il monaco non effettui un'azione per interromperle. In alternativa, quando effettua l'azione di Attacco nel proprio turno, può rinunciare a uno degli attacchi per porre fine alle vibrazioni. Per farlo, il monaco e il bersaglio devono trovarsi sullo stesso piano di esistenza. Quando il monaco pone fine alle vibrazioni, il bersaglio deve effettuare un tiro salvezza su Costituzione; subisce 10d12 danni da forza in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nIl monaco può tenere soltanto una creatura alla volta sotto l'effetto di questo privilegio. Le vibrazioni possono essere interrotte senza provocare danni (nessuna azione richiesta).","page":69},"class.paladin":{"name":"Paladino","description":"> **Giuramenti infranti**\\n>\\n> Un paladino si sforza sempre di mantenere una condotta impeccabile, ma anche il più virtuoso può fallire, violando il proprio giuramento.\\n>\\n> Un paladino che ha infranto il suo giuramento solitamente va in cerca di redenzione, trascorrendo un'intera notte in preghiera o facendo un digiuno. Dopo un rito di perdono, viene di nuovo considerato senza macchia.\\n>\\n> Se invece il personaggio viola il giuramento senza pentirsene, parlane con il GM. Forse dovresti scegliere una sottoclasse più adatta o persino abbandonare la classe del paladino in favore di un'altra.","page":70,"classSpecialFeatures":{"class.paladin.core-traits":{"name":"Tratti del paladino","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutti i tratti nella tabella Tratti del paladino.\\n- Ottiene i privilegi di 1º livello da paladino, elencati nella tabella Privilegi del paladino.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti dalla tabella Tratti del paladino: Dado Vita, competenza nelle armi da guerra, nelle armature leggere, medie e negli scudi.\\n- Ottiene i privilegi di 1º livello da paladino, elencati nella tabella Privilegi del paladino. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.paladin.subclass":{"name":"Sottoclasse del paladino","description":"Livello 3: Sottoclasse del paladino\\n\\nIl personaggio ottiene una sottoclasse del paladino a scelta. La descrizione della sottoclasse Giuramento di Devozione segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da paladino. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da paladino attuale o a quelli inferiori.\\n"},"class.paladin.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da paladino.\\n"},"class.paladin.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da paladino.\\n"},"class.paladin.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da paladino.\\n"},"class.paladin.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da paladino.\\n"},"class.paladin.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono della vista pura."}}},"feature.paladin.lay-on-hands":{"name":"Imposizione delle mani","resourceNames":{"lay-on-hands":"Imposizione delle mani (punti ferita)"},"description":"Il tocco benedetto di un paladino è in grado di guarire le ferite. Un paladino possiede una riserva di poteri curativi che si ricostituisce quando completa un riposo lungo. Questa gli consente di ripristinare un numero totale di punti ferita pari a cinque volte il proprio livello da paladino.\\n\\nCome azione bonus, il paladino può toccare una creatura (anche se stesso) e attingere al potere della sua riserva per ripristinare un certo numero di punti ferita in quella creatura, fino all'ammontare massimo in essa disponibile.\\n\\nInoltre, può consumare 5 punti ferita della riserva per curare l'avvelenamento. In questo caso, i punti ferita impiegati non vanno a ripristinare quelli della creatura interessata.","page":71},"feature.paladin.spellcasting":{"name":"Incantesimi","description":"Il paladino impara a lanciare incantesimi attraverso la preghiera e la meditazione. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicare tali regole agli incantesimi da paladino, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Slot incantesimo.** La tabella Privilegi del paladino mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\n**Incantesimi preparati di 1º livello o superiore.** Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, sceglie due incantesimi da paladino di 1º livello. Sono consigliati eroismo e punizione incandescente.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da paladino, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del paladino. Ogni volta che il numero cresce, il paladino deve scegliere altri incantesimi finché il numero sulla lista non combacia con quello mostrato nella tabella Privilegi del paladino. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di un paladino di 5º livello, la sua lista di incantesimi preparati può includere sei incantesimi da paladino di 1º e 2º livello in qualsiasi combinazione.\\n\\nSe un altro privilegio del paladino gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da paladino.\\n\\n**Cambiare gli incantesimi preparati.** Quando completa un riposo lungo, il paladino può sostituire un incantesimo sulla propria lista con un altro incantesimo di cui possiede degli slot.\\n\\n**Caratteristica da incantatore.** Carisma è la caratteristica da incantatore per gli incantesimi da paladino.\\n\\n**Focus da incantatore.** Il paladino può usare un simbolo sacro come focus da incantatore per i suoi incantesimi da paladino.","page":71},"feature.paladin.weapon-mastery":{"name":"Padronanza d'armi","description":"Il paladino è addestrato nell'uso delle armi, e per questo può avvalersi della proprietà di padronanza per due tipi di armi a sua scelta in cui ha competenza, come le spade lunghe e i giavellotti.\\n\\nOgni volta che completa un riposo lungo, può cambiare il tipo di arma utilizzato. Per esempio, è possibile passare alle proprietà di padronanza per alabarde e mazzafrusti.","page":71},"feature.paladin.paladins-smite":{"name":"Punizione del paladino","description":"L'incantesimo punizione divina è sempre considerato preparato. Inoltre, il paladino può lanciarlo senza consumare alcuno slot incantesimo, ma deve completare un riposo lungo prima di poterlo lanciare nuovamente in questo modo.","page":71},"feature.paladin.fighting-style":{"name":"Stile di combattimento","description":"Il paladino ottiene un talento Stile di combattimento a sua scelta (vedi capitolo \\"Talenti\\" per i talenti). Tuttavia, invece di sceglierne uno tra quelli proposti, è possibile avvalersi dell'opzione sottostante.\\n\\n**Guerriero benedetto.** Il paladino impara due trucchetti da chierico a scelta (consulta la sezione della classe del chierico per una lista dei suoi incantesimi). Sono consigliati guida e fiamma sacra. I trucchetti scelti valgono come incantesimi da paladino e la caratteristica da incantatore per usarli è Carisma. Ogni volta che il personaggio ottiene un livello da paladino, puoi sostituire uno dei trucchetti con un altro trucchetto da chierico.","page":71},"feature.paladin.channel-divinity":{"name":"Incanalare divinità","description":"Il paladino può incanalare l'energia divina direttamente dai Piani Esterni, usandola per alimentare effetti magici. Inizia con uno di questi effetti: Percezione del Divino, descritto di seguito. Gli altri privilegi del paladino gli conferiscono ulteriori effetti di Incanalare Divinità. Ogni volta che il personaggio usa Incanalare Divinità di questa classe, è possibile scegliere l'effetto desiderato della classe.\\n\\nIl paladino può usare Incanalare divinità due volte. Per quanto riguarda gli utilizzi consumati, ne recupera uno dopo aver completato un riposo breve e li recupera tutti dopo un riposo lungo. Ottiene un uso aggiuntivo una volta raggiunto il livello 11.\\n\\nSe un effetto di Incanalare divinità richiede un tiro salvezza, la CD equivale alla CD del tiro salvezza sull'incantesimo del privilegio Incantesimi di questa classe.\\n\\n**Percezione del divino.** Come azione bonus, il paladino può amplificare i propri sensi per individuare celestiali, immondi e non morti. Per i prossimi 10 minuti o finché non è incapacitato, conosce la posizione di ogni creatura summenzionata in un raggio di 18 metri da sé e può distinguerne la tipologia. Entro lo stesso raggio, il paladino individua anche la presenza di qualsiasi luogo o oggetto sacro o sacrilego, con gli stessi effetti dell'incantesimo santificare.","page":72},"feature.paladin.extra-attack":{"name":"Attacco extra","description":"Quando effettua l'azione di Attacco nel proprio turno, il paladino può attaccare due volte anziché una.","page":72},"feature.paladin.faithful-steed":{"name":"Fido destriero","description":"Il paladino può richiedere l'aiuto di una cavalcatura ultraterrena e l'incantesimo trova cavalcatura è sempre considerato preparato.\\n\\nPuò lanciarlo una volta senza consumare uno slot incantesimo e ne recupera l'utilizzo dopo aver completato un riposo lungo.","page":72},"feature.paladin.aura-of-protection":{"name":"Aura di protezione","description":"Il paladino sprigiona un'aura protettiva invisibile in una emanazione di 3 metri che ha origine da sé. L'aura diventa inattiva quando è incapacitato.\\n\\nL'aura conferisce al personaggio e ai suoi alleati un bonus ai tiri salvezza pari al suo modificatore di Carisma (fino a un bonus minimo di +1).\\n\\nSe è presente un altro paladino, le creature possono usufruire di una sola Aura di protezione per volta: spetta alla creatura interessata scegliere quale.","page":72},"feature.paladin.abjure-foes":{"name":"Abiurare nemici","description":"Come azione di Magia, il paladino può consumare uno degli usi di Incanalare divinità per sopraffare gli avversari. Dopo aver estratto il suo simbolo sacro o l'arma, può prendere di mira un numero di creature corrispondente al proprio modificatore di Carisma (minimo una creatura) che egli può vedere in un raggio di 18 metri da sé. Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà spaventato per 1 minuto o finché non subirà dei danni. Mentre è in questa condizione, nel proprio turno può svolgere solo una delle seguenti azioni: muoversi, effettuare un'azione o un'azione bonus.","page":72},"feature.paladin.aura-of-courage":{"name":"Aura di coraggio","description":"Il paladino e i suoi alleati sono immuni alla paura finché si trovano all'interno dell'Aura di protezione. Se un alleato spaventato entra nel suo raggio d'influenza, non subirà più l'effetto della paura finché sarà al suo interno.","page":72},"feature.paladin.radiant-strikes":{"name":"Colpi radiosi","description":"I colpi del paladino ora possiedono poteri soprannaturali. Quando colpisce un bersaglio con un tiro per colpire utilizzando un'arma da mischia o un colpo senz'armi, questo subisce 1d8 danni radiosi aggiuntivi.","page":72},"feature.paladin.restoring-touch":{"name":"Tocco rigenerante","description":"Quando il paladino usa Imposizione delle mani su una creatura, può anche liberarla da una delle seguenti condizioni: accecato, affascinato, assordato, paralizzato, spaventato o stordito. Per farlo, è necessario attingere a 5 punti ferita della riserva curativa di Imposizione delle mani per ognuna delle condizioni rimosse. Tuttavia, i punti consumati non ripristinano i punti ferita della creatura.","page":72},"feature.paladin.aura-expansion":{"name":"Ampliamento dell'aura","description":"L'Aura di protezione del paladino è ora un'emanazione di 9 metri.","page":72},"subclass.paladin.oath-of-devotion":{"name":"Giuramento di devozione","description":"Tieni fede agli ideali di giustizia e ordine\\n\\nIl Giuramento di devozione vincola i paladini agli ideali di giustizia e ordine, avvicinandoli all'archetipo del \\"cavaliere senza macchia e senza paura\\". Si considerano modelli esemplari di condotta e alcuni di loro, nel bene e nel male, applicano gli stessi parametri al resto del mondo.\\n\\nMolti di coloro che prestano questo giuramento sono devoti agli dèi della legalità e del bene, e usano i dettami delle loro divinità come misura della propria devozione. Altri, invece, prendono gli angeli come esempi dei propri ideali e integrano immagini di ali angeliche nei propri elmi o stemmi.\\n\\nCondividono i seguenti dettami:\\n\\n- Che la tua parola sia vincolante come una promessa.\\n- Proteggi i deboli e non aver mai paura di agire.\\n- Che le tue onorevoli gesta siano da esempio per gli altri.","page":73},"feature.paladin.oath-of-devotion.sacred-weapon":{"name":"Arma consacrata","description":"Quando il paladino effettua l'azione di Attacco, può consumare uno degli usi di Incanalare divinità per infondere energia positiva nell'arma da mischia che impugna. Per 10 minuti o fino al prossimo utilizzo del privilegio, il paladino aggiunge il suo modificatore di Carisma ai tiri per colpire eseguiti con quell'arma (fino a un bonus minimo di +1) e, ogni volta che colpisce, può infliggere danni normali o radiosi.\\n\\nInoltre, l'arma emette luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri.\\n\\nQuesto effetto può essere interrotto in anticipo (nessuna azione richiesta). L'effetto termina se il paladino non ha più con sé l'arma interessata.","page":74},"feature.paladin.oath-of-devotion.spells":{"name":"Incantesimi del Giuramento di devozione","description":"La magia del giuramento del paladino gli consente di avere sempre pronti determinati incantesimi. Una volta raggiunto un livello specificato nella tabella Incantesimi del Giuramento di devozione, gli incantesimi lì elencati saranno sempre considerati come preparati.\\n\\n**Tabella: Incantesimi del Giuramento di devozione**\\n\\n|Livello da paladino|Incantesimi|\\n|---|---|\\n|3|Protezione dal bene e dal male, scudo della fede|\\n|5|Aiuto, zona di verità|\\n|9|Faro di speranza, dissolvi magie|\\n|13|Libertà di movimento, guardiano della fede|\\n|17|Comunione, colpo infuocato|","page":73},"feature.paladin.oath-of-devotion.aura-of-devotion":{"name":"Aura di devozione","description":"Il paladino e i suoi alleati non possono essere affascinati finché si trovano all'interno dell'Aura di protezione. Se un alleato affascinato entra nel suo raggio d'influenza, non subirà più quell'effetto finché sarà al suo interno.","page":74},"feature.paladin.oath-of-devotion.smite-of-protection":{"name":"Punizione protettiva","description":"La punizione magica del paladino ora emana energia protettiva. Ogni volta che utilizza punizione divina, il paladino e i suoi alleati ottengono mezza copertura finché sono nell'Aura di protezione. Questo beneficio rimane attivo fino all'inizio del suo turno successivo.","page":74},"feature.paladin.oath-of-devotion.holy-nimbus":{"name":"Nube sacra","description":"Come azione bonus, il paladino può infondere la sua Aura di protezione con del potere sacro, conferendo i benefici sottostanti per 10 minuti o finché non vengono interrotti (nessuna azione richiesta). Dopo aver utilizzato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo. Tuttavia, è possibile ripristinarne l'uso consumando uno slot incantesimo di 5º livello (nessuna azione richiesta).\\n\\n**Danni radiosi.** Se un nemico comincia il suo turno all'interno dell'aura, subisce danni radiosi pari al modificatore di Carisma più il bonus di competenza del paladino.\\n\\n**Luce del sole.** L'aura rifulge di luce intensa, ovvero la luce solare.\\n\\n**Sentinella sacra.** Se costretto a effettuare dei tiri salvezza da un immondo o un non morto, il paladino dispone di vantaggio.","page":74},"class.ranger":{"name":"Ranger","page":75,"classSpecialFeatures":{"class.ranger.core-traits":{"name":"Tratti del ranger","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutti i tratti nella tabella Tratti del ranger.\\n- Ottiene i privilegi di 1º livello da ranger, elencati nella tabella Privilegi del ranger.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti dalla tabella Tratti del ranger: Dado Vita, competenza nelle armi da guerra, competenza in un'abilità a scelta dalla lista delle abilità del ranger, oltre che competenza in armature leggere, medie e scudi.\\n- Ottiene i privilegi di 1º livello da ranger, elencati nella tabella Privilegi del ranger. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.ranger.subclass":{"name":"Sottoclasse del ranger","description":"Livello 3: Sottoclasse del ranger\\n\\nIl personaggio ottiene una sottoclasse del ranger a scelta. La descrizione della sottoclasse Cacciatore segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da ranger. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da ranger attuale o a quelli inferiori.\\n"},"class.ranger.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da ranger.\\n"},"class.ranger.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da ranger.\\n"},"class.ranger.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da ranger.\\n"},"class.ranger.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da ranger.\\n"},"class.ranger.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del viaggio dimensionale."}}},"feature.ranger.spellcasting":{"name":"Incantesimi","description":"Il ranger ha imparato a incanalare l'essenza della natura per usare la magia. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicare tali regole agli incantesimi da ranger, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\nSlot incantesimo. La tabella Privilegi del ranger mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\nIncantesimi preparati di 1º livello o superiore. Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, sceglie due incantesimi da ranger di 1º livello. Sono consigliati cura ferite e colpo intrappolante.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da ranger, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del ranger. Ogni volta che il numero cresce, il ranger deve scegliere altri incantesimi finché il numero sulla lista non combacia con quello mostrato nella tabella Privilegi del ranger. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di un ranger di 5º livello, la sua lista di incantesimi preparati può includere sei incantesimi da ranger di 1º e 2º livello in qualsiasi combinazione.\\n\\nSe un altro privilegio del ranger gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da ranger.\\n\\nCambiare gli incantesimi preparati. Quando completa un riposo lungo, il ranger può sostituire un incantesimo sulla propria lista con un altro incantesimo di cui possiede degli slot.\\n\\nCaratteristica da incantatore. Saggezza è la caratteristica da incantatore usata per gli incantesimi da ranger.\\n\\nFocus da incantatore. Il ranger può usare un focus druidico per i suoi incantesimi da ranger.","page":76},"feature.ranger.weapon-mastery":{"name":"Padronanza d'armi","description":"Il ranger è addestrato nell'uso delle armi, e per questo può avvalersi della proprietà di padronanza per due tipi di armi a sua scelta in cui ha competenza, come gli archi lunghi e le spade corte.\\n\\nOgni volta che completa un riposo lungo, può cambiare il tipo di arma utilizzato. Per esempio, è possibile passare alle proprietà di padronanza per scimitarre e spade lunghe.","page":76},"feature.ranger.favored-enemy":{"name":"Nemico prescelto","description":"L'incantesimo marchio del cacciatore del ranger è sempre considerato come preparato. È possibile lanciarlo due volte senza spendere alcuno slot incantesimo. I suoi utilizzi vengono ripristinati dopo aver completato un riposo lungo.\\n\\nIl numero di volte in cui è possibile lanciare tale incantesimo aumenta al raggiungimento di determinati livelli da ranger, come mostrato nella colonna Nemico prescelto della tabella Privilegi del ranger.","page":76},"feature.ranger.fighting-style":{"name":"Stile di combattimento","description":"Il ranger ottiene un talento Stile di combattimento a sua scelta (vedi \\"Talenti\\"). Tuttavia, invece di sceglierne uno tra quelli proposti, è possibile avvalersi dell'opzione sottostante.\\n\\nGuerriero druidico. Il ranger apprende due trucchetti da druido a scelta (vedi la sezione della classe del druido per una lista dei relativi incantesimi). Sono consigliati guida e luce splendente. I trucchetti scelti valgono come incantesimi da ranger e la caratteristica da incantatore per usarli è Saggezza. Ogni volta che il personaggio ottiene un livello da ranger, può sostituire uno dei trucchetti con un altro trucchetto da druido.","page":76},"feature.ranger.deft-explorer":{"name":"Esploratore esperto","description":"Grazie ai suoi tanti viaggi, il ranger ottiene i seguenti benefici.\\n\\n**Maestria.** Il ranger può scegliere una delle competenze nelle abilità in cui non possiede maestria, così da ottenerla.\\n\\n**Lingue.** Il ranger conosce due lingue a scelta dal relativo elenco nel capitolo \\"Creazione del personaggio\\".","page":76},"feature.ranger.extra-attack":{"name":"Attacco extra","description":"Quando effettua l'azione di Attacco nel proprio turno, il ranger può attaccare due volte anziché una.","page":76},"feature.ranger.roving":{"name":"Girovago","description":"La velocità del ranger aumenta di 3 metri, purché non indossi un'armatura pesante. Inoltre, ha una velocità di scalata e nuoto pari alla propria velocità.","page":77},"feature.ranger.expertise":{"name":"Maestria","description":"Il ranger può scegliere due delle competenze nelle abilità in cui non possiede maestria, così da ottenerla.","page":77},"feature.ranger.tireless":{"name":"Instancabile","description":"Le forze primordiali ora alimentano i viaggi del ranger, fornendogli i seguenti benefici.\\n\\nPunti ferita temporanei. Come azione di Magia, il ranger può ottenere un numero di punti ferita temporanei pari a 1d8 + il suo modificatore di Saggezza (minimo di 1 punto ferita temporaneo). Il personaggio può utilizzare questa azione un numero di volte pari al valore del suo modificatore di Saggezza (minimo una volta) e recupera tutti gli utilizzi consumati quando completa un riposo lungo.\\n\\nDiminuisci indebolimento. Quando il ranger completa un riposo breve, il suo livello di indebolimento, se presente, diminuisce di 1.","page":77},"feature.ranger.relentless-hunter":{"name":"Cacciatore implacabile","description":"Pur subendo danni, il ranger non interrompe la sua concentrazione sul marchio del cacciatore.","page":77},"feature.ranger.natures-veil":{"name":"Velo della natura","description":"Il ranger invoca gli spiriti della natura per nascondersi magicamente. Come azione bonus, può conferirsi la condizione di invisibilità fino al termine del suo turno successivo.\\n\\nIl personaggio può utilizzare questo privilegio un numero di volte pari al valore del suo modificatore di Saggezza (minimo una volta) e recupera tutti gli utilizzi consumati quando completa un riposo lungo.","page":77},"feature.ranger.precise-hunter":{"name":"Precisione del cacciatore","description":"Il ranger ottiene vantaggio ai tiri per colpire contro la creatura su cui è posto il suo marchio del cacciatore.","page":77},"feature.ranger.feral-senses":{"name":"Sensi ferini","description":"Il legame con le forze della natura conferisce al ranger vista cieca entro un raggio di 9 metri.","page":77},"feature.ranger.foe-slayer":{"name":"Sterminatore di nemici","description":"I danni del marchio del cacciatore sono calcolati con un d10 anziché un d6.","page":77},"subclass.ranger.hunter":{"name":"Cacciatore","description":"Proteggi la natura e le persone dalla distruzione\\n\\nBracchi la preda sia nelle terre selvagge che in ogni altro luogo, utilizzando le tue abilità di cacciatore per proteggere la natura e le persone dalle forze che intendono distruggerle.","page":78},"feature.ranger.hunter.hunters-prey":{"name":"Preda del cacciatore","description":"Il ranger ottiene una delle seguenti opzioni di privilegio a scelta. Ogni volta che completa un riposo breve o lungo, può sostituire l'opzione selezionata con l'altra.\\n\\nDevastatore dell'orda. Una volta per turno quando il ranger effettua un attacco con un'arma, può sferrare un altro attacco con la stessa arma contro una creatura diversa che sia entro 1,5 metri dal bersaglio originale e a portata dell'arma, e che non abbia già attaccato nel corso del turno corrente.\\n\\nSterminatore di colossi. La tenacia del ranger scoraggia anche i nemici più resilienti. Quando colpisce una creatura con un'arma, questa infligge 1d8 danni aggiuntivi al bersaglio se gli mancano dei punti ferita. Può infliggere questi danni extra solo una volta per turno.","page":78},"feature.ranger.hunter.hunters-lore":{"name":"Sapienza del cacciatore","description":"Il cacciatore può fare appello alle forze della natura per scoprire punti di forza e debolezza della propria preda. Se una creatura ha su di sé il marchio del cacciatore del personaggio, questi saprà se il bersaglio ha immunità, resistenze e vulnerabilità, e quali sono.","page":78},"feature.ranger.hunter.defensive-tactics":{"name":"Tattiche difensive","description":"Il ranger ottiene una delle seguenti opzioni di privilegio a scelta. Ogni volta che completa un riposo breve o lungo, può sostituire l'opzione selezionata con l'altra.\\n\\nDifesa dal multiattacco. Se una creatura colpisce il ranger con un tiro per colpire subirà svantaggio a tutti gli altri tiri per colpire effettuati contro il ranger durante il turno.\\n\\nSfuggire all'orda. Gli attacchi di opportunità effettuati contro il personaggio subiscono svantaggio.","page":78},"feature.ranger.hunter.superior-hunters-prey":{"name":"Preda del cacciatore superiore","description":"Una volta per turno, quando il ranger infligge danni a una creatura su cui è posto il suo marchio del cacciatore, può infliggere i danni aggiuntivi dell'incantesimo anche a una creatura nel suo campo visivo che si trovi entro 9 metri dal primo bersaglio.","page":78},"feature.ranger.hunter.superior-hunters-defense":{"name":"Difesa del cacciatore superiore","description":"Quando il ranger subisce danni, può utilizzare una reazione per ottenere resistenza a quel danno e ad altri dello stesso tipo fino al termine del turno in corso.","page":78},"class.sorcerer":{"name":"Stregone","page":79,"classSpecialFeatures":{"class.sorcerer.core-traits":{"name":"Tratti dello stregone","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutti i tratti nella tabella Tratti dello stregone.\\n- Ottiene i privilegi di 1º livello da stregone, elencati nella tabella Privilegi dello stregone.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene il Dado Vita dalla tabella Tratti dello stregone.\\n- Ottiene i privilegi di 1º livello da stregone, elencati nella tabella Privilegi dello stregone. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.sorcerer.subclass":{"name":"Sottoclasse dello stregone","description":"Livello 3: Sottoclasse dello stregone\\n\\nIl personaggio ottiene una sottoclasse dello stregone a scelta. La descrizione della sottoclasse Stregoneria draconica segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da stregone. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da stregone attuale o a quelli inferiori.\\n"},"class.sorcerer.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da stregone.\\n"},"class.sorcerer.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da stregone.\\n"},"class.sorcerer.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da stregone.\\n"},"class.sorcerer.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da stregone.\\n"},"class.sorcerer.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del viaggio dimensionale."}}},"feature.sorcerer.innate-sorcery":{"name":"Stregoneria innata","description":"Lo stregone è stato segnato in maniera indelebile da un evento del suo passato, che gli ha conferito un potere magico dormiente. Come azione bonus, può scatenarlo per 1 minuto e ottenere i seguenti benefici per la sua durata:\\n\\n- La CD del tiro salvezza sull'incantesimo degli incantesimi da stregone aumenta di 1.\\n- Lo stregone ha vantaggio ai tiri per colpire degli incantesimi lanciati.\\n\\nIl personaggio può utilizzare questo privilegio per due volte e recuperare tutti gli utilizzi spesi quando completa un riposo lungo.","page":79},"feature.sorcerer.spellcasting":{"name":"Incantesimi","description":"Attingendo alla propria magia innata, lo stregone è in grado di lanciare incantesimi. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicare tali regole agli incantesimi da stregone, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Trucchetti.** Il personaggio conosce quattro trucchetti da stregone a scelta. Sono consigliati luce, prestidigitazione, stretta folgorante e stregoneria esplosiva. Ogni volta che il personaggio ottiene un livello da stregone, può sostituire uno dei trucchetti di questo privilegio con un altro trucchetto a scelta.\\n\\nDopo aver raggiunto il 4º e il 10º livello da stregone, il personaggio apprende un altro trucchetto a scelta, come mostrato nella colonna Trucchetti della tabella Privilegi dello stregone.\\n\\nSlot incantesimo. La tabella Privilegi dello stregone mostra gli slot incantesimo disponibili per i propri incantesimi di 1º livello o superiore. Tutti gli slot incantesimo consumati vengono ripristinati una volta completato un riposo lungo.\\n\\nIncantesimi preparati di 1º livello o superiore. Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, sceglie due incantesimi da stregone di 1º livello. Sono consigliati mani brucianti e individuazione del magico.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da stregone, come mostrato nella colonna Incantesimi preparati della tabella Privilegi dello stregone. Ogni volta che il numero cresce, lo stregone deve scegliere altri incantesimi finché il numero sulla lista non combacia con quello mostrato nella tabella Privilegi dello stregone. Gli incantesimi scelti devono essere di un livello di cui possiede degli slot incantesimo. Per esempio, nel caso di uno stregone di 3º livello, la sua lista di incantesimi preparati può includere sei incantesimi da stregone di 1º e 2º livello in qualsiasi combinazione.\\n\\nSe un altro privilegio dello stregone gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da stregone.\\n\\nCambiare gli incantesimi preparati. Quando completa un riposo lungo, lo stregone può sostituire un incantesimo sulla propria lista con un altro incantesimo da stregone di cui possiede degli slot.\\n\\nCaratteristica da incantatore. Carisma è la caratteristica da incantatore per gli incantesimi da stregone.\\n\\nFocus da incantatore. Uno stregone può usare un focus arcano come focus da incantatore per i suoi incantesimi da stregone.","page":79},"feature.sorcerer.font-of-magic":{"name":"Fonte di magia","resourceNames":{"sorcery-points":"Punti stregoneria"},"description":"Lo stregone può attingere alla fonte del potere magico dentro di sé. Essa è rappresentata dai punti stregoneria, che gli consentono di creare una vasta gamma di effetti magici.\\n\\nUno stregone parte con 2 punti stregoneria e ne ottiene altri ai livelli superiori, come indicato nella colonna Punti stregoneria nella tabella Privilegi dello stregone. Non può avere un numero di punti stregoneria superiore al numero indicato nella tabella per il suo livello. Il personaggio recupera tutti i punti stregoneria spesi quando completa un riposo lungo.\\n\\nÈ possibile sfruttare i punti stregoneria per alimentare le opzioni sottostanti, oltre che altri privilegi che ne fanno uso come Metamagia.\\n\\nConvertire gli slot incantesimo in punti stregoneria. Lo stregone può consumare uno slot incantesimo per ottenere un numero di punti stregoneria pari al livello dello slot (nessuna azione richiesta).\\n\\nCreare slot incantesimo. Come azione bonus, lo stregone può trasformare i punti stregoneria non spesi in uno slot incantesimo. La tabella Creazione degli slot incantesimo indica il costo di creazione di uno slot di un determinato livello, oltre che il livello da stregone minimo necessario per creare uno slot. Non è possibile creare slot incantesimo di livello superiore al 5º.\\n\\nOgni slot incantesimo creato tramite questo privilegio svanisce quando lo stregone completa un riposo lungo.\\n\\n**Creazione degli slot incantesimo**\\n\\n|Livello slot incantesimo|Costo in punti stregoneria|Livello da stregone minimo|\\n|---|---|---|\\n|1|2|2|\\n|2|3|3|\\n|3|5|5|\\n|4|6|7|\\n|5|7|9|","page":80},"feature.sorcerer.metamagic":{"name":"Metamagia","description":"Poiché la magia è un'abilità innata dello stregone, quest'ultimo può alterare i suoi incantesimi secondo necessità, per questo ottiene due opzioni di Metamagia dalla sezione Opzioni di metamagia, che si trova più avanti nella descrizione della classe. Le opzioni selezionate possono essere utilizzate per modificare temporaneamente gli incantesimi lanciati. Per fare uso di un'opzione, è necessario consumare il costo corrispondente in punti stregoneria.\\n\\nLo stregone può usare soltanto un'opzione di Metamagia su un incantesimo quando lo lancia, a meno che non sia specificato diversamente.\\n\\nOgni volta che il personaggio ottiene un livello da stregone, è possibile sostituire una delle opzioni di Metamagia con una che ancora non conosce. Lo stregone ottiene due ulteriori opzioni al 10º livello e altre due al 17º livello.","page":81},"feature.sorcerer.sorcerous-restoration":{"name":"Ripristino stregonesco","description":"Quando lo stregone completa un riposo breve, può recuperare i punti stregoneria consumati, ma non più di un numero pari a metà del proprio livello da stregone (arrotondato per difetto). Dopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.","page":81},"feature.sorcerer.sorcery-incarnate":{"name":"Stregoneria incarnata","description":"Se ha consumato tutti i suoi utilizzi di Stregoneria innata, come azione bonus può spendere 2 punti stregoneria per attivarla.\\n\\nInoltre, mentre il privilegio Stregoneria innata è attivo, lo stregone può usare fino a due delle sue opzioni di Metamagia su ogni incantesimo lanciato.","page":81},"feature.sorcerer.arcane-apotheosis":{"name":"Apoteosi arcana","description":"Quando il privilegio Stregoneria innata è attivo, lo stregone può usare un'opzione di Metamagia a ogni turno senza dover consumare punti stregoneria.","page":81},"subclass.sorcerer.draconic-sorcery":{"name":"Stregoneria draconica","description":"Lasciati inebriare dalla magia dei draghi\\n\\nLa magia innata dello stregone proviene dal dono di un drago. Potrebbe averla ereditata da un drago antico che, prossimo alla morte, ha conferito il proprio potere magico a lui o a un suo antenato, o magari l'ha assorbito da un luogo pregno di energia draconica o da uno dei tesori di queste creature. Oppure uno dei suoi antenati era un drago.","page":84},"feature.sorcerer.draconic-sorcery.draconic-resilience":{"name":"Resilienza draconica","description":"La magia nel corpo dello stregone fa sì che il suo corpo mostri i tratti fisici del proprio dono draconico. I punti ferita massimi del personaggio salgono di 3 e aumentano di nuovo di 1 ogni volta che acquisisce un livello da stregone.\\n\\nInoltre, alcune parti del suo corpo sono ricoperte da scaglie di drago. Se non indossa armatura, la Classe Armatura base corrisponde a 10 più i modificatori di Destrezza e Carisma.","page":84},"feature.sorcerer.draconic-sorcery.draconic-spells":{"name":"Incantesimi draconici","description":"Quando lo stregone raggiunge un livello specificato nella tabella Incantesimi draconici, gli incantesimi lì elencati sono considerati come preparati.\\n\\n**Incantesimi draconici**\\n\\n|Livello da stregone|Incantesimi|\\n|---|---|\\n|3|Alterare se stesso, globo cromatico, comando, soffio del drago|\\n|5|Paura, volare|\\n|7|Occhio arcano, charme sui mostri|\\n|9|Conoscenza delle leggende, richiama drago|","page":85},"feature.sorcerer.draconic-sorcery.elemental-affinity":{"name":"Affinità elementale","description":"Grazie alla sua magia draconica, lo stregone ha affinità con un tipo di danno associato ai draghi e può sceglierne uno fra quelli seguenti: acido, freddo, fulmine, fuoco o veleno.\\n\\nLo stregone è dotato di resistenza al tipo di danno selezionato e, quando lancia un incantesimo di quell'elemento, può aggiungere il proprio modificatore di Carisma a un tiro per i danni per quell'incantesimo.","page":85},"feature.sorcerer.draconic-sorcery.dragon-wings":{"name":"Ali di drago","description":"Come azione bonus, lo stregone può far apparire delle ali draconiche sulla sua schiena per 1 ora o finché non le fa scomparire (nessuna azione richiesta). Per tutta la durata dell'abilità, il personaggio ha velocità di volo di 18 metri.\\n\\nDopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo; può ignorare questo limite spendendo 3 punti stregoneria (nessuna azione richiesta).","page":85},"class.warlock":{"name":"Warlock","page":85,"equipmentNotes":{"item.book":"scienze occulte"},"classSpecialFeatures":{"class.warlock.core-traits":{"name":"Tratti del warlock","description":"Come personaggio di 1º livello\\n\\n- Ottiene tutte le caratteristiche nella tabella Tratti del warlock.\\n- Ottiene i privilegi di 1º livello da warlock, elencati nella tabella Privilegi del warlock.\\n","multiclassDescription":"Come personaggio multiclasse\\n\\n- Ottiene i seguenti tratti dalla tabella Tratti del warlock: Dado Vita e competenza nelle armature leggere.\\n- Ottiene i privilegi di 1º livello da warlock, elencati nella tabella Privilegi del warlock. Per determinare il numero di slot incantesimo disponibili, vedi le regole multiclasse nel capitolo \\"Creazione del personaggio\\".\\n"},"class.warlock.subclass":{"name":"Sottoclasse del warlock","description":"Livello 3: Sottoclasse del warlock\\n\\nIl personaggio ottiene una sottoclasse del warlock a scelta. La descrizione della sottoclasse Patrono immondo segue quella di questa classe. Una sottoclasse è una specializzazione che conferisce dei privilegi a determinati livelli da warlock. Per il resto della sua carriera, il personaggio ottiene tutti i privilegi della sottoclasse pari al suo livello da warlock attuale o a quelli inferiori.\\n"},"class.warlock.ability-score-improvement-4":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da warlock.\\n"},"class.warlock.ability-score-improvement-8":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da warlock.\\n"},"class.warlock.ability-score-improvement-12":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da warlock.\\n"},"class.warlock.ability-score-improvement-16":{"name":"Aumento dei punteggi di caratteristica","description":"Livello 4: Aumento dei punteggi di caratteristica\\n\\nIl personaggio ottiene l'aumento dei punteggi di caratteristica (vedi capitolo \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. Questo privilegio si ottiene nuovamente all'8º, al 12º e al 16º livello da warlock.\\n"},"class.warlock.epic-boon":{"name":"Dono epico","description":"Livello 19: Dono epico\\n\\nIl personaggio ottiene un Dono epico (vedi \\"Talenti\\") o un altro talento a scelta di cui possiede i prerequisiti. È consigliato il Dono del fato."}}},"feature.warlock.pact-magic":{"name":"Magia del patto","description":"Attraverso una cerimonia occulta, il warlock ha stretto un patto con un'entità misteriosa al fine di ottenere dei poteri magici. Nonostante sia poco più di una voce nelle tenebre dall'identità sconosciuta, il suo dono è alquanto concreto: la capacità di lanciare incantesimi. Consulta il capitolo \\"Incantesimi\\" per le regole relative al lancio degli incantesimi. Le informazioni sottostanti spiegano come applicare tali regole agli incantesimi da warlock, elencati nella relativa lista degli incantesimi più avanti nella descrizione della classe.\\n\\n**Trucchetti.** Il warlock conosce due trucchetti a scelta. Sono consigliati deflagrazione occulta e prestidigitazione. Ogni volta che il personaggio ottiene un livello da warlock, può sostituire uno dei trucchetti di questo privilegio con un altro trucchetto a scelta.\\n\\nDopo aver raggiunto il 4º e il 10º livello da warlock, il personaggio apprende un altro trucchetto a scelta, come mostrato nella colonna Trucchetti della tabella Privilegi del warlock.\\n\\nSlot incantesimo. La tabella Privilegi del warlock mostra quanti slot incantesimo sono a disposizione del personaggio per lanciare incantesimi da warlock dal 1º al 5º livello. La tabella mostra anche il livello di tali slot (tutti dello stesso livello). Il warlock recupera tutti gli slot incantesimo della Magia del patto spesi quando completa un riposo breve o lungo.\\n\\nPer esempio, se il warlock è di 5º livello, possiede due slot incantesimo di 3º livello. Per lanciare l'incantesimo di 1º livello charme su persone, deve consumare uno di questi slot e lanciarlo come un incantesimo di 3º livello.\\n\\nIncantesimi preparati di 1º livello o superiore. Con questo privilegio, il personaggio prepara una lista di incantesimi di 1º livello o superiore che può lanciare. Per iniziare, sceglie due incantesimi da warlock di 1º livello. Sono consigliati charme su persone e sortilegio.\\n\\nIl numero di incantesimi nella lista aumenta man mano che il personaggio ottiene livelli da warlock, come mostrato nella colonna Incantesimi preparati della tabella Privilegi del warlock. Ogni volta che il numero cresce, il warlock deve scegliere altri incantesimi finché il numero sulla lista non combacia con quello mostrato nella tabella Privilegi del warlock. Ognuno di questi incantesimi deve appartenere a un livello pari o inferiore al livello dello slot relativo al livello attuale del personaggio e indicato nella sua tabella. Per esempio, quando il warlock raggiunge il 6º livello, ottiene un nuovo incantesimo di un livello dal 1º al 3º.\\n\\nSe un altro privilegio del warlock gli fornisce incantesimi che sono sempre preparati, questi non contano ai fini del numero di incantesimi preparabili con questo privilegio. Tuttavia, valgono comunque come incantesimi da warlock.\\n\\nCambiare gli incantesimi preparati. Ogni volta che il personaggio ottiene un livello da warlock, può sostituire un incantesimo della lista con un altro incantesimo da warlock di livello adeguato.\\n\\nCaratteristica da incantatore. La caratteristica da incantatore per gli incantesimi da warlock è il Carisma.\\n\\nFocus da incantatore. Un warlock può usare un focus arcano come focus da incantatore per i suoi incantesimi da warlock.","page":86},"feature.warlock.eldritch-invocations":{"name":"Suppliche occulte","description":"Il warlock ha scoperto le Suppliche occulte, ovvero frammenti di conoscenze proibite che gli conferiscono persistenti doti magiche o altre verità nascoste, tra cui la capacità di effettuare una supplica a scelta, come il Patto del Tomo. Per ulteriori dettagli sulle suppliche, consulta la sezione Opzioni di suppliche occulte dopo la descrizione di questa classe.\\n\\n**Prerequisiti.** Se una supplica ha un prerequisito, questo deve essere soddisfatto affinché venga appresa con successo. Per esempio, se la supplica richiede un warlock di 5º livello o superiore, è possibile farne uso solo una volta raggiunto il livello indicato.\\n\\nSostituire e ottenere suppliche. Ogni volta che il personaggio ottiene un livello da warlock, può sostituire una delle sue suppliche con un'altra di cui possiede i prerequisiti. Non è possibile sostituire una supplica che sia un prerequisito per un'altra supplica già in possesso del personaggio.\\n\\nQuando il warlock raggiunge livelli superiori, ottiene ulteriori suppliche a scelta, come indicato nella colonna Suppliche nella tabella Privilegi del warlock.\\n\\nNon è possibile scegliere una supplica più di una volta, salvo diversamente indicato.","page":85},"feature.warlock.magical-cunning":{"name":"Scaltrezza magica","description":"Il warlock può eseguire un rito esoterico per 1 minuto. Dopo che lo ha portato a termine, recupera gli slot incantesimo spesi di Magia del patto, ma non più di un numero pari a metà del loro massimo (arrotondando per eccesso). Dopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.","page":86},"feature.warlock.contact-patron":{"name":"Contatta patrono","description":"In passato, il warlock contattava il proprio patrono attraverso degli intermediari. Invece, ora è in grado di farlo in maniera diretta e ha l'incantesimo contattare altri piani sempre preparato. Con questo privilegio, il warlock può lanciare l'incantesimo senza consumare uno slot, in modo da contattare il patrono. Inoltre, supera automaticamente il relativo tiro salvezza.\\n\\nDopo aver lanciato l'incantesimo in questo modo, non può farlo di nuovo prima di aver completato un riposo lungo.","page":87},"feature.warlock.mystic-arcanum":{"name":"Arcanum mistico","description":"Il patrono del warlock gli rivela un segreto magico noto come arcanum. Tale arcanum è rappresentato da un incantesimo da warlock di 6º livello a scelta.\\n\\nIl warlock può lanciare l'arcanum una volta senza spendere alcuno slot incantesimo, ma deve completare un riposo lungo prima di poterlo lanciare nuovamente in questo modo.\\n\\nCome mostrato nella tabella Privilegi del warlock, il personaggio ottiene un altro incantesimo da warlock a scelta da lanciare in questo modo una volta raggiunti i livelli 13 (incantesimo di 7º livello), 15 (incantesimo di 8º livello) e 17 (incantesimo di 9º livello). Recupera tutti gli utilizzi del suo Arcanum mistico quando completa un riposo lungo.\\n\\nOgni volta che il personaggio ottiene un livello da warlock, è possibile sostituire uno degli incantesimi arcanum con un altro incantesimo da warlock dello stesso livello.","page":87},"feature.warlock.eldritch-master":{"name":"Maestro dell'occulto","description":"Quando il warlock usa il suo privilegio Scaltrezza magica, recupera tutti gli slot incantesimo spesi di Magia del patto.","page":88},"subclass.warlock.fiend-patron":{"name":"Patrono immondo","description":"Stringi un patto con i Piani Inferiori\\n\\nGrazie al patto stretto, il warlock attinge i suoi poteri dai Piani Inferiori, ovvero i regni della perdizione. Potrebbe aver stipulato un accordo con un signore dei demoni, un arcidiavolo o un altro immondo particolarmente potente. Il patrono ha obiettivi malvagi, come la corruzione o la distruzione di tutto (incluso il warlock stesso) e il percorso del personaggio sarà plasmato dalla misura in cui si batterà per sabotarli.","page":91},"feature.warlock.fiend-patron.dark-ones-blessing":{"name":"Benedizione dell'oscuro","description":"Quando il personaggio fa scendere un nemico a 0 punti ferita, ottiene una quantità di punti ferita temporanei pari al modificatore di Carisma più il proprio livello da warlock (minimo 1 punto ferita temporaneo). Questo beneficio viene ottenuto anche nel caso in cui un nemico entro 3 metri dal warlock sia ridotto a 0 punti ferita da qualcun altro.","page":91},"feature.warlock.fiend-patron.fiend-spells":{"name":"Incantesimi immondi","description":"La magia del patrono consente al warlock di avere sempre pronti determinati incantesimi. Una volta raggiunto un livello specificato nella tabella Incantesimi immondi, gli incantesimi lì elencati saranno sempre considerati come preparati.\\n\\n**Incantesimi immondi**\\n\\n|Livello da warlock|Incantesimi|\\n|---|---|\\n|3|Comando, mani brucianti, raggio rovente, suggestione|\\n|5|Nube maleodorante, palla di fuoco|\\n|7|Muro di fuoco, scudo di fuoco|\\n|9|Costrizione, piaga degli insetti|","page":92},"feature.warlock.fiend-patron.dark-ones-own-luck":{"name":"Fortuna dell'Oscuro","resourceNames":{"dark-ones-own-luck":"Fortuna dell'Oscuro"},"description":"Il warlock può appellarsi al proprio patrono immondo per alterare il fato in suo favore. Quando effettua una prova di caratteristica o un tiro salvezza, può utilizzare questo privilegio per aggiungere 1d10 al suo tiro. Può farlo dopo avere visto il tiro, ma prima che qualsiasi effetto del tiro sia applicato.\\n\\nQuesto privilegio è utilizzabile un numero di volte pari al modificatore di Carisma del personaggio (minimo una volta), ma non più di una volta per ogni tiro. Tutti gli utilizzi spesi vengono recuperati quando il personaggio completa un riposo lungo.","page":92},"feature.warlock.fiend-patron.fiendish-resilience":{"name":"Resilienza immonda","description":"Ogni volta che il personaggio completa un riposo breve o lungo, è possibile scegliere un tipo di danno (tranne forza). Così facendo, ottiene resistenza a quel tipo di danno finché non ne sceglie uno diverso tramite questo privilegio.","page":92},"feature.warlock.fiend-patron.hurl-through-hell":{"name":"Scagliare all'Inferno","description":"Una volta per turno, quando il warlock colpisce una creatura con un tiro per colpire, può tentare di trasferire istantaneamente il bersaglio nei Piani Inferiori. Quest'ultimo deve superare un tiro salvezza su Carisma contro la CD del tiro salvezza sull'incantesimo del personaggio, altrimenti scomparirà e piomberà in un luogo raccapricciante. Se il bersaglio non è un immondo, subisce 8d10 danni psichici ed è incapacitato fino alla fine del turno successivo del personaggio, quando tornerà nello spazio precedentemente occupato o in quello libero più vicino.\\n\\nDopo aver usato questo privilegio, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo; può ignorare questo limite spendendo uno slot incantesimo della Magia del patto (nessuna azione richiesta).","page":92},"feature.warlock.eldritch-invocations.armor-of-shadows":{"name":"Armatura delle ombre","description":"Il warlock può lanciare armatura magica su se stesso senza spendere uno slot incantesimo.","page":88},"feature.warlock.eldritch-invocations.otherworldly-leap":{"name":"Balzo ultraterreno","description":"*Prerequisito: warlock di 2º livello o superiore*\\n\\nIl warlock può lanciare saltare su se stesso senza spendere uno slot incantesimo.","page":88},"feature.warlock.eldritch-invocations.lessons-of-the-first-ones":{"name":"Conoscenze degli Antichi","description":"*Prerequisito: warlock di 2º livello o superiore*\\n\\nUn'antica entità ha conferito dei frammenti di conoscenza al warlock, consentendogli di ottenere un talento della categoria Origini a scelta (vedi capitolo \\"Talenti\\").\\n\\n**Ripetibile.** Questa supplica è ottenibile più di una volta. A ogni utilizzo, è necessario selezionare un talento diverso della categoria Origini.","page":88},"feature.warlock.eldritch-invocations.agonizing-blast":{"name":"Deflagrazione agonizzante","description":"*Prerequisito: warlock di 2º livello o superiore, un trucchetto da warlock che infligge danni*\\n\\nIl warlock sceglie uno dei suoi trucchetti che infligge danni e aggiunge il proprio modificatore di Carisma al tiro per i danni.\\n\\n**Ripetibile.** Questa supplica è ottenibile più di una volta. A ogni utilizzo, è necessario selezionare un trucchetto diverso che ne soddisfi i prerequisiti.","page":88},"feature.warlock.eldritch-invocations.repelling-blast":{"name":"Deflagrazione respingente","description":"*Prerequisito: warlock di 2º livello o superiore, un trucchetto da warlock che infligge danni con un tiro per colpire*\\n\\nIl warlock sceglie uno dei suoi trucchetti conosciuti che infligge danni e richiede un tiro per colpire. Quando colpisce una creatura di taglia Grande o inferiore con quel trucchetto, può spingerla via di un massimo di 3 metri lontano da sé.\\n\\n**Ripetibile.** Questa supplica è ottenibile più di una volta. A ogni utilizzo, è necessario selezionare un trucchetto diverso che ne soddisfi i prerequisiti.","page":88},"feature.warlock.eldritch-invocations.gift-of-the-depths":{"name":"Dono degli abissi","description":"*Prerequisito: warlock di 5º livello o superiore*\\n\\nIl warlock può respirare sott'acqua e ottenere una velocità di nuoto pari alla sua velocità.\\n\\nInoltre, può lanciare respirare sott'acqua senza consumare uno slot incantesimo. Per riutilizzare tale abilità in questo modo è necessario completare un riposo lungo.","page":88},"feature.warlock.eldritch-invocations.gift-of-the-protectors":{"name":"Dono del protettore","description":"*Prerequisito: warlock di 9º livello o superiore, supplica del Patto del tomo*\\n\\nQuando il warlock evoca il Libro delle Ombre, al suo interno appare una nuova pagina. Con il suo permesso, una creatura può usare un'azione per scrivere il proprio nome su tale pagina, che può contenere tanti nomi quanto il modificatore di Carisma del warlock (minimo un nome).\\n\\nQuando una qualsiasi creatura il cui nome è sulla pagina si ritrova con 0 punti ferita, ma ancora in vita, questa passa magicamente a 1 punto ferita invece di 0. Una volta innescata la magia, nessun'altra creatura può trarne beneficio finché il warlock non completa un riposo lungo.\\n\\nCome azione di Magia, il warlock può cancellare magicamente un nome dalla pagina toccandolo.","page":88},"feature.warlock.eldritch-invocations.investment-of-the-chain-master":{"name":"Investitura del Signore delle Catene","description":"*Prerequisito: Warlock di 5º livello o superiore, supplica del Patto della catena*\\n\\nQuando il warlock lancia trova famiglio, infonde il famiglio evocato con parte del proprio potere occulto, conferendo alla creatura i seguenti benefici.\\n\\nVolo o nuoto. Il famiglio ottiene una velocità di volo o una velocità di nuoto (a scelta del warlock) di 12 metri.\\n\\nAttacco rapido. Come azione bonus, il warlock può ordinare al famiglio di effettuare l'azione di Attacco.\\n\\nDanni necrotici o radiosi. Quando il famiglio infligge danni contundenti, perforanti o taglienti, è possibile trasformarli in danni necrotici o radiosi.\\n\\nCD tiro salvezza dell'incantesimo del warlock. Se il famiglio costringe una creatura a effettuare un tiro salvezza, questo usa la CD del tiro salvezza dell'incantesimo del warlock.\\n\\n**Resistenza.** Quando il famiglio subisce danni, il warlock può usare la sua reazione per conferirgli resistenza contro quel danno.","page":88},"feature.warlock.eldritch-invocations.thirsting-blade":{"name":"Lama assetata","description":"*Prerequisito: warlock di 5º livello o superiore, supplica del Patto della lama*\\n\\nIl warlock ottiene il privilegio Attacco extra solo per l'arma del patto. Questo consente all'incantatore di attaccare due volte invece di una quando usa quell'arma ed effettua l'azione di Attacco nel proprio turno.","page":89},"feature.warlock.eldritch-invocations.devouring-blade":{"name":"Lama divoratrice","description":"*Prerequisito: warlock di 12º livello o superiore, supplica Lama assetata*\\n\\nL'Attacco extra della supplica Lama assetata consente di eseguire due attacchi aggiuntivi anziché uno.","page":89},"feature.warlock.eldritch-invocations.eldritch-spear":{"name":"Lancia occulta","description":"*Prerequisito: warlock di 2º livello o superiore, un trucchetto da warlock che infligge danni*\\n\\nIl warlock sceglie uno dei suoi trucchetti che infligge danni e ha una gittata di 3 metri o superiore. Quando l'incantesimo viene lanciato, la sua gittata aumenta di 9 metri per ogni livello da warlock.\\n\\n**Ripetibile.** Questa supplica è ottenibile più di una volta. A ogni utilizzo, è necessario selezionare un trucchetto diverso che ne soddisfi i prerequisiti.","page":89},"feature.warlock.eldritch-invocations.master-of-myriad-forms":{"name":"Maestro di mille forme","description":"*Prerequisito: warlock di 5º livello o superiore*\\n\\nIl warlock può lanciare alterare se stesso senza spendere uno slot incantesimo.","page":89},"feature.warlock.eldritch-invocations.mask-of-many-faces":{"name":"Maschera dei molti volti","description":"*Prerequisito: warlock di 2º livello o superiore*\\n\\nIl warlock può lanciare camuffare se stesso senza spendere uno slot incantesimo.","page":89},"feature.warlock.eldritch-invocations.eldritch-mind":{"name":"Mente occulta","description":"Il warlock dispone di vantaggio ai tiri salvezza su Costituzione per mantenere la concentrazione.","page":89},"feature.warlock.eldritch-invocations.ascendant-step":{"name":"Passo ascendente","description":"*Prerequisito: warlock di 5º livello o superiore*\\n\\nIl warlock può lanciare levitazione su se stesso senza spendere uno slot incantesimo.","page":89},"feature.warlock.eldritch-invocations.pact-of-the-chain":{"name":"Patto della catena","description":"Il warlock impara l'incantesimo trova famiglio e può lanciarlo come azione di Magia senza spendere uno slot incantesimo.\\n\\nQuando il warlock lancia l'incantesimo, può scegliere per il suo famiglio una delle forme normali o una di quelle speciali seguenti: imp, pseudodrago, quasit, scheletro, sfinge della meraviglia, spiritello o serpente velenoso (vedi l'appendice \\"Mostri\\" per la scheda delle statistiche del famiglio).\\n\\nInoltre, quando effettua l'azione di Attacco, il warlock può rinunciare a uno dei suoi attacchi per consentire al famiglio di effettuare un attacco individuale con la sua reazione.","page":89},"feature.warlock.eldritch-invocations.pact-of-the-blade":{"name":"Patto della lama","description":"Come azione bonus, il warlock può evocare un'arma del patto nella propria mano: un'arma da mischia semplice o da guerra a scelta con cui ha un legame. In alternativa, può crearne uno con un'arma magica che tocca. Non è possibile stabilire un legame con un'arma magica con cui qualcun altro è in sintonia o già legata a un altro warlock. Fino al termine del legame, il personaggio ha competenza nell'arma e può usarla come focus da incantatore.\\n\\nOgni volta che attacca con l'arma con cui ha un legame, al posto di Forza o Destrezza il warlock può usare il suo modificatore di Carisma per i tiri per colpire e per i danni. Inoltre, può far sì che infligga danni necrotici, psichici, radiosi o normali (a seconda della tipologia dell'arma).\\n\\nIl legame termina una volta riutilizzato il privilegio come azione bonus, quando l'arma è a più di 1,5 metri da sé per più di un minuto o se il personaggio muore. Un'arma evocata sparisce all'interruzione del legame.","page":89},"feature.warlock.eldritch-invocations.pact-of-the-tome":{"name":"Patto del tomo","description":"Mettendo insieme dei brandelli di tenebra, il warlock è in grado di evocare un libro nelle proprie mani dopo aver completato un riposo breve o lungo. Questo Libro delle Ombre (di cui puoi scegliere l'aspetto) contiene magia occulta accessibile solo al warlock e conferisce i benefici sottostanti. Se questo privilegio viene usato per evocare un altro libro o se il warlock muore, il libro sparisce.\\n\\nTrucchetti e rituali. Quando il libro appare, il warlock sceglie tre trucchetti e due incantesimi di 1º livello con il descrittore rituale. Gli incantesimi possono provenire dalla relativa lista di qualunque classe e devono essere incantesimi che il personaggio non ha già preparato. Finché il libro rimarrà con il warlock, gli incantesimi scelti sono considerati come preparati e valgono come incantesimi da warlock.\\n\\nFocus da incantatore. Il warlock può usare il libro come focus da incantatore.","page":89},"feature.warlock.eldritch-invocations.eldritch-smite":{"name":"Punizione occulta","description":"*Prerequisito: warlock di 5º livello o superiore, supplica del Patto della lama*\\n\\nUna volta per turno, quando il warlock colpisce una creatura con l'arma del patto, può spendere uno slot incantesimo della Magia del patto per infliggere 1d8 danni da forza extra al bersaglio, più 1d8 aggiuntivo per ogni livello dello slot. Inoltre, se l'avversario è di taglia Enorme o inferiore, diventa prono.","page":89},"feature.warlock.eldritch-invocations.gaze-of-two-minds":{"name":"Sguardo delle due menti","description":"*Prerequisito: warlock di 5º livello o superiore*\\n\\nCome azione bonus, il warlock può toccare una creatura consenziente e percepire il mondo attraverso i suoi sensi fino alla fine del proprio turno successivo. Finché la creatura si trova sullo stesso piano di esistenza del warlock, quest'ultimo può usare un'azione bonus nei turni successivi per mantenere il legame, estendendone la durata fino alla fine del suo turno successivo. In caso contrario, il legame si interrompe.\\n\\nMentre il warlock utilizza i sensi dell'altra creatura per percepire ciò che lo circonda, può anche trarre beneficio da qualsiasi senso speciale che possiede. Inoltre, se si trova entro 18 metri da tale creatura, può lanciare incantesimi come se si trovasse nel proprio spazio o in quello della creatura.","page":89},"feature.warlock.eldritch-invocations.lifedrinker":{"name":"Succhiavita","description":"*Prerequisito: Warlock di 9º livello o superiore, supplica del Patto della lama*\\n\\nUna volta per turno, quando il warlock colpisce una creatura con l'arma del patto, può infliggerle 1d6 danni extra di tipo necrotico, psichico o radioso (a scelta). Inoltre, può consumare uno dei suoi Dadi Vita per tirarlo e recuperare un numero di punti ferita pari al risultato ottenuto, più il modificatore di Costituzione (minimo 1 punto ferita).","page":90},"feature.warlock.eldritch-invocations.whispers-of-the-grave":{"name":"Sussurri dalla tomba","description":"*Prerequisito: warlock di 7º livello o superiore*\\n\\nIl warlock può lanciare parlare con i morti senza spendere uno slot incantesimo.","page":90},"feature.warlock.eldritch-invocations.one-with-shadows":{"name":"Tutt'uno con le ombre","description":"*Prerequisito: warlock di 5º livello o superiore*\\n\\nMentre il warlock è in un'area di oscurità o luce fioca, può lanciare invisibilità su di sé senza spendere uno slot incantesimo.","page":90},"feature.warlock.eldritch-invocations.fiendish-vigor":{"name":"Vigore immondo","description":"*Prerequisito: warlock di 2º livello o superiore*\\n\\nIl warlock può lanciare vita falsata su se stesso senza spendere uno slot incantesimo. Quando l'incantesimo viene lanciato con questo privilegio, non è necessario effettuare il tiro per i punti ferita temporanei, poiché si ottiene in automatico il numero massimo possibile.","page":90},"feature.warlock.eldritch-invocations.visions-of-distant-realms":{"name":"Visione dei Reami Lontani","description":"*Prerequisito: warlock di 9º livello o superiore*\\n\\nIl warlock può lanciare occhio arcano senza spendere uno slot incantesimo.","page":90},"feature.warlock.eldritch-invocations.misty-visions":{"name":"Visioni velate","description":"*Prerequisito: warlock di 2º livello o superiore*\\n\\nIl warlock può lanciare immagine silenziosa senza spendere uno slot incantesimo.","page":90},"feature.warlock.eldritch-invocations.devils-sight":{"name":"Vista del diavolo","description":"*Prerequisito: warlock di 2º livello o superiore*\\n\\nIl warlock può vedere normalmente con luce fioca e oscurità (sia di natura magica che non magica) entro 36 metri da sé.","page":90},"feature.warlock.eldritch-invocations.witch-sight":{"name":"Vista stregata","description":"*Prerequisito: warlock di 15º livello o superiore*\\n\\nIl warlock ottiene vista pura con un raggio di 9 metri.","page":90},"feature.sorcerer.metamagic.distant-spell":{"name":"Incantesimo distante","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone lancia un incantesimo che ha una gittata pari o superiore a 1,5 metri, può spendere 1 punto stregoneria per raddoppiarla. Se invece lancia un incantesimo che ha una gittata a contatto, può spendere 1 punto stregoneria per aumentarla a 9 metri.","page":81},"feature.sorcerer.metamagic.extended-spell":{"name":"Incantesimo esteso","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone lancia un incantesimo di durata pari o superiore a 1 minuto, può spendere 1 punto stregoneria per raddoppiarla fino a un massimo di 24 ore.\\n\\nSe l'incantesimo interessato richiede concentrazione, il personaggio dispone di vantaggio a ogni tiro salvezza effettuato per mantenere la concentrazione.","page":82},"feature.sorcerer.metamagic.heightened-spell":{"name":"Incantesimo intensificato","description":"*Costo: 2 punti stregoneria*\\n\\nQuando lo stregone lancia un incantesimo che obbliga una creatura a effettuare un tiro salvezza, può spendere 2 punti stregoneria per infliggere svantaggio a un bersaglio dell'incantesimo sui tiri salvezza contro di esso.","page":82},"feature.sorcerer.metamagic.seeking-spell":{"name":"Incantesimo mirato","description":"*Costo: 1 punto stregoneria*\\n\\nSe lo stregone effettua un tiro per colpire per un incantesimo e fallisce, può spendere 1 punto stregoneria per tirare nuovamente il d20 e deve usare il nuovo risultato.\\n\\nLo stregone può utilizzare Incantesimo mirato anche se ha già utilizzato un'opzione diversa di Metamagia durante il lancio dell'incantesimo.","page":82},"feature.sorcerer.metamagic.empowered-spell":{"name":"Incantesimo potenziato","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone tira per i danni di un incantesimo, può spendere 1 punto stregoneria per ripetere il tiro di un numero massimo di dadi pari al suo modificatore di Carisma (minimo di uno), e deve usare i nuovi risultati.\\n\\nLo stregone può utilizzare Incantesimo potenziato anche se ha già utilizzato un'opzione diversa di Metamagia durante il lancio dell'incantesimo.","page":82},"feature.sorcerer.metamagic.careful-spell":{"name":"Incantesimo preciso","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone lancia un incantesimo che obbliga altre creature a effettuare un tiro salvezza, può proteggere alcune di esse dalla piena forza dell'incantesimo. Per farlo, spende 1 punto stregoneria e sceglie un numero massimo di creature pari al suo modificatore di Carisma (minimo una creatura). Le creature scelte superano automaticamente i loro tiri salvezza contro l'incantesimo e non subiscono alcun danno se normalmente subirebbero la metà dei danni in caso di tiro salvezza superato.","page":82},"feature.sorcerer.metamagic.twinned-spell":{"name":"Incantesimo raddoppiato","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone produce un incantesimo lanciabile consumando uno slot di livello superiore per colpire un bersaglio aggiuntivo, come charme su persone, può spendere 1 punto stregoneria per aumentarne il livello effettivo di 1.","page":82},"feature.sorcerer.metamagic.quickened-spell":{"name":"Incantesimo rapido","description":"*Costo: 2 punti stregoneria*\\n\\nQuando lo stregone lancia un incantesimo che ha un tempo di lancio di 1 azione, può spendere 2 punti stregoneria per cambiarlo a 1 azione bonus per quel lancio. Non è possibile eseguire questa modifica se il personaggio ha già lanciato un incantesimo di 1º livello o superiore nel turno attuale, così come non si può lanciare un incantesimo di 1º livello o superiore in questo turno dopo aver modificato l'incantesimo come indicato sopra.","page":82},"feature.sorcerer.metamagic.transmuted-spell":{"name":"Incantesimo trasmutato","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone lancia un incantesimo che infligge un tipo di danno presente nella lista seguente, può spendere 1 punto stregoneria per cambiare il tipo di danno in un altro della lista: acido, freddo, fulmine, fuoco, tuono, veleno.","page":82},"feature.cleric.divine-order.protector":{"name":"Protettore","description":"Addestrato a combattere, il chierico ha acquisito competenza con le armi da guerra e con le armature pesanti.","page":41},"feature.cleric.divine-order.thaumaturge":{"name":"Taumaturgo","description":"Il chierico conosce un trucchetto extra dalla lista degli incantesimi da chierico. Inoltre, la connessione mistica con il divino gli conferisce un bonus alle prove di Intelligenza (Arcano o Religione). Il bonus è pari al suo modificatore di Saggezza (minimo di +1).","page":42},"feature.cleric.blessed-strikes.divine-strike":{"name":"Colpo divino","description":"Una volta per ogni suo turno, quando il chierico colpisce una creatura con un tiro per colpire usando un'arma, può far sì che il bersaglio subisca 1d8 danni necrotici o radiosi extra (a scelta).","page":43},"feature.cleric.blessed-strikes.potent-spellcasting":{"name":"Incantesimi potenti","description":"Il personaggio aggiunge il suo modificatore di Saggezza al danno che infligge con qualsiasi trucchetto da chierico.","page":43},"feature.druid.primal-order.warden":{"name":"Custode","description":"Addestrato a combattere, il druido ha acquisito competenza con le armi da guerra e con le armature medie.","page":48},"feature.druid.primal-order.magician":{"name":"Mago","description":"Il druido conosce un trucchetto extra dalla lista degli incantesimi da druido. Inoltre, la connessione mistica con la natura gli conferisce un bonus alle prove di Intelligenza (Arcano o Natura). Il bonus è pari al suo modificatore di Saggezza (bonus minimo di +1).","page":48},"feature.druid.elemental-fury.potent-spellcasting":{"name":"Incantesimi potenti","description":"Il personaggio aggiunge il suo modificatore di Saggezza al danno che infligge con qualsiasi trucchetto da druido.","page":49},"feature.druid.elemental-fury.primal-strike":{"name":"Colpo primordiale","description":"Una volta per ogni suo turno, quando il druido colpisce una creatura con un tiro per colpire usando un'arma o un attacco della forma bestiale in Forma selvatica, può far sì che il bersaglio subisca 1d8 danni da freddo, fuoco, fulmine o tuono extra (a scelta).","page":49},"feature.ranger.fighting-style.druidic-warrior":{"name":"Guerriero druidico","description":"Il ranger apprende due trucchetti da druido a scelta (vedi la sezione della classe del druido per una lista dei relativi incantesimi). Sono consigliati guida e luce splendente. I trucchetti scelti valgono come incantesimi da ranger e la caratteristica da incantatore per usarli è Saggezza. Ogni volta che il personaggio ottiene un livello da ranger, può sostituire uno dei trucchetti con un altro trucchetto da druido.","page":76},"feature.ranger.hunter.defensive-tactics.escape-the-horde":{"name":"Sfuggire all'orda","description":"Gli attacchi di opportunità effettuati contro il personaggio subiscono svantaggio.","page":78},"feature.ranger.hunter.defensive-tactics.multiattack-defense":{"name":"Difesa dal multiattacco","description":"Se una creatura colpisce il ranger con un tiro per colpire subirà svantaggio a tutti gli altri tiri per colpire effettuati contro il ranger durante il turno.","page":78},"feature.ranger.hunter.hunters-prey.colossus-slayer":{"name":"Sterminatore di colossi","description":"La tenacia del ranger scoraggia anche i nemici più resilienti. Quando colpisce una creatura con un'arma, questa infligge 1d8 danni aggiuntivi al bersaglio se gli mancano dei punti ferita. Può infliggere questi danni extra solo una volta per turno.","page":78},"feature.ranger.hunter.hunters-prey.horde-breaker":{"name":"Devastatore dell'orda","description":"Una volta per turno quando il ranger effettua un attacco con un'arma, può sferrare un altro attacco con la stessa arma contro una creatura diversa che sia entro 1,5 metri dal bersaglio originale e a portata dell'arma, e che non abbia già attaccato nel corso del turno corrente.","page":78},"feature.sorcerer.draconic-sorcery.dragon-companion":{"name":"Seguace draconico","description":"Lo stregone può lanciare richiama drago senza usare una componente materiale. Inoltre, può anche lanciarlo una volta senza consumare uno slot incantesimo e recupera l'abilità di lanciarlo in questo modo dopo aver completato un riposo lungo.\\n\\nOgni volta che lo stregone lancia l'incantesimo, può modificarlo in modo che non richieda concentrazione. Così facendo, per quel lancio la durata dell'incantesimo diventa di 1 minuto.","page":85},"feature.druid.circle-of-the-land.spell-list.arid":{"name":"Terra arida","description":"**Terra arida**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Dardo di fuoco, mani brucianti, sfocatura|\\n|5|Palla di fuoco|\\n|7|Inaridire|\\n|9|Muro di pietra|","page":52},"feature.druid.circle-of-the-land.spell-list.polar":{"name":"Terra polare","description":"**Terra polare**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Blocca persone, nube di nebbia, raggio di gelo|\\n|5|Tempesta di nevischio|\\n|7|Tempesta di ghiaccio|\\n|9|Cono di freddo|","page":52},"feature.druid.circle-of-the-land.spell-list.temperate":{"name":"Terra temperata","description":"**Terra temperata**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Passo velato, sonno e stretta folgorante|\\n|5|Fulmine|\\n|7|Libertà di movimento|\\n|9|Traslazione arborea|","page":52},"feature.druid.circle-of-the-land.spell-list.tropical":{"name":"Terra tropicale","description":"**Terra tropicale**\\n\\n|Livello da druido|Incantesimi del Circolo|\\n|---|---|\\n|3|Fiotto acido, raggio di infermità, ragnatela|\\n|5|Nube maleodorante|\\n|7|Metamorfosi|\\n|9|Piaga degli insetti|","page":52},"feature.sorcerer.metamagic.subtle-spell":{"name":"Incantesimo celato","description":"*Costo: 1 punto stregoneria*\\n\\nQuando lo stregone lancia un incantesimo, può spendere 1 punto stregoneria per farlo senza utilizzare componenti verbali, somatiche o materiali, fatta eccezione per le componenti materiali consumate dall'incantesimo o il cui costo è specificato nella sua descrizione.","page":81},"feature.paladin.fighting-style.blessed-warrior":{"name":"Guerriero benedetto","description":"Il paladino impara due trucchetti da chierico a scelta (consulta la sezione della classe del chierico per una lista dei suoi incantesimi). Sono consigliati guida e fiamma sacra. I trucchetti scelti valgono come incantesimi da paladino e la caratteristica da incantatore per usarli è Carisma. Ogni volta che il personaggio ottiene un livello da paladino, puoi sostituire uno dei trucchetti con un altro trucchetto da chierico.","page":71},"feat.magic-initiate":{"name":"Iniziato alla magia","description":"Il personaggio ottiene i seguenti benefici. Due trucchetti. Il personaggio apprende due trucchetti a scelta tratti dalla lista degli incantesimi da chierico, druido o mago. La caratteristica da incantatore per gli incantesimi di questo talento può essere Intelligenza, Saggezza o Carisma (scegli la caratteristica quando ottieni questo talento).\\n\\nIncantesimo di 1º livello. Scegli un incantesimo di 1º livello dalla stessa lista da cui hai selezionato i trucchetti forniti da questo talento. Tale incantesimo è sempre considerato come preparato. Il personaggio può lanciarlo una volta senza consumare uno slot incantesimo e ne recupera l'utilizzo in questo modo dopo aver completato un riposo lungo. Può anche lanciare l'incantesimo usando uno qualsiasi degli slot incantesimo a sua disposizione.\\n\\nCambio incantesimo. Quando il personaggio ottiene un nuovo livello, puoi sostituire uno degli incantesimi scelti per questo talento con un altro dello stesso livello dalla lista prescelta.\\n\\n**Ripetibile.** Questo talento è ottenibile più di una volta, ma devi scegliere una lista degli incantesimi diversa a ogni selezione.","page":98},"feat.alert":{"name":"Allerta","description":"Il personaggio ottiene i seguenti benefici. Competenza in iniziativa. Quando tiri per l'iniziativa, puoi aggiungere il bonus di competenza del personaggio al risultato del tiro.\\n\\nScambio di iniziativa. Subito dopo aver tirato per l'iniziativa, puoi scambiare il risultato ottenuto con quello di un alleato consenziente durante il medesimo combattimento. Se il tuo personaggio o il suo alleato è incapacitato, non è possibile eseguire lo scambio.","page":98},"feat.savage-attacker":{"name":"Aggressore selvaggio","description":"Il personaggio si è allenato per sferrare colpi particolarmente letali. Una volta per turno, quando colpisce un bersaglio con un'arma, puoi tirare due volte per i danni dell'arma e scegliere il risultato che preferisci.","page":98},"feat.skilled":{"name":"Abile","description":"Il personaggio ottiene competenza in una combinazione di tre abilità o strumenti a scelta.\\n\\n**Ripetibile.** Questo talento è ottenibile più di una volta.","page":98},"feat.ability-score-improvement":{"name":"Aumento dei punteggi di caratteristica","description":"Aumenta un punteggio di caratteristica a sua scelta di 2, oppure aumenta due punteggi di caratteristica di 1. Questo talento non può incrementare un punteggio di caratteristica oltre il 20.\\n\\n**Ripetibile.** Questo talento è ottenibile più di una volta.","page":98},"feat.grappler":{"name":"Lottatore","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica. Il suo punteggio di Forza o Destrezza aumenta di 1, fino a un massimo di 20.\\n\\nColpisci e afferra. Quando il personaggio colpisce una creatura con un colpo senz'armi come parte di un'azione di Attacco nel proprio turno, può usare sia l'opzione Danni che Presa. Questo beneficio è utilizzabile una sola volta per turno.\\n\\nAttacco con vantaggio. Dispone di vantaggio ai tiri per colpire contro le creature che ha afferrato.\\n\\nLottatore rapido. Il personaggio non deve spendere alcun movimento extra se sposta una creatura che ha afferrato che sia della sua stessa categoria di taglia o inferiore.","page":98},"feat.archery":{"name":"Tiro","description":"Il personaggio ottiene un bonus di +2 ai tiri per colpire che effettua con le armi a distanza.","page":99},"feat.defense":{"name":"Difesa","description":"Finché il personaggio indossa un'armatura leggera, media o pesante, ottiene un +1 alla Classe Armatura.","page":99},"feat.great-weapon-fighting":{"name":"Combattere con armi possenti","description":"Quando tiri per i danni per un attacco effettuato con un'arma da mischia che il personaggio impugna a due mani, se il risultato ottenuto è 1 o 2, puoi invece considerarlo come un 3. L'arma deve possedere la proprietà a due mani o versatile affinché ottenga questo beneficio.","page":99},"feat.two-weapon-fighting":{"name":"Combattere con due armi","description":"Quando il personaggio effettua un attacco extra come risultato dell'uso di un'arma leggera, puoi aggiungere il suo modificatore di caratteristica al danno di quell'attacco a patto che non sia già stato aggiunto in altro modo.","page":99},"feat.boon-of-irresistible-offense":{"name":"Dono dell'offensiva irresistibile","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica. Il suo punteggio di Forza o Destrezza aumenta di 1, fino a un massimo di 30.\\n\\nIgnora difese. I danni contundenti, perforanti e taglienti inflitti dal personaggio ignorano sempre la resistenza.\\n\\nColpo soverchiante. Quando tira per colpire con il d20 e ottiene un 20, il personaggio può infliggere una quantità di danni extra al bersaglio pari al punteggio di caratteristica incrementato da questo talento. Il danno aggiuntivo è dello stesso tipo di quello dell'attacco.","page":99},"feat.boon-of-combat-prowess":{"name":"Dono delle abilità di combattimento","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica.\\n\\nIl punteggio di una sua caratteristica a scelta aumenta di 1, fino a un massimo di 30.\\n\\nMira impareggiabile. Quando il tiro per colpire del personaggio non va a segno, è possibile colpire comunque il bersaglio. Una volta sfruttato questo beneficio, non può essere riutilizzato fino all'inizio del turno successivo del personaggio.","page":99},"feat.boon-of-fate":{"name":"Dono del fato","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica.\\n\\nIl punteggio di una sua caratteristica a scelta aumenta di 1, fino a un massimo di 30.\\n\\nFato migliorato. Quando il personaggio o un'altra creatura entro 18 metri da sé supera o fallisce una prova con d20, può tirare 2d4 e applicare il risultato ottenuto come bonus o penalità a tale prova con d20. Una volta utilizzato questo beneficio, non può più utilizzarlo finché non tira per l'iniziativa o non completa un riposo breve o lungo.","page":99},"feat.boon-of-the-night-spirit":{"name":"Dono dello spirito notturno","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica.\\n\\nIl punteggio di una sua caratteristica a scelta aumenta di 1, fino a un massimo di 30.\\n\\nFusione con le ombre. Finché si trova in un'area di oscurità o luce fioca, può diventare invisibile come azione bonus. Tale condizione termina subito dopo che il personaggio effettua un'azione, un'azione bonus o una reazione.\\n\\nForma d'ombra. Finché si trova in un'area di oscurità o luce fioca, ha resistenza a tutti i tipi di danno, tranne quelli psichici e radiosi.","page":99},"feat.boon-of-dimensional-travel":{"name":"Dono del viaggio dimensionale","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica.\\n\\nIl punteggio di una sua caratteristica a scelta aumenta di 1, fino a un massimo di 30.\\n\\nPassi fulminei. Subito dopo che il personaggio effettua un'azione di Attacco o Magia, può teletrasportarsi di massimo 9 metri in uno spazio libero che è in grado di vedere.","page":100},"feat.boon-of-spell-recall":{"name":"Dono del richiamo degli incantesimi","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica. Il suo punteggio di Intelligenza, Saggezza o Carisma aumenta di 1, fino a un massimo di 30.\\n\\nLancio libero. Quando lancia un incantesimo con uno slot di livello da 1 a 4, tira 1d4. Se il risultato corrisponde al livello dello slot, questo non verrà consumato.","page":100},"feat.boon-of-truesight":{"name":"Dono della vista pura","description":"Il personaggio ottiene i seguenti benefici. Incremento dei punteggi di caratteristica.\\n\\nIl punteggio di una sua caratteristica a scelta aumenta di 1, fino a un massimo di 30.\\n\\nVista pura. Il personaggio ottiene vista pura con un raggio di 18 metri.","page":99},"item.handaxe":{"name":"Ascia"},"item.quarterstaff":{"name":"Bastone ferrato"},"item.sickle":{"name":"Falcetto"},"item.javelin":{"name":"Giavellotto"},"item.spear":{"name":"Lancia"},"item.light-hammer":{"name":"Martello leggero"},"item.mace":{"name":"Mazza"},"item.dagger":{"name":"Pugnale"},"item.greatclub":{"name":"Randello pesante"},"item.club":{"name":"Randello"},"item.shortbow":{"name":"Arco corto"},"item.light-crossbow":{"name":"Balestra leggera"},"item.dart":{"name":"Dardo"},"item.sling":{"name":"Fionda"},"item.halberd":{"name":"Alabarda"},"item.greataxe":{"name":"Ascia bipenne"},"item.battleaxe":{"name":"Ascia da battaglia"},"item.glaive":{"name":"Falcione"},"item.whip":{"name":"Frusta"},"item.lance":{"name":"Lancia da cavaliere"},"item.maul":{"name":"Maglio"},"item.warhammer":{"name":"Martello da guerra"},"item.morningstar":{"name":"Mazza chiodata"},"item.flail":{"name":"Mazzafrusto"},"item.pike":{"name":"Picca"},"item.war-pick":{"name":"Piccone da guerra"},"item.scimitar":{"name":"Scimitarra"},"item.shortsword":{"name":"Spada corta"},"item.longsword":{"name":"Spada lunga"},"item.greatsword":{"name":"Spadone"},"item.rapier":{"name":"Stocco"},"item.trident":{"name":"Tridente"},"item.longbow":{"name":"Arco lungo"},"item.hand-crossbow":{"name":"Balestra a mano"},"item.heavy-crossbow":{"name":"Balestra pesante"},"item.blowgun":{"name":"Cerbottana"},"item.musket":{"name":"Moschetto"},"item.pistol":{"name":"Pistola"},"item.padded-armor":{"name":"Armatura imbottita"},"item.leather-armor":{"name":"Armatura di cuoio"},"item.studded-leather-armor":{"name":"Armatura di cuoio borchiato"},"item.hide-armor":{"name":"Armatura di pelle"},"item.chain-shirt":{"name":"Giaco di maglia"},"item.scale-mail":{"name":"Corazza a scaglie"},"item.breastplate":{"name":"Corazza di piastre"},"item.half-plate-armor":{"name":"Mezza armatura"},"item.ring-mail":{"name":"Corazza ad anelli"},"item.chain-mail":{"name":"Cotta di maglia"},"item.splint-armor":{"name":"Corazza a strisce"},"item.plate-armor":{"name":"Armatura a piastre"},"item.shield":{"name":"Scudo"},"item.alchemists-supplies":{"name":"Scorte da alchimista","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** identificare una sostanza (CD 15) o appiccare il fuoco (CD 15)\\n\\n**Creazione:** acido, fuoco dell'alchimista, borsa per componenti, olio, carta, profumo"},"item.brewers-supplies":{"name":"Scorte da birraio","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** individuare una bevanda avvelenata (CD 15) o identificare alcolici (CD 10)\\n\\n**Creazione:** antitossina"},"item.calligraphers-supplies":{"name":"Scorte da calligrafo","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** scrivere testi usando una calligrafia articolata per impedirne la riproduzione (CD 15)\\n\\n**Creazione:** inchiostro, *pergamena magica*"},"item.cobblers-tools":{"name":"Strumenti da calzolaio","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** modificare calzature per conferire vantaggio alla prossima prova di Destrezza (Acrobazia) di chi le indossa (CD 10)\\n\\n**Creazione:** attrezzi da scalatore"},"item.cartographers-tools":{"name":"Strumenti da cartografo","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** disegnare una mappa di una piccola area (CD 15)\\n\\n**Creazione:** mappa"},"item.leatherworkers-tools":{"name":"Strumenti da conciatore","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** aggiungere un motivo a un oggetto di cuoio (CD 10)\\n\\n**Creazione:** fionda, frusta, armatura di pelle, armatura di cuoio, armatura di cuoio borchiato, zaino, custodia per quadrelli da balestra, custodia per mappe o pergamene, pergamena, borsa, faretra, otre"},"item.smiths-tools":{"name":"Strumenti da fabbro","description":"**Caratteristica:** Forza\\n\\n**Utilizzo:** forzare l'apertura di una porta o un contenitore (CD 20)\\n\\n**Creazione:** Arma da mischia (eccetto randello, randello pesante, bastone ferrato e frusta), armatura media (eccetto di pelle), armatura pesante, sfere metalliche, secchio, triboli, catena, piede di porco, proiettili per armi da fuoco, rampino, pentola di ferro, spuntoni di ferro, proiettili da fionda"},"item.carpenters-tools":{"name":"Strumenti da falegname","description":"**Caratteristica:** Forza\\n\\n**Utilizzo:** sigillare o forzare l'apertura di una porta o un contenitore (CD 20)\\n\\n**Creazione:** randello, randello pesante, bastone ferrato, barile, forziere, scala a pioli, asta, ariete portatile, torcia"},"item.jewelers-tools":{"name":"Strumenti da gioielliere","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** determinare il valore di una gemma (CD 15)\\n\\n**Creazione:** focus arcano, simbolo sacro"},"item.woodcarvers-tools":{"name":"Strumenti da intagliatore","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** intagliare un motivo nel legno (CD 10)\\n\\n**Creazione:** randello, randello pesante, bastone ferrato, armi a distanza (eccetto pistola, moschetto e fionda), focus arcano, frecce, quadrelli, focus druidico, pennino, aghi"},"item.tinkers-tools":{"name":"Strumenti da inventore","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** realizzare un oggetto minuscolo sfruttando materiali di scarto che cadrà a pezzi dopo 1 minuto (CD 20)\\n\\n**Creazione:** moschetto, pistola, campanella, lanterna a lente sporgente, ampolla, lanterna schermabile, tagliola, serratura, manette, specchio, pala, fischietto da richiamo, acciarino con pietra focaia"},"item.masons-tools":{"name":"Strumenti da muratore","description":"**Caratteristica:** Forza\\n\\n**Utilizzo:** intagliare un simbolo o scavare un buco nella pietra (CD 10)\\n\\n**Creazione:** carrucola e paranco"},"item.painters-supplies":{"name":"Strumenti da pittore","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** dipingere un'immagine riconoscibile di qualcosa che il personaggio ha visto (CD 10)\\n\\n**Creazione:** focus druidico, simbolo sacro"},"item.glassblowers-tools":{"name":"Strumenti da soffiatore","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** capire il contenuto di un oggetto di vetro delle ultime 24 ore (CD 15)\\n\\n**Creazione:** bottiglia di vetro, lente d'ingrandimento, cannocchiale, fiala"},"item.weavers-tools":{"name":"Strumenti da tessitore","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** rammendare tessuti lacerati (CD 10) o cucire un motivo minuscolo (CD 10)\\n\\n**Creazione:** armatura imbottita, cesto, giaciglio, coperta, abiti eleganti, rete, veste, corda, sacco, spago, tenda, abiti da viaggiatore"},"item.potters-tools":{"name":"Strumenti da vasaio","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** capire il contenuto di un oggetto di ceramica delle ultime 24 ore (CD 15)\\n\\n**Creazione:** brocca, lampada"},"item.cooks-utensils":{"name":"Utensili da cuoco","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** migliorare il sapore del cibo (CD 10) o individuare cibo avariato o avvelenato (CD 15)\\n\\n**Creazione:** razioni"},"item.forgery-kit":{"name":"Arnesi da falsario","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** scrivere 10 parole o meno copiando la scrittura di qualcun altro (CD 15) o duplicare un sigillo di cera (CD 20)"},"item.thieves-tools":{"name":"Arnesi da scasso","description":"**Caratteristica:** Destrezza\\n\\n**Utilizzo:** scassinare una serratura (CD 15) o disattivare una trappola (CD 15)"},"item.herbalism-kit":{"name":"Borsa da erborista","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** identificare una pianta (CD 10)\\n\\n**Creazione:** antitossina, candela, borsa del guaritore, *pozione di guarigione*"},"item.gaming-set-dice":{"name":"Gioco, Dadi","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** capire se qualcuno sta barando (CD 10) o vincere una partita (CD 20)"},"item.gaming-set-dragonchess":{"name":"Gioco, scacchi dei draghi","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** capire se qualcuno sta barando (CD 10) o vincere una partita (CD 20)"},"item.gaming-set-playing-cards":{"name":"Gioco, carte da gioco","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** capire se qualcuno sta barando (CD 10) o vincere una partita (CD 20)"},"item.gaming-set-three-dragon-ante":{"name":"Gioco, Tre draghi al buio","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** capire se qualcuno sta barando (CD 10) o vincere una partita (CD 20)"},"item.poisoners-kit":{"name":"Sostanze da avvelenatore","description":"**Caratteristica:** Intelligenza\\n\\n**Utilizzo:** individuare un oggetto avvelenato (CD 10)\\n\\n**Creazione:** veleno base"},"item.navigators-tools":{"name":"Strumenti da navigatore","description":"**Caratteristica:** Saggezza\\n\\n**Utilizzo:** pianificare una rotta (CD 10) o determinare la propria posizione scrutando le stelle (CD 15)"},"item.musical-instrument-bagpipes":{"name":"Strumento musicale, Cornamusa","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-drum":{"name":"Strumento musicale, tamburo","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-dulcimer":{"name":"Strumento musicale, dulcimer","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-flute":{"name":"Strumento musicale, flauto","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-horn":{"name":"Strumento musicale, corno","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-lute":{"name":"Strumento musicale, liuto","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-lyre":{"name":"Strumento musicale, lira","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-pan-flute":{"name":"Strumento musicale, flauto di pan","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-shawm":{"name":"Strumento musicale, ciaramella","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.musical-instrument-viol":{"name":"Strumento musicale, viola","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** suonare una canzone conosciuta (CD 10) o improvvisarne una (CD 15)"},"item.disguise-kit":{"name":"Trucchi per il camuffamento","description":"**Caratteristica:** Carisma\\n\\n**Utilizzo:** truccarsi (CD 10)\\n\\n**Creazione:** costume"},"item.clothes-travelers":{"name":"Abiti da viaggiatore","description":"Gli abiti da viaggiatore sono resistenti e progettati per sopportare svariati ambienti.","page":107},"item.clothes-fine":{"name":"Abiti eleganti","description":"Gli abiti eleganti sono realizzati con stoffe pregiate e decorati con dettagli raffinati. Alcuni eventi e luoghi consentono l'accesso solo a chi li indossa.","page":107},"item.tinderbox":{"name":"Acciarino con pietra focaia","description":"Si tratta di un piccolo contenitore usato per accendere il fuoco, che contiene acciarino, pietra focaia e materiale combustibile (solitamente stracci essiccati e bagnati d'olio). Utilizzarlo per accendere una candela, una lampada, una lanterna, una torcia o qualunque altra cosa con sopra materiale infiammabile richiede un'azione bonus. Per accendere un fuoco di qualsiasi altro tipo è richiesto 1 minuto.","page":107},"item.acid":{"name":"Acido","description":"Quando il personaggio effettua un'azione di Attacco, puoi sostituire uno dei suoi attacchi con il lancio di una fiala di acido. Può prendere di mira una creatura o un oggetto che egli è in grado di vedere entro 6 metri da sé. Il bersaglio deve superare un tiro salvezza su Destrezza (CD 8 più il modificatore di Destrezza e il bonus di competenza del personaggio), altrimenti subirà 2d6 danni da acido.","page":107},"item.holy-water":{"name":"Acqua santa","description":"Quando il personaggio effettua un'azione di Attacco, puoi sostituire uno dei suoi attacchi con il lancio di una ampolla di acqua santa verso una creatura che egli è in grado di vedere entro un raggio di 6 metri da sé. Il bersaglio deve superare un tiro salvezza su Destrezza (CD 8 più il modificatore di Destrezza e il bonus di competenza del personaggio), altrimenti subirà 2d8 danni radiosi se è un immondo o un non morto.","page":107},"item.flask":{"name":"Ampolla","description":"Un'ampolla ha una capacità di 0,5 litri.","page":107},"item.antitoxin":{"name":"Antitossina","description":"Come azione bonus, per evitare di essere avvelenato o interrompere tale condizione, il personaggio può bere una fiala di antitossina per ottenere vantaggio ai relativi tiri salvezza.","page":107},"item.ram-portable":{"name":"Ariete portatile","description":"Un ariete portatile può essere usato per sfondare le porte e conferisce un bonus di +4 alla prova di Forza del personaggio. Un altro personaggio può aiutare il primo a usare l'ariete, nel qual caso quest'ultimo dispone di vantaggio alla prova.","page":107},"item.pole":{"name":"Asta","description":"Un'asta è lunga 3 metri. Il personaggio può usarla per toccare qualcosa a massimo 3 metri di distanza da sé. Se deve effettuare una prova di Forza (Atletica) come parte di un salto in alto o in lungo, può effettuarla con vantaggio sfruttando l'asta.","page":107},"item.climbers-kit":{"name":"Attrezzi da scalatore","description":"Un kit da scalatore è composto da punte per stivali, guanti, chiodi da rocciatore e un'imbragatura. Come azione di Utilizzo, il personaggio può usare gli attrezzi da scalatore per ancorarsi; quando lo fa, non può cadere per più di 7,5 metri dal punto in cui si è ancorato e non può arrampicarsi per più di 7,5 metri dal quel punto senza disfare l'ancoraggio come azione bonus.","page":107},"item.barrel":{"name":"Barile","description":"Un barile può contenere fino a 16 litri di liquido o 4 cubi con spigolo di 30 centimetri di merci essiccate.","page":107},"item.pouch":{"name":"Borsa","description":"Una borsa può contenere fino a 3 chilogrammi e 5 litri.","page":107},"item.healers-kit":{"name":"Borsa del guaritore","description":"La borsa del guaritore è utilizzabile dieci volte. Come azione di Utilizzo, il personaggio può consumarne un uso per stabilizzare una creatura priva di sensi con 0 punti ferita senza dover effettuare una prova di Saggezza (Medicina).","page":107},"item.component-pouch":{"name":"Borsa per componenti","description":"Una borsa per componenti è impermeabile e piena di scompartimenti in cui sono conservate tutte le componenti materiali sfuse degli incantesimi del personaggio.","page":107},"item.bottle-glass":{"name":"Bottiglia di vetro","description":"Una bottiglia di vetro ha una capacità di 0,75 litri.","page":109},"item.jug":{"name":"Brocca","description":"Una brocca ha una capacità di 4 litri.","page":109},"item.bell":{"name":"Campana","description":"Come azione di Utilizzo, la campana può essere suonata affinché produca un suono udibile fino a 18 metri di distanza.","page":109},"item.candle":{"name":"Candela","description":"Per 1 ora, una candela accesa proietta luce intensa entro un raggio di 1,5 metri e luce fioca per altri 1,5 metri.","page":109},"item.spyglass":{"name":"Cannocchiale","description":"Gli oggetti osservati attraverso un cannocchiale appaiono grandi il doppio della loro taglia.","page":109},"item.block-and-tackle":{"name":"Carrucola e paranco","description":"Carrucola e paranco consentono al personaggio di sollevare fino a quattro volte il peso massimo che solleverebbe normalmente.","page":109},"item.paper":{"name":"Carta","description":"Un foglio di carta può contenere circa 250 parole scritte a mano.","page":109},"item.chain":{"name":"Catena","description":"Come azione di Utilizzo, se supera una prova di Forza (Atletica) con CD 13, il personaggio può avvolgere la catena attorno a una creatura non consenziente entro 1,5 metri da sé che sia afferrata, incapacitata o trattenuta. Se le vengono legate le gambe, sarà trattenuta finché non riuscirà a scappare. Per liberarsi dalla catena è necessario superare una prova di Destrezza (Acrobazia) con CD 18 con un'azione. Rompere la catena richiede il superamento di una prova di Forza (Atletica) con CD 20 con un'azione.","page":109},"item.basket":{"name":"Cesto","description":"Un cesto può contenere fino a 20 chilogrammi entro 2 cubi con spigolo di 30 centimetri.","page":109},"item.blanket":{"name":"Coperta","description":"Finché il personaggio è avvolto dalla coperta, dispone di vantaggio ai tiri salvezza contro il freddo estremo (vedi \\"Strumenti per le modalità di gioco\\").","page":109},"item.rope":{"name":"Corda","description":"Come azione di Utilizzo, il personaggio può stringere un nodo con la corda se supera una prova di Destrezza (Rapidità di mano) con CD 10. La corda può essere spezzata superando una prova di Forza (Atletica) con CD 20.\\n\\nIl personaggio può legare una creatura non consenziente con la corda solo se questa è afferrata, incapacitata o trattenuta. Se le vengono legate le gambe, sarà trattenuta finché non riuscirà a scappare. Per liberarsi dalla corda è necessario superare una prova di Destrezza (Acrobazia) con CD 15 con un'azione.","page":109},"item.costume":{"name":"Costume","description":"Quando il personaggio indossa un costume, dispone di vantaggio a qualsiasi prova di caratteristica effettuata per impersonare qualcuno o una specifica tipologia di persona.","page":109},"item.case-map-or-scroll":{"name":"Custodia per mappe o pergamene","description":"Una custodia per mappe o pergamene può contenere fino a 10 fogli di carta o 5 di pergamena.","page":109},"item.case-crossbow-bolt":{"name":"Custodia per quadrelli da balestra","description":"Una custodia per quadrelli da balestra può contenerne fino a 20 unità.","page":109},"item.dungeoneers-pack":{"name":"Dotazione da avventuriero","description":"Una dotazione da avventuriero contiene i seguenti oggetti: zaino, triboli, piede di porco, 2 ampolle di olio, 10 razioni giornaliere, corda, acciarino con pietra focaia, 10 torce e un otre.","page":109},"item.diplomats-pack":{"name":"Dotazione da diplomatico","description":"Una dotazione da diplomatico contiene i seguenti oggetti: forziere, abiti eleganti, inchiostro, 5 pennini, lampada, 2 custodie per mappe o pergamene, 4 ampolle di olio, 5 fogli di carta, 5 fogli di pergamena, profumo e acciarino con pietra focaia.","page":109},"item.explorers-pack":{"name":"Dotazione da esploratore","description":"Una dotazione da esploratore contiene i seguenti oggetti: zaino, giaciglio, 2 ampolle di olio, 10 razioni giornaliere, corda, acciarino con pietra focaia, 10 torce e un otre.","page":109},"item.entertainers-pack":{"name":"Dotazione da intrattenitore","description":"Una dotazione da intrattenitore contiene i seguenti i oggetti: zaino, giaciglio, campana, lanterna a lente sporgente, 3 costumi, specchio, 8 ampolle di olio, 9 razioni giornaliere e un otre.","page":109},"item.priests-pack":{"name":"Dotazione da sacerdote","description":"Una dotazione da sacerdote contiene i seguenti oggetti: zaino, coperta, acqua santa, lampada, 7 razioni giornaliere, tunica e acciarino con pietra focaia.","page":109},"item.burglars-pack":{"name":"Dotazione da scassinatore","description":"Una dotazione da scassinatore comprende i seguenti oggetti: zaino, sfere metalliche, campana, 10 candele, piede di porco, lanterna schermabile, 7 ampolle di olio, 5 razioni giornaliere, corda, acciarino con pietra focaia e un otre.","page":109},"item.scholars-pack":{"name":"Dotazione da studioso","description":"Una dotazione da studioso contiene i seguenti oggetti: zaino, libro, inchiostro, pennino, lampada, 10 ampolle di olio, 10 fogli di pergamena e acciarino con pietra focaia.","page":109},"item.quiver":{"name":"Faretra","description":"Una faretra può contenere fino a 20 frecce.","page":110},"item.vial":{"name":"Fiala","description":"Una fiala ha una capacità di 120 millilitri.","page":110},"item.signal-whistle":{"name":"Fischietto da richiamo","description":"Se il personaggio soffia al suo interno con un'azione di Utilizzo, il fischietto da richiamo produce un suono udibile fino a 180 metri di distanza.","page":110},"item.chest":{"name":"Forziere","description":"Un forziere ha una capacità di 12 cubi con spigolo di 30 centimetri.","page":110},"item.alchemists-fire":{"name":"Fuoco dell'alchimista","description":"Quando il personaggio effettua un'azione di Attacco, puoi sostituire uno dei suoi attacchi con il lancio di una ampolla di fuoco dell'alchimista. Può prendere di mira una creatura o un oggetto che egli è in grado di vedere entro 6 metri da sé. Il bersaglio deve superare un tiro salvezza su Destrezza (CD 8 più il modificatore di Destrezza e il bonus di competenza del personaggio), altrimenti subirà 1d4 danni da fuoco e sarà in fiamme (vedi \\"Glossario delle regole\\").","page":110},"item.bedroll":{"name":"Giaciglio","description":"Su un giaciglio può dormire una creatura di taglia Piccola o Media. Finché il personaggio si trova in un giaciglio, supera automaticamente i tiri salvezza contro il freddo estremo (vedi \\"Strumenti per le modalità di gioco\\").","page":110},"item.ink":{"name":"Inchiostro","description":"L'inchiostro è reperibile in boccette da 30 grammi ciascuna, con abbastanza materiale per scrivere circa 500 pagine.","page":110},"item.lamp":{"name":"Lampada","description":"Una lampada brucia olio per proiettare luce intensa in un raggio di 4,5 metri e luce fioca per ulteriori 9 metri.","page":110},"item.lantern-bullseye":{"name":"Lanterna a lente sporgente","description":"Una lanterna a lente sporgente sfrutta l'olio come combustibile per proiettare luce intensa in un cono di 18 metri e luce fioca per ulteriori 18 metri.","page":110},"item.lantern-hooded":{"name":"Lanterna schermabile","description":"Una lanterna schermabile brucia olio per proiettare luce intensa in un raggio di 9 metri e luce fioca per ulteriori 9 metri. Come azione bonus, un personaggio può schermare la lanterna, riducendo la luce proiettata a luce fioca in un raggio di 1,5 metri o riaprirla.","page":110},"item.magnifying-glass":{"name":"Lente d'ingrandimento","description":"Una lente d'ingrandimento conferisce vantaggio a ogni prova di caratteristica effettuata per valutare o ispezionare un oggetto estremamente dettagliato. Per accendere un fuoco con la lente d'ingrandimento è necessaria una luce da concentrare intensa quanto quella del sole, dei rametti da accendere e circa 5 minuti affinché il fuoco attecchisca.","page":110},"item.book":{"name":"Libro","description":"I libri possono contenere sia opere di finzione che di carattere divulgativo. Se il personaggio ne consulta uno che tratta di un determinato argomento, ottiene un bonus di +5 alle prove di Intelligenza (Arcano, Storia, Natura o Religione) eseguite su tale argomento.","page":110},"item.manacles":{"name":"Manette","description":"Come azione di Utilizzo, se supera una prova di Destrezza (Rapidità di mano) con CD 13, il personaggio può usare le manette per bloccare una creatura non consenziente di taglia Piccola o Media entro 1,5 metri da sé che sia afferrata, incapacitata o trattenuta. Mentre è ammanettata, la creatura ha svantaggio ai tiri per colpire ed è trattenuta se le manette sono attaccate a una catena o un gancio fissi in posizione. Per liberarsi è necessario superare una prova di Destrezza (Rapidità di mano) con CD 20 con un'azione. Per romperle bisogna invece superare una prova di Forza (Atletica) con CD 25 con un'azione.\\n\\nOgni coppia di manette ha la sua chiave. Senza di essa, una creatura può scassinarne la serratura utilizzando gli arnesi da scasso e superando una prova di Destrezza (Rapidità di mano) con CD 15.","page":110},"item.map":{"name":"Mappa","description":"Se il personaggio consulta una mappa accurata, ottiene un bonus di +5 alle prove di Saggezza (Sopravvivenza) effettuate per tracciare un percorso nel luogo che raffigura.","page":111},"item.oil":{"name":"Olio","description":"Il personaggio può gettare olio su una creatura, un oggetto o un'area. In alternativa, può usarlo come combustibile, come descritto sotto.\\n\\n***Gettare olio su una creatura o un oggetto.*** Quando il personaggio effettua un'azione di Attacco, puoi sostituire uno dei suoi attacchi con il lancio di un'ampolla di olio verso una creatura o un oggetto entro 6 metri da sé. Il bersaglio deve superare un tiro salvezza su Destrezza (CD 8 più il modificatore di Destrezza e il bonus di competenza del personaggio), altrimenti sarà coperto di olio. Se il bersaglio subisce danni da fuoco prima che l'olio si asciughi (dopo 1 minuto), subisce 5 danni da fuoco extra a causa dell'olio incendiato.\\n\\n***Gettare olio su una superficie.*** Come azione di Utilizzo, il personaggio può versare un'ampolla di olio su una superficie piana per coprire una zona di 1,5 metri quadrati entro 1,5 metri da sé. Se incendiato, l'olio brucia per 2 round fino al termine del turno (o 12 secondi) e infligge 5 danni da fuoco a qualsiasi creatura entri in quell'area o finisca lì il suo turno. Una creatura può subire questi danni solo una volta per turno.\\n\\n***Combustibile.*** L'olio è utilizzabile come combustibile per lampade e lanterne. Una volta versata un'ampolla di olio in una lampada o una lanterna, questo brucerà per 6 ore. Tale durata non deve necessariamente essere consecutiva: è possibile spegnere il fuoco (come azione di Utilizzo) e riaccenderlo finché la durata totale della combustione non raggiunge le 6 ore.","page":111},"item.waterskin":{"name":"Otre","description":"Un otre ha una capacità di 2 litri. Se il personaggio non beve abbastanza acqua, corre il rischio di disidratazione (vedi \\"Glossario delle regole\\").","page":111},"item.shovel":{"name":"Pala","description":"Se il personaggio impiega 1 ora di lavoro, può usare la pala per scavare una buca nel terreno di 1,5 metri per lato.","page":111},"item.ink-pen":{"name":"Pennino","description":"Usando pennino e inchiostro è possibile scrivere o disegnare.","page":111},"item.pot-iron":{"name":"Pentola di ferro","description":"Una pentola di ferro ha una capacità di 4 litri.","page":111},"item.parchment":{"name":"Pergamena","description":"Un foglio di pergamena può contenere circa 250 parole scritte a mano.","page":111},"item.spell-scroll-cantrip":{"name":"Pergamena magica (trucchetto)","description":"Una *pergamena magica* (trucchetto) o una *pergamena magica* (livello 1) sono oggetti magici contenenti rispettivamente le parole di un trucchetto o un incantesimo di livello 1, che variano in base al volere del loro creatore. Se l'incantesimo è nella lista degli incantesimi della classe del personaggio, quest'ultimo può leggere la pergamena e lanciare l'incantesimo con il suo normale tempo di lancio e senza fornire componenti materiali.\\n\\nSe l'incantesimo richiede di effettuare un tiro salvezza o un tiro per colpire, la CD del tiro salvezza sull'incantesimo è 13, mentre il bonus di attacco è +5. Una volta terminato il lancio, la pergamena si disintegra.","page":111},"item.spell-scroll-level-1":{"name":"Pergamena magica (livello 1)","description":"Una *pergamena magica* (trucchetto) o una *pergamena magica* (livello 1) sono oggetti magici contenenti rispettivamente le parole di un trucchetto o un incantesimo di livello 1, che variano in base al volere del loro creatore. Se l'incantesimo è nella lista degli incantesimi della classe del personaggio, quest'ultimo può leggere la pergamena e lanciare l'incantesimo con il suo normale tempo di lancio e senza fornire componenti materiali.\\n\\nSe l'incantesimo richiede di effettuare un tiro salvezza o un tiro per colpire, la CD del tiro salvezza sull'incantesimo è 13, mentre il bonus di attacco è +5. Una volta terminato il lancio, la pergamena si disintegra.","page":111},"item.crowbar":{"name":"Piede di porco","description":"Utilizzando un piede di porco, il personaggio ottiene vantaggio alle prove di Forza in cui è possibile applicare la sua leva.","page":111},"item.potion-of-healing":{"name":"Pozione di guarigione","description":"Questa pozione è un oggetto magico. Come azione bonus, il personaggio può berne una o somministrarla a un'altra creatura entro 1,5 metri da sé. Chi beve il fluido magico rosso contenuto in questa fiala recupera 2d4 + 2 punti ferita.","page":111},"item.perfume":{"name":"Profumo","description":"I profumi sono disponibili in ampolle con capacità di 120 millilitri. Dopo che il personaggio ha applicato su di sé il profumo, per 1 ora avrà vantaggio alle prove di Carisma (Persuasione) effettuate per influenzare un umanoide indifferente entro 1,5 metri da sé.","page":112},"item.grappling-hook":{"name":"Rampino","description":"Come azione di Utilizzo, il personaggio può lanciare il rampino verso una ringhiera, una sporgenza o un altro appiglio entro 15 metri da sé. Per far sì che il gancio faccia presa è necessario superare una prova di Destrezza (Acrobazia) con CD 13. Se al gancio viene legata una corda, è possibile arrampicarsi.","page":112},"item.rations":{"name":"Razioni","description":"Le razioni sono composte da cibo da viaggio, come carne secca, frutta secca, gallette e noci. Per scoprire i rischi del digiuno, consulta la sezione \\"Malnutrizione\\" nel \\"Glossario delle regole\\".","page":112},"item.net":{"name":"Rete","description":"Quando il personaggio effettua un'azione di Attacco, puoi sostituire uno dei suoi attacchi con il lancio di una rete verso una creatura che egli è in grado di vedere entro un raggio di 4,5 metri da sé. Il bersaglio deve superare un tiro salvezza su Destrezza (CD 8 più il modificatore di Destrezza e il bonus di competenza del personaggio), altrimenti sarà trattenuto finché non riuscirà a liberarsi. Se il bersaglio è di taglia Enorme o superiore, supera automaticamente la prova.\\n\\nPer fuggire, il bersaglio o una creatura entro 1,5 metri da lui deve effettuare un'azione per eseguire una prova di Forza (Atletica) con CD 10, liberando la creatura trattenuta in caso di successo. È possibile ottenere il medesimo risultato distruggendo la rete (CA 10; 5 PF; immunità a danni contundenti, da veleno e psichici).","page":112},"item.sack":{"name":"Sacco","description":"Un sacco può contenere fino a 15 chilogrammi all'interno di 1 cubo con spigolo di 30 centimetri.","page":112},"item.ladder":{"name":"Scala a pioli","description":"Una scala a pioli è alta 3 metri. Per scendere dalla scala o salirci è necessario arrampicarsi.","page":112},"item.bucket":{"name":"Secchio","description":"Un secchio ha una capacità di 14 litri.","page":112},"item.lock":{"name":"Serratura","description":"Ogni serratura è dotata della sua chiave. Senza tale chiave, una creatura può scassinarla utilizzando gli arnesi da scasso e superando una prova di Destrezza (Rapidità di mano) con CD 15.","page":112},"item.ball-bearings":{"name":"Sfere metalliche","description":"Con un'azione di Utilizzo, il personaggio può far cadere delle sfere metalliche dalla sua borsa. Queste si diffonderanno per coprire una superficie piana di 3 metri quadrati entro 3 metri da sé. Chiunque entri in quest'area per la prima volta in un turno deve superare un tiro salvezza su Destrezza con CD 10, altrimenti cadrà prono. Per recuperare le sfere metalliche sono necessari 10 minuti.","page":112},"item.string":{"name":"Spago","description":"Una matassa di spago è lunga 3 metri. Come azione di Utilizzo, il personaggio può utilizzarlo per stringere un nodo.","page":112},"item.mirror":{"name":"Specchio","description":"Uno specchio d'acciaio portatile è utile sia per la cura della persona che per sbirciare dietro gli angoli o riflettere la luce per mandare un segnale a qualcuno.","page":112},"item.spikes-iron":{"name":"Spuntoni di ferro","description":"Gli spuntoni di ferro sono ottenibili in gruppi di dieci. Come azione di Utilizzo, il personaggio può usare un oggetto contundente come un martello leggero per conficcare gli spuntoni nel legno, nel terreno o in altri materiali simili. Tale azione è utile per bloccare una porta o per avere un supporto a cui legare una corda o una catena.","page":112},"item.hunting-trap":{"name":"Tagliola","description":"Come azione di Utilizzo, il personaggio può piazzare una tagliola, ovvero un anello metallico dentellato che si chiude di scatto qualora una creatura calpesti la piastra a pressione collocata al centro. La trappola viene fissata a una pesante catena o a un oggetto immobile come un albero o un palo piantato a terra. Quando una creatura mette un piede sulla piastra, deve superare un tiro salvezza su Destrezza con CD 13, altrimenti subisce 1d4 danni perforanti e la sua velocità scende a 0 fino all'inizio del turno successivo. A quel punto, finché non si libera dalla trappola, il suo movimento è limitato dalla lunghezza della catena (solitamente 90 centimetri). Una creatura può usare la sua azione per effettuare una prova di Forza (Atletica) con CD 13 e liberare se stessa o qualcun altro a portata in caso di successo. Ogni prova fallita infligge 1 danno perforante alla creatura intrappolata.","page":112},"item.tent":{"name":"Tenda","description":"In una tenda possono dormire un massimo di due creature di taglia Piccola o Media.","page":113},"item.torch":{"name":"Torcia","description":"Una torcia arde per 1 ora e proietta luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri. Quando il personaggio effettua l'azione di Attacco, può farlo con la torcia usandola come arma da mischia semplice. Se il colpo va a segno, il bersaglio subisce 1 danno da fuoco.","page":113},"item.caltrops":{"name":"Triboli","description":"Come azione di Utilizzo, il personaggio può spargere triboli dalla sua borsa per coprire una superficie di 1,5 metri quadrati entro 1,5 metri da sé. Chiunque entri in quest'area per la prima volta in un turno deve superare un tiro salvezza su Destrezza con CD 15, altrimenti subirà 1 danno perforante e la sua velocità sarà ridotta a 0 fino all'inizio del proprio turno successivo. Per recuperare i triboli sono necessari 10 minuti.","page":113},"item.robe":{"name":"Tunica","description":"Una tunica può avere un significato cerimoniale o professionale. In alcuni luoghi ed eventi sono ammesse solo persone che indossano una tunica di un determinato colore e recante uno specifico simbolo.","page":113},"item.poison-basic":{"name":"Veleno base","description":"Come azione bonus, il personaggio può cospargere un'arma o fino a tre munizioni col contenuto di una fiala di veleno base. Una creatura che subisce danni perforanti o taglienti da armi o munizioni avvelenate subisce 1d4 danni da veleno extra. Una volta applicato, il veleno preserva le sue proprietà per 1 minuto o finché non vengono inflitti dei danni, a seconda dell'opzione che si verifica per prima.","page":113},"item.backpack":{"name":"Zaino","description":"Uno zaino può contenere fino a 15 chilogrammi all'interno di un cubo con spigolo di 30 centimetri. Può fungere anche da bisaccia.","page":113},"item.arcane-focus-wand":{"name":"Focus arcano (Bacchetta)","page":110},"item.arcane-focus-staff":{"name":"Focus arcano (Bastone)","page":110},"item.arcane-focus-crystal":{"name":"Focus arcano (Cristallo)","page":110},"item.arcane-focus-orb":{"name":"Focus arcano (Globo)","page":110},"item.arcane-focus-rod":{"name":"Focus arcano (Verga)","page":110},"item.druidic-focus-yew-wand":{"name":"Focus druidico, Bacchetta in legno di tasso","page":110},"item.druidic-focus-wooden-staff":{"name":"Focus druidico, Bastone di legno","page":110},"item.druidic-focus-sprig-of-mistletoe":{"name":"Focus druidico, Rametto di vischio","page":110},"item.needles-50":{"name":"Aghi (50)","page":111},"item.arrows-20":{"name":"Frecce (20)","page":111},"item.bullets-firearm-10":{"name":"Proiettili, arma da fuoco (10)","page":111},"item.bullets-sling-20":{"name":"Proiettili, fionda (20)","page":111},"item.bolts-20":{"name":"Quadrelli (20)","page":111},"item.holy-symbol-amulet":{"name":"Simbolo sacro, Amuleto","page":112},"item.holy-symbol-emblem":{"name":"Simbolo sacro, Emblema","page":112},"item.holy-symbol-reliquary":{"name":"Simbolo sacro, Reliquiario","page":112},"item.camel":{"name":"Cammello","page":113},"item.horse-riding":{"name":"Cavallo da galoppo","page":113},"item.warhorse":{"name":"Cavallo da guerra","page":113},"item.horse-draft":{"name":"Cavallo da tiro","page":113},"item.elephant":{"name":"Elefante","page":113},"item.mastiff":{"name":"Mastino","page":113},"item.mule":{"name":"Mulo","page":113},"item.pony":{"name":"Pony","page":113},"item.chariot":{"name":"Biga","page":114},"item.cart":{"name":"Carretto","page":114},"item.wagon":{"name":"Carro","page":114},"item.carriage":{"name":"Carrozza","page":114},"item.feed-per-day":{"name":"Nutrimento (al giorno)","page":114},"item.saddle-riding":{"name":"Sella (Da galoppo)","page":114},"item.saddle-exotic":{"name":"Sella (Esotica)","page":114},"item.saddle-military":{"name":"Sella (Militare)","page":114},"item.sled":{"name":"Slitta","page":114},"item.stabling-per-day":{"name":"Stallaggio (al giorno)","page":114},"item.rowboat":{"name":"Barca a remi","page":114},"item.keelboat":{"name":"Barcone","page":114},"item.airship":{"name":"Dirigibile","page":114},"item.galley":{"name":"Galea","page":114},"item.sailing-ship":{"name":"Nave a vela","page":114},"item.warship":{"name":"Nave da guerra","page":114},"item.longship":{"name":"Nave lunga","page":114},"item.arcane-focus":{"name":"Focus arcano","description":"Un focus arcano assume una delle forme elencate nella tabella Focus arcani, ed è adornato con gioielli o intagliato affinché possa incanalare l'energia arcana. Un mago, uno stregone o un warlock può usare questo oggetto come focus da incantatore.\\n\\n**Focus arcani**\\n\\n| Focus | Peso | Costo |\\n| --- | --- | --- |\\n| Bacchetta | 0,5 kg | 10 mo |\\n| Bastone (anche bastone ferrato) | 2 kg | 5 mo |\\n| Cristallo | 0,5 kg | 10 mo |\\n| Globo | 1,5 kg | 20 mo |\\n| Verga | 1 kg | 10 mo |","page":110},"item.druidic-focus":{"name":"Focus druidico","description":"Un focus druidico assume una delle forme indicate nella tabella Focus druidici ed è intagliato, legato con del nastro o dipinto per incanalare la magia primordiale. Un oggetto del genere è utilizzabile come focus da incantatore da un druido o un ranger.\\n\\n**Focus druidici**\\n\\n| Focus | Peso | Costo |\\n| --- | --- | --- |\\n| Bacchetta in legno di tasso | 0,5 kg | 10 mo |\\n| Bastone di legno (anche bastone ferrato) | 2 kg | 5 mo |\\n| Rametto di vischio | — | 1 mo |","page":110},"item.holy-symbol":{"name":"Simbolo sacro","description":"Un simbolo sacro può assumere una delle forme elencate nella tabella Simbolo sacro ed è adornato o dipinto in modo che incanali l'energia divina. Un chierico o un paladino possono usare un simbolo sacro come focus da incantatore.\\n\\nLa tabella indica se il simbolo sacro deve essere tenuto in mano, indossato o portato su un tessuto (tabarro o striscione) o su uno scudo.\\n\\n**Simboli sacri**\\n\\n| Simbolo | Peso | Costo |\\n| --- | --- | --- |\\n| Amuleto (indossato o tenuto in mano) | 0,5 kg | 5 mo |\\n| Emblema (portato su un tessuto o uno scudo) | — | 5 mo |\\n| Reliquiario (tenuto in mano) | 1 kg | 5 mo |","page":112},"item.spellbook":{"name":"Libro degli incantesimi","description":"Lo studio delle arti arcane da parte del mago ha raggiunto il suo apice con la creazione di un particolare tomo: il suo libro degli incantesimi. Si tratta di un oggetto minuscolo che pesa 1,5 chilogrammi, conta 100 pagine e può essere letto solo dal personaggio o da qualcuno che lanci *identificare*. L'aspetto e i materiali che compongono il libro sono a tua discrezione: potrebbe essere un tomo dal dorso dorato o una raccolta di pergamene tenute insieme con della corda.","page":60},"item.ioun-stone":{"name":"Pietra di Ioun","description":"Le *pietre di Ioun* sono delle dimensioni approssimative di una biglia e devono il loro nome a Ioun, dea della conoscenza e della profezia venerata su alcuni mondi. Esistono molti tipi di *pietre di Ioun*, ognuno dei quali ha una diversa combinazione di forma e colore.\\n\\nQuando il personaggio effettua un'azione di Magia per lanciare una *pietra di Ioun* in aria, l'oggetto orbita intorno alla sua testa a una distanza di 1d3 metri, conferendogli il suo beneficio nel frattempo. Una creatura può avere fino a tre *pietre di Ioun* che orbitano intorno alla sua testa contemporaneamente.\\n\\nOgni pietra che orbita intorno alla testa è considerata un oggetto indossato. La pietra orbitante evita il contatto con altre creature e oggetti, regolando la sua orbita per evitare collisioni e vanificando tutti i tentativi di altre creature di attaccarla o agguantarla.\\n\\nIl personaggio può effettuare un'azione di Utilizzo per afferrare e riporre un numero qualsiasi di *pietre di Ioun* che orbitano intorno alla sua testa. Se la sintonia con una *pietra di Ioun* termina mentre orbita intorno alla testa, l'oggetto cade come se fosse stato lasciato cadere a terra.\\n\\nIl tipo di pietra ne determina la rarità e gli effetti.\\n\\n***Agilità (molto rara).*** Finché questa sfera color rosso scuro orbita intorno alla testa del personaggio, il suo punteggio di Destrezza aumenta di 2, fino a un massimo di 20.\\n\\n***Assorbimento (molto rara).*** Finché orbita intorno alla testa del personaggio, questo ellissoide color lavanda chiaro gli permette di usare una reazione per annullare un incantesimo di 4º livello o inferiore lanciato da una creatura che il personaggio è in grado di vedere. Un incantesimo annullato non ha effetto e le risorse utilizzate per lanciarlo vengono sprecate. Dopo aver annullato 20 livelli di incantesimi, la pietra prende fuoco, assume una tonalità grigia e opaca e perde la sua magia.\\n\\n***Assorbimento superiore (leggendaria).*** Finché orbita intorno alla testa del personaggio, questo ellissoide con venature verdi e color lavanda gli permette di usare una reazione per annullare un incantesimo di 8º livello o inferiore lanciato da una creatura che il personaggio è in grado di vedere. Un incantesimo annullato non ha effetto e le risorse utilizzate per lanciarlo vengono sprecate. Dopo aver annullato 20 livelli di incantesimi, la pietra prende fuoco, assume una tonalità grigia e opaca e perde la sua magia.\\n\\n***Autorità (molto rara).*** Finché questa sfera con venature rosa e verdi orbita intorno alla testa del personaggio, il punteggio di Carisma del personaggio aumenta di 2, fino a un massimo di 20.\\n\\n***Consapevolezza (rara).*** Mentre questo romboide blu scuro orbita intorno alla testa del personaggio, quest'ultimo dispone di vantaggio ai tiri per l'iniziativa e alle prove di Saggezza (Percezione).\\n\\n***Forza (molto rara).*** Finché questo romboide azzurro orbita intorno alla testa del personaggio, il suo punteggio di Forza aumenta di 2, fino a un massimo di 20.\\n\\n***Intelletto (molto rara).*** Finché questa sfera con venature blu e rosso scarlatto orbita intorno alla testa del personaggio, il punteggio di Intelligenza del personaggio aumenta di 2, fino a un massimo di 20.\\n\\n***Intuizione (molto rara).*** Finché questa sfera blu incandescente orbita intorno alla testa del personaggio, il punteggio di Saggezza del personaggio aumenta di 2, fino a un massimo di 20.\\n\\n***Maestria (leggendaria).*** Finché questo prisma verde chiaro orbita intorno alla testa del personaggio, il bonus di competenza del personaggio aumenta di 1.\\n\\n***Protezione (rara).*** Finché questo prisma rosa antico orbita intorno alla testa del personaggio, quest'ultimo ottiene un bonus di +1 alla Classe Armatura.\\n\\n***Rigenerazione (leggendaria).*** Finché questo fuso color madreperla orbita intorno alla testa del personaggio, quest'ultimo recupera 15 punti ferita alla fine di ogni ora, purché abbia almeno 1 punto ferita.\\n\\n***Riserva (rara).*** Questo prisma viola acceso accumula al suo interno gli incantesimi lanciati su di esso, conservandoli finché il personaggio non li usa. Può contenere fino a 4 livelli di incantesimo per volta. Quando viene trovata, contiene 1d4 livelli di incantesimi accumulati scelti dal GM.\\n\\nQualsiasi creatura può lanciare nella pietra un incantesimo di livello compreso tra il 1º e il 4º toccandola al momento del lancio dell'incantesimo. L'incantesimo non ha alcun effetto, a parte quello di essere immagazzinato nella pietra. Se la pietra non può contenere altri incantesimi, quello lanciato viene sprecato senza provocare alcun effetto. Il livello dello slot usato per lanciare l'incantesimo determina lo spazio che occupa.\\n\\nFinché la pietra orbita intorno alla testa del personaggio, quest'ultimo può lanciare qualsiasi incantesimo conservato al suo interno. L'incantesimo usa il livello di slot, la CD del tiro salvezza sull'incantesimo, il bonus all'attacco con incantesimo e la caratteristica da incantatore di chi l'ha lanciato in origine, ma sotto ogni altro aspetto si considera che sia stato il personaggio a lanciarlo. L'incantesimo lanciato dalla pietra non è più conservato al suo interno, liberando il relativo spazio.\\n\\n***Sostentamento (rara).*** Finché questo fuso trasparente orbita intorno alla testa del personaggio, quest'ultimo non ha bisogno di mangiare o bere.\\n\\n***Tempra (molto rara).*** Finché questo romboide rosa orbita intorno alla testa del personaggio, il punteggio di Costituzione del personaggio aumenta di 2, fino a un massimo di 20.","page":271},"item.potion-of-giant-strength":{"name":"Pozione della forza dei giganti","description":"Quando il personaggio beve questa pozione, il suo punteggio di Forza cambia per 1 ora, come determinato dal tipo di gigante (vedi la tabella sottostante). Se il punteggio di Forza del personaggio è pari o superiore a quello conferito dalla pozione, non ha alcun effetto.\\n\\nNel liquido trasparente di questa pozione galleggia un frammento argenteo che ricorda l'unghia di un gigante.\\n\\n| Pozione | For | Rarità |\\n| --- | --- | --- |\\n| *Pozione della forza dei giganti* (delle colline) | 21 | Non comune |\\n| *Pozione della forza dei giganti* (del gelo o delle pietre) | 23 | Rara |\\n| *Pozione della forza dei giganti* (del fuoco) | 25 | Rara |\\n| *Pozione della forza dei giganti* (delle nuvole) | 27 | Molto rara |\\n| *Pozione della forza dei giganti* (delle tempeste) | 29 | Leggendaria |","page":274},"item.potions-of-healing":{"name":"Pozioni di guarigione","description":"Quando il personaggio beve questa pozione, recupera punti ferita. L'ammontare di punti ferita dipende dalla rarità della pozione, come indicato nella tabella sottostante.\\n\\nA prescindere dalla sua potenza, il liquido rosso della pozione brilla quando viene agitato.\\n\\n| Pozione | PF recuperati | Rarità |\\n| --- | --- | --- |\\n| *Pozione di guarigione* | 2d4 + 2 | Comune |\\n| *Pozione di guarigione* (maggiore) | 4d4 + 4 | Non comune |\\n| *Pozione di guarigione* (superiore) | 8d4 + 8 | Rara |\\n| *Pozione di guarigione* (suprema) | 10d4 + 20 | Molto rara |","page":276},"rule.skill":{"name":"Abilità","description":"Un'abilità è un'area di specializzazione associata a una prova di caratteristica. Se il tuo personaggio ha competenza in un'abilità, può aggiungere il suo bonus di competenza al risultato di una prova di caratteristica associata a quella abilità. *Vedi anche* \\"Come si gioca\\" (\\"Competenza\\").","page":202},"rule.grappling":{"name":"Afferrare","description":"Una creatura può afferrare un'altra creatura. I personaggi tipicamente possono afferrare una creatura utilizzando un colpo senz'armi. Molti mostri dispongono di attacchi speciali che permettono loro di afferrare rapidamente la preda. A prescindere dal tipo di presa, bisogna fare riferimento alle seguenti regole. *Vedi anche* \\"Colpo senz'armi\\" e \\"Afferrato\\".\\n\\n***Condizione afferrato.*** Se un personaggio riesce ad afferrare una creatura, questa subisce la condizione \\"afferrato\\".\\n\\n***Una presa per ogni mano.*** Una creatura deve avere una mano libera per poter afferrare un'altra creatura. Alcune schede delle statistiche ed effetti di gioco consentono a una creatura di afferrarne un'altra utilizzando tentacoli, fauci o altre parti del corpo. A prescindere dalle modalità, una creatura può afferrare solo una creatura alla volta con la parte del corpo che ha scelto di usare, e non può utilizzare quella parte per bersagliare un'altra creatura, a meno che non termini la presa.\\n\\n***Sfuggire a una presa.*** Una creatura afferrata può usare la sua azione per effettuare una prova di Forza (Atletica) o di Destrezza (Acrobazia) contro la CD per sfuggire alla presa, ponendo fine alla condizione \\"afferrato\\" su di sé in caso di successo. La condizione termina anche se chi ha afferrato la creatura è incapacitato o se la distanza tra il bersaglio afferrato e chi lo afferra supera la portata della presa. Inoltre, chi ha afferrato la creatura può lasciar andare il bersaglio in qualsiasi momento (nessuna azione richiesta).","page":202},"rule.action.help":{"name":"Aiuto [azione]","description":"Quando il personaggio effettua l'azione di Aiuto, può scegliere di fare una di queste cose.\\n\\n***Aiuto a una prova di caratteristica.*** Il personaggio sceglie una delle competenze in un'abilità (o in uno strumento) e un alleato sufficientemente vicino da poter aiutare verbalmente o fisicamente quando questi effettua una prova di caratteristica. L'alleato dispone di vantaggio alla successiva prova di caratteristica che effettua con l'abilità o lo strumento scelto. Questo beneficio termina se l'alleato non lo utilizza prima dell'inizio del turno successivo del personaggio. Il GM ha l'ultima parola sulla possibilità dell'aiuto da parte del personaggio.\\n\\n***Aiuto a un tiro per colpire.*** Il personaggio distrae momentaneamente un nemico entro 1,5 metri da sé, fornendo vantaggio al tiro per colpire successivo di uno dei suoi alleati contro il nemico. Questo beneficio termina all'inizio del turno successivo del personaggio.","page":203},"rule.per-day":{"name":"Al giorno","description":"Se una regola stabilisce che il personaggio può utilizzare qualcosa per un certo numero di volte al giorno, significa che, una volta esaurite le possibilità d'uso, deve terminare un riposo lungo per poter utilizzare quel qualcosa nuovamente.","page":203},"rule.ally":{"name":"Alleato","description":"Una creatura si definisce \\"alleata\\" se fa parte del gruppo di avventurieri del tuo personaggio, se gli è amica, se si schiera al suo fianco in combattimento o se si tratta di una creatura indicata come alleata dalle regole del gioco o dal GM.","page":203},"rule.create-your-character.alignment":{"name":"Allineamento","description":"L'allineamento di una creatura descrive a grandi linee i suoi ideali e atteggiamenti etici, ed è una combinazione di due fattori: il primo identifica la moralità (buona, malvagia o neutrale), mentre il secondo descrive l'atteggiamento nei confronti dell'ordine (legale, caotico o neutrale). Questi fattori danno vita a nove possibili combinazioni come, ad esempio, legale buono e neutrale malvagio. *Vedi anche* \\"Creazione del personaggio\\" (\\"Creare il personaggio\\").","page":203},"rule.attitude.friendly":{"name":"Amichevole [atteggiamento]","description":"Una creatura amichevole ha un'opinione positiva del personaggio, il quale dispone di vantaggio a una prova di caratteristica per influenzare una creatura amichevole. *Vedi anche* \\"Influenza\\".","page":203},"rule.area-of-effect":{"name":"Area di effetto","description":"Nelle descrizioni di molti incantesimi e privilegi, viene indicata la loro area di effetto che, tipicamente, ha una delle seguenti sei forme descritte più avanti nel glossario:\\n\\n|Cilindro|Cubo|Linea|\\n|---|---|---|\\n|Cono|Emanazione|Sfera|\\n\\nOgni area di effetto ha un punto di origine da cui scaturisce l'energia dell'effetto. Le regole relative a ogni forma specificano dove posizionare il punto di origine. Se tutte le linee rette che si estendono dal punto di origine fino a un punto nell'area di effetto sono bloccate, tale punto non è incluso nell'area di effetto. Per bloccare una linea, un'ostruzione deve fornire copertura totale. *Vedi anche* \\"Copertura\\".\\n\\nSe il creatore di un'area di effetto posiziona l'area in un punto che non può vedere ed è presente un'ostruzione (come ad esempio un muro) tra il creatore e quel punto, il punto di origine si forma sul lato più vicino dell'ostruzione.","page":203},"rule.weapon":{"name":"Arma","description":"Un'arma è un oggetto che rientra nella categoria delle armi semplici o da guerra. *Vedi anche* \\"Equipaggiamento\\" (\\"Armi\\").","page":203},"rule.improvised-weapons":{"name":"Armi improvvisate","description":"Un'arma improvvisata è un oggetto brandito come un'arma alla buona, quale ad esempio vetri rotti, la gamba di un tavolo o una padella. Anche un'arma semplice o da guerra conta come un'arma improvvisata se è impugnata in modo contrario al suo scopo originario; inoltre, qualora il personaggio utilizzi un'arma a distanza per effettuare un attacco in mischia o lanci un'arma da mischia priva della proprietà da lancio, l'arma conta come un'arma improvvisata. Un'arma improvvisata segue le regole illustrate di seguito:\\n\\n***Competenza.*** Il personaggio non aggiunge il bonus di competenza ai tiri per colpire con un'arma improvvisata.\\n\\n***Danni.*** Se il colpo va a segno, l'arma infligge 1d4 danni del tipo ritenuto appropriato dal GM per l'oggetto utilizzato.\\n\\n***Gittata.*** Un'arma improvvisata ha una gittata normale di 6 metri e una gittata lunga di 18 metri.\\n\\n***Equivalenti delle armi.*** Se un'arma improvvisata assomiglia a un'arma semplice o da guerra, il GM può decretarne un funzionamento analogo e usare le stesse regole di quell'arma. Per esempio, il GM può considerare la gamba di un tavolo come un randello.","page":203},"rule.round-down":{"name":"Arrotondare per difetto","description":"Ogni volta che è necessario dividere o moltiplicare un numero nel gioco, si deve arrotondare per difetto se il risultato è una frazione, anche nel caso in cui la frazione raggiunga o superi la metà. Alcune regole fanno eccezione e specificano di arrotondare per eccesso.","page":204},"rule.opportunity-attacks":{"name":"Attacchi di opportunità","description":"Il personaggio può effettuare un attacco di opportunità quando una creatura che egli è in grado di vedere esce dalla sua portata; la creatura può farlo utilizzando un'azione, un'azione bonus, una reazione o una delle sue velocità. Per sferrare l'attacco di opportunità, il personaggio effettua una reazione per eseguire un attacco in mischia con un'arma o con un colpo senz'armi contro la creatura che l'ha provocato. L'attacco avviene subito prima che la creatura esca dalla portata del personaggio. *Vedi anche* \\"Come si gioca\\" (\\"Combattimento\\").","page":204},"rule.action.attack":{"name":"Attacco [azione]","description":"Quando il personaggio effettua l'azione di Attacco, può effettuare un tiro per colpire con un'arma o con un colpo senz'armi.\\n\\n***Equipaggiarsi con le armi e riporle.*** Quando il personaggio effettua l'azione di Attacco come parte di questa azione, può anche equipaggiarsi con un'arma o riporla, decidendo se farlo prima o dopo l'attacco. Anche se il personaggio si equipaggia con un'arma prima di un attacco, non deve necessariamente usarla per quell'attacco. Equipaggiarsi con un'arma significa estrarla da un fodero o raccoglierla. Riporre un'arma significa rinfoderarla, metterla da parte o lasciarla cadere.\\n\\n***Muoversi tra un attacco e l'altro.*** Se nel suo turno il personaggio si muove e ha un privilegio come, ad esempio, Attacco extra, questo gli fornisce la possibilità di effettuare più di un attacco come parte dell'azione di Attacco: il personaggio può quindi utilizzare (in parte o interamente) il movimento che ha a disposizione per muoversi tra un attacco e l'altro.","page":204},"rule.weapon-attack":{"name":"Attacco con arma","description":"Un attacco con arma è un tiro per colpire effettuato con un'arma. *Vedi anche* \\"Arma\\".","page":204},"rule.spell-attack":{"name":"Attacco con incantesimo","description":"Un attacco con incantesimo è un tiro per colpire effettuato come parte di un incantesimo o di un altro effetto magico. *Vedi anche* \\"Incantesimi\\" (\\"Lanciare gli incantesimi\\").","page":204},"rule.attitude":{"name":"Atteggiamento","description":"Ogni mostro ha un atteggiamento iniziale verso il personaggio giocante: amichevole, ostile o indifferente. *Vedi anche* \\"Amichevole\\", \\"Ostile\\", \\"Indifferente\\" e \\"Influenza\\".","page":204},"rule.adventure":{"name":"Avventura","description":"Un'avventura consiste in una serie di incontri: giocandoci, prende vita una storia. *Vedi anche* \\"Incontro\\".","page":204},"rule.action":{"name":"Azione","description":"Nel suo turno, il tuo personaggio può effettuare un'azione, scegliendo tra quelle disponibili di seguito, o tra le azioni speciali fornite dai privilegi di cui dispone. *Vedi anche* \\"Come si gioca\\" (\\"Azioni\\"). Queste azioni sono descritte più avanti nel glossario:\\n\\n* Aiuto\\n* Attacco\\n* Disimpegno\\n* Influenza\\n* Magia\\n* Nascondersi\\n* Prepararsi\\n* Ricerca\\n* Scatto\\n* Schivata\\n* Studio\\n* Utilizzo","page":204},"rule.bonus-action":{"name":"Azione bonus","description":"Un'azione bonus è un'azione speciale che il personaggio può effettuare nello stesso turno in cui effettua un'azione. Il personaggio non può effettuare più di un'azione bonus per turno, e ne ha una a disposizione solo se una regola lo indica esplicitamente. *Vedi anche* \\"Come si gioca\\" (\\"Azioni\\").","page":205},"rule.target":{"name":"Bersaglio","description":"Un bersaglio è la creatura o l'oggetto bersagliato da un tiro per colpire, costretto da un effetto a effettuare un tiro salvezza, o selezionato per ricevere gli effetti di un incantesimo o di un altro fenomeno.","page":205},"rule.hazard.falling":{"name":"Caduta [pericolo]","description":"Una creatura che cade subisce 1d6 danni contundenti alla fine della caduta per ogni 3 metri di caduta, fino a un massimo di 20d6. Quando la creatura atterra, cade prona, a meno che non riesca a evitare di subire danni dalla caduta.\\n\\nUna creatura che cade nell'acqua o in un altro liquido può usare la sua reazione per effettuare una prova di Forza (Atletica) o di Destrezza (Acrobazia) con CD 15 per raggiungere la superficie con la testa o con i piedi. Se supera la prova, i danni eventualmente subiti dalla caduta vengono dimezzati.","page":205},"rule.campaign":{"name":"Campagna","description":"Una campagna consiste in una serie di avventure. *Vedi anche* \\"Avventura\\".","page":205},"rule.carrying-capacity":{"name":"Capacità di trasporto","description":"La taglia e il punteggio di Forza del tuo personaggio determinano il peso massimo, misurato in chilogrammi, che il personaggio può trasportare, come indicato nella tabella \\"Capacità di trasporto\\". La tabella indica anche il peso massimo che il personaggio può trascinare, sollevare o spingere.\\n\\nMentre il personaggio trascina, solleva o spinge un peso superiore a quello massimo che è capace di trasportare, la sua velocità non può superare 1,5 metri.\\n\\n**Capacità di trasporto**\\n\\n|Taglia delle creature|Trasportare|Trascinare/sollevare/spingere|\\n|---|---|---|\\n|Minuscola|For × 3,75 kg|For × 7,5 kg|\\n|Piccola/Media|For × 7,5 kg|For × 15 kg|\\n|Grande|For × 15 kg|For × 30 kg|\\n|Enorme|For × 30 kg|For × 60 kg|\\n|Mastodontica|For × 60 kg|For × 120 kg|","page":205},"rule.area-of-effect.cylinder":{"name":"Cilindro [area di effetto]","description":"Un cilindro è un'area di effetto che si estende in linee rette da un punto di origine situato al centro della parte circolare superiore o inferiore del cilindro. L'effetto che crea un cilindro specifica il raggio della base e l'altezza del cilindro.\\n\\nIl punto di origine di un cilindro è incluso nell'area di effetto.","page":205},"rule.multiclassing.armor-class":{"name":"Classe Armatura","description":"La Classe Armatura (CA) è il numero bersaglio per un tiro per colpire: rappresenta il grado di difficoltà per colpire un bersaglio.\\n\\nLa CA base del tuo personaggio si calcola sommando 10 al modificatore di Destrezza. Se una regola prevede che tu debba calcolare la CA base diversamente, scegli quale metodo adottare per definirla: non puoi usarne più di uno. *Vedi anche* \\"Tiro per colpire\\".","page":205},"rule.difficulty-class":{"name":"Classe Difficoltà","description":"La Classe Difficoltà (CD) è il numero bersaglio per una prova di caratteristica o per un tiro salvezza. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\").","page":205},"rule.damage-and-healing.critical-hits":{"name":"Colpo critico","description":"Se un tiro per colpire ottiene un 20 sul d20, metti a segno un colpo critico, e l'attacco va a segno a prescindere da qualsiasi modificatore o dalla CA del bersaglio. Un colpo critico ti consente di tirare dadi extra per i danni dell'attacco contro il bersaglio. Tira tutti i dadi di danno dell'attacco due volte e sommali, poi aggiungi gli eventuali modificatori rilevanti. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":205},"rule.unarmed-strike":{"name":"Colpo senz'armi","description":"Invece di usare un'arma per effettuare un attacco in mischia, il personaggio può sferrare un pugno, un calcio, una testata o un altro colpo violento di natura simile. In termini di gioco, questo si definisce un colpo senz'armi: un attacco in mischia che prevede l'uso del corpo per danneggiare, afferrare o spingere un bersaglio entro 1,5 metri dal personaggio.\\n\\nOgni volta che il personaggio usa un colpo senz'armi, scegli una delle seguenti opzioni per determinarne l'effetto:\\n\\n***Danni.*** Effettui un tiro per colpire contro il bersaglio. Il tuo bonus al tiro è pari al modificatore di Forza del personaggio più il bonus di competenza. Se il colpo va a segno, il bersaglio subisce danni contundenti pari a 1 più il modificatore di Forza del personaggio.\\n\\n***Presa.*** Il bersaglio deve superare un tiro salvezza su Forza o su Destrezza (a sua scelta), altrimenti viene afferrato. La CD per il tiro salvezza e per qualsiasi tentativo di sfuggire alla presa è pari a 8 più il modificatore di Forza e il bonus di competenza del personaggio. La presa è possibile solo se il bersaglio è al massimo di una taglia più grande del personaggio e se quest'ultimo ha una mano libera per afferrarlo. *Vedi anche* \\"Afferrare\\".\\n\\n***Spinta.*** Il bersaglio deve superare un tiro salvezza su Forza o su Destrezza (a sua scelta), altrimenti il personaggio lo spinge a 1,5 metri di distanza oppure lo fa diventare prono. La CD per il tiro salvezza è pari a 8 più il modificatore di Forza e il bonus di competenza del personaggio. La spinta è possibile solo se il bersaglio è al massimo di una taglia più grande del personaggio.","page":205},"rule.armor-training":{"name":"Competenza nelle armature","description":"La competenza nelle armature consente al tuo personaggio di utilizzare un'armatura di una certa categoria senza gli svantaggi illustrati di seguito. Se il personaggio indossa un'armatura leggera, media o pesante senza avere la competenza per farlo, subisce svantaggio a tutte le prove con d20 relative a Forza o Destrezza, e non può lanciare incantesimi. Se il personaggio usa uno scudo senza avere la competenza per farlo, non riceve il bonus alla CA. *Vedi anche* \\"Svantaggio\\" e \\"Equipaggiamento\\" (\\"Armatura\\").","page":206},"rule.concentration":{"name":"Concentrazione","description":"Per rimanere attivi, alcuni incantesimi e altri effetti richiedono concentrazione, come specificato nelle rispettive descrizioni. Se il creatore dell'effetto perde la concentrazione, l'effetto termina. Se l'effetto ha una durata massima, la descrizione dell'effetto specifica quanto a lungo il creatore può concentrarsi su di esso: fino a 1 minuto, 1 ora o un'altra durata. Il creatore può terminare la concentrazione in qualsiasi momento (nessuna azione richiesta). La concentrazione viene interrotta dai fattori descritti di seguito.\\n\\n***Un altro effetto di concentrazione.*** Il personaggio perde la concentrazione su un effetto nel momento in cui inizia a lanciare un incantesimo che richiede concentrazione, o se attiva un altro effetto che richiede concentrazione.\\n\\n***Danni.*** Se il personaggio subisce danni, deve effettuare un tiro salvezza su Costituzione per mantenere la concentrazione. La CD è pari a 10 o alla metà dei danni subiti (arrotondata per difetto): si sceglie il numero più alto tra i due valori, fino a una CD di massimo 30.\\n\\n***Incapacitato o morto.*** Se il personaggio è incapacitato o muore, la sua concentrazione termina.","page":206},"rule.condition":{"name":"Condizione","description":"Una condizione è uno stato di gioco temporaneo. Nella descrizione di una condizione, vengono indicati gli effetti su chi ne è affetto, e varie regole definiscono le modalità per terminarla. Nel glossario sono definite le seguenti condizioni:\\n\\n|Accecato|Incapacitato|Privo di sensi|\\n|---|---|---|\\n|Affascinato|Indebolimento|Prono|\\n|Afferrato|Invisibile|Spaventato|\\n|Assordato|Paralizzato|Stordito|\\n|Avvelenato|Pietrificato|Trattenuto|\\n\\nNon è possibile accumulare più istanze di una condizione: chi ne è affetto o ce l'ha o non ce l'ha. La condizione \\"indebolimento\\" costituisce l'eccezione alla regola.","page":206},"rule.area-of-effect.cone":{"name":"Cono [area di effetto]","description":"Un cono è un'area di effetto che si estende in linee rette da un punto di origine nella direzione scelta dal suo creatore. La larghezza del cono, misurata in un qualsiasi punto della sua lunghezza, è pari alla distanza di quel punto dal punto di origine. Per esempio, un cono è largo 4,5 metri in un determinato punto della sua lunghezza che misura 4,5 metri dal punto di origine. L'effetto che crea un cono ne specifica la lunghezza massima.\\n\\nIl punto di origine di un cono non è incluso nell'area di effetto, a meno che il suo creatore non decida altrimenti.","page":206},"rule.combat.cover":{"name":"Copertura","description":"La copertura fornisce un certo grado di protezione a un bersaglio che si trova dietro di essa. Esistono tre gradi di copertura, ognuno dei quali offre un beneficio diverso a un bersaglio: mezza copertura (bonus di +2 alla CA e ai tiri salvezza su Destrezza), tre quarti di copertura (bonus di +5 alla CA e ai tiri salvezza su Destrezza) e copertura totale (il bersaglio non può essere bersagliato direttamente). Se il bersaglio si trova dietro a più di un grado di copertura, beneficia solo del grado più protettivo. *Vedi anche* \\"Come si gioca\\" (\\"Combattimento\\").","page":206},"rule.creature":{"name":"Creatura","description":"Qualsiasi essere all'interno del gioco, incluso il personaggio di un giocatore, è una creatura. *Vedi anche* \\"Tipo di creatura\\".","page":206},"rule.area-of-effect.cube":{"name":"Cubo [area di effetto]","description":"Un cubo è un'area di effetto che si estende in linee rette da un punto di origine situato in qualsiasi punto di una faccia del cubo. L'effetto che crea un cubo ne specifica la grandezza, che è definita dalla lunghezza di ogni suo lato.\\n\\nIl punto di origine di un cubo non è incluso nell'area di effetto, a meno che il suo creatore non decida altrimenti.","page":206},"rule.hit-point-dice":{"name":"Dadi Vita","description":"I Dadi Vita aiutano a determinare i punti ferita massimi di un personaggio giocante, come spiegato in \\"Creazione del personaggio\\". Anche la maggior parte dei mostri ha i Dadi Vita. Durante un riposo breve, una creatura può spendere Dadi Vita per recuperare punti ferita. *Vedi anche* \\"Riposo breve\\".","page":207},"rule.damage":{"name":"Danni","description":"I danni rappresentano ciò che fa perdere punti ferita a creature e oggetti colpiti.","page":207},"rule.hazard.dehydration":{"name":"Disidratazione [pericolo]","description":"In base alla propria taglia, una creatura necessita di una certa quantità di acqua al giorno, come indicato nella tabella \\"Fabbisogno d'acqua giornaliero\\". Una creatura che beve meno della metà dell'acqua necessaria in un giorno ottiene 1 livello di indebolimento alla fine della giornata. L'indebolimento causato dalla disidratazione può essere rimosso solo quando la creatura beve l'intera quantità d'acqua richiesta in un giorno. *Vedi anche* \\"Indebolimento\\".\\n\\n**Fabbisogno d'acqua giornaliero**\\n\\n|Taglia|Acqua|Taglia|Acqua|\\n|---|---|---|---|\\n|Minuscola|1 litro|Grande|16 litri|\\n|Piccola|4 litri|Enorme|64 litri|\\n|Media|4 litri|Mastodontica|256 litri|","page":207},"rule.action.disengage":{"name":"Disimpegno [azione]","description":"Se il personaggio effettua un'azione di Disimpegno, il suo movimento non provoca attacchi di opportunità per il resto del turno in corso.","page":207},"rule.simultaneous-effects":{"name":"Effetti simultanei","description":"Se due o più eventi accadono nello stesso momento in un turno, a decidere l'ordine degli eventi è la persona al tavolo (giocatore o GM) che sta giocando il turno in quel momento. Ad esempio, se due effetti si applicano all'inizio del turno di un personaggio giocante, il giocatore che controlla quel personaggio decide quale dei due effetti si applica per primo.","page":207},"rule.magical-effect":{"name":"Effetto magico","description":"Un effetto si definisce \\"magico\\" se viene creato da un incantesimo, da un oggetto magico o da un fenomeno che una regola definisce come \\"magico\\".","page":207},"rule.area-of-effect.emanation":{"name":"Emanazione [area di effetto]","description":"Un'emanazione è un'area di effetto che si estende in linee rette da una creatura o da un oggetto in tutte le direzioni. L'effetto che crea un'emanazione specifica la distanza fino a cui essa si estende.\\n\\nUn'emanazione si muove insieme alla creatura o all'oggetto che ne costituisce l'origine, a meno che non si tratti di un effetto istantaneo o stazionario.\\n\\nL'origine di un'emanazione (creatura o oggetto) non è inclusa nell'area di effetto, a meno che il suo creatore non decida altrimenti.","page":207},"rule.hover":{"name":"Fluttuare","description":"Alcune creature sono in grado di fluttuare, come specificato nella loro scheda delle statistiche. Inoltre, alcuni incantesimi e altri effetti concedono l'abilità di fluttuare. Fluttuando mentre è in volo, il personaggio evita di cadere in determinate circostanze. *Vedi anche* \\"Volare\\".","page":207},"rule.spellcasting-focus":{"name":"Focus da incantatore","description":"Un focus da incantatore è un oggetto che alcune creature possono utilizzare al posto delle componenti materiali di un incantesimo solo se tali materiali non vengono consumati dall'incantesimo e non hanno un costo specificato. Alcune classi consentono ai propri membri di utilizzare tipi specifici di focus da incantatore. *Vedi anche* \\"Incantesimi\\" (\\"Lanciare gli incantesimi\\").","page":207},"rule.challenge-rating":{"name":"Grado di sfida","description":"Il grado di sfida (GS) indica quanto è grave la minaccia costituita da un mostro per un gruppo di quattro personaggi giocanti. Confronta il GS di un mostro con il livello dei personaggi. Se il GS è superiore, è probabile che il mostro costituisca un pericolo. Se il GS è inferiore, è probabile che il mostro non costituisca una seria minaccia. Tuttavia, le circostanze e il numero di personaggi giocanti possono alterare significativamente l'effettivo grado di minaccia di un mostro nel gioco. \\"Strumenti di gioco\\" (\\"Incontri di combattimento\\") fornisce una guida per il GM su come utilizzare i GS nel pianificare potenziali incontri di combattimento. *Vedi anche* \\"Scheda delle statistiche\\".","page":207},"rule.damage-and-healing.healing":{"name":"Guarigione","description":"La guarigione è il modo in cui il tuo personaggio recupera punti ferita. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":207},"rule.illusions":{"name":"Illusioni","description":"Incantesimi e altri effetti a volte creano illusioni magiche. Tali effetti definiscono cosa fa l'illusione e in che modo essa inganna i sensi o le facoltà mentali di una creatura.\\n\\nSe un'illusione si manifesta in uno spazio, è inconsistente e priva di peso, ma sembra essere influenzata dall'ambiente come se fosse reale, a meno che l'effetto che l'ha creata non specifichi diversamente. Per esempio, l'illusione visiva di una creatura proietta ombre e riflessi, e il vento sembra influenzare la creatura illusoria. Allo stesso modo, un'illusione acustica riecheggia in uno spazio che produce eco.","page":207},"rule.damage-and-healing.immunity":{"name":"Immunità","description":"Se il personaggio è immune a un tipo di danno o a una condizione, significa che non ne subisce gli effetti in alcun modo.","page":208},"rule.spell":{"name":"Incantesimo","description":"Un incantesimo è un effetto magico che ha le caratteristiche descritte in \\"Incantesimi\\".","page":208},"rule.condition.incapacitated":{"name":"Incapacitato [condizione]","description":"Quando il tuo personaggio ha la condizione \\"incapacitato\\", subisce i seguenti effetti:\\n\\n***Inattività.*** Il personaggio non è in grado di effettuare azioni, azioni bonus o reazioni.\\n\\n***Nessuna concentrazione.*** La concentrazione del personaggio è interrotta.\\n\\n***Senza parole.*** Il personaggio non è in grado di parlare.\\n\\n***Sorpresa.*** Se il personaggio è incapacitato quando tira per l'iniziativa, subisce svantaggio al tiro.","page":208},"rule.encounter":{"name":"Incontro","description":"Un incontro è una scena di un'avventura che fa parte di almeno uno dei tre pilastri del gioco: interazioni sociali, esplorazione o combattimento. *Vedi anche* \\"Come si gioca\\" (\\"Interazioni sociali\\", \\"Esplorazione\\" e \\"Combattimento\\").","page":208},"rule.condition.exhaustion":{"name":"Indebolimento [condizione]","description":"Quando il tuo personaggio ha la condizione \\"indebolimento\\", subisce i seguenti effetti:\\n\\n***Livelli di indebolimento.*** Questa condizione è cumulativa. Ogni volta che il personaggio la riceve, ottiene 1 livello di indebolimento. Il personaggio muore se il suo livello di indebolimento è pari a 6.\\n\\n***Influenza sulle prove con d20.*** Quando effettui una prova con d20, il risultato ottenuto è ridotto del doppio del livello di indebolimento del personaggio.\\n\\n***Velocità ridotta.*** La velocità del personaggio è ridotta di una quantità di metri pari a 1,5 × il suo livello di indebolimento.\\n\\n***Rimozione dei livelli di indebolimento.*** Terminando un riposo lungo, il personaggio perde 1 livello di indebolimento. Quando l'indebolimento raggiunge il livello 0, la condizione termina.","page":208},"rule.attitude.indifferent":{"name":"Indifferente [atteggiamento]","description":"Una creatura indifferente non ha alcun desiderio di aiutare o ostacolare il personaggio. L'indifferenza è l'atteggiamento predefinito dei mostri. *Vedi anche* \\"Influenza\\".","page":208},"rule.hazard.burning":{"name":"In fiamme [pericolo]","description":"Una creatura o un oggetto in fiamme subisce 1d4 danni da fuoco all'inizio di ogni suo turno. Con un'azione, un personaggio può estinguere le fiamme che lo avvolgono assumendo la condizione prono e rotolandosi sul terreno. Le fiamme si estinguono anche se vengono spente, sommerse o soffocate.","page":208},"rule.action.influence":{"name":"Influenza [azione]","description":"Con l'azione di Influenza, il personaggio esorta un mostro a fare qualcosa. Descrivi o interpreta il modo in cui interagisce con il mostro: il personaggio cerca di ingannarlo, intimidirlo, intrattenerlo o persuaderlo gentilmente? Il GM determina se, dopo l'interazione, il mostro si sente ben disposto o meno verso il personaggio, o se è esitante. In base a ciò, si stabilisce se sia necessaria una prova di caratteristica, come spiegato di seguito:\\n\\n***Ben disposto.*** Se l'esortazione del personaggio si allinea con i desideri del mostro, non è necessaria alcuna prova di caratteristica: il mostro soddisfa la richiesta del personaggio nel modo che preferisce.\\n\\n***Maldisposto.*** Se l'esortazione del personaggio è sgradita al mostro o è contraria al suo allineamento, non è necessaria alcuna prova di caratteristica: il mostro si rifiuta di soddisfare la richiesta.\\n\\n***Esitante.*** Se il personaggio esorta il mostro a fare qualcosa ma questo si mostra esitante, il personaggio deve effettuare una prova di caratteristica influenzata dall'atteggiamento del mostro: indifferente, amichevole, ostile (ciascuno dei quali è definito nel glossario). La tabella Prove di influenza indica quali prove di caratteristica effettuare in base all'interazione del personaggio con il mostro. Il GM sceglie la prova da effettuare, la quale ha una CD predefinita pari a 15 o pari al punteggio di Intelligenza del mostro (si sceglie il valore più alto tra i due). Se la prova viene superata, il mostro esegue la richiesta del personaggio. In caso di fallimento, il personaggio deve aspettare 24 ore (o un intervallo di tempo definito dal GM) prima di esortare di nuovo il mostro allo stesso modo.\\n\\n**Prove di Influenza**\\n\\n|Prova di caratteristica|Interazione|\\n|---|---|\\n|Carisma (Inganno)|Ingannare un mostro che capisce il personaggio|\\n|Carisma (Intimidire)|Intimidire un mostro|\\n|Carisma (Intrattenere)|Intrattenere un mostro|\\n|Carisma (Persuasione)|Persuadere un mostro che capisce il personaggio|\\n|Saggezza (Addestrare animali)|Persuadere gentilmente una bestia o una mostruosità|","page":208},"rule.initiative":{"name":"Iniziativa","description":"L'iniziativa determina l'ordine dei turni durante il combattimento. Le regole di combattimento in \\"Come si gioca\\" spiegano in che modo tirare per l'iniziativa.\\n\\nTalvolta, il GM potrebbe chiedere ai combattenti di utilizzare i loro punteggi di iniziativa piuttosto che tirare per l'iniziativa. Il punteggio di iniziativa è pari a 10 più il modificatore di Destrezza. Se il personaggio dispone di vantaggio ai tiri per l'iniziativa, il suo punteggio di iniziativa aumenta di 5; se invece subisce svantaggio ai tiri, il suo punteggio di iniziativa diminuisce di 5. *Vedi anche* \\"Come si gioca\\" (\\"Combattimento\\").","page":208},"rule.condition.invisible":{"name":"Invisibile [condizione]","description":"Quando il tuo personaggio ha la condizione \\"invisibile\\", subisce i seguenti effetti:\\n\\n***Sorpresa.*** Se il personaggio è invisibile quando tira per l'iniziativa, dispone di vantaggio al tiro.\\n\\n***Occultamento.*** Il personaggio non è influenzato da alcun effetto che richieda la vista del bersaglio, a meno che il creatore dell'effetto non riesca in qualche modo a vederlo. Anche l'equipaggiamento che il personaggio indossa o trasporta è occultato.\\n\\n***Influenza sugli attacchi.*** I tiri per colpire contro il personaggio subiscono svantaggio, mentre i suoi tiri per colpire dispongono di vantaggio. Se una creatura è in grado di vederlo, il personaggio non ottiene questo beneficio in relazione a quella creatura.","page":209},"rule.heroic-inspiration":{"name":"Ispirazione eroica","description":"Se un personaggio giocante ha Ispirazione eroica, può spenderla per ripetere il tiro di un dado subito dopo averlo tirato, usando obbligatoriamente il nuovo risultato ottenuto.\\n\\nSe il personaggio già possiede Ispirazione eroica e la ottiene di nuovo, quest'ultima va perduta, a meno che il personaggio non decida di donarla a un personaggio giocante che non ce l'ha.","page":209},"rule.lightly-obscured":{"name":"Leggermente oscurata","description":"Un personaggio che cerca di vedere qualcosa in un'area leggermente oscurata subisce svantaggio alle prove di Saggezza (Percezione). *Vedi anche* \\"Luce Fioca\\", \\"Oscurità\\" e \\"Come si gioca\\" (\\"Esplorazione\\").","page":209},"rule.area-of-effect.line":{"name":"Linea [area di effetto]","description":"Una linea è un'area di effetto che si estende da un punto di origine in linea retta lungo la sua lunghezza e copre un'area definita dalla sua larghezza. L'effetto che crea una linea ne specifica la lunghezza e la larghezza.\\n\\nIl punto di origine di una linea non è incluso nell'area di effetto, a meno che il suo creatore non decida altrimenti.","page":209},"rule.dim-light":{"name":"Luce fioca","description":"Un'area con luce fioca è leggermente oscurata. *Vedi anche* \\"Leggermente oscurata\\" e \\"Come si gioca\\" (\\"Esplorazione\\").","page":209},"rule.bright-light":{"name":"Luce intensa","description":"La luce intensa rappresenta la normale illuminazione. *Vedi anche* \\"Come si gioca\\" (\\"Esplorazione\\").","page":209},"rule.expertise":{"name":"Maestria","description":"La maestria è un privilegio che migliora l'uso di una competenza in un'abilità. Quando il tuo personaggio effettua una prova di caratteristica con una competenza in un'abilità in cui ha maestria, il suo bonus di competenza è raddoppiato per quella prova, a meno che il bonus non sia raddoppiato da un altro privilegio.\\n\\nSe il personaggio ottiene maestria, la ottiene in un'abilità in cui è competente. Non è possibile avere più di una maestria nella stessa competenza in un'abilità.\\n\\n*Vedi anche* \\"Come si gioca\\" (\\"Competenza\\").","page":209},"rule.action.magic":{"name":"Magia [azione]","description":"Quando il personaggio esegue l'azione di Magia, lancia un incantesimo che ha il tempo di lancio di un'azione, oppure usa un privilegio o un oggetto magico che richiede un'azione di Magia per essere attivato.\\n\\nSe il personaggio lancia un incantesimo che ha un tempo di lancio di 1 minuto o più, deve effettuare un'azione di Magia in ogni turno del lancio e, allo stesso tempo, deve mantenere la concentrazione. Se la sua concentrazione viene interrotta, l'incantesimo fallisce, ma il personaggio non consuma uno slot incantesimo. *Vedi anche* \\"Concentrazione\\".","page":209},"rule.curses":{"name":"Maledizioni","description":"Alcuni effetti di gioco maledicono creature e oggetti. L'effetto che infligge una maledizione ne definisce le conseguenze. È possibile rimuovere le maledizioni con gli incantesimi *rimuovi maledizione* e *ristorare superiore*, o con altre magie in grado di porre fine alle maledizioni.","page":209},"rule.hazard.malnutrition":{"name":"Malnutrizione [pericolo]","description":"In base alla propria taglia, una creatura necessita di una certa quantità di cibo al giorno, come indicato nella tabella \\"Fabbisogno di cibo giornaliero\\". Una creatura che mangia ma consuma meno della metà del cibo richiesto in un giorno, deve superare un tiro salvezza su Costituzione con CD 10, altrimenti ottiene 1 livello di indebolimento alla fine della giornata. Una creatura che non mangia niente per 5 giorni ottiene automaticamente 1 livello di indebolimento alla fine del quinto giorno e un livello aggiuntivo alla fine di ogni giorno successivo trascorso senza magiare.\\n\\nL'indebolimento causato dalla malnutrizione non può essere rimosso finché la creatura non mangia l'intera quantità di cibo richiesta in un giorno. *Vedi anche* \\"Indebolimento\\".\\n\\n**Fabbisogno di cibo giornaliero**\\n\\n|Taglia|Cibo|Taglia|Cibo|\\n|---|---|---|---|\\n|Minuscola|125 grammi|Grande|2 chili|\\n|Piccola|0,5 chili|Enorme|8 chili|\\n|Media|0,5 chili|Mastodontica|32 chili|","page":209},"rule.dead":{"name":"Morte","description":"Una creatura morta non ha punti ferita e non può recuperarne, a meno che non venga prima riportata in vita dalla magia, come tramite gli incantesimi *rianimare morti* e *rinascita*. Quando un incantesimo di questo tipo viene lanciato, lo spirito riconosce l'incantatore che lo sta lanciando e può rifiutarlo. Lo spirito di una creatura morta ha lasciato il suo corpo e si è recato nei Piani Esterni: per riportare in vita la creatura è necessario richiamarne lo spirito.\\n\\nSe la creatura torna in vita, l'effetto di rinascita ne determina i punti ferita attuali. Salvo diversamente indicato, la creatura ritorna in vita con tutte le condizioni, i contagi magici o le maledizioni che la affliggevano al momento della morte, se la durata di tali effetti è ancora in corso. Se la creatura è morta mentre aveva uno o più livelli di indebolimento, ritorna in vita con 1 livello in meno. Se la creatura aveva sintonia con uno o più oggetti magici, perde la sintonia con ognuno di essi.","page":210},"rule.monster":{"name":"Mostro","description":"Una creatura controllata dal GM viene definita \\"mostro\\", anche se tale creatura è benevola. *Vedi anche* \\"Creatura\\" e \\"PNG\\".","page":210},"rule.shape-shifting":{"name":"Mutaforma","description":"Se un effetto, come Forma Selvatica o l'incantesimo *metamorfosi*, consente al tuo personaggio di mutare forma, la descrizione dell'effetto specifica cosa gli accade. A meno che la descrizione non indichi diversamente, qualsiasi effetto in corso che stia influenzando il personaggio (condizioni, incantesimi, maledizioni e simili) si trasmette alla sua nuova forma. Se muore, il personaggio torna alla sua forma naturale.","page":210},"rule.action.hide":{"name":"Nascondersi [azione]","description":"Con l'azione di Nascondersi, il personaggio cerca di nascondersi. Per farlo, deve superare una prova di Destrezza (Furtività) con CD 15 mentre si trova in un'area pesantemente oscurata o dietro tre quarti di copertura o dietro copertura totale; inoltre, deve essere fuori dal campo visivo di qualsiasi nemico. Se il personaggio è in grado di vedere una creatura, può capire se anch'essa è in grado di vederlo.\\n\\nSe la prova viene superata, il personaggio ha la condizione \\"invisibile\\" finché resta nascosto. Prendi nota del risultato totale della prova: questo costituisce la CD contro cui la creatura deve superare una prova di Saggezza (Percezione) per trovare il personaggio.\\n\\nIl personaggio non è più nascosto quando si verifica uno dei seguenti eventi: il personaggio emette un suono più forte di un sussurro, effettua un tiro per colpire, lancia un incantesimo con una componente verbale o viene trovato da un nemico.","page":210},"rule.enemy":{"name":"Nemico","description":"Una creatura si definisce \\"nemica\\" se combatte contro il personaggio in combattimento, se si adopera attivamente per danneggiarlo o se si tratta di una creatura indicata come nemica dalle regole del gioco o dal GM.","page":210},"rule.swimming":{"name":"Nuotare","description":"Quando il personaggio nuota, ogni 30 centimetri di movimento costano 30 centimetri extra (60 centimetri extra in caso di terreno difficile). Se il personaggio ha una velocità di nuoto e la usa per nuotare, ignora i costi extra descritti. A discrezione del GM, se il personaggio si muove di una qualsiasi distanza in acque agitate, potrebbe dover superare una prova di Forza (Atletica) con CD 15.","page":210},"rule.object":{"name":"Oggetto","description":"Un oggetto è una cosa ben distinta e non vivente. Cose dal carattere composito, come gli edifici, comprendono più di un oggetto. *Vedi anche* \\"Rompere gli oggetti\\".","page":210},"rule.darkness":{"name":"Oscurità","description":"Un'area di oscurità è un'area pesantemente oscurata. *Vedi anche* \\"Pesantemente oscurata\\" e \\"Come si gioca\\" (\\"Esplorazione\\").","page":210},"rule.attitude.hostile":{"name":"Ostile [atteggiamento]","description":"Una creatura ostile ha un'opinione negativa del personaggio, il quale subisce svantaggio a una prova di caratteristica per influenzare una creatura ostile. *Vedi anche* \\"Influenza\\".","page":210},"rule.condition.paralyzed":{"name":"Paralizzato [condizione]","description":"Quando il tuo personaggio ha la condizione \\"paralizzato\\", subisce i seguenti effetti:\\n\\n***Incapacitato.*** Il personaggio ha la condizione \\"incapacitato\\".\\n\\n***Velocità 0.*** La velocità del personaggio è pari a 0 e non può aumentare.\\n\\n***Influenza sui tiri salvezza.*** Il personaggio fallisce automaticamente i tiri salvezza su Forza e Destrezza.\\n\\n***Influenza sugli attacchi.*** I tiri per colpire contro il personaggio dispongono di vantaggio.\\n\\n***Colpi critici automatici.*** Ogni tiro per colpire che colpisce il personaggio è un colpo critico se l'attaccante si trova entro 1,5 metri dal personaggio.","page":210},"rule.passive-perception":{"name":"Percezione passiva","description":"La Percezione passiva è un punteggio che riflette la consapevolezza generale dell'ambiente circostante da parte di una creatura. Il GM usa questo punteggio per determinare se una creatura nota qualcosa senza effettuare consapevolmente una prova di Saggezza (Percezione).\\n\\nLa Percezione passiva di una creatura è pari a 10 più il suo bonus alla prova di Saggezza (Percezione). Se la creatura dispone di vantaggio a tali prove, il punteggio di Percezione passiva aumenta di 5; se invece subisce svantaggio a tali prove, il punteggio di Percezione passiva diminuisce di 5. Per esempio, un personaggio di 1º livello con Saggezza 15 e una competenza in Percezione, ha una Percezione passiva pari a 14 (10 + 2 + 2). Se lo stesso personaggio dispone anche di vantaggio alle prove di Saggezza (Percezione), il punteggio di Percezione passiva arriva a 19.","page":211},"rule.tremorsense":{"name":"Percezione tellurica","description":"Una creatura con percezione tellurica può individuare la posizione di creature e di oggetti in movimento entro un raggio specifico, a condizione che la creatura con percezione tellurica e la creatura o oggetto individuato siano a contatto con la stessa superficie (per esempio, il terreno, una parete o un soffitto) o con lo stesso liquido.\\n\\nPercezione tellurica non è in grado di individuare creature o oggetti in aria, e non conta come forma di vista.","page":211},"rule.hazard":{"name":"Pericolo","description":"Un pericolo è un rischio ambientale. *Vedi anche* \\"Caduta\\", \\"Disidratazione\\", \\"In fiamme\\", \\"Malnutrizione\\" e \\"Soffocamento\\".","page":211},"rule.player-character":{"name":"Personaggio giocante","description":"Un personaggio giocante è un personaggio controllato da un giocatore. *Vedi anche* \\"Creazione del personaggio\\".","page":211},"rule.nonplayer-character":{"name":"Personaggio non giocante","description":"Un personaggio non giocante (PNG) è un mostro che ha un nome proprio e una personalità distinta. *Vedi anche* \\"Mostro\\".","page":211},"rule.heavily-obscured":{"name":"Pesantemente oscurata","description":"Se il personaggio cerca di scorgere qualcosa in un'area pesantemente oscurata, ha la condizione \\"accecato\\". *Vedi anche* \\"Accecato\\", \\"Oscurità\\" e \\"Come si gioca\\" (\\"Esplorazione\\").","page":211},"rule.condition.petrified":{"name":"Pietrificato [condizione]","description":"Quando il tuo personaggio ha la condizione \\"pietrificato\\", subisce i seguenti effetti:\\n\\n***Trasformazione in sostanza inanimata.*** Il personaggio viene trasformato, insieme a tutti gli oggetti non magici che indossa e trasporta, in una sostanza solida inanimata (solitamente in pietra). Il personaggio cessa di invecchiare e il suo peso viene decuplicato.\\n\\n***Incapacitato.*** Il personaggio ha la condizione \\"incapacitato\\".\\n\\n***Velocità 0.*** La velocità del personaggio è pari a 0 e non può aumentare.\\n\\n***Influenza sugli attacchi.*** I tiri per colpire contro il personaggio dispongono di vantaggio.\\n\\n***Influenza sui tiri salvezza.*** Il personaggio fallisce automaticamente i tiri salvezza su Forza e Destrezza.\\n\\n***Resistenza ai danni.*** Il personaggio è resistente a tutti i danni.\\n\\n***Immunità ai veleni.*** Il personaggio è immune alla condizione \\"avvelenato\\".","page":211},"rule.reach":{"name":"Portata","description":"Una creatura ha una portata di 1,5 metri, a meno che una regola non indichi diversamente.","page":211},"rule.possession":{"name":"Possessione","description":"Alcuni effetti fanno sì che una creatura venga posseduta da un'altra creatura o entità. Un effetto di possessione definisce in che modo questa si verifica. È possibile impedire le possessioni utilizzando l'incantesimo *protezione dal bene e dal male* ed è possibile terminarle con l'incantesimo *dissolvi il bene e il male*.","page":211},"rule.action.ready":{"name":"Prepararsi [azione]","description":"Il personaggio effettua l'azione di Prepararsi nell'attesa che si verifichi una data circostanza prima di agire. A tale scopo, nel suo turno il personaggio effettua questa azione, che gli consente di agire effettuando la sua reazione prima dell'inizio del suo turno successivo.\\n\\nPer prima cosa, il giocatore deve decidere quale circostanza percettibile innescherà la sua reazione. Poi deve scegliere quale azione effettuerà in risposta a quell'innesco, oppure può decidere di muoversi al massimo della sua velocità. Alcuni esempi includono: \\"Se il cultista passa sopra la botola, tiro la leva che la apre\\" e \\"Se lo zombi si avvicina a me, mi muovo per allontanarmi\\".\\n\\nQuando l'innesco si verifica, il personaggio può scegliere se eseguire la sua reazione non appena l'innesco si è concluso o se ignorarlo.\\n\\nQuando il personaggio prepara un incantesimo, lo lancia normalmente (spendendo le risorse utilizzate per lanciarlo) ma trattiene la sua energia, liberandola con la sua reazione quando l'innesco si verifica. Al fine di poter essere preparato, un incantesimo deve avere il tempo di lancio di 1 azione; inoltre, trattenere la magia dell'incantesimo richiede concentrazione, che il personaggio riesce a mantenere fino all'inizio del suo turno successivo. Se la concentrazione viene interrotta, l'incantesimo si dissipa senza avere effetto.","page":211},"rule.condition.unconscious":{"name":"Privo di sensi [condizione]","description":"Quando il tuo personaggio ha la condizione \\"privo di sensi\\", subisce i seguenti effetti:\\n\\n***Inerte.*** Il personaggio ha le condizioni \\"incapacitato\\" e \\"prono\\", e lascia cadere qualsiasi cosa stia impugnando. Quando la condizione termina, il personaggio resta prono.\\n\\n***Velocità 0.*** La velocità del personaggio è pari a 0 e non può aumentare.\\n\\n***Influenza sugli attacchi.*** I tiri per colpire contro il personaggio dispongono di vantaggio.\\n\\n***Influenza sui tiri salvezza.*** Il personaggio fallisce automaticamente i tiri salvezza su Forza e Destrezza.\\n\\n***Colpi critici automatici.*** Ogni tiro per colpire che colpisce il personaggio è un colpo critico se l'attaccante si trova entro 1,5 metri dal personaggio.\\n\\n***Ignaro.*** Il personaggio non è consapevole di ciò che lo circonda.","page":212},"rule.condition.prone":{"name":"Prono [condizione]","description":"Quando il tuo personaggio ha la condizione \\"prono\\", subisce i seguenti effetti:\\n\\n***Movimento limitato.*** Le uniche possibilità di movimento del personaggio sono strisciare o spendere una quantità di movimento pari alla metà della sua velocità (arrotondata per difetto) per rialzarsi e, quindi, porre fine alla condizione. Se la sua velocità è pari a 0, il personaggio non può rialzarsi.\\n\\n***Influenza sugli attacchi.*** Il personaggio subisce svantaggio ai tiri per colpire. Un tiro per colpire contro il personaggio dispone di vantaggio se l'attaccante si trova entro 1,5 metri dal personaggio. Altrimenti, il tiro per colpire subisce svantaggio.","page":212},"rule.d20-test":{"name":"Prova con D20","description":"Le prove con d20 includono i tre principali tiri con d20 presenti nel gioco: la prova di caratteristica, il tiro per colpire e il tiro salvezza. Se qualche elemento di gioco influisce sulle prove con d20, influisce su tutti e tre i tiri descritti. È il GM a determinare se una prova con d20 è giustificata in una certa circostanza. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\").","page":212},"rule.d20-tests.ability-checks":{"name":"Prova di caratteristica","description":"Una prova di caratteristica è una prova effettuata con un d20: rappresenta l'uso di una delle sei caratteristiche (o di un'abilità speciale associata a una caratteristica) al fine di superare una sfida. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\" e \\"Competenza\\").","page":212},"rule.the-six-abilities.ability-scores":{"name":"Punteggio di caratteristica e modificatore","description":"Una creatura ha sei punteggi di caratteristica (Forza, Destrezza, Costituzione, Intelligenza, Saggezza e Carisma), ognuno dei quali ha un modificatore corrispondente. Quando effettui una prova con d20 relativa a una caratteristica, o quando una regola lo richiede, aggiungi il modificatore corrispondente. *Vedi anche* \\"Come si gioca\\" (\\"Le sei caratteristiche\\").","page":212},"rule.experience-points":{"name":"Punti esperienza","description":"Superando sfide e completando avventure, i personaggi ottengono punti esperienza (PE), che vengono assegnati dal Game Master. Quando il totale dei PE di un personaggio supera una certa soglia, il livello del personaggio aumenta. *Vedi anche* \\"Avanzamento di livello\\".","page":212},"rule.damage-and-healing.hit-points":{"name":"Punti ferita","description":"I punti ferita (PF) servono a misurare quanto è difficile uccidere o distruggere una creatura o un oggetto. I danni riducono i punti ferita e la guarigione li ripristina. Un personaggio non può avere più punti ferita dei suoi punti ferita massimi, e non può averne meno di 0. *Vedi anche* \\"Rompere gli oggetti\\" e \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":212},"rule.damage-and-healing.temporary-hit-points":{"name":"Punti ferita temporanei","description":"I punti ferita temporanei sono concessi da alcuni effetti e servono ad ammortizzare la perdita dei punti ferita veri e propri. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":212},"rule.reaction":{"name":"Reazione","description":"Una reazione è un'azione speciale effettuata in risposta a una circostanza di innesco indicata nella descrizione della reazione. Il tuo personaggio può effettuare una reazione nel turno di un'altra creatura. Se effettua la reazione nel proprio turno, può comunque effettuare anche un'azione, un'azione bonus o entrambe. Una volta effettuata una reazione, il personaggio non può effettuarne un'altra fino all'inizio del suo turno successivo. L'attacco di opportunità è una reazione disponibile per tutte le creature. *Vedi anche* \\"Attacchi di opportunità\\" e \\"Come si gioca\\" (\\"Azioni\\").","page":212},"rule.resistance":{"name":"Resistenza","description":"Se un personaggio è dotato di resistenza a un tipo di danno, i danni di quel tipo che subisce sono dimezzati (arrotondando per difetto). La resistenza si applica una sola volta per ogni istanza di danno ricevuta. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":212},"rule.action.search":{"name":"Ricerca [azione]","description":"Quando il personaggio effettua l'azione di Ricerca, effettua una prova di Saggezza per discernere qualcosa che non sia ovvio. La tabella Cercare indica quali abilità sono applicabili quando si usa questa azione, in base a ciò che il personaggio sta cercando di individuare.\\n\\n**Ricerca**\\n\\n|Abilità|Elemento da individuare|\\n|---|---|\\n|Intuizione|Stato mentale di una creatura|\\n|Medicina|Malattia o causa di morte di una creatura|\\n|Percezione|Creature o oggetti nascosti|\\n|Sopravvivenza|Tracce di cibo|","page":212},"rule.short-rest":{"name":"Riposo breve","description":"Un riposo breve è un periodo di inattività della durata di 1 ora, durante il quale una creatura non svolge alcuna attività che sia più faticosa di leggere, parlare, mangiare o montare la guardia. Per iniziare un riposo breve, il personaggio deve avere almeno 1 punto ferita.\\n\\n***Benefici del riposo.*** Una volta terminato il riposo, il personaggio ottiene i seguenti benefici:\\n\\n- **Dadi Vita da spendere.** Puoi spendere uno o più dei Dadi Vita del tuo personaggio per fargli recuperare punti ferita. Per ogni Dado Vita speso in questo modo, lancia il dado e aggiungi al risultato il modificatore di Costituzione del personaggio. Il personaggio recupera un numero di punti ferita pari al totale ottenuto (il minimo è 1). Dopo ogni tiro, puoi decidere se spendere un Dado Vita aggiuntivo.\\n- **Capacità speciali.** Alcune capacità si ricaricano con un riposo breve. Se il personaggio possiede una capacità del genere, essa si ricarica nella modalità indicata nella sua descrizione.\\n\\n***Interruzione del riposo.*** Un riposo breve viene interrotto dai seguenti eventi:\\n\\n- Tirare per l'iniziativa\\n- Lanciare un incantesimo diverso da un trucchetto\\n- Subire danni\\n\\nUn riposo breve interrotto non conferisce alcun beneficio.","page":213},"rule.long-rest":{"name":"Riposo lungo","description":"Un riposo lungo è un periodo di inattività esteso (almeno 8 ore) disponibile per tutte le creature. Durante un riposo lungo, il personaggio dorme per almeno 6 ore e svolge non più di 2 ore di attività poco impegnative come leggere, parlare, mangiare o montare la guardia.\\n\\nDurante il sonno, il personaggio ha la condizione \\"privo di sensi\\". Dopo aver terminato un riposo lungo, il personaggio deve aspettare almeno 16 ore prima di poterne iniziare un altro.\\n\\n***Benefici del riposo.*** Per iniziare un riposo lungo, il personaggio deve avere almeno 1 punto ferita. Una volta terminato il riposo, ottiene i seguenti benefici:\\n\\n- **Recupero di tutti i PF.** Il personaggio recupera tutti i punti ferita perduti e tutti i Dadi Vita spesi. Se i suoi punti ferita massimi erano ridotti, ritornano alla normalità.\\n- **Ripristino dei punteggi di caratteristica.** Se uno o più punteggi di caratteristica del personaggio erano ridotti, ritornano alla normalità.\\n- **Riduzione dell'indebolimento.** Se il personaggio ha la condizione \\"indebolimento\\", questa diminuisce di 1 livello.\\n- **Capacità speciali.** Alcune capacità si ricaricano con un riposo lungo. Se il personaggio possiede una capacità del genere, essa si ricarica nella modalità indicata nella sua descrizione.\\n\\n***Interruzione del riposo.*** Un riposo lungo viene interrotto dai seguenti eventi:\\n\\n- Tirare per l'iniziativa\\n- Lanciare un incantesimo diverso da un trucchetto\\n- Subire danni\\n- 1 ora di camminata o di un altro tipo di sforzo fisico\\n\\nSe il personaggio si è riposato per almeno 1 ora prima dell'interruzione, riceve i benefici di un riposo breve. *Vedi anche* \\"Riposo breve\\".\\n\\nIl personaggio può riprendere un riposo lungo subito dopo un'interruzione. In questo caso, per essere completato, il riposo richiede 1 ora in più per ogni interruzione.","page":213},"rule.ritual":{"name":"Rituale","description":"Se il tuo personaggio ha un incantesimo con il descrittore \\"rituale\\" preparato, può lanciarlo come rituale. La versione rituale di un incantesimo richiede 10 minuti in più rispetto alla norma per essere lanciata. Inoltre non consuma uno slot incantesimo, il che significa che la versione rituale di un incantesimo non può essere lanciata a un livello superiore. *Vedi anche* \\"Incantesimi\\".","page":213},"rule.breaking-objects":{"name":"Rompere gli oggetti","description":"È possibile danneggiare gli oggetti usando attacchi o alcuni incantesimi, facendo riferimento alle regole di seguito. Se un oggetto è estremamente fragile, il GM può consentire a una creatura di romperlo automaticamente con l'azione di Attacco o di Utilizzo.\\n\\n***Classe Armatura.*** La tabella \\"Classe Armatura degli oggetti\\" indica le CA di materiali diversi.\\n\\n**Classe Armatura degli oggetti**\\n\\n|CA|Materiale|CA|Materiale|\\n|---|---|---|---|\\n|11|Stoffa, carta, corda|19|Ferro, acciaio|\\n|13|Cristallo, vetro, ghiaccio|21|Mithral|\\n|15|Legno|23|Adamantio|\\n|17|Pietra|||\\n\\n***Punti ferita.*** Un oggetto viene distrutto quando scende a 0 punti ferita. Nella tabella \\"Punti ferita degli oggetti\\" sono elencati i punti ferita suggeriti per gli oggetti fragili e resilienti di taglia Grande o inferiore. Per tenere conto dei punti ferita di un oggetto Enorme o Mastodontico, suddividilo in sezioni di taglia Grande o inferiore e annota i punti ferita di ciascuna sezione separatamente. Il GM determina se la distruzione di una parte di un oggetto lo fa crollare interamente.\\n\\n**Punti ferita degli oggetti**\\n\\n|Taglia|Fragile|Resiliente|\\n|---|---|---|\\n|Minuscola (bottiglia, serratura)|2 (1d4)|5 (2d4)|\\n|Piccola (forziere, liuto)|3 (1d6)|10 (3d6)|\\n|Media (barile, lampadario)|4 (1d8)|18 (4d8)|\\n|Grande (carro, tavolo da pranzo)|5 (1d10)|27 (5d10)|\\n\\n***Tipi di danno e oggetti.*** Gli oggetti sono immuni ai danni psichici e da veleno. Il GM può stabilire che, contro un determinato oggetto, certi tipi di danno siano più o meno efficaci. Per esempio, i danni contundenti sono efficaci nel caso si voglia spaccare qualcosa, ma non per tagliare. Gli oggetti di carta o di tessuto possono essere vulnerabili ai danni da fuoco.\\n\\n***Soglia di danno.*** Certi oggetti molto grossi, come le mura di un castello, sono sovente più resistenti e per questo possiedono una soglia di danno. *Vedi anche* \\"Soglia di danno\\".\\n\\n***Nessun punteggio di caratteristica.*** Un oggetto non possiede punteggi di caratteristica, a meno che una regola non preveda diversamente e glieli assegni. Senza punteggi di caratteristica, un oggetto non è in grado di effettuare prove di caratteristica e fallisce tutti i tiri salvezza.","page":213},"rule.jumping":{"name":"Saltare","description":"Quando il tuo personaggio salta, può compiere un salto in lungo (in orizzontale) o un salto in alto (in verticale). *Vedi anche* \\"Salto in lungo\\" e \\"Salto in alto\\".","page":214},"rule.high-jump":{"name":"Salto in alto","description":"Quando il tuo personaggio compie un salto in alto, si solleva in aria di un'altezza pari a 3 + il suo modificatore di Forza moltiplicato per 30 centimetri (minimo 0 centimetri), purché si sia mosso di almeno 3 metri a piedi immediatamente prima di saltare. Se compie un salto in alto da fermo, raggiunge solo metà di quell'altezza. In entrambi i casi, ogni 30 centimetri percorsi con il salto costano 30 centimetri di movimento.\\n\\nIl personaggio può allungare le braccia fino a metà della propria altezza durante il salto, al fine di raggiungere una distanza pari all'altezza del salto più 1,5 volte la propria altezza.","page":214},"rule.long-jump":{"name":"Salto in lungo","description":"Quando un personaggio compie un salto in lungo, copre una distanza pari al suo punteggio di Forza moltiplicato per 30 centimetri, purché si sia mosso di almeno 3 metri immediatamente prima di saltare. Se compie un salto in lungo da fermo, copre solo metà di quella distanza. In entrambi i casi, ogni 30 centimetri percorsi con il salto costano 30 centimetri di movimento.\\n\\nSe il personaggio atterra su terreno difficile, deve superare una prova di Destrezza (Acrobazia) con CD 10, altrimenti cade a terra prono.\\n\\nQuesta regola riguardo al salto in lungo presume che l'altezza del salto sia irrilevante, come per esempio nel caso di un salto oltre un corso d'acqua o un baratro. A discrezione del GM, un personaggio potrebbe dover superare una prova di Forza (Atletica) con CD 10 per superare un ostacolo basso (che non superi in altezza un quarto della distanza coperta dal salto), come una siepe o un muretto. Se fallisce, il personaggio colpisce l'ostacolo.","page":214},"rule.bloodied":{"name":"Sanguinante","description":"Una creatura è sanguinante se le rimane la metà o meno dei suoi punti ferita.","page":214},"rule.climbing":{"name":"Scalare","description":"Quando il personaggio scala, ogni 30 centimetri di movimento costano 30 centimetri extra (60 centimetri extra in caso di terreno difficile). Se il personaggio ha una velocità di scalata e la usa per scalare, ignora i costi extra descritti.\\n\\nA discrezione del GM, per scalare una superficie scivolosa o una che offra pochi appigli potrebbe essere necessario superare una prova di Forza (Atletica) con CD 15.","page":214},"rule.action.dash":{"name":"Scatto [azione]","description":"Quando il personaggio effettua l'azione di Scatto, ottiene del movimento extra per il turno in corso. Questo incremento è pari alla sua velocità, dopo avere applicato eventuali modificatori. Per esempio, se il personaggio ha una velocità di 9 metri, nel suo turno può muoversi fino a 18 metri se scatta. Se il personaggio ha una velocità di 9 metri che viene ridotta a 4,5 metri, nel suo turno può muoversi fino a 9 metri se scatta.\\n\\nSe il personaggio possiede una velocità speciale, come una velocità di volo o di nuoto, può usarla in sostituzione alla sua velocità quando effettua questa azione. Ogni volta che effettua l'azione, può scegliere quale velocità utilizzare. *Vedi anche* \\"Velocità\\".","page":214},"rule.stat-block":{"name":"Scheda delle statistiche","description":"Una scheda delle statistiche contiene le statistiche di gioco di un mostro. Ogni scheda contiene le seguenti informazioni, presentate subito dopo il nome del mostro:\\n\\n***Taglia.*** Un mostro può essere Minuscolo, Piccolo, Medio, Grande, Enorme o Mastodontico. *Vedi anche* \\"Taglia\\".\\n\\n***Tipo di creatura.*** Questa voce riporta la famiglia a cui appartiene il mostro, insieme ad altri descrittori. *Vedi anche* \\"Tipo di creatura\\".\\n\\n***Allineamento.*** Per ogni mostro viene suggerito un allineamento, ma questo può essere definito a discrezione del GM. *Vedi anche* \\"Allineamento\\".\\n\\n***CA, iniziativa e PF.*** Queste voci indicano la Classe Armatura, l'iniziativa e i punti ferita del mostro, descritti in dettaglio in \\"Come si gioca\\". Tra parentesi, dopo i punti ferita, sono indicati i Dadi Vita del mostro e, se presente, il contributo dato dalla sua caratteristica Costituzione ai suoi punti ferita. Il punteggio di iniziativa è indicato subito dopo il modificatore di iniziativa. Alcune creature che sono state create dalla magia non presentano informazioni riguardanti i Dadi Vita e l'iniziativa.\\n\\n***Velocità.*** Qui viene indicata la velocità del mostro, insieme a eventuali velocità speciali. *Vedi anche* \\"Velocità di nuoto\\", \\"Velocità di scalata\\", \\"Velocità di scavo\\" e \\"Velocità di volo\\".\\n\\n***Punteggi di caratteristica.*** In una tabella sono indicati i punteggi di caratteristica, i modificatori e i modificatori ai tiri salvezza del mostro, descritti in dettaglio in \\"Come si gioca\\".\\n\\n***Abilità.*** Questa voce elenca le competenze nelle abilità del mostro, se presenti. *Vedi anche* \\"Come si gioca\\" (\\"Competenza\\").\\n\\n***Resistenza e vulnerabilità.*** Queste voci elencano le resistenze e le vulnerabilità del mostro, se presenti. *Vedi anche* \\"Resistenza\\" e \\"Vulnerabilità\\".\\n\\n***Immunità.*** Questa sezione indica le immunità del mostro a danni e condizioni, se presenti. *Vedi anche* \\"Immunità\\".\\n\\n***Attrezzatura.*** Se il mostro ha qualsiasi tipo di equipaggiamento recuperabile o che può essere ceduto, viene indicato in questa voce.\\n\\n***Sensi.*** Questa voce elenca i sensi speciali del mostro, come la percezione passiva e la scurovisione. *Vedi anche* \\"Percezione passiva\\".\\n\\n***Lingue.*** Questa voce elenca le lingue che il mostro conosce.\\n\\n***GS.*** Il grado di sfida indica quanto è grave la minaccia costituita dal mostro ed è descritta in dettaglio in \\"Mostri\\". Subito dopo vengono indicati i punti esperienza che i personaggi ricevono per aver sconfitto il mostro, e il bonus di competenza del mostro. Alcune creature create dalla magia non hanno alcun GS. *Vedi anche* \\"Grado di sfida\\" e \\"Punti esperienza\\".\\n\\n***Tratti.*** I tratti del mostro, se presenti, sono caratteristiche sempre attive o attive solo in certe situazioni.\\n\\n***Azioni.*** Oltre alle azioni descritte nel glossario, il mostro può effettuare le azioni indicate in questa sezione. *Vedi anche* \\"Come si gioca\\" (\\"Azioni\\").\\n\\n***Azioni bonus.*** Se il mostro ha delle azioni bonus da effettuare, sono indicate in questa sezione.\\n\\n***Reazioni.*** Se il mostro può effettuare delle reazioni speciali, sono indicate in questa sezione.\\n\\n***Informazioni sull'attacco.*** La voce che descrive l'attacco di un mostro fornisce varie informazioni, a partire dal tipo di attacco (in mischia o a distanza), il bonus al tiro per colpire, la sua portata o gittata, e le conseguenze se il colpo va a segno. Un attacco è inteso contro un singolo bersaglio, a meno che la voce non indichi altrimenti.\\n\\n***Informazioni sul tiro salvezza.*** Se un effetto costringe a effettuare un tiro salvezza, la voce riferita all'effetto indica il tipo di tiro salvezza richiesto e fornisce la CD dell'incantesimo, una descrizione di quali creature devono effettuare il tiro, e le conseguenze di un tiro salvezza riuscito o fallito.\\n\\n***Informazioni sui danni.*** La scheda delle statistiche, per ogni istanza di danno, di solito fornisce sia un numero statico sia una formula che utilizza i dadi. Ad esempio, un attacco potrebbe infliggere 4 (1d4 + 2) danni se il colpo va a segno. È il GM a scegliere se far utilizzare il numero statico o la formula con i dadi in parentesi. Non bisogna utilizzare entrambi.","page":215},"rule.character-sheet":{"name":"Scheda del personaggio","description":"La scheda del personaggio è una nota digitale o cartacea che usi per tenere traccia delle informazioni sul tuo personaggio. *Vedi anche* \\"Creazione del personaggio\\".","page":215},"rule.action.dodge":{"name":"Schivata [azione]","description":"Se il personaggio effettua l'azione di Schivata, ottiene i seguenti benefici: fino all'inizio del suo turno successivo, ogni tiro per colpire effettuato contro il personaggio subisce svantaggio se il personaggio è in grado di vedere l'attaccante, e ogni suo tiro salvezza su Destrezza dispone di vantaggio.\\n\\nIl personaggio perde questi benefici se è incapacitato o se la sua velocità scende a 0.","page":215},"rule.darkvision":{"name":"Scurovisione","description":"Se il personaggio ha scurovisione, è in grado di vedere in condizioni di luce fioca, entro un raggio specificato, come se si trovasse in condizioni di luce intensa; è in grado di vedere in condizioni di oscurità, entro un raggio specificato, come se si trovasse in condizioni di luce fioca. Nell'oscurità, il personaggio riconosce i colori solamente come sfumature di grigio. *Vedi anche* \\"Come si gioca\\" (\\"Esplorazione\\").","page":215},"rule.condition.blinded":{"name":"Accecato [condizione]","description":"Quando il tuo personaggio ha la condizione \\"accecato\\", subisce i seguenti effetti:\\n\\n***Non è in grado di vedere.*** Il personaggio non è in grado di vedere e fallisce automaticamente qualsiasi prova di caratteristica che richieda l'uso della vista.\\n\\n***Influenza sugli attacchi.*** I tiri per colpire contro il personaggio dispongono di vantaggio, mentre i suoi tiri per colpire subiscono svantaggio.","page":202},"rule.condition.charmed":{"name":"Affascinato [condizione]","description":"Quando il tuo personaggio ha la condizione \\"affascinato\\", subisce i seguenti effetti:\\n\\n***Non può attaccare chi lo ha affascinato.*** Il personaggio non può attaccare chi lo ha affascinato né bersagliarlo con abilità o effetti magici dannosi.\\n\\n***Vantaggio sociale.*** Chi ha affascinato il personaggio dispone di vantaggio a qualsiasi prova di caratteristica effettuata per interagire socialmente con il personaggio.","page":202},"rule.condition.deafened":{"name":"Assordato [condizione]","description":"Quando il personaggio ha la condizione \\"assordato\\", subisce il seguente effetto:\\n\\n***Non è in grado di sentire.*** Il personaggio non è in grado di sentire e fallisce automaticamente qualsiasi prova di caratteristica che richieda l'uso dell'udito.","page":204},"rule.condition.frightened":{"name":"Spaventato","description":"Quando il tuo personaggio ha la condizione \\"spaventato\\", subisce i seguenti effetti:\\n\\nInfluenza sulle prove di caratteristica e sugli attacchi. Il personaggio subisce svantaggio alle prove di caratteristica e ai tiri per colpire finché la fonte della sua paura è nel suo campo visivo.\\n\\nNon è in grado di avvicinarsi. Il personaggio non è in grado di avvicinarsi volontariamente alla fonte della sua paura.","page":216},"rule.condition.grappled":{"name":"Afferrato [condizione]","description":"Quando il tuo personaggio ha la condizione \\"afferrato\\", subisce i seguenti effetti:\\n\\n***Velocità 0.*** La velocità del personaggio è pari a 0 e non può aumentare.\\n\\n***Influenza sugli attacchi.*** Il personaggio subisce svantaggio ai tiri per colpire contro qualsiasi bersaglio che non sia chi lo ha afferrato.\\n\\n***Movibile.*** Chi ha afferrato il personaggio, muovendosi, può trascinarlo o spostarlo, ma ogni 30 centimetri di movimento costano 30 centimetri extra, a meno che il personaggio non sia Minuscolo o più piccolo di due taglie o più rispetto a chi lo ha afferrato.","page":203},"rule.condition.poisoned":{"name":"Avvelenato [condizione]","description":"Quando il personaggio ha la condizione \\"avvelenato\\", subisce il seguente effetto:\\n\\n***Influenza sulle prove di caratteristica e sugli attacchi.*** Il personaggio subisce svantaggio ai tiri per colpire e alle prove di caratteristica.","page":204},"rule.condition.restrained":{"name":"Trattenuto","description":"Quando il tuo personaggio ha la condizione \\"trattenuto\\", subisce i seguenti effetti:\\n\\nVelocità 0. La velocità del personaggio è pari a 0 e non può aumentare.\\n\\nInfluenza sugli attacchi. I tiri per colpire contro il personaggio dispongono di vantaggio, mentre i suoi tiri per colpire subiscono svantaggio.\\n\\nInfluenza sui tiri salvezza. Il personaggio subisce svantaggio ai tiri salvezza su Destrezza.","page":218},"rule.condition.stunned":{"name":"Stordito","description":"Quando il tuo personaggio ha la condizione \\"stordito\\", subisce i seguenti effetti:\\n\\n**Incapacitato.** Il personaggio ha la condizione \\"incapacitato\\".\\n\\nInfluenza sui tiri salvezza. Il personaggio fallisce automaticamente i tiri salvezza su Forza e Destrezza.\\n\\nInfluenza sugli attacchi. I tiri per colpire contro il personaggio dispongono di vantaggio.","page":216},"rule.combat":{"name":"Combattimento","description":"Gli avventurieri incontrano molti mostri pericolosi e perversi manipolatori. In simili casi, spesso si è costretti a combattere.","page":14},"rule.combat.the-order-of-combat":{"name":"L'ordine di combattimento","description":"Un tipico incontro di combattimento è uno scontro tra due fazioni: una fulminea sequenza di colpi d'arma, finte, parate, scarti e incantesimi. Il gioco organizza il caos di un combattimento in un ciclo di round e di turni. Un round rappresenta circa 6 secondi di tempo nel mondo di gioco. Nel corso di un round, ogni partecipante al combattimento svolge un turno. L'ordine dei turni viene determinato all'inizio di un incontro di combattimento, quando tutti effettuano i tiri per l'iniziativa. Quando tutti hanno svolto un turno, se nessuna delle parti ha sconfitto l'altra, il combattimento continua con il round successivo.\\n\\n### Le fasi del combattimento\\n\\nIl combattimento si svolge seguendo queste fasi:\\n\\n- **1: Stabilire le posizioni.** Il Game Master stabilisce dove sono situati tutti i personaggi e i mostri. Tenendo presente l'ordine di marcia degli avventurieri o le posizioni che essi hanno dichiarato di raggiungere in una stanza o in un'altra area, il GM decide dove si trovano gli avversari: a che distanza e in quale direzione.\\n- **2: Tirare per l'iniziativa.** Tutti i partecipanti al combattimento tirano per l'iniziativa, determinando l'ordine di turno dei combattenti.\\n- **3: Svolgere i turni.** Ogni partecipante alla battaglia svolge un turno secondo l'ordine di iniziativa. Quando tutti i partecipanti al combattimento hanno svolto un turno, il round termina. Questa fase viene ripetuta finché il combattimento non si conclude.\\n\\n### Iniziativa\\n\\nL'iniziativa determina l'ordine dei turni durante il combattimento. Quando il combattimento inizia, ogni partecipante tira per l'iniziativa, ovvero effettua una prova di Destrezza per determinare la sua posizione nell'ordine di iniziativa. Il GM tira per i mostri. Il GM effettua un solo tiro per un intero gruppo di creature identiche, quindi tutti i membri di quel gruppo hanno la stessa iniziativa.\\n\\n***Sorpresa.*** Se un combattente viene sorpreso dall'inizio del combattimento, ha svantaggio al tiro per l'iniziativa. Per esempio, se un personaggio sbuca fuori di colpo dalla boscaglia per dare inizio a un combattimento contro un nemico ignaro della sua presenza, quel nemico è sorpreso.\\n\\n***Ordine di iniziativa.*** Il totale della prova di un combattente è il punteggio di iniziativa, anche detto semplicemente \\"iniziativa\\". Il GM elenca i combattenti, da quello con il punteggio di iniziativa più alto a quello con il punteggio più basso. Questo è l'ordine in cui agiranno nel corso di ogni round. L'ordine di iniziativa rimane lo stesso per tutti i round.\\n\\n***Parità.*** In caso di parità, il GM stabilisce l'ordine tra le creature in parità sotto il suo controllo e i giocatori decidono l'ordine tra i personaggi. Se si verifica una parità tra un mostro e un personaggio giocante, è il GM a decidere l'ordine.\\n\\n### Il turno di un personaggio\\n\\nNel proprio turno, un personaggio può muoversi di una distanza massima pari alla sua velocità ed effettuare un'azione. Il personaggio può decidere liberamente se per prima cosa vuole muoversi oppure effettuare la sua azione.\\n\\nLe azioni principali che si possono effettuare sono elencate in \\"Azioni\\" in precedenza nel capitolo \\"Come si gioca\\". Le opzioni di azione sono fornite anche dai privilegi di un personaggio e dalla scheda delle statistiche di un mostro. La sezione \\"Movimento e posizione\\", che compare più avanti nel capitolo \\"Come si gioca\\", descrive invece le regole relative al movimento.\\n\\n***Comunicazione.*** Nel corso del turno, il personaggio può comunicare in qualsiasi modo gli sia consentito tramite brevi frasi e gesti. Così facendo, non usi né la tua azione né la tua mossa.\\n\\nUna comunicazione estesa, come una spiegazione dettagliata o un tentativo di persuasione di un nemico, richiede un'azione. L'azione di Influenza è il modo principale in cui cercare di influenzare un mostro.\\n\\n***Interazioni con le cose.*** Durante il proprio movimento o la propria azione, il personaggio può interagire con un oggetto o un elemento dell'ambiente senza costi. Per esempio, potrebbe aprire una porta durante il suo movimento mentre avanza verso un avversario.\\n\\nPer interagire con un secondo oggetto è necessaria l'azione di Utilizzo. Alcuni oggetti magici e altri oggetti speciali richiedono sempre un'azione per essere utilizzati, come specificato nella loro descrizione.\\n\\nIl GM potrebbe richiedere al personaggio di usare un'azione per ognuna di queste attività quando è necessaria una certa attenzione o quando si presenta un ostacolo inconsueto. Per esempio, potrebbe chiedere di effettuare un'azione di Utilizzo per aprire una porta incastrata o per girare la manovella che consentirà di abbassare un ponte levatoio.\\n\\n***Non fare nulla nel proprio turno.*** Un personaggio può rinunciare a muoversi o a effettuare un'azione, o anche decidere di non fare nulla nel suo turno. Se non riesce a decidere cosa fare, può prendere in considerazione l'azione difensiva di Schivata o l'azione di Prepararsi per ritardare l'azione.\\n\\n### Terminare il combattimento\\n\\nIl combattimento termina quando una delle due parti viene sconfitta, ovvero quando le creature vengono uccise o messe fuori combattimento, o quando si sono arrese o sono fuggite. Il combattimento può anche terminare quando entrambe le parti sono d'accordo nel porvi fine.","page":14},"rule.combat.playing-on-a-grid":{"name":"Giocare su una griglia","description":"Se si gioca su una griglia a quadretti usando miniature e altri segnalini, si applicano le regole seguenti.\\n\\n***Quadretti.*** Ogni quadretto rappresenta 1,5 metri.\\n\\n***Velocità.*** Anziché muoversi con distanze in metri, ci si muove di quadretto in quadretto sulla griglia, misurando la velocità in segmenti da 1,5 metri. È possibile trasformare la propria velocità in quadretti dividendola per 1,5. Per esempio, una velocità di 9 metri si trasforma in una velocità di 6 quadretti. Chi fa spesso uso di una griglia può annotare la propria velocità sulla scheda del personaggio direttamente in quadretti.\\n\\n***Entrare in un quadretto.*** Per entrare in un quadretto, è necessario disporre di movimento a sufficienza. Entrare in un quadretto non occupato adiacente ortogonalmente o diagonalmente al proprio costa 1 quadretto di movimento. Un quadretto di terreno difficile ne costa invece 2. Altri effetti possono aumentare il costo di un quadretto.\\n\\n***Angoli.*** Un movimento in diagonale non può oltrepassare l'angolo di una parete, un albero grande o altri elementi del terreno che occupano uno spazio analogo.\\n\\n***Gittate.*** Per determinare la gittata tra due elementi su una griglia (che si tratti di oggetti o creature) si iniziano a contare i quadretti da un quadretto adiacente al primo elemento e si termina il conteggio sul quadretto dell'altro elemento, seguendo il percorso più breve.","page":14},"rule.combat.movement-and-position":{"name":"Movimento e posizione","description":"Durante il proprio turno, il personaggio può muoversi di una distanza massima pari alla sua velocità, ma può anche decidere di non muoversi.\\n\\nIl movimento può comprendere scalare, strisciare, saltare e nuotare (ciascuno spiegato nel \\"Glossario delle regole\\"). Queste diverse modalità di movimento possono essere combinate al modo di muoversi abituale del personaggio o possono costituire il suo intero movimento.\\n\\nComunque si muova, il personaggio deve dedurre la distanza di ogni parte del suo movimento dalla sua velocità finché non l'avrà usata tutta o non deciderà di avere concluso il suo movimento, a seconda dell'opzione che si verifica per prima.\\n\\nLa velocità di un personaggio viene determinata durante la sua creazione. La velocità di un mostro è indicata nella relativa scheda delle statistiche. Per ulteriori informazioni sulla velocità e sulle velocità speciali, come la velocità di scalata, volo o nuoto, vedi il capitolo \\"Glossario delle regole\\".\\n\\n### Terreno difficile\\n\\nI combattenti sono spesso rallentati da terreno difficile. Mobili bassi, detriti, arbusti, scalinate ripide, neve e acqua bassa sono tutti esempi di terreno difficile.\\n\\nOgni 30 centimetri di movimento su terreno difficile costano 30 centimetri extra, anche se più cose in uno stesso spazio contano come terreno difficile.\\n\\n### Spezzare il proprio movimento\\n\\nÈ possibile spezzare un movimento, utilizzando parte di esso prima e dopo qualsiasi azione, azione bonus o reazione effettuata nello stesso turno. Per esempio, se il personaggio ha una velocità di 9 metri può muoversi per 3 metri, effettuare un'azione e poi muoversi per ulteriori 6 metri.\\n\\n### Buttarsi a terra proni\\n\\nNel proprio turno, il personaggio può utilizzare la condizione prono (vedi \\"Glossario delle regole\\") senza usare un'azione o la propria velocità, ma non può farlo se la sua velocità è pari a 0.\\n\\n### Taglia delle creature\\n\\nOgni creatura appartiene a una categoria di taglia, che determina la larghezza dello spazio quadrato che la creatura occupa su una mappa, come mostrato nella tabella Taglie e spazio delle creature, che elenca le dimensioni dalla più piccola (Minuscola) alla più grande (Mastodontica). Lo spazio di una creatura è l'area che essa controlla a tutti gli effetti in combattimento, nonché l'area di cui ha bisogno per combattere con efficacia.\\n\\nLa taglia di un personaggio è determinata dalla sua specie, mentre la taglia di un mostro è specificata nella sua scheda delle statistiche.\\n\\n**Taglie e spazio delle creature**\\n\\n|Taglia|Spazio (metri)|Spazio (quadretti)|\\n|---|---|---|\\n|Minuscola|75 × 75 cm|4 per quadretto|\\n|Piccola|1,5 m × 1,5 m|1 quadretto|\\n|Media|1,5 m × 1,5 m|1 quadretto|\\n|Grande|3 m × 3 m|4 quadretti (2 per 2)|\\n|Enorme|4,5 m × 4,5 m|9 quadretti (3 per 3)|\\n|Mastodontica|6 m × 6 m|16 quadretti (4 per 4)|\\n\\n### Muoversi attorno ad altre creature\\n\\nDurante il proprio movimento, il personaggio può attraversare lo spazio di un alleato, di una creatura incapacitata (vedi \\"Glossario delle regole\\"), di una creatura di taglia Minuscola o di una creatura di due categorie di taglia più grande o più piccola rispetto a quella del personaggio.\\n\\nLo spazio di un'altra creatura è considerato terreno difficile per il personaggio, a meno che quella creatura non sia di taglia Minuscola o un alleato.\\n\\nNon è possibile terminare volontariamente il proprio movimento in uno spazio occupato da un'altra creatura. Se in qualche modo il personaggio termina il turno in uno spazio con un'altra creatura, subisce la condizione prono (vedi \\"Glossario delle regole\\") a meno che non sia di taglia Minuscola o di taglia più grande rispetto all'altra creatura.","page":15},"rule.combat.making-an-attack":{"name":"Effettuare un attacco","description":"Per attaccare, si esegue l'azione di Attacco. Anche alcune altre azioni, azioni bonus e reazioni consentono di effettuare un attacco. Che si tratti di sferrare un colpo con un'arma da mischia, usare un'arma a distanza o effettuare un tiro per colpire come parte di un incantesimo, un attacco segue questa struttura:\\n\\n- **1: Scelta di un bersaglio.** Il personaggio sceglie un bersaglio entro la gittata del suo attacco: una creatura, un oggetto o un luogo.\\n- **2: Determinare i modificatori.** Il GM determina se il bersaglio beneficia di copertura (vedi la sezione seguente) e se l'attaccante dispone di vantaggio o svantaggio contro il bersaglio. Inoltre, gli incantesimi, le capacità speciali e gli altri effetti possono applicare bonus o penalità al tuo tiro per colpire.\\n- **3: Sferrare l'attacco.** Il personaggio effettua un tiro per colpire, come descritto in precedenza in \\"Come si gioca\\". Se colpisce il bersaglio, tira per i danni, a meno che quel particolare attacco non preveda regole che specifichino diversamente. Alcuni attacchi generano effetti speciali in aggiunta o al posto dei danni.","page":16},"rule.combat.unseen-attackers-and-target":{"name":"Attaccanti e bersagli non visibili","description":"Quando il personaggio attacca un bersaglio che non è in grado di vedere, subisce svantaggio al tiro per colpire. Questo vale sia che stia tirando a indovinare la posizione del bersaglio, sia che stia prendendo di mira una creatura che è in grado di udire ma non di vedere. Se il bersaglio non si trova nel punto che il personaggio ha bersagliato, l'attacco manca automaticamente.\\n\\nQuando una creatura non è in grado di vedere il personaggio, questi dispone di vantaggio ai tiri per colpire contro tale creatura.\\n\\nSe il personaggio è nascosto ed effettua un tiro per colpire, rivela la sua posizione quando l'attacco colpisce o manca il bersaglio.","page":16},"rule.combat.ranged-attacks":{"name":"Attacchi a distanza","description":"Un personaggio effettua un attacco a distanza quando tira con un arco, lancia un'ascia o scaglia in altri modi dei proiettili allo scopo di colpire un nemico distante. Anche molti incantesimi prevedono un attacco a distanza.\\n\\n### Gittata\\n\\nUn personaggio può effettuare un attacco a distanza soltanto contro un bersaglio che si trovi entro una gittata specifica. Se un attacco a distanza (come per esempio un incantesimo) prevede una singola gittata, non è possibile attaccare un bersaglio oltre tale raggio.\\n\\nAlcuni attacchi a distanza, come quelli effettuati con un arco lungo, prevedono due gittate. Il numero più piccolo indica la gittata normale, mentre quello più grande indica la gittata lunga. Se il bersaglio si trova oltre la gittata normale, il tiro per colpire subisce svantaggio; se si trova oltre la gittata lunga, il personaggio non può attaccarlo.\\n\\n### Attacchi a distanza in combattimento ravvicinato\\n\\nColpire un bersaglio con un attacco a distanza è più difficile quando il nemico è molto vicino. Quando il personaggio effettua un tiro per colpire a distanza con un'arma, un incantesimo o altri mezzi, subisce svantaggio al tiro se si trova entro 1,5 metri da una creatura nemica non incapacitata e che sia in grado di vederlo (vedi \\"Glossario delle regole\\").","page":17},"rule.combat.melee-attacks":{"name":"Attacchi in mischia","description":"Un attacco in mischia consente di attaccare un nemico entro la portata del personaggio, e di solito prevede l'uso di un'arma impugnata o un colpo senz'armi. Molti mostri effettuano attacchi in mischia con artigli, zanne o altre parti del corpo. Anche alcuni incantesimi prevedono attacchi in mischia.\\n\\n### Portata\\n\\nUna creatura ha una portata di 1,5 metri e può quindi attaccare i bersagli entro 1,5 metri da sé quando effettua un attacco in mischia. Alcune creature possono effettuare attacchi in mischia con una portata superiore a 1,5 metri, come indicato nella loro descrizione.\\n\\n### Attacchi di opportunità\\n\\nI combattenti attendono che i nemici abbassino la guardia. Se cerchi di sfuggire o passare accanto ai nemici, questi ultimi ne approfitteranno per sferrare un attacco di opportunità.\\n\\n***Evitare un attacco di opportunità.*** È possibile evitare di provocare un attacco di opportunità effettuando l'azione di Disimpegno. Inoltre, un personaggio non provoca un attacco di opportunità quando si teletrasporta o quando viene mosso senza che usi il proprio movimento, azione, azione bonus o reazione. Ad esempio, non provoca un attacco di opportunità se un'esplosione lo scaraventa fuori dalla portata di un nemico o se cade oltre un nemico.\\n\\n***Effettuare un attacco di opportunità.*** È possibile effettuare un attacco di opportunità quando una creatura che il personaggio è in grado di vedere esce dalla sua portata. Per attaccare, il personaggio effettua una reazione per eseguire un attacco in mischia con un'arma o con un colpo senz'armi contro la creatura. L'attacco avviene poco prima che la creatura lasci la sua portata.","page":17},"rule.combat.mounted-combat":{"name":"Combattere in sella","description":"Una creatura consenziente di taglia superiore di almeno una categoria a quella di un cavaliere e dotata di un'anatomia appropriata può fungere da cavalcatura per tale personaggio, purché siano rispettate le regole seguenti.\\n\\n### Salire e smontare dalla sella\\n\\nDurante il movimento, il personaggio può salire in sella a una cavalcatura situata a 1,5 metri da sé o smontare da essa. Per farlo deve spendere un ammontare di movimento pari a metà della sua velocità (arrotondato per difetto). Per esempio, se possiede una velocità di 9 metri, spende 4,5 metri di movimento per montare a cavallo.\\n\\n### Controllare una cavalcatura\\n\\nUn personaggio può controllare una cavalcatura solo se questa è stata addestrata a tale scopo. I cavalli domestici, gli asini e le creature simili hanno ricevuto questo addestramento.\\n\\nL'iniziativa di una cavalcatura controllata cambia per coincidere con quella del personaggio nel momento in cui sale in sella. La cavalcatura si muove secondo le sue indicazioni e ha solo tre opzioni di azione: Disimpegno, Scatto e Schivata. Una cavalcatura controllata può muoversi e agire già nel turno in cui il personaggio sale in sella.\\n\\nAl contrario, una cavalcatura indipendente (che si lascia cavalcare ma ignora i comandi) mantiene il proprio posto nell'ordine di iniziativa, muovendosi e agendo a proprio piacimento.\\n\\n### Cadute\\n\\nSe un effetto fa muovere la cavalcatura contro la sua volontà quando il personaggio è in sella, quel personaggio deve superare un tiro salvezza su Destrezza con CD 10, altrimenti cadrà dalla cavalcatura, atterrando prono (vedi \\"Glossario delle regole\\") in uno spazio libero entro 1,5 metri da essa.\\n\\nSe il personaggio o la cavalcatura vengono buttati a terra proni quando il personaggio è in sella, deve effettuare lo stesso tiro salvezza.","page":17},"rule.combat.underwater-combat":{"name":"Combattere sott'acqua","description":"Un combattimento sott'acqua segue queste regole:\\n\\n### Armi ostacolate\\n\\nQuando si effettua un tiro per colpire in mischia con un'arma sott'acqua, una creatura che non ha velocità di nuoto subisce svantaggio sul tiro per colpire, a meno che l'arma non infligga danni perforanti.\\n\\nUn tiro per colpire a distanza con un'arma sott'acqua manca automaticamente un bersaglio oltre la gittata normale dell'arma, e il tiro per colpire subisce svantaggio contro un bersaglio che si trova entro la gittata normale.\\n\\n### Resistenza al fuoco\\n\\nTutto ciò che si trova sott'acqua ha resistenza ai danni da fuoco (come spiegato in \\"Danni e guarigione\\").","page":18},"rule.damage-and-healing":{"name":"Danni e guarigione","description":"Ferite e morte sono minacce frequenti, come spiegato dettagliatamente nelle seguenti regole.","page":18},"rule.damage-and-healing.resting":{"name":"Riposo","description":"Gli avventurieri non possono trascorrere ogni ora all'avventura, hanno anche bisogno di riposo. Ogni creatura può concedersi dei riposi brevi di un'ora nell'arco della giornata e un riposo lungo di 8 ore alla conclusione della giornata. Il recupero dei punti ferita è uno dei principali benefici del riposo. Il \\"Glossario delle regole\\" fornisce le regole per i riposi brevi e lunghi.","page":18},"rule.damage-and-healing.saving-throws-and-damage":{"name":"Tiri salvezza e danni","description":"I danni inflitti tramite tiri salvezza utilizzano le seguenti regole.\\n\\n### Danni contro bersagli multipli\\n\\nQuando crei un effetto dannoso che costringe due o più bersagli a effettuare tiri salvezza contro di esso contemporaneamente, tira per i danni una volta sola per tutti i bersagli. Ad esempio, quando un mago lancia *palla di fuoco*, i danni dell'incantesimo si tirano una volta sola per tutte le creature coinvolte nell'esplosione.\\n\\n### Danni dimezzati\\n\\nMolti effetti dei tiri salvezza infliggono la metà dei danni (arrotondati per difetto) quando il bersaglio supera il tiro salvezza. I danni dimezzati corrispondono alla metà dei danni che verrebbero inflitti con un tiro salvezza fallito.","page":18},"rule.damage-and-healing.resistance-and-vulnerability":{"name":"Resistenza e vulnerabilità","description":"Alcune creature e oggetti sono dotati di resistenza o vulnerabilità a determinati tipi di danno. Se un personaggio è dotato di resistenza a un tipo di danno, i danni di quel tipo che subisce sono dimezzati (arrotondando per difetto). Se un personaggio è dotato di vulnerabilità a un tipo di danno, i danni di quel tipo che subisce sono raddoppiati. Ad esempio, se possiede resistenza ai danni da freddo, tali danni sono dimezzati, mentre se possiede vulnerabilità ai danni da fuoco, tali danni sono raddoppiati.\\n\\n### Nessun accumulo\\n\\nPiù istanze di resistenza o vulnerabilità che influenzano lo stesso tipo di danno contano sempre come una sola istanza. Ad esempio, se il personaggio possiede resistenza ai danni necrotici e resistenza a tutti i danni, i danni necrotici subiti vengono ridotti della metà.\\n\\n### Ordine di applicazione\\n\\nI modificatori ai danni vengono applicati nel seguente ordine: le modifiche come bonus, penalità o moltiplicatori vengono applicate per prime; la resistenza viene applicata per seconda; la vulnerabilità viene applicata per terza.\\n\\nPer esempio, una creatura dotata di resistenza a tutti i danni e vulnerabilità ai danni da fuoco si trova all'interno di un'aura magica che riduce di 5 tutti i danni. Se subisce 28 danni da fuoco, i danni vengono prima ridotti di 5 (a 23), poi dimezzati per la resistenza della creatura (e arrotondati per difetto a 11), quindi raddoppiati per la sua vulnerabilità (a 22).","page":19},"rule.damage-and-healing.dropping-to-zero-hit-points":{"name":"Scendere a 0 punti ferita","description":"Quando una creatura scende a 0 punti ferita, muore immediatamente o perde conoscenza rimanendo priva di sensi, come spiegato di seguito.\\n\\n### Morte istantanea\\n\\nEcco i principali modi in cui una creatura può morire all'istante.\\n\\n***Morte del mostro.*** Un mostro muore nell'istante in cui scende a 0 punti ferita; tuttavia, il Game Master può ignorare questa regola per un singolo mostro e trattarlo come un personaggio.\\n\\n***Punti ferita massimi pari a 0.*** Una creatura muore se i suoi punti ferita massimi raggiungono lo 0. Alcuni effetti risucchiano l'energia vitale, riducendo i punti ferita massimi di una creatura.\\n\\n***Danni considerevoli.*** Quando i danni riducono un personaggio a 0 punti ferita e ci sono danni non utilizzati, il personaggio muore se il danno rimanente è uguale o superiore ai propri punti ferita massimi. Ad esempio, se il personaggio ha 12 punti ferita massimi, 6 punti ferita attuali e subisce 18 danni, il personaggio scende a 0 punti ferita, ma restano ancora 12 danni da applicare. In questo caso il personaggio muore, poiché 12 equivale ai suoi punti ferita massimi.\\n\\n### Scomparsa del personaggio\\n\\nSe il personaggio muore, gli altri potrebbero trovare un modo magico per riportarlo in vita, come ad esempio l'incantesimo *rianimare morti*. Altrimenti, puoi confrontarti con il GM per aggiungere un nuovo personaggio al gruppo. Il \\"Glossario delle regole\\" contiene ulteriori informazioni sulla morte.\\n\\n### Perdere conoscenza (privo di sensi)\\n\\nSe il personaggio raggiunge 0 punti ferita e non muore istantaneamente, ha la condizione privo di sensi (vedi \\"Glossario delle regole\\") finché non recupera un qualsiasi ammontare di punti ferita. Inoltre, deve effettuare tiri salvezza contro morte (vedi di seguito).\\n\\n### Tiri salvezza contro morte\\n\\nOgni volta che un personaggio inizia il suo turno a 0 punti ferita, deve effettuare un tiro salvezza contro morte per determinare se scivola ulteriormente verso la morte o si aggrappa alla vita. A differenza degli altri tiri salvezza, questo non è collegato ad alcun punteggio di caratteristica. Il personaggio è nelle mani del destino.\\n\\n***Tre tiri superati/falliti.*** Tira 1d20. Se il risultato è pari o superiore a 10, il tiro salvezza è superato. Altrimenti è fallito. Un tiro salvezza superato o fallito non ha alcun effetto in sé. Al terzo tiro salvezza superato, il personaggio diventa stabile (vedi \\"Stabilizzare un personaggio\\" di seguito). Al terzo tiro salvezza fallito, invece, il personaggio muore.\\n\\nNon è necessario che i tiri superati o falliti siano consecutivi: si tiene il conto di entrambi finché non se ne accumulano tre di un certo tipo. Il numero di entrambi i tipi torna a zero quando il personaggio recupera dei punti ferita o diventa stabile.\\n\\n***Ottenere un 1 o un 20.*** Quando il personaggio ottiene 1 come risultato al tiro del d20 per un tiro salvezza contro morte, questo equivale a due tiri falliti. Se ottiene 20 come risultato al tiro del d20, recupera 1 punto ferita.\\n\\n***Danni a 0 punti ferita.*** Se un personaggio subisce danni quando ha 0 punti ferita, questo equivale a un tiro salvezza contro morte fallito. Se i danni provengono da un colpo critico, equivalgono a due tiri salvezza contro morte falliti. Se i danni sono pari o superiori ai suoi punti ferita massimi, il personaggio muore istantaneamente.\\n\\n### Stabilizzare un personaggio\\n\\nSi può effettuare l'azione di Aiuto per cercare di stabilizzare una creatura con 0 punti ferita, superando una prova di Saggezza (Medicina) con CD 10.\\n\\nUna creatura stabile non effettua tiri salvezza contro morte, anche se ha 0 punti ferita, ma continua ad avere la condizione privo di sensi. Se la creatura subisce danni, smette di essere stabile e ricomincia a effettuare tiri salvezza contro morte. Una creatura stabile che non viene curata recupera 1 punto ferita dopo 1d4 ore.","page":19},"rule.create-your-character":{"name":"Creare il personaggio","description":"Le fasi di creazione di un personaggio sono le seguenti, ciascuna approfondita di seguito:\\n\\n- **1: Scegliere una classe.** Ogni avventuriero è membro di una classe. La classe descrive a grandi linee la vocazione di un personaggio, i suoi talenti speciali e le sue tattiche preferite.\\n- **2: Determinare le origini.** Le origini di un personaggio comprendono due elementi: il background e la specie. Come ha trascorso gli anni che lo hanno condotto a un'esistenza votata all'avventura? Chi sono i suoi antenati? È inoltre possibile scegliere le lingue del personaggio.\\n- **3: Determinare i punteggi di caratteristica.** Gran parte delle azioni del personaggio nel gioco dipende dalle sue sei caratteristiche.\\n- **4: Scegliere un allineamento.** L'allineamento corrisponde alla bussola morale del personaggio.\\n- **5: Inserire i dettagli.** Utilizzando le scelte fatte, compila i dettagli rimanenti sulla scheda del personaggio.","page":21},"rule.create-your-character.choose-class":{"name":"Fase 1: Scegliere una classe","description":"Scegli una classe e scrivila sulla scheda del personaggio. Le classi sono sintetizzate nella tabella Panoramica delle classi. Per i dettagli sulle classi, consulta il capitolo \\"Classi\\".\\n\\n**Panoramica delle classi**\\n\\n|Classe|Predilige...|Caratteristiche primarie|Complessità|\\n|---|---|---|---|\\n|Barbaro|Battaglia|Forza|Media|\\n|Bardo|Esibizione|Carisma|Alta|\\n|Chierico|Dèi|Saggezza|Media|\\n|Druido|Natura|Saggezza|Alta|\\n|Guerriero|Armi|Forza o Destrezza|Bassa|\\n|Ladro|Furtività|Destrezza|Bassa|\\n|Mago|Libri di incantesimi|Intelligenza|Media|\\n|Monaco|Combattimento senz'armi|Destrezza e Saggezza|Alta|\\n|Paladino|Difesa|Forza e Carisma|Media|\\n|Ranger|Sopravvivenza|Destrezza e Saggezza|Media|\\n|Stregone|Potere|Carisma|Alta|\\n|Warlock|Scienze occulte|Carisma|Alta|\\n\\n### Scrivere il livello\\n\\nScrivi il livello del personaggio sulla scheda del personaggio. In genere, il personaggio inizia al 1º livello e tramite le avventure a cui partecipa guadagna dei punti esperienza (PE) che gli consentono di avanzare di livello.\\n\\n***Scrivere i PE.*** Annota anche i punti esperienza. Un personaggio di livello 1 ha 0 PE.\\n\\n***Iniziare a un livello superiore.*** Il GM potrebbe farti iniziare a un livello superiore. Se parti da un livello pari o superiore al 3º, scrivi la sottoclasse scelta sulla scheda del personaggio. Per ulteriori informazioni, vedi la sezione \\"Iniziare a livelli superiori\\" più avanti nel capitolo \\"Creazione del personaggio\\".\\n\\n### Annotare la competenza nelle armature\\n\\nLa tua classe potrebbe fornirti competenza con determinate categorie di armature. Annota la competenza nelle armature sulla scheda del personaggio. La competenza in un tipo di armatura significa che quell'armatura può essere indossata in modo efficace, ottenendo da essa bonus difensivi. Le categorie di armature sono descritte nel capitolo \\"Equipaggiamento\\".","page":21},"rule.create-your-character.character-origin":{"name":"Fase 2: Origini del personaggio","description":"Per determinare le origini del personaggio è necessario scegliere un background, una specie e due lingue.\\n\\nIl background di un personaggio rappresenta il luogo e l'occupazione che lo hanno formato maggiormente. La combinazione di background, specie e lingue offre terreno fertile per l'immaginazione nel momento in cui rifletti sugli albori del personaggio.\\n\\n### Scegliere un background\\n\\nScegli il background e scrivilo sulla scheda del personaggio. Puoi scegliere un background qualsiasi tra quelli descritti nel capitolo \\"Origini dei personaggi\\". Inoltre, il GM potrebbe offrire ulteriori background come opzioni.\\n\\nIl background scelto influenza la fase 3, in cui determinerai i punteggi di caratteristica del personaggio. Se hai difficoltà nella scelta, la tabella Punteggi di caratteristica e background mostra quali background avvantaggiano determinati punteggi di caratteristica. Lì puoi trovare la caratteristica primaria della tua classe.\\n\\n**Punteggi di caratteristica e background**\\n\\n|Caratteristica|Background|\\n|---|---|\\n|Forza|Soldato|\\n|Destrezza|Soldato|\\n|Costituzione|Soldato|\\n|Intelligenza|Accolito|\\n|Saggezza|Accolito|\\n|Carisma|Accolito|\\n\\n***Registra il tuo talento.*** Un background conferisce un talento, che fornisce al personaggio particolari capacità. I talenti sono descritti nel capitolo \\"Talenti\\". Scrivi il talento sulla scheda del personaggio.\\n\\n***Annota le competenze.*** Il background fornisce competenza in due abilità e in uno strumento. Registra queste informazioni sulla scheda del personaggio.\\n\\nAnche la classe fornisce competenze. Controlla la descrizione della tua classe nel capitolo \\"Classi\\" e annota le competenze sulla scheda del personaggio.\\n\\nLa tabella dei privilegi nella descrizione della classe mostra il bonus di competenza (descritto nel capitolo \\"Come si gioca\\"), che corrisponde a +2 per un personaggio di 1º livello. Annota questo numero sulla scheda del personaggio. Nella fase 5 inserirai altri numeri legati a queste competenze.\\n\\n### Scegliere l'equipaggiamento di partenza\\n\\nSia il background che la classe forniscono l'equipaggiamento di partenza. Puoi spendere immediatamente le monete che guadagni in questa fase per acquistare l'equipaggiamento del capitolo \\"Equipaggiamento\\".\\n\\nRegistra l'equipaggiamento scelto sulla scheda del personaggio. L'equipaggiamento è descritto nel capitolo \\"Equipaggiamento\\", ma per il momento è sufficiente annotarlo e cercare le specifiche in quel capitolo più tardi. Annota le monete rimaste dopo l'acquisto dell'equipaggiamento.\\n\\n### Scegliere una specie\\n\\nScegli una specie per il personaggio. Le seguenti opzioni di specie sono descritte nel capitolo \\"Origini dei personaggi\\": Dragonide, elfo, gnomo, goliath, halfling, nano, orco, tiefling e umano. Dopo che hai scelto la specie, scrivila sulla scheda del personaggio, poi registrane i tratti.\\n\\nLa taglia e la velocità del personaggio sono determinate dalla sua specie; annotale negli appositi spazi della scheda del personaggio (è sufficiente scrivere la prima lettera della taglia).\\n\\n### Immaginare il passato e il presente\\n\\nLasciati ispirare dal background e dalla specie del personaggio per immaginare il suo passato, che ora alimenta il presente. Tienilo a mente e rispondi alle seguenti domande come se fossi il tuo personaggio:\\n\\n- Chi è la tua famiglia?\\n- Chi era il tuo più caro amico d'infanzia?\\n- Hai trascorso l'infanzia con un animale domestico?\\n- Hai una relazione romantica? Se sì, con chi?\\n- Fai parte di un'organizzazione, come una gilda o una religione? Se sì, ne sei ancora membro?\\n- Quali elementi del tuo passato ti hanno ispirato a vivere un presente votato all'avventura?\\n\\n### Scegliere le lingue\\n\\nIl personaggio conosce almeno tre lingue: il Comune più altre due lingue a sua scelta o assegnate in maniera casuale effettuando un tiro sulla tabella Lingue standard. Conoscere una lingua significa poterla usare per comunicare, leggere e scrivere. Anche la classe e altri privilegi potrebbero fornire accesso a delle lingue.\\n\\nLa tabella Lingue standard elenca le lingue più diffuse nell'ambientazione. Tutti i personaggi giocanti conoscono il Comune. Le altre lingue standard nacquero con i primi membri delle specie più importanti dell'ambientazione e da allora si sono ampiamente diffuse.\\n\\n**Lingue standard**\\n\\n|1d12|Lingua|\\n|---|---|\\n|—|Comune|\\n|1|Lingua dei segni comune|\\n|2|Draconico|\\n|3–4|Nanico|\\n|5–6|Elfico|\\n|7|Gigante|\\n|8|Gnomesco|\\n|9|Goblin|\\n|10–11|Halfling|\\n|12|Orchesco|\\n\\nLa tabella Lingue rare elenca le lingue segrete o derivate da altri piani di esistenza e quindi meno diffuse nei mondi del Piano Materiale. Alcuni privilegi permettono al personaggio di imparare una lingua rara.\\n\\n**Lingue rare**\\n\\n|Lingua|Lingua|\\n|---|---|\\n|Abissale|Primordiale*|\\n|Celestiale|Silvano|\\n|Druidico|Sottocomune|\\n|Gergo delle profondità|Gergo ladresco|\\n|Infernale||\\n\\n\\\\*Il Primordiale include i dialetti Aquan, Auran, Ignan e Terran. Le creature che parlano dialetti diversi di una stessa lingua sono in grado di comunicare tra loro.","page":21},"rule.create-your-character.ability-scores":{"name":"Fase 3: Punteggi di caratteristica","description":"Per determinare i punteggi di caratteristica del personaggio, occorre innanzitutto generare una serie di sei numeri utilizzando le istruzioni riportate di seguito e poi assegnarli alle sei caratteristiche. Il capitolo \\"Come si gioca\\" spiega il significato di ciascuna caratteristica.\\n\\n### Generare i punteggi\\n\\nDetermina i punteggi di caratteristica utilizzando uno dei tre metodi seguenti. Il GM potrebbe preferire che ne venga usato uno in particolare.\\n\\n***Serie standard.*** Utilizza i seguenti sei punteggi per le tue caratteristiche: 15, 14, 13, 12, 10, 8.\\n\\n***Generazione casuale.*** Tira quattro d6 e registra il totale dei tre dadi più alti. Poi ripeti l'operazione altre cinque volte in modo da avere sei numeri.\\n\\n***Costo in punti.*** Hai a disposizione 27 punti da spendere per i punteggi di caratteristica. Il costo di ciascun punteggio è indicato nella tabella Costi in punti del punteggio di caratteristica. Ad esempio, un punteggio di 14 costa 7 dei tuoi 27 punti.\\n\\n**Costi in punti del punteggio di caratteristica**\\n\\n|Punteggio|Costo|Punteggio|Costo|\\n|---|---|---|---|\\n|8|0|12|4|\\n|9|1|13|5|\\n|10|2|14|7|\\n|11|3|15|9|\\n\\n### Assegnare i punteggi di caratteristica\\n\\nDopo che hai generato i sei punteggi, assegnali a Forza, Destrezza, Costituzione, Intelligenza, Saggezza e Carisma, tenendo presente la caratteristica primaria della tua classe. Poi, aggiungi i modificatori di caratteristica.\\n\\nSe utilizzi l'opzione serie standard, consulta la tabella Serie standard per classe per suggerimenti su come assegnare i punteggi per la classe del tuo personaggio. La tabella riporta i punteggi più alti nelle caratteristiche principali di una classe. Se hai utilizzato un metodo diverso per generare i punteggi, puoi comunque utilizzare questa tabella per orientarti nella collocazione dei punteggi più alti e più bassi.\\n\\n**Serie standard per classe**\\n\\n|Classe|For|Des|Cos|Int|Sag|Car|\\n|---|---|---|---|---|---|---|\\n|Barbaro|15|13|14|10|12|8|\\n|Bardo|8|14|12|13|10|15|\\n|Chierico|14|8|13|10|15|12|\\n|Druido|8|12|14|13|15|10|\\n|Guerriero|15|14|13|8|10|12|\\n|Ladro|12|15|13|14|10|8|\\n|Mago|8|12|13|15|14|10|\\n|Monaco|12|15|13|10|14|8|\\n|Paladino|15|10|13|8|12|14|\\n|Ranger|12|15|13|8|14|10|\\n|Stregone|10|13|14|8|12|15|\\n|Warlock|8|14|13|12|10|15|\\n\\n### Modificare i punteggi di caratteristica\\n\\nDopo aver assegnato i punteggi di caratteristica, modificali in base al background. Il background elenca tre caratteristiche; aumenta un punteggio di 2 e un altro di 1, oppure aumenta tutti e tre i punteggi di 1. Nessuno di questi incrementi può far salire il punteggio al di sopra di 20.\\n\\nAd alcuni giocatori piace aumentare la caratteristica primaria della propria classe, mentre altri preferiscono aumentare un punteggio basso.\\n\\n### Determinare i modificatori di caratteristica\\n\\nInfine, calcola i modificatori di caratteristica del personaggio usando la tabella Punteggi di caratteristica e modificatori. Ogni modificatore va annotato accanto alla relativa caratteristica del personaggio.\\n\\n**Punteggi di caratteristica e modificatori**\\n\\n|Punteggio|Modificatore|Punteggio|Modificatore|\\n|---|---|---|---|\\n|3|−4|12–13|+1|\\n|4–5|−3|14–15|+2|\\n|6–7|−2|16–17|+3|\\n|8–9|−1|18–19|+4|\\n|10–11|+0|20|+5|","page":23},"rule.create-your-character.character-creation-details":{"name":"Fase 5: Creazione del personaggio","description":"Ora puoi compilare il resto della scheda del personaggio.\\n\\n### Registrare i privilegi di classe\\n\\nDai un'occhiata alla tabella dei privilegi della tua classe nel capitolo \\"Classi\\" e annota i privilegi di 1º livello. I privilegi di classe sono descritti in dettaglio nel medesimo capitolo.\\n\\nAlcuni privilegi di classe offrono delle scelte. Assicurati di leggere tutti i tuoi privilegi e compiere ogni scelta proposta.\\n\\n### Inserire i numeri\\n\\nAnnota questi numeri sulla scheda del personaggio.\\n\\n***Tiri salvezza.*** Per i tiri salvezza in cui hai competenza, aggiungi il bonus di competenza al modificatore di caratteristica appropriato e annota il totale. Alcuni giocatori annotano anche il modificatore per i tiri salvezza in cui non hanno competenza, che è semplicemente il relativo modificatore di caratteristica.\\n\\n***Abilità.*** Per le abilità in cui hai competenza, aggiungi il bonus di competenza al modificatore di caratteristica associato a quell'abilità e annota il totale. Potresti anche annotare il modificatore per le abilità in cui non hai competenza, che è semplicemente il relativo modificatore di caratteristica.\\n\\n***Percezione passiva.*** A volte il GM determina se il personaggio nota qualcosa senza chiedergli di effettuare una prova di Saggezza (Percezione) facendo riferimento alla Percezione passiva del personaggio. La Percezione passiva è un punteggio che rispecchia la consapevolezza generale dell'ambiente circostante quando non si sta cercando attivamente qualcosa. Utilizza questa formula per determinare il tuo punteggio di Percezione passiva:\\n\\n**Percezione passiva** = 10 + il modificatore di Saggezza (Percezione)\\n\\nIncludi tutti i modificatori che si applicano alle prove di Saggezza (Percezione). Ad esempio, se un personaggio possiede Saggezza 15 e ha competenza nell'abilità Percezione, la sua Percezione passiva sarà pari a 14 (10 + 2 per il modificatore di Saggezza + 2 per la competenza).\\n\\n***Punti ferita.*** La tua classe e il modificatore di Costituzione determinano i tuoi punti ferita massimi al 1º livello, come indicato nella tabella Punti ferita per classe al 1º livello.\\n\\n**Punti ferita per classe al 1º livello**\\n\\n|Classe|Punti ferita massimi|\\n|---|---|\\n|Barbaro|12 + modificatore di Cos|\\n|Guerriero, paladino o ranger|10 + modificatore di Cos|\\n|Bardo, chierico, druido, monaco, ladro o warlock|8 + modificatore di Cos|\\n|Stregone o mago|6 + modificatore di Cos|\\n\\nLa scheda del personaggio include uno spazio per annotare i punti ferita attuali quando si subiscono danni, nonché i punti ferita temporanei che è possibile guadagnare. Inoltre, c'è spazio per annotare i tiri salvezza contro morte.\\n\\n***Dadi Vita.*** La descrizione della classe indica il tipo di Dado Vita del personaggio; annotalo sulla scheda del personaggio. Al 1º livello, il personaggio ha 1 Dado Vita. Durante un riposo breve, si possono spendere Dadi Vita per recuperare punti ferita. La scheda del personaggio include anche uno spazio per annotare quanti Dadi Vita sono stati spesi.\\n\\n***Iniziativa.*** Annota il tuo modificatore di Destrezza nello spazio dedicato all'iniziativa sulla scheda del personaggio.\\n\\n***Classe Armatura.*** Senza armatura o scudo, la Classe Armatura base è pari a 10 più il modificatore di Destrezza. Se l'equipaggiamento di partenza comprende un'armatura o uno scudo (o entrambi), calcola la CA utilizzando le regole del capitolo \\"Equipaggiamento\\". Alcuni privilegi di classe potrebbero offrire un modo diverso per calcolare la CA.\\n\\n***Attacchi.*** Nella sezione Armi e trucchetti da combattimento della scheda del personaggio, annota le armi di partenza. Il bonus al tiro per colpire di un'arma in cui si ha competenza è uno dei seguenti, a meno che l'arma non abbia una proprietà che indichi diversamente:\\n\\n**Bonus di attacco in mischia** = il modificatore di Forza + il bonus di competenza\\n\\n**Bonus di attacco a distanza** = il modificatore di Destrezza + il bonus di competenza\\n\\nConsulta il capitolo \\"Equipaggiamento\\" per i danni e le proprietà delle armi. Aggiungi ai tiri per i danni con un'arma lo stesso modificatore di caratteristica che usi per gli attacchi con quell'arma.\\n\\n***Incantesimi.*** Annota sia la CD del tiro salvezza per i tuoi incantesimi, sia il bonus d'attacco per gli attacchi che effettui con essi, utilizzando queste formule:\\n\\n**CD del tiro salvezza sull'incantesimo** = 8 + il modificatore di caratteristica da incantatore + il bonus di competenza\\n\\n**Bonus di attacco dell'incantesimo** = il modificatore di caratteristica da incantatore + il bonus di competenza\\n\\nIl modificatore di caratteristica da incantatore per un incantesimo è determinato dal privilegio che conferisce l'abilità di lanciare l'incantesimo.\\n\\n***Slot incantesimo, trucchetti e incantesimi preparati.*** Se la classe del personaggio conferisce il privilegio Incantesimi o Magia del patto, la tabella dei privilegi di classe indica il numero di slot incantesimo disponibili, il numero di trucchetti conosciuti e il numero di incantesimi che il personaggio può preparare. Scegli i trucchetti e gli incantesimi preparati e annotali sulla scheda del personaggio insieme al numero di slot incantesimo.","page":24},"rule.create-your-character.gaining-a-level":{"name":"Acquisire un livello","description":"Quando il personaggio acquisisce un livello, segui questi passaggi:\\n\\n- **1: Scegli una classe.** La maggior parte dei personaggi avanza nella propria classe iniziale. Tuttavia, il personaggio può decidere di acquisire un livello in un'altra classe utilizzando le regole della sezione \\"Multiclasse\\".\\n- **2: Modifica i punti ferita e i Dadi Vita.** Ogni volta che il personaggio acquisisce un nuovo livello, ottiene un Dado Vita aggiuntivo. Il personaggio tira quel dado, somma il modificatore di Costituzione al risultato del tiro e aggiunge il totale (minimo di 1) al suo massimo dei punti ferita. Invece di tirare, può anche decidere di usare il valore fisso indicato nella tabella Punti ferita fissi per classe.\\n\\n**Punti ferita fissi per classe**\\n\\n|Classe|Punti ferita per livello|\\n|---|---|\\n|Barbaro|7 + modificatore di Cos|\\n|Guerriero, paladino o ranger|6 + modificatore di Cos|\\n|Bardo, chierico, druido, monaco, ladro o warlock|5 + modificatore di Cos|\\n|Stregone o mago|4 + modificatore di Cos|\\n\\n- **3: Registra nuovi privilegi di classe.** Dai un'occhiata alla tabella dei privilegi di classe nel capitolo \\"Classi\\" e annota i privilegi che il personaggio acquisisce avanzando di livello in quella classe. Il personaggio può compiere qualsiasi scelta offerta dal nuovo privilegio.\\n- **4: Modifica il bonus di competenza.** Il bonus di competenza di un personaggio aumenta a certi livelli, come indicato nella tabella Avanzamento dei personaggi e nella tabella dei privilegi di classe del capitolo \\"Classi\\". Quando il bonus di competenza aumenta, aumentano tutti i numeri della scheda del personaggio che includono il bonus di competenza.\\n- **5: Modifica i modificatori di caratteristica.** Scegliendo un talento che fa aumentare uno o più punteggi di caratteristica, se il nuovo punteggio è un numero pari cambia anche il modificatore di caratteristica. Quando ciò accade, modifica tutti i numeri della scheda del personaggio che utilizzano quel modificatore di caratteristica. Quando il modificatore di Costituzione del personaggio aumenta di 1, i punti ferita massimi aumentano di 1 per ogni livello acquisito. Ad esempio, se un personaggio raggiunge l'8º livello e il suo punteggio di Costituzione aumenta da 17 a 18, il modificatore di Costituzione aumenta a +4. I punti ferita massimi del personaggio aumentano di 8, in aggiunta ai punti ferita guadagnati per aver raggiunto l'8º livello.","page":26},"rule.create-your-character.starting-at-higher-levels":{"name":"Iniziare a livelli superiori","description":"Il GM potrebbe far partire i personaggi del gruppo da un livello superiore al 1º. In particolare, è consigliato iniziare dal 3º livello se il gruppo è composto da giocatori esperti di D&D.\\n\\n### Creare il personaggio\\n\\nLa creazione di un personaggio di livello superiore comprende le stesse fasi descritte in questo capitolo, nonché le regole di avanzamento oltre il 1º livello fornite nella sezione \\"Avanzamento di livello\\". Si inizia con il numero minimo di PE necessari per raggiungere il livello di partenza. Ad esempio, se il GM fa iniziare i giocatori al 10º livello, i personaggi avranno 64.000 PE.\\n\\n> **Talenti bonus al 20º livello**\\n>\\n> Dopo che i personaggi hanno raggiunto il 20º livello, il GM può utilizzare i talenti come forma di avanzamento per conferire maggiori poteri ai personaggi che non hanno più livelli da acquisire. Con questo approccio, ogni personaggio ottiene un talento a scelta per ogni 30.000 PE guadagnati oltre i 355.000 PE. Sebbene i talenti Dono epico siano specialmente adatti per questi talenti bonus, il giocatore può scegliere qualsiasi talento per cui il suo personaggio di 20º livello sia idoneo.\\n\\n### Equipaggiamento iniziale\\n\\nIl GM decide se il personaggio inizia con un equipaggiamento superiore a quello standard per un personaggio di 1º livello, eventualmente anche con uno o più oggetti magici. La tabella Equipaggiamento di partenza a livelli superiori funge da guida per il GM.\\n\\nPuoi anche verificare con il GM quale equipaggiamento puoi comprare con il tuo denaro iniziale. Ad esempio, le armi da fuoco descritte nel capitolo \\"Equipaggiamento\\" sono troppo costose per i personaggi di 1º livello, ma potrebbe essere possibile acquistarle se il GM lo consente.\\n\\n**Equipaggiamento di partenza a livelli superiori**\\n\\n|Livello di partenza|Equipaggiamento e denaro|Oggetti magici|\\n|---|---|---|\\n|2–4|Equipaggiamento di partenza ordinario|1 comune|\\n|5–10|500 mo più 1d10 × 25 mo più equipaggiamento di partenza ordinario|1 comune, 1 non comune|\\n|11–16|5.000 mo più 1d10 × 250 mo più equipaggiamento di partenza ordinario|2 comuni, 3 non comuni, 1 raro|\\n|17–20|20.000 mo più 1d10 × 250 mo più equipaggiamento di partenza ordinario|2 comuni, 4 non comuni, 3 rari, 1 molto raro|","page":27},"rule.multiclassing":{"name":"Multiclasse","description":"L'avanzamento multiclasse consente a un personaggio di acquisire livelli in più classi. Grazie a questa regola, un personaggio può acquisire un livello in una nuova classe ogni volta che avanza di livello, anziché guadagnare un livello nella sua classe attuale. In questo modo, è possibile combinare le abilità di quelle classi per realizzare un tipo di personaggio che potrebbe non essere rappresentato a dovere da una singola classe.","page":27},"rule.multiclassing.prerequisties":{"name":"Prerequisiti","description":"Per essere idoneo a una nuova classe, un personaggio deve avere un punteggio pari o superiore a 13 nella caratteristica primaria della nuova classe e nelle classi attuali. Ad esempio, un barbaro che decide di diventare multiclasse acquisendo la classe del druido deve possedere sia un punteggio di Forza che un punteggio di Saggezza pari o superiori a 13, poiché la Forza è la caratteristica primaria dei barbari e la saggezza è la caratteristica primaria dei druidi.","page":27},"rule.multiclassing.experience-points":{"name":"Punti esperienza","description":"Il costo in punti esperienza per acquisire un livello è basato sul livello totale del personaggio, come indicato nella tabella Avanzamento dei personaggi nel capitolo \\"Creazione del personaggio\\", e non sul suo livello in una particolare classe. Per esempio, un personaggio multiclasse chierico 6/guerriero 1 deve accumulare abbastanza PE per arrivare all'8º livello prima di poter acquisire il suo secondo livello come guerriero o il suo settimo livello come chierico.","page":27},"rule.multiclassing.hit-points":{"name":"Punti ferita e Dadi Vita","description":"Il personaggio ottiene i punti ferita della sua nuova classe come descritto per i livelli successivi al 1º. Si ottengono punti ferita di 1º livello per una classe solo quando il livello totale del personaggio corrisponde al 1º.\\n\\nIl personaggio somma i Dadi Vita conferitigli da tutte le sue classi per formare la sua riserva di Dadi Vita. Se i dadi sono dello stesso tipo, può semplicemente raggrupparli in un unico insieme. Per esempio, sia il guerriero che il paladino hanno un Dado Vita d10, quindi un personaggio multiclasse guerriero 5/paladino 5 avrà dieci Dadi Vita d10. Se le sue classi gli forniscono Dadi Vita di tipi diversi, dovrà annotarli separatamente. Per esempio, un personaggio multiclasse chierico 5/paladino 5 avrà cinque Dadi Vita d8 e cinque Dadi Vita d10.","page":27},"rule.multiclassing.proficiencies":{"name":"Competenze","description":"Quando un personaggio ottiene il suo primo livello in una classe diversa dalla sua classe iniziale, riceve soltanto alcune delle nuove competenze di partenza della nuova classe, come indicato nella descrizione di ogni classe nel capitolo \\"Classi\\".","page":28},"rule.multiclassing.class-features":{"name":"Privilegi di classe","description":"Quando un personaggio ottiene un nuovo livello in una classe, ottiene i privilegi di quella classe relativi a quel livello. Alcuni privilegi hanno regole aggiuntive quando il personaggio è multiclasse. Controlla le informazioni sui personaggi multiclasse incluse nelle descrizioni di ciascuna classe.\\n\\nLe regole speciali si applicano ai privilegi Attacco extra, Incantesimi e ai privilegi (come Difesa senza armatura) che offrono modi alternativi per calcolare la Classe Armatura.","page":28},"rule.multiclassing.extra-attack":{"name":"Attacco extra","description":"Se il personaggio ottiene il privilegio Attacco extra da più di una classe, i privilegi non sono cumulativi. Non può effettuare più di due attacchi con questo privilegio, a meno che non abbia un privilegio che lo preveda (come Due attacchi extra del guerriero).\\n\\nAnalogamente, l'invocazione Lama assetata del warlock, che concede il privilegio Attacco extra con l'arma del patto, non conferisce attacchi aggiuntivi se si ha anche Attacco extra.","page":28},"rule.multiclassing.spellcasting":{"name":"Incantesimi","description":"Le capacità da incantatore del personaggio dipendono in parte dai suoi livelli combinati in tutte le sue classi da incantatore e in parte dai suoi livelli individuali in quelle classi. Una volta ottenuto il privilegio Incantesimi da più di una classe, il personaggio usa le regole sottostanti. Se un personaggio multiclasse possiede il privilegio Incantesimi soltanto da una classe, segue le regole descritte in quella classe.\\n\\n***Incantesimi preparati.*** Il personaggio determina gli incantesimi che può preparare per ogni classe separatamente, come se fosse un membro monoclasse appartenente a quella classe. Per esempio, un personaggio multiclasse ranger 4/stregone 3 può preparare cinque incantesimi da ranger di 1º livello e sei incantesimi da stregone di 1º o 2º livello (oltre a quattro trucchetti da stregone).\\n\\nOgni incantesimo che il personaggio prepara è associato a una delle sue classi; il personaggio userà la caratteristica da incantatore di quella classe quando lancia l'incantesimo.\\n\\n***Trucchetti.*** Se un trucchetto aumenta di potenza a livelli superiori, l'incremento si basa sul livello totale del personaggio, non sul livello in una classe particolare, a meno che l'incantesimo non indichi diversamente.\\n\\n***Slot incantesimo.*** Per determinare gli slot incantesimo disponibili, il personaggio somma i seguenti valori:\\n\\n- Tutti i suoi livelli nelle classi del bardo, chierico, druido, stregone e mago\\n- Metà dei suoi livelli (arrotondati per eccesso) nelle classi del paladino e del ranger\\n\\nCercherà poi questo totale nella colonna Livello della tabella Incantatore multiclasse. Il personaggio utilizza gli slot di quel livello per lanciare incantesimi del livello appropriato da qualsiasi classe di cui possiede il privilegio Incantesimi.\\n\\nQuesta tabella potrebbe fornire al personaggio slot incantesimo di livello superiore a quello degli incantesimi preparati. Può usare quegli slot, ma soltanto per lanciare i suoi incantesimi di livello inferiore. Se un incantesimo di livello inferiore da lui lanciato, come *mani brucianti*, prevede un effetto potenziato se lanciato con uno slot di livello superiore, il personaggio può usare l'effetto potenziato come di consueto.\\n\\nPer esempio, un personaggio multiclasse ranger 4/stregone 3 è considerato un personaggio di 5º livello al fine di determinare i suoi slot incantesimo, contando tutti i livelli da stregone e metà dei livelli da ranger. Come indicato nella tabella Incantatore multiclasse, il personaggio possiede quattro slot incantesimo di 1º livello, tre slot di 2º livello e due slot di 3º livello. Tuttavia, non può preparare alcun incantesimo di 3º livello, né alcun incantesimo da ranger di 2º livello. Può usare gli slot incantesimo di quei livelli per lanciare gli incantesimi che prepara e, se lo desidera, potenziare i loro effetti.\\n\\n***Magia del patto.*** Se il personaggio possiede il privilegio Magia del patto della classe warlock e il privilegio Incantesimi, può usare gli slot incantesimo che ottiene dalla Magia del patto per lanciare gli incantesimi che ha preparato dalle classi con il privilegio Incantesimi. Inoltre, può usare gli slot incantesimo che ottiene dal privilegio Incantesimi per lanciare gli incantesimi da warlock che ha preparato.\\n\\n**Incantatore multiclasse: slot incantesimo per livello di incantesimo**\\n\\n|Livello|1|2|3|4|5|6|7|8|9|\\n|---|---|---|---|---|---|---|---|---|---|\\n|1|2|—|—|—|—|—|—|—|—|\\n|2|3|—|—|—|—|—|—|—|—|\\n|3|4|2|—|—|—|—|—|—|—|\\n|4|4|3|—|—|—|—|—|—|—|\\n|5|4|3|2|—|—|—|—|—|—|\\n|6|4|3|3|—|—|—|—|—|—|\\n|7|4|3|3|1|—|—|—|—|—|\\n|8|4|3|3|2|—|—|—|—|—|\\n|9|4|3|3|3|1|—|—|—|—|\\n|10|4|3|3|3|2|—|—|—|—|\\n|11|4|3|3|3|2|1|—|—|—|\\n|12|4|3|3|3|2|1|—|—|—|\\n|13|4|3|3|3|2|1|1|—|—|\\n|14|4|3|3|3|2|1|1|—|—|\\n|15|4|3|3|3|2|1|1|1|—|\\n|16|4|3|3|3|2|1|1|1|—|\\n|17|4|3|3|3|2|1|1|1|1|\\n|18|4|3|3|3|3|1|1|1|1|\\n|19|4|3|3|3|3|2|1|1|1|\\n|20|4|3|3|3|3|2|2|1|1|","page":28},"rule.trinkets":{"name":"Monili","description":"Quando crei il personaggio, puoi tirare una volta sulla tabella Monili per ottenere un monile minuscolo, un oggetto semplice e avvolto da un sottile velo di mistero. Anche il GM potrebbe utilizzare questa tabella per rifornire la stanza di un dungeon o per riempire le tasche di una creatura.\\n\\n**Monili**\\n\\n|1d100|Monile|\\n|---|---|\\n|01|Una mano di goblin mummificata|\\n|02|Un frammento di cristallo che risplende debolmente alla luce della luna|\\n|03|Una moneta d'oro forgiata in una terra ignota|\\n|04|Un diario scritto in una lingua ignota|\\n|05|Un anello di ottone che non si consuma mai|\\n|06|Un vecchio pezzo degli scacchi fatto in vetro|\\n|07|Un paio di dadi fatto in ossa di falange; ognuno mostra il simbolo di un teschio sul lato che normalmente mostrerebbe sei punti|\\n|08|Un piccolo idolo che raffigura una creatura da incubo e fa fare brutti sogni a chi dorme nelle sue vicinanze|\\n|09|Una ciocca di capelli|\\n|10|L'atto di proprietà di un appezzamento di terra in un reame sconosciuto|\\n|11|Un cubetto fatto di un materiale sconosciuto del peso di 30 grammi|\\n|12|Una piccola bambola di pezza trafitta da aghi|\\n|13|Una zanna di una bestia sconosciuta|\\n|14|Una scaglia enorme, forse appartenente a un drago|\\n|15|Una sgargiante piuma verde|\\n|16|Una vecchia carta da chiromante su cui compare il ritratto del personaggio|\\n|17|Un globo di vetro pieno di sbuffi di fumo|\\n|18|Un uovo da mezzo chilo dal guscio color rosso chiaro|\\n|19|Un tubo per soffiare bolle di sapone|\\n|20|Un vaso di vetro che contiene uno strano pezzo di carne immerso in un liquido conservante|\\n|21|Un carillon di fattura gnomesca il cui motivo richiama vagamente una melodia che il personaggio ricorda dall'infanzia|\\n|22|Una statuetta di legno con le fattezze di un halfling strafottente|\\n|23|Un globo di ottone ricoperto di strane incisioni runiche|\\n|24|Un disco di pietra multicolore|\\n|25|Un'icona d'argento a forma di corvo|\\n|26|Un sacchetto contenente quarantasette denti, tra cui uno marcio|\\n|27|Un frammento di ossidiana che risulta sempre caldo al tatto|\\n|28|Un artiglio di drago che pende da una collana in cuoio|\\n|29|Un paio di vecchi calzini|\\n|30|Un libro vuoto le cui pagine non si lasciano sporcare da inchiostro, gesso, grafite o qualsiasi altra sostanza o segno|\\n|31|Un distintivo d'argento a forma di una stella a cinque punte|\\n|32|Un coltello appartenuto a un parente|\\n|33|Una fiala di vetro piena di unghie tagliate|\\n|34|Un congegno di metallo rettangolare con due minuscole coppe di metallo a un'estremità che emettono scintille quando bagnate|\\n|35|Un guanto bianco ricoperto di lustrini della taglia di un umano|\\n|36|Una veste con cento minuscole tasche|\\n|37|Una pietra priva di peso|\\n|38|Un ritratto appena abbozzato di un goblin|\\n|39|Una fiala di vetro vuota che emana un buon profumo|\\n|40|Una gemma che sembra un pezzo di carbone quando viene esaminata da chiunque al di fuori del personaggio|\\n|41|Un pezzo di stoffa strappato di una vecchia bandiera|\\n|42|Una mostrina dei gradi di un legionario scomparso|\\n|43|Un campanello d'argento senza batacchio|\\n|44|Una lampada con all'interno un canarino meccanico|\\n|45|Uno scrigno in miniatura scolpito per apparire dotato di numerose zampe alla base|\\n|46|Uno spiritello morto all'interno di una bottiglia di vetro trasparente|\\n|47|Un cilindro di metallo privo di qualsiasi apertura ma che sembra pieno di un liquido, di sabbia, di ragni o di vetri rotti (a scelta del giocatore)|\\n|48|Un globo di vetro pieno d'acqua al cui interno nuota un pesce rosso meccanico|\\n|49|Un cucchiaio d'argento con una M incisa sul manico|\\n|50|Un fischietto in legno dorato|\\n|51|Uno scarabeo morto, grande quanto la mano di un uomo|\\n|52|Due soldatini giocattolo, di cui uno privo della testa|\\n|53|Uno scrigno pieno di bottoni di tutte le taglie|\\n|54|Una candela impossibile da accendere|\\n|55|Una minuscola gabbia priva di porticina|\\n|56|Una vecchia chiave|\\n|57|Una mappa del tesoro indecifrabile|\\n|58|L'elsa di una spada infranta|\\n|59|Una zampa di coniglio|\\n|60|Un occhio di vetro|\\n|61|Un medaglione contenente il ritratto di una persona orribile|\\n|62|Un teschio d'argento grande come una moneta|\\n|63|Una maschera di alabastro|\\n|64|Un cono di incenso nero appiccicoso e dal pessimo odore|\\n|65|Un berretto da notte che, quando indossato, fa fare al portatore sogni piacevoli|\\n|66|Un singolo tribolo fatto d'osso|\\n|67|La montatura di un monocolo dorato privo di lente|\\n|68|Un cubo con spigolo di 2,5 cm, con ogni faccia dipinta di un colore diverso|\\n|69|Una maniglia di cristallo di una porta|\\n|70|Un pacchetto pieno di polvere rosa|\\n|71|Una strofa di una magnifica canzone, scritta come una serie di note musicali su due frammenti di pergamena|\\n|72|Un orecchino d'argento a forma di goccia contenente una vera lacrima|\\n|73|Il guscio di un uovo su cui sono raffigurate scene di varie disgrazie dipinte con inquietante precisione|\\n|74|Un ventaglio che, una volta aperto, mostra un gatto addormentato|\\n|75|Una serie di flauti in osso|\\n|76|Un quadrifoglio custodito tra le pagine di un manuale di galateo|\\n|77|Una pergamena su cui è stato disegnato un marchingegno meccanico|\\n|78|Un elegante fodero che non si adatta a nessuna lama che il personaggio abbia mai visto|\\n|79|Un invito a una festa a cui è stato commesso un delitto|\\n|80|Un pentacolo di bronzo con l'immagine di una testa di ratto incisa al centro|\\n|81|Un fazzoletto viola su cui è stato ricamato il nome di un potente arcimago|\\n|82|Metà della planimetria di un tempio, un castello o una struttura di altro tipo|\\n|83|Un pezzo di stoffa ripiegato che, una volta spiegato, si trasforma in un elegante mantello|\\n|84|La ricevuta di un deposito presso una banca di una città molto lontana|\\n|85|Un diario con sette pagine mancanti|\\n|86|Una tabacchiera d'argento vuota con la scritta \\"sogni\\" incisa sul coperchio|\\n|87|Un simbolo sacro in ferro dedicato a un dio sconosciuto|\\n|88|Un libro che racconta la storia dell'ascesa e della caduta di un eroe leggendario, privo dell'ultimo capitolo|\\n|89|Una fiala di sangue di drago|\\n|90|Un'antica freccia di fattura elfica|\\n|91|Un ago impossibile da piegare|\\n|92|Un'elegante spilla di fattura nanica|\\n|93|Una bottiglia di vino vuota con un'elegante etichetta che recita \\"Enoteca del Mago dei Vini, Torchietto del drago, 331422-W\\"|\\n|94|La tessera di un mosaico dalla superficie lucida e multicolore|\\n|95|Un topo pietrificato|\\n|96|Una bandiera nera da pirata decorata con le tibie incrociate e il teschio di un drago|\\n|97|Un minuscolo granchio o ragno meccanico che si anima e si sposta quando nessuno lo osserva|\\n|98|Un vaso di vetro pieno di lardo con un'etichetta che recita: \\"Grasso di Grifone\\"|\\n|99|Uno scrigno di legno con il fondo di ceramica che contiene un verme vivo con una testa a ogni estremità del suo corpo|\\n|00|Un'urna di metallo contenente le ceneri di un eroe|","page":29},"rule.rhythm-of-play":{"name":"Ritmo di gioco","description":"I tre pilastri principali di D&D sono le interazioni sociali, l'esplorazione e il combattimento. Qualunque sia l'esperienza, il gioco si sviluppa secondo questo schema di base:\\n\\n- **1: Il Game Master descrive una scena.** Il GM descrive ai giocatori il luogo in cui si trovano i rispettivi avventurieri e cosa li circonda (quante porte conducono fuori da una stanza, cosa c'è su un tavolo e così via).\\n- **2: I giocatori descrivono come agiscono i loro personaggi.** In genere, i personaggi restano uniti mentre attraversano un dungeon o un altro ambiente. A volte, i singoli avventurieri potrebbero fare cose diverse: uno potrebbe rovistare in un forziere, mentre un altro esamina un misterioso simbolo tracciato su un muro e un terzo fa la guardia nel caso arrivino dei mostri. Fuori dal combattimento, il GM si assicura che ogni personaggio abbia la possibilità di agire e decide come risolvere la sua azione. In combattimento, i personaggi agiscono a turno.\\n- **3: Il GM narra i risultati delle azioni degli avventurieri.** A volte, risolvere un'azione è facile. Se un avventuriero attraversa una stanza e cerca di aprire una porta, il GM potrebbe dire che la porta si apre e descrivere ciò che si trova oltre la soglia. Ma la porta potrebbe essere chiusa a chiave, il pavimento potrebbe celare una trappola, o altre circostanze potrebbero rendere più arduo per un avventuriero completare un compito. In questi casi, il GM potrebbe chiedere al giocatore di tirare un dado per determinare cosa accade. La descrizione dei risultati in genere conduce a un altro snodo decisionale, che riporta il gioco al punto 1.\\n\\nQuesto schema è valido per ogni sessione di gioco (ogni volta che ci si siede a giocare a D&D), sia che gli avventurieri stiano parlando con un nobile, sia che stiano esplorando delle rovine o combattendo contro un drago. In certe situazioni, specialmente in combattimento, l'azione è più strutturata e tutti devono svolgere dei turni.\\n\\n> **Le eccezioni sostituiscono le regole generali**\\n>\\n> Ogni parte del gioco è governata da regole generali: secondo le regole di combattimento, per esempio, gli attacchi in mischia usano la Forza e gli attacchi a distanza la Destrezza. Questa è una regola generale, che è valida finché qualcosa nel gioco non asserisce esplicitamente il contrario.\\n>\\n> Il gioco contiene anche elementi, come privilegi di classe, talenti, proprietà delle armi, incantesimi, oggetti magici, abilità dei mostri e altro ancora, che talvolta contraddicono le regole generali. Quando una regola generale e un'eccezione si contraddicono, è l'eccezione a vincere. Per esempio, se un privilegio dice che una creatura può effettuare attacchi in mischia usando il proprio Carisma, potrà farlo anche se ciò contraddice la regola generale.","page":5},"rule.the-six-abilities":{"name":"Le sei caratteristiche","description":"Tutte le creature, personaggi e mostri, hanno sei caratteristiche che ne misurano le facoltà fisiche e mentali, come indicato nella tabella Descrizioni delle caratteristiche.\\n\\n**Descrizioni delle caratteristiche**\\n\\n|Caratteristica|Il punteggio misura...|\\n|---|---|\\n|Forza|Potenza fisica|\\n|Destrezza|Agilità, riflessi ed equilibrio|\\n|Costituzione|Salute e resistenza fisica|\\n|Intelligenza|Ragionamento e memoria|\\n|Saggezza|Percezione e fortezza mentale|\\n|Carisma|Disinvoltura, padronanza di sé e fascino|","page":5},"rule.the-six-abilities.ability-modifiers":{"name":"Modificatori di caratteristica","description":"A ogni caratteristica è abbinato un modificatore che si applica ogni volta che si effettua una prova con d20 con quella caratteristica (come spiegato nel capitolo \\"Prove con d20\\"). Un modificatore di caratteristica deriva dal suo punteggio, come indicato nella tabella \\"Modificatori di caratteristica\\".\\n\\n> **Arrotondare per difetto**\\n>\\n> Ogni volta che è necessario dividere o moltiplicare un numero nel gioco, si deve arrotondare per difetto se il risultato è una frazione, anche nel caso in cui la frazione raggiunga o superi la metà. Alcune regole fanno eccezione e specificano di arrotondare per eccesso.\\n\\n**Modificatori di caratteristica**\\n\\n|Punteggio|Modificatore|Punteggio|Modificatore|\\n|---|---|---|---|\\n|1|−5|16–17|+3|\\n|2–3|−4|18–19|+4|\\n|4–5|−3|20–21|+5|\\n|6–7|−2|22–23|+6|\\n|8–9|−1|24–25|+7|\\n|10–11|+0|26–27|+8|\\n|12–13|+1|28–29|+9|\\n|14–15|+2|30|+10|","page":6},"rule.d20-tests":{"name":"Prove con d20","description":"Quando l'esito di un'azione è incerto, il gioco utilizza il tiro di un d20 per determinarne il successo o il fallimento. Questi tiri si chiamano prove con d20 e sono di tre tipi: prove di caratteristica, tiri salvezza e tiri per colpire. Tutti e tre prevedono i passi seguenti:\\n\\n- **1: Tirare 1d20.** Ottenere un numero alto è sempre il risultato migliore. Se il tiro dispone di vantaggio o svantaggio (descritti più avanti nel capitolo \\"Come si gioca\\"), si tirano due d20, ma si usa soltanto un risultato: quello più alto se si dispone di vantaggio o quello più basso se si subisce svantaggio.\\n- **2: Aggiungere i modificatori.** Si tira un d20 e si aggiungono questi modificatori al numero ottenuto:\\n  - **Il modificatore di caratteristica rilevante.** I capitoli \\"Come si gioca\\" e \\"Glossario delle regole\\" spiegano quali modificatori di caratteristica utilizzare per le varie prove con d20.\\n  - **Il proprio bonus di competenza, se rilevante.** Ogni creatura possiede un bonus di competenza, ovvero un numero da aggiungere alla prova con d20 che utilizza qualcosa in cui il personaggio abbia una certa competenza, come un'abilità. Vedi la sezione \\"Competenza\\" più avanti nel capitolo \\"Come si gioca\\".\\n  - **Bonus e penalità circostanziali.** Un privilegio di classe, un incantesimo o un'altra regola potrebbe conferire un bonus o una penalità al tiro.\\n- **3: Confrontare il totale con un numero bersaglio.** Se il totale ottenuto sommando il tiro del d20 e i relativi modificatori è pari o superiore al numero bersaglio, la prova con d20 ha successo. In caso contrario, fallisce. Il Game Master determina i numeri bersaglio e comunica ai giocatori se i loro tiri hanno avuto o meno successo. Il numero bersaglio per una prova di caratteristica o un tiro salvezza viene chiamato Classe Difficoltà (CD). Il numero bersaglio relativo a un tiro per colpire viene chiamato Classe Armatura (CA) e appare sulla scheda del personaggio o nella sua scheda delle statistiche (vedi \\"Glossario delle regole\\").","page":6},"rule.d20-tests.saving-throw":{"name":"Tiri salvezza","description":"Un tiro salvezza rappresenta un tentativo di eludere o respingere una minaccia, come ad esempio un'esplosione infuocata, un'ondata di gas velenoso o un incantesimo che cerca di invadere la mente. Di norma i giocatori non decidono di effettuare un tiro salvezza; sono obbligati a effettuarne uno quando un personaggio o un mostro (se sei il GM) rischia di subire danni. Il risultato di un tiro salvezza è descritto nell'effetto che l'ha causato.\\n\\nSe il personaggio non vuole resistere all'effetto, può scegliere di fallire il tiro salvezza senza tirare.\\n\\n### Modificatore di caratteristica\\n\\nI tiri salvezza prendono il nome dai modificatori di caratteristica che utilizzano: un tiro salvezza su Costituzione, un tiro salvezza su Saggezza e così via. Per resistere a tipi di effetti diversi, si utilizzano tiri salvezza diversi, come indicato nella tabella Esempi di tiri salvezza.\\n\\n**Esempi di tiri salvezza**\\n\\n|Caratteristica|Effettua un tiro salvezza per...|\\n|---|---|\\n|Forza|Resistere fisicamente alla forza diretta|\\n|Destrezza|Schivare dei pericoli|\\n|Costituzione|Sopravvivere a un pericolo tossico|\\n|Intelligenza|Riconoscere un'illusione come falsa|\\n|Saggezza|Resistere a un attacco psichico|\\n|Carisma|Affermare la propria identità|\\n\\n### Bonus di competenza\\n\\nSi aggiunge il proprio bonus di competenza al tiro salvezza se si dispone di competenza in quel tipo di tiro. Vedi la sezione \\"Competenza\\" più avanti nel capitolo \\"Come si gioca\\".\\n\\n### Classe Difficoltà\\n\\nLa Classe Difficoltà di un tiro salvezza è determinata dall'effetto che lo causa o da chi ha il ruolo di GM. Ad esempio, se un incantesimo costringe a effettuare un tiro salvezza, la CD è determinata dalla caratteristica da incantatore e dal bonus di competenza di chi lo ha lanciato. Le abilità dei mostri che richiedono tiri salvezza specificano la CD.","page":7},"rule.d20-tests.attack-rolls":{"name":"Tiri per colpire","description":"Un tiro per colpire determina se un attacco colpisce un bersaglio. Il tiro va a segno se il risultato è pari o superiore alla Classe Armatura del bersaglio. Di solito i tiri per colpire vengono effettuati in battaglia, come descritto in \\"Combattimento\\" più avanti nel capitolo \\"Come si gioca\\", ma il GM potrebbe chiedere di eseguire un tiro per colpire anche in altre situazioni, come in una gara di tiro con l'arco.\\n\\n### Modificatore di caratteristica\\n\\nLa tabella Caratteristiche dei tiri per colpire mostra quale modificatore di caratteristica utilizzare per i diversi tipi di tiri per colpire.\\n\\n**Caratteristiche dei tiri per colpire**\\n\\n|Caratteristica|Tipo di attacco|\\n|---|---|\\n|Forza|Attacco in mischia con un'arma o colpo senz'armi (vedi il \\"Glossario delle regole\\")|\\n|Destrezza|Attacco a distanza con un'arma|\\n|Variabile|Attacco con incantesimo (la caratteristica utilizzata è determinata dal privilegio Incantesimi dell'incantatore, come spiegato nel capitolo \\"Incantesimi\\")|\\n\\nAlcuni privilegi consentono l'uso di diversi modificatori di caratteristica tra quelli elencati. Ad esempio, la proprietà accurata (vedi \\"Equipaggiamento\\") consente di utilizzare Forza o Destrezza con un'arma che possiede tale proprietà.\\n\\n### Bonus di competenza\\n\\nAggiungi il tuo bonus di competenza al tiro per colpire quando attacchi usando un'arma in cui possiedi competenza, nonché quando attacchi con un incantesimo. Per ulteriori informazioni sulle competenze nelle armi, vedi la sezione \\"Competenza\\" più avanti nel capitolo \\"Come si gioca\\".\\n\\n### Classe Armatura\\n\\nLa Classe Armatura di una creatura rappresenta la sua capacità di evitare di essere ferita in combattimento. La CA di un personaggio viene determinata al momento della sua creazione (vedi \\"Creazione del personaggio\\"), mentre la CA di un mostro compare nella sua scheda delle statistiche.\\n\\n***Calcolare la CA.*** Tutte le creature iniziano con lo stesso calcolo della CA base:\\n\\n**CA base** = 10 + il modificatore di Destrezza della creatura\\n\\nLa CA di una creatura può essere modificata da armature, oggetti magici, incantesimi e altro.\\n\\n***La CA base è solo una.*** Alcuni incantesimi e privilegi di classe offrono ai personaggi un modo diverso per calcolare la loro CA. Se un personaggio dispone di più privilegi che offrono modi diversi di calcolare la CA, deve scegliere quale usare, poiché alla creatura può essere applicato soltanto un calcolo di base.\\n\\n### Ottenere un 20 o un 1\\n\\nSe su un tiro per colpire ottieni un 20 sul d20 (detto \\"20 naturale\\"), l'attacco va a segno a prescindere da qualsiasi modificatore o dalla CA del bersaglio. Questo viene definito un colpo critico (vedi \\"Combattimento\\" più avanti nel capitolo \\"Come si gioca\\").\\n\\nSe su un tiro per colpire ottieni un 1 sul d20 (un \\"1 naturale\\"), l'attacco non va a segno a prescindere da qualsiasi modificatore o dalla CA del bersaglio.","page":7},"rule.proficiency.bonus-dont-stack":{"name":"I bonus non si accumulano","description":"Il bonus di competenza non può essere aggiunto a un tiro del dado o a un altro numero più di una volta. Ad esempio, se una regola consente di effettuare una prova di Carisma (Inganno o Persuasione), il personaggio aggiunge il bonus di competenza se è competente in una delle due abilità, ma non lo aggiunge due volte se è competente in entrambe.\\n\\nIn alcune occasioni il bonus di competenza potrebbe essere moltiplicato o diviso (raddoppiato o dimezzato, per esempio) prima di essere aggiunto. Ad esempio, il privilegio Maestria (vedi \\"Glossario delle regole\\") raddoppia il bonus di competenza per alcune prove di caratteristica. Quando il bonus viene utilizzato, può essere moltiplicato e diviso una sola volta.","page":9},"rule.proficiency.skill-proficiencies":{"name":"Competenze nelle abilità","description":"La maggior parte delle prove di caratteristica comporta l'uso di un'abilità, che rappresenta una categoria di azioni che le creature tentano di compiere con una prova di caratteristica. Le descrizioni delle azioni compiute dal personaggio (vedi \\"Azioni\\" più avanti nel capitolo \\"Come si gioca\\") specificano quale abilità si applica se si effettua una prova di caratteristica per quell'azione. Inoltre, molte altre regole indicano quando un'abilità è rilevante, ma l'ultima parola sulla rilevanza di un'abilità in una determinata situazione è sempre del GM.\\n\\nSe una creatura è competente in un'abilità, applica il suo bonus di competenza alle prove di caratteristica che riguardano quell'abilità. Senza competenza in un'abilità, una creatura può comunque effettuare prove di caratteristica che riguardano quell'abilità, ma senza aggiungere il bonus di competenza. Ad esempio, se un personaggio cerca di arrampicarsi su una parete rocciosa, il GM potrebbe richiedere una prova di Forza (Atletica). Se il personaggio ha competenza in Atletica, aggiunge il suo bonus di competenza alla prova di Forza. Se non possiede tale competenza, effettua una prova senza aggiungere il rispettivo bonus.\\n\\n**Abilità**\\n\\n|Abilità|Caratteristica|Esempio d'uso|\\n|---|---|---|\\n|Acrobazia|Destrezza|Rimani in piedi in una situazione difficile o esegui un'acrobazia.|\\n|Addestrare animali|Saggezza|Calma o addestra un animale, o fallo comportare in una certa maniera.|\\n|Arcano|Intelligenza|Richiama la conoscenza su incantesimi, oggetti magici e piani di esistenza.|\\n|Atletica|Forza|Salta più lontano del normale, resta a galla in acque agitate o rompi qualcosa.|\\n|Furtività|Destrezza|Sfuggi all'attenzione altrui muovendoti silenziosamente e nascondendoti dietro le cose.|\\n|Indagare|Intelligenza|Trova informazioni sepolte nei libri o deduci il funzionamento degli oggetti più disparati.|\\n|Inganno|Carisma|Racconta una bugia convincente o indossa un travestimento credibile.|\\n|Intimidire|Carisma|Impressiona o minaccia qualcuno facendogli fare quello che vuoi.|\\n|Intrattenere|Carisma|Recita, narra una storia, suona o danza.|\\n|Intuizione|Saggezza|Discerni l'umore e le intenzioni di una persona.|\\n|Medicina|Saggezza|Diagnostica una malattia o determina cosa abbia recentemente ucciso qualcuno.|\\n|Natura|Intelligenza|Richiama la conoscenza su terreno, piante, animali e tempo.|\\n|Percezione|Saggezza|Usando una combinazione di sensi, nota qualcosa che è facile trascurare.|\\n|Persuasione|Carisma|Convinci qualcuno di qualcosa con onestà e buone maniere.|\\n|Rapidità di mano|Destrezza|Svuota le tasche, nascondi un oggetto tenuto in mano o esegui un gioco di prestigio.|\\n|Religione|Intelligenza|Richiama la conoscenza su divinità, rituali religiosi e simboli sacri.|\\n|Sopravvivenza|Saggezza|Segui le tracce, va' alla ricerca di cibo, trova una pista o evita i pericoli naturali.|\\n|Storia|Intelligenza|Ricorda dati e leggende su eventi storici, persone, nazioni e culture.|\\n\\n### Lista delle abilità\\n\\nLe abilità sono indicate nella tabella Abilità, che riporta esempi di utilizzo per ogni competenza e la prova di caratteristica a cui l'abilità si applica più spesso.\\n\\n### Determinare le abilità\\n\\nLe competenze nelle abilità iniziali di un personaggio sono determinate nel corso della sua creazione, mentre le competenze nelle abilità di un mostro sono indicate nella sua scheda delle statistiche.","page":9},"rule.proficiency.saving-throw-proficiencies":{"name":"Competenze nei tiri salvezza","description":"La competenza in un tiro salvezza consente a un personaggio di aggiungere il suo bonus di competenza ai tiri salvezza che utilizzano una particolare caratteristica. Ad esempio, la competenza nei tiri salvezza su Saggezza consente di aggiungere il bonus di competenza a tali tiri. Anche alcuni mostri hanno competenze nei tiri salvezza, come indicato nelle loro schede delle statistiche.\\n\\nOgni classe conferisce competenza in almeno due tiri salvezza, che rappresentano l'addestramento di quella classe nell'eludere o respingere determinate minacce. I maghi, ad esempio, si allenano per resistere agli attacchi psichici e sono competenti nei tiri salvezza su Intelligenza e Saggezza.","page":9},"rule.proficiency.equipment-proficiencies":{"name":"Competenze nell'equipaggiamento","description":"Un personaggio acquisisce competenza in varie armi e strumenti in base alla sua classe e al suo background. Esistono due categorie di competenza negli equipaggiamenti:\\n\\n- **Armi.** Chiunque può brandire un'arma, ma la competenza rende il personaggio più abile nel brandirla. Se il personaggio ha competenza in un'arma, aggiunge il bonus di competenza ai tiri per colpire effettuati con essa.\\n- **Strumenti.** Se il personaggio ha competenza in uno strumento, può aggiungere il bonus di competenza a qualsiasi prova di caratteristica che effettua utilizzandolo. Se è dotato di competenza nell'abilità utilizzata per quella prova, effettuerà la prova con vantaggio. Ciò significa che può beneficiare sia della competenza nell'abilità che della competenza negli strumenti nella stessa prova di caratteristica.","page":9},"rule.social-interaction":{"name":"Interazioni sociali","description":"Durante le loro avventure, i personaggi giocanti incontrano molte persone diverse e affrontano mostri desiderosi più di parlare che di combattere. In simili situazioni bisogna passare alle interazioni sociali, che possono assumere molte forme. Ad esempio, un personaggio potrebbe cercare di convincere un ladro a confessare una malefatta o di adulare una guardia. Il Game Master interpreta i ruoli di tutti i personaggi non giocanti che partecipano all'interazione.\\n\\nL'atteggiamento di un PNG nei confronti del personaggio è amichevole, indifferente o ostile, come descritto in \\"Glossario delle regole\\". I PNG amichevoli sono disposti ad aiutare il personaggio, mentre quelli ostili tenderanno a ostacolarlo.\\n\\nLe interazioni sociali avvengono in due modi: attraverso l'interpretazione del ruolo e le prove di caratteristica.","page":11},"rule.social-interaction.roleplaying":{"name":"Interpretazione del ruolo","description":"L'interpretazione del ruolo è esattamente ciò che suggerisce il termine stesso, ovvero l'atto di interpretare il ruolo di un personaggio, nella fattispecie le scelte che determinano in che modo il tuo personaggio pensa, agisce e parla. L'interpretazione del ruolo è parte di ogni aspetto del gioco, ma diventa di primaria importanza nel corso delle interazioni sociali.\\n\\nDurante l'interpretazione, valuta se preferisci un approccio attivo o un approccio descrittivo.\\n\\nIl GM usa la personalità di un PNG e le azioni e gli atteggiamenti di un personaggio per determinare in che modo un PNG reagisce. Un bandito codardo potrebbe cedere di fronte a una minaccia di reclusione. Una mercantessa testarda si rifiuta di prestare aiuto se i personaggi la importunano. Un drago vanesio adora sentirsi adulato.\\n\\nDurante le interazioni con un PNG è bene prestare attenzione a come il GM ne interpreta la personalità: potresti essere in grado di apprendere gli obiettivi di un PNG e usare queste informazioni per influenzarlo.\\n\\nOffrendo a un PNG qualcosa che desidera oppure facendo leva sui suoi obiettivi, le sue simpatie o le sue paure, puoi stringere amicizie, scongiurare il ricorso alla violenza o apprendere informazioni chiave. D'altro canto, chi insulta un orgoglioso guerriero o parla male degli alleati di un nobile difficilmente vedrà i suoi tentativi di persuasione o di inganno andare a buon fine.","page":11},"rule.social-interaction.ability-checks":{"name":"Prove di caratteristica","description":"Le prove di caratteristica sono essenziali al fine di determinare l'esito di un'interazione sociale. L'interpretazione può modificare l'atteggiamento di un PNG, ma potrebbe comunque persistere un elemento di casualità se il GM vuole che i dadi abbiano un ruolo nel determinare la reazione di un PNG. In queste situazioni, il GM chiederà in genere di effettuare un'azione di Influenza.\\n\\nI giocatori dovrebbero prestare attenzione alle proprie competenze nelle abilità quando pensano a come interagire con un PNG, e utilizzare un approccio che si basi sulle competenze dei personaggi. Ad esempio, se il gruppo deve ingannare una guardia per ottenere l'accesso al castello, un ladro competente in Inganno dovrebbe avviare la discussione.","page":12},"rule.exploration":{"name":"Esplorazione","description":"Per definizione, un'esplorazione prevede l'addentrarsi in luoghi pericolosi e ammantati di mistero. Le regole presentate in questa sezione descrivono alcuni dei modi in cui avventurieri e avventuriere interagiscono con l'ambiente quando esplorano simili luoghi.","page":12},"rule.exploration.adventuring-equipment":{"name":"Equipaggiamento per l'avventura","description":"Durante le esplorazioni, l'equipaggiamento può tornare utile agli avventurieri in molti modi. Ad esempio, possono raggiungere luoghi fuori mano con una scala a pioli, percepire cose che altrimenti non noterebbero con una torcia o un'altra fonte di luce, aggirare porte e contenitori chiusi a chiave con gli arnesi da scasso e creare ostacoli per gli inseguitori con i triboli.\\n\\nConsulta il capitolo \\"Equipaggiamento\\" per le regole riguardanti numerosi oggetti utili nelle avventure. Di particolare utilità sono gli oggetti descritti in \\"Strumenti\\" ed \\"Equipaggiamento d'avventura\\". Le armi nel capitolo \\"Equipaggiamento\\" possono essere usate anche per scopi diversi dalla battaglia; ad esempio, si può usare un bastone ferrato per premere un pulsante dall'aspetto sinistro che si preferisce non toccare.","page":12},"rule.exploration.vision-and-light":{"name":"Visione e illuminazione","description":"Alcune attività in un'avventura, come notare i pericoli, colpire un nemico e lanciare determinati incantesimi, fanno affidamento sulla vista, quindi gli effetti che limitano la visione possono ostacolare gli avventurieri, come spiegato di seguito.\\n\\n### Aree oscurate\\n\\nUn'area potrebbe essere leggermente o pesantemente oscurata. In un'area leggermente oscurata, come per esempio una zona di luce fioca, di nebbia rarefatta o di fogliame moderato, il personaggio subisce svantaggio alle prove di Saggezza (Percezione) basate sulla vista.\\n\\nUn'area pesantemente oscurata, come per esempio un'area con oscurità, nebbia fitta o fogliame denso, è opaca. Quando un personaggio cerca di vedere qualcosa in quell'area, subisce la condizione accecato (vedi \\"Glossario delle regole\\").\\n\\n### Luce\\n\\nLa presenza o l'assenza di luce determina la categoria di illuminazione di un'area, come definito di seguito.\\n\\n***Luce intensa.*** La luce intensa consente alla maggior parte delle creature di vedere le cose normalmente. Anche le giornate di cielo coperto forniscono luce intensa, così come le torce, le lanterne, i fuochi e le altre fonti di illuminazione entro un raggio specifico.\\n\\n***Luce fioca.*** La luce fioca, equivalente alla condizione di ombra, crea un'area leggermente oscurata. Un'area di luce fioca si trova solitamente a metà tra una fonte di luce intensa e l'oscurità circostante. Anche la luce tenue del crepuscolo e dell'alba conta come luce fioca. Ad esempio, la luna piena potrebbe proiettare luce fioca nell'area.\\n\\n***Oscurità.*** L'oscurità genera un'area pesantemente oscurata. I personaggi si ritrovano immersi nell'oscurità di notte quando sono all'aperto (anche nella maggior parte delle notti di luna), quando sono all'interno di un dungeon privo di fonti di luce o in un'area di oscurità magica.\\n\\n### Sensi speciali\\n\\nAlcune creature hanno sensi speciali che le aiutano a percepire le cose in determinate situazioni. Il capitolo \\"Glossario delle regole\\" definisce i seguenti sensi speciali:\\n\\n- Vista cieca\\n- Scurovisione\\n- Percezione tellurica\\n- Vista pura","page":12},"rule.exploration.hiding":{"name":"Nascondersi","description":"Avventurieri e mostri spesso si nascondono per spiarsi l'un l'altro, per sgattaiolare oltre un guardiano o per tendere imboscate. È il Game Master a decidere le circostanze in cui è possibile nascondersi. Quando cerchi di nasconderti, effettui l'azione di Nascondersi.","page":13},"rule.exploration.interacting-with-objects":{"name":"Interazioni con gli oggetti","description":"L'interazione con gli oggetti in genere si risolve in modo semplice. Il giocatore annuncia al GM che il suo personaggio sta facendo qualcosa, ad esempio azionare una leva o aprire una porta, e il GM descrive cosa accade. A volte, tuttavia, le regole governano ciò che un personaggio può fare con un oggetto, come descritto nelle seguenti sezioni.\\n\\n### Che cos'è un oggetto?\\n\\nAi fini delle regole, per oggetto si considera qualcosa di distinto e inanimato come una finestra, una porta, una spada, un libro, un tavolo, una sedia o una roccia. Edifici e veicoli non rientrano in questa categoria, perché sono composti da molti altri oggetti.\\n\\n### Interazioni con oggetti a tempo limitato\\n\\nQuando il tempo stringe, come ad esempio in combattimento, le interazioni con gli oggetti sono limitate: è possibile una sola interazione libera per turno, che deve avvenire durante il movimento o l'azione di una creatura. Qualsiasi interazione aggiuntiva richiede l'azione di Utilizzo, come spiegato in \\"Combattimento\\" più avanti nel capitolo \\"Come si gioca\\".\\n\\n### Trovare un oggetto nascosto\\n\\nQuando un personaggio cerca un oggetto nascosto, come una porta segreta o una trappola, il GM solitamente gli chiede di effettuare una prova di Saggezza (Percezione), a condizione che il giocatore descriva il personaggio intento a cercare nelle vicinanze dell'oggetto nascosto. In caso di successo, il personaggio trova l'oggetto, altri dettagli importanti o entrambi.\\n\\nSe il giocatore descrive il suo personaggio che esamina un'area lontana dall'oggetto nascosto, una prova di Saggezza (Percezione) non rivelerà l'oggetto, indipendentemente dal totale della prova.\\n\\n### Trasportare gli oggetti\\n\\nDi solito il personaggio può trasportare l'attrezzatura e il tesoro senza preoccuparsi del peso di questi oggetti. Se cerca di trasportare un oggetto insolitamente pesante o un numero elevato di oggetti più leggeri, il GM potrebbe richiedere di attenersi alle regole di capacità di trasporto in \\"Glossario delle regole\\".\\n\\n### Rompere gli oggetti\\n\\nCon un'azione, si può distruggere o rompere automaticamente un oggetto fragile e non magico, come un contenitore di vetro o un pezzo di carta. Se si cerca di danneggiare qualcosa di più resistente, il GM potrebbe applicare le regole per rompere gli oggetti in \\"Glossario delle regole\\".","page":13},"rule.exploration.marching-order":{"name":"Ordine di marcia","description":"Gli avventurieri dovrebbero stabilire un ordine di marcia durante i loro viaggi, che siano al chiuso o all'aperto. Un ordine di marcia rende più facile determinare quali personaggi vengono colpiti dalle trappole, quali sono in grado di individuare i nemici nascosti e quali sono più vicini ai nemici in caso di combattimento. È possibile cambiare l'ordine di marcia quando non si è impegnati in un combattimento e annotarlo nel modo che si preferisce: scrivendolo, ad esempio, o disponendo le miniature in modo da mostrarlo.","page":12},"rule.exploration.hazards":{"name":"Pericoli","description":"I mostri sono i pericoli principali che i personaggi devono affrontare, ma non sono gli unici. Il capitolo \\"Glossario delle regole\\" definisce i seguenti pericoli:\\n\\n- In fiamme\\n- Disidratazione\\n- Caduta\\n- Malnutrizione\\n- Soffocamento","page":13},"rule.exploration.travel":{"name":"Viaggiare","description":"Durante un'avventura, i personaggi potrebbero percorrere lunghe distanze in viaggi che richiedono ore o addirittura giorni. Il GM può riassumere questi viaggi senza calcolarne esattamente distanze e tempi, oppure può far usare le regole del Passo di viaggio riportate di seguito.\\n\\nSe hai bisogno di sapere a quale velocità puoi muoverti quando ogni secondo è di vitale importanza, usa le regole di movimento in \\"Combattimento\\" più avanti nel capitolo \\"Come si gioca\\".\\n\\n### Passo di viaggio\\n\\nQuando è in viaggio e non sta combattendo, un gruppo può muoversi a passo veloce, normale o lento, come indicato nella tabella \\"Passo di viaggio\\". La tabella determina la distanza che un gruppo riesce a coprire in un periodo di tempo; in sella a cavalli o ad altre cavalcature, il gruppo può percorrere il doppio di quella distanza per 1 ora, dopodiché le cavalcature necessitano di un riposo breve o lungo prima di potersi muovere di nuovo a passo più veloce (vedi \\"Equipaggiamento\\" per una selezione di cavalcature in vendita). \\"Strumenti di gioco\\" include regole che influenzano la scelta del passo in certi tipi di terreno.\\n\\n**Passo di viaggio**\\n\\n|Passo|Distanza percorsa ogni...|||\\n|---|---|---|---|\\n||Minuto|Ora|Giorno|\\n|Veloce|120 m|6 km|45 km|\\n|Normale|90 m|4,5 km|36 km|\\n|Lento|60 m|3 km|27 km|\\n\\nOgni passo di viaggio ha un effetto sul gioco, come definito di seguito.\\n\\n***Veloce.*** Viaggiare a passo veloce impone uno svantaggio alle prove di Saggezza (Percezione o Sopravvivenza) e Destrezza (Furtività) del viaggiatore.\\n\\n***Normale.*** Viaggiare a passo normale impone uno svantaggio alle prove di Destrezza (Furtività).\\n\\n***Lento.*** Viaggiare a passo lento conferisce vantaggio alle prove di Saggezza (Percezione o Sopravvivenza).\\n\\n### Veicoli\\n\\nI viaggiatori a bordo di carri, carrozze o altri veicoli terrestri avanzano a passo normale. I personaggi a bordo di un'imbarcazione sono limitati alla velocità di quell'imbarcazione e non scelgono il passo di viaggio. In base al tipo di vascello e alle dimensioni dell'equipaggio, un'imbarcazione potrebbe essere in grado di viaggiare anche per 24 ore al giorno. Il capitolo \\"Equipaggiamento\\" include i veicoli in vendita.","page":13},"rule.skill.acrobatics":{"name":"Acrobazia","description":"Rimani in piedi in una situazione difficile o esegui un'acrobazia.","page":10},"rule.skill.animal-handling":{"name":"Addestrare animali","description":"Calma o addestra un animale, o fallo comportare in una certa maniera.","page":10},"rule.skill.arcana":{"name":"Arcano","description":"Richiama la conoscenza su incantesimi, oggetti magici e piani di esistenza.","page":10},"rule.skill.athletics":{"name":"Atletica","description":"Salta più lontano del normale, resta a galla in acque agitate o rompi qualcosa.","page":10},"rule.skill.deception":{"name":"Inganno","description":"Racconta una bugia convincente o indossa un travestimento credibile.","page":10},"rule.skill.history":{"name":"Storia","description":"Ricorda dati e leggende su eventi storici, persone, nazioni e culture.","page":10},"rule.skill.insight":{"name":"Intuizione","description":"Discerni l'umore e le intenzioni di una persona.","page":10},"rule.skill.intimidation":{"name":"Intimidire","description":"Impressiona o minaccia qualcuno facendogli fare quello che vuoi.","page":10},"rule.skill.investigation":{"name":"Indagare","description":"Trova informazioni sepolte nei libri o deduci il funzionamento degli oggetti più disparati.","page":10},"rule.skill.medicine":{"name":"Medicina","description":"Diagnostica una malattia o determina cosa abbia recentemente ucciso qualcuno.","page":10},"rule.skill.nature":{"name":"Natura","description":"Richiama la conoscenza su terreno, piante, animali e tempo.","page":10},"rule.skill.perception":{"name":"Percezione","description":"Usando una combinazione di sensi, nota qualcosa che è facile trascurare.","page":10},"rule.skill.performance":{"name":"Intrattenere","description":"Recita, narra una storia, suona o danza.","page":10},"rule.skill.persuasion":{"name":"Persuasione","description":"Convinci qualcuno di qualcosa con onestà e buone maniere.","page":10},"rule.skill.religion":{"name":"Religione","description":"Richiama la conoscenza su divinità, rituali religiosi e simboli sacri.","page":10},"rule.skill.sleight-of-hand":{"name":"Rapidità di mano","description":"Svuota le tasche, nascondi un oggetto tenuto in mano o esegui un gioco di prestigio.","page":10},"rule.skill.stealth":{"name":"Furtività","description":"Sfuggi all'attenzione altrui muovendoti silenziosamente e nascondendoti dietro le cose.","page":10},"rule.skill.survival":{"name":"Sopravvivenza","description":"Segui le tracce, va' alla ricerca di cibo, trova una pista o evita i pericoli naturali.","page":10},"rule.ability.cha":{"name":"Carisma","description":"Disinvoltura, padronanza di sé e fascino","page":5},"rule.ability.con":{"name":"Costituzione","description":"Salute e resistenza fisica","page":5},"rule.ability.dex":{"name":"Destrezza","description":"Agilità, riflessi ed equilibrio","page":5},"rule.ability.int":{"name":"Intelligenza","description":"Ragionamento e memoria","page":5},"rule.ability.str":{"name":"Forza","description":"Potenza fisica","page":5},"rule.ability.wis":{"name":"Saggezza","description":"Percezione e fortezza mentale","page":5},"rule.mastery.cleave":{"name":"Doppio fendente","description":"Se il personaggio colpisce una creatura con un tiro per colpire in mischia usando quest'arma, può effettuarne un altro con la stessa arma contro un altro bersaglio entro 1,5 metri dal primo che sia a portata. Se il colpo va a segno, la seconda creatura subisce i danni inferti dall'arma, ma non puoi aggiungere il modificatore di caratteristica del personaggio al danno a meno che questo non sia di valore negativo. L'attacco extra può essere eseguito solo una volta per turno.","page":102},"rule.mastery.graze":{"name":"Colpo di striscio","description":"Se il tiro per colpire con quest'arma non va a segno contro una creatura, il personaggio può infliggere una quantità di danni alla creatura pari al modificatore di caratteristica utilizzato per il tiro per colpire. Il danno è della stessa tipologia dell'arma e può essere aumentato solo incrementando il modificatore di caratteristica.","page":102},"rule.weapon-property.heavy":{"name":"Pesante","description":"Il personaggio ha svantaggio ai tiri per colpire se utilizza un'arma pesante da mischia e il suo punteggio di Forza è inferiore a 13 o se usa un'arma pesante a distanza e il suo punteggio di Destrezza è inferiore a 13.","page":102},"rule.mastery.nick":{"name":"Graffio","description":"Quando il personaggio effettua l'attacco extra della proprietà leggera, può renderlo parte dell'azione di Attacco invece che dell'azione bonus. L'attacco extra può essere eseguito solo una volta per turno.","page":102},"rule.mastery.sap":{"name":"Fiaccare","description":"Se il personaggio colpisce una creatura con quest'arma, la creatura avrà svantaggio al prossimo tiro per colpire prima dell'inizio del prossimo turno del personaggio.","page":102},"rule.mastery.slow":{"name":"Lentezza","description":"Se il personaggio colpisce una creatura con quest'arma e le infligge dei danni, può ridurne la velocità di 3 metri fino all'inizio del turno successivo del personaggio. Se la creatura viene colpita più di una volta da armi con questa proprietà, la riduzione di velocità non supera i 3 metri.","page":102},"rule.weapon-property.two-handed":{"name":"A due mani","description":"Quest'arma richiede di essere impugnata a due mani quando il personaggio la usa per attaccare.","page":101},"rule.weapon-property.reach":{"name":"Portata","description":"Aggiunge 1,5 metri alla portata del personaggio quando la usa per attaccare e per determinare la portata di possibili attacchi di opportunità.","page":102},"rule.weapon-property.loading":{"name":"Ricarica","description":"Il personaggio può scagliare una sola munizione da un'arma con la proprietà ricarica quando usa un'azione, un'azione bonus o una reazione per fare fuoco, a prescindere dal numero di attacchi che potrebbe normalmente effettuare.","page":102},"rule.mastery.topple":{"name":"Rovesciamento","description":"Se il personaggio colpisce una creatura con quest'arma, può costringerla a effettuare un tiro salvezza su Costituzione (CD 8 più il modificatore di caratteristica utilizzato per il tiro per colpire e il bonus di competenza del personaggio). Se lo fallisce, cade a terra prona.","page":102},"rule.weapon-property.finesse":{"name":"Accurata","description":"Quando un personaggio effettua un attacco con un'arma accurata, può scegliere se usare il modificatore di Forza o di Destrezza per il tiro per colpire e il tiro per i danni. Deve usare lo stesso modificatore per entrambi i tiri.","page":101},"rule.proficiency":{"name":"Competenza","description":"Se il tuo personaggio ha una competenza in qualcosa, può aggiungere il bonus di competenza a qualsiasi prova con d20 effettuata per utilizzare ciò in cui è competente. Una creatura può avere competenza nell'uso di un'abilità, in un tiro salvezza o nell'uso di un'arma o strumento. *Vedi anche* \\"Come si gioca\\" (\\"Competenza\\").","page":206},"rule.weapon-property.ammunition":{"name":"Munizioni","description":"Il personaggio può effettuare un attacco a distanza usando un'arma dotata della proprietà Munizioni solo se possiede delle munizioni da utilizzare. La tipologia di munizioni richiesta è specificata insieme alla gittata dell'arma. Ogni attacco consuma una certa quantità di munizioni. Estrarre la munizione è considerato parte dell'attacco (il personaggio ha bisogno di una mano libera per caricare un'arma a una mano). Dopo un combattimento, il personaggio può impiegare 1 minuto per recuperare metà delle munizioni (arrotondate per difetto) utilizzate nel combattimento. Il resto è considerato irrecuperabile.","page":102},"rule.weapon-property.light":{"name":"Leggera","description":"Quando il personaggio utilizza un'azione di Attacco nel suo turno per attaccare con un'arma leggera, durante lo stesso turno può sferrare un attacco extra come azione bonus. Tuttavia, deve essere eseguito con un'arma leggera diversa e non puoi sommarci il modificatore di caratteristica del personaggio, a meno che non sia di valore negativo. Per esempio, il personaggio può attaccare con una spada corta in una mano e un pugnale in un'altra utilizzando l'azione di Attacco e l'azione bonus, ma non può aggiungere il suo modificatore di Forza o Destrezza al tiro per i danni dell'azione bonus, a meno che non sia di valore negativo.","page":101},"rule.weapon-property.thrown":{"name":"Lancio","description":"Se un'arma possiede la proprietà da lancio, il personaggio può lanciarla per effettuare un attacco a distanza ed estrarla come parte dell'attacco. Se è un'arma da mischia, il personaggio applica al tiro per colpire e al tiro per i danni lo stesso modificatore di caratteristica che userebbe per un attacco in mischia effettuato con quell'arma.","page":101},"rule.weapon-property.versatile":{"name":"Versatile","description":"Un'arma versatile può essere usata a una o due mani. Insieme alla proprietà viene visualizzato un valore del danno tra parentesi: questo è il danno inflitto dall'arma se utilizzata a due mani per eseguire un attacco in mischia.","page":102},"rule.mastery.vex":{"name":"Vessazione","description":"Se il personaggio colpisce una creatura con quest'arma e le infligge dei danni, avrà vantaggio al prossimo tiro per colpire eseguito contro la creatura prima del termine del proprio turno successivo.","page":103},"rule.mastery.push":{"name":"Spinta","description":"Se il personaggio colpisce una creatura con quest'arma, può spingerla via da sé di almeno 3 metri se è di taglia Grande o inferiore.","page":103},"rule.area-of-effect.sphere":{"name":"Sfera [area di effetto]","description":"Una sfera è un'area di effetto che si estende in linee rette da un punto di origine verso l'esterno in tutte le direzioni. L'effetto che crea una sfera specifica la distanza fino a cui essa si estende, indicando il raggio della sfera.\\n\\nIl punto di origine di una sfera è incluso nella sua area di effetto.","page":216},"rule.attunement":{"name":"Sintonia","description":"Alcuni oggetti magici richiedono che la creatura entri in sintonia con loro prima che possa utilizzarne le proprietà magiche. Una creatura può avere sintonia con non più di tre oggetti magici alla volta. *Vedi anche* \\"Equipaggiamento\\" (\\"Oggetti magici\\").","page":216},"rule.hazard.suffocation":{"name":"Soffocamento [pericolo]","description":"Una creatura può trattenere il fiato per un numero di minuti pari a 1 + il suo modificatore di Costituzione (minimo di 30 secondi) prima di iniziare a soffocare. Quando una creatura resta senza fiato o sta soffocando, ottiene 1 livello di indebolimento alla fine di ogni suo turno. Quando riesce a respirare di nuovo, la creatura rimuove tutti i livelli di indebolimento che ha ottenuto dal soffocamento.","page":216},"rule.damage-threshold":{"name":"Soglia di danno","description":"Una creatura o un oggetto che possiede una soglia di danno è immune a tutti i danni, a meno che non subisca una quantità di danni pari o superiore alla sua soglia di danno da un singolo attacco o effetto, nel qual caso subisce l'intera istanza di danno. I danni che non riescono a eguagliare o superare la soglia di danno sono superficiali e non riducono i punti ferita. Ad esempio, se un oggetto ha una soglia di danno pari a 10, non subisce danni se gli vengono inflitti 9 danni, poiché questa quantità di danni non supera la soglia di danno. Se all'oggetto vengono inflitti 11 danni, l'oggetto li subisce interamente.","page":216},"rule.surprise":{"name":"Sorpresa","description":"Se una creatura viene colta alla sprovvista all'inizio del combattimento, è sorpresa: subisce quindi svantaggio al tiro per l'iniziativa. *Vedi anche* \\"Come si gioca\\" (\\"Combattimento\\").","page":216},"rule.unoccupied-space":{"name":"Spazio libero","description":"Uno spazio si definisce \\"libero\\" se nessuna creatura si trova al suo interno o se esso non è completamente pieno di oggetti.","page":216},"rule.occupied-space":{"name":"Spazio occupato","description":"Uno spazio si definisce \\"occupato\\" se una creatura si trova al suo interno o se esso è completamente pieno di oggetti.","page":216},"rule.stable":{"name":"Stabile","description":"Una creatura è stabile se ha 0 punti ferita ma non deve effettuare tiri salvezza contro morte. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":216},"rule.crawling":{"name":"Strisciare","description":"Quando il personaggio striscia, ogni 30 centimetri di movimento costano 30 centimetri extra (60 centimetri extra in caso di terreno difficile). *Vedi anche* \\"Velocità\\".","page":216},"rule.action.study":{"name":"Studio [azione]","description":"Quando il personaggio effettua l'azione di Studio, effettua una prova di Intelligenza per analizzare la propria memoria, un libro, un indizio o un'altra fonte di conoscenza, richiamando alla mente un'informazione importante a riguardo.\\n\\nLa tabella Aree di conoscenza indica quali abilità sono applicabili alle varie aree di conoscenza.\\n\\n**Aree di conoscenza**\\n\\n|Abilità|Aree|\\n|---|---|\\n|Arcano|Incantesimi, oggetti magici, simboli occulti, tradizioni magiche, piani di esistenza e alcune creature (aberrazioni, costrutti, elementali, folletti e mostruosità)|\\n|Indagare|Trappole, cifrari, indovinelli e congegni|\\n|Natura|Terreno, flora, tempo atmosferico e alcune creature (bestie, draghi, melme e vegetali)|\\n|Religione|Divinità, riti e gerarchie religiose, simboli sacri, culti e alcune creature (celestiali, immondi e non morti)|\\n|Storia|Eventi e personaggi storici, antiche civiltà, guerre e alcune creature (giganti e umanoidi)|","page":216},"rule.disadvantage":{"name":"Svantaggio","description":"Se il personaggio subisce svantaggio a una prova con d20, tira due d20 e scegli il risultato più basso. Un tiro non può essere influenzato da più di uno svantaggio; inoltre, vantaggio e svantaggio sullo stesso tiro si annullano a vicenda. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\").","page":217},"rule.size":{"name":"Taglia","description":"A ogni creatura o oggetto è assegnata una categoria di taglia: Minuscola, Piccola, Media, Grande, Enorme o Mastodontica. La taglia di una creatura determina quanto spazio essa occupa in combattimento. La dimensione di un oggetto influisce sui suoi punti ferita. *Vedi anche* \\"Rompere gli oggetti\\" e \\"Come si gioca\\" (\\"Combattimento\\").","page":217},"rule.telepathy":{"name":"Telepatia","description":"La telepatia è un'abilità magica che consente a una creatura di comunicare mentalmente con un'altra creatura entro un raggio specificato. A meno che non indicato diversamente da una regola, per comprendere la comunicazione ricevuta, non è necessario che la creatura contattata parli la stessa lingua della creatura telepatica, ma deve essere in grado di comprendere almeno una lingua o essere essa stessa telepatica.\\n\\nLa creatura telepatica non deve necessariamente vedere la creatura che ha contattato, e può iniziare o terminare il contatto telepatico in qualsiasi momento (nessuna azione richiesta). Il contatto telepatico non può essere iniziato ed è immediatamente interrotto se la creatura telepatica o la creatura contattata è incapacitata. Inoltre, il contatto telepatico si interrompe se la creatura contattata non è più nel raggio della telepatia o se la creatura telepatica contatta una creatura diversa entro gittata.\\n\\nUna creatura priva di telepatia può ricevere i messaggi telepatici, ma non può avviare una conversazione telepatica. Una volta iniziata la conversazione telepatica, la creatura che è stata contattata può comunicare mentalmente con la creatura telepatica fino al termine della connessione.","page":217},"rule.teleportation":{"name":"Teletrasporto","description":"Il teletrasporto è un tipo speciale di trasporto magico. Se il tuo personaggio si teletrasporta, scompare e riappare altrove istantaneamente, senza muoversi nello spazio che separa i due luoghi. Questo tipo di trasporto non consuma movimento, a meno che una regola non indichi il contrario, e il teletrasporto non provoca mai attacchi di opportunità.\\n\\nQuando il personaggio si teletrasporta, si teletrasporta anche l'equipaggiamento che indossa e trasporta. Se, mentre si teletrasporta, il personaggio tocca un'altra creatura, questa non si teletrasporta insieme al personaggio, a meno che l'effetto di teletrasporto non indichi il contrario.\\n\\nSe lo spazio di destinazione del teletrasporto è occupato da un'altra creatura o è bloccato da un ostacolo solido, il personaggio appare nello spazio libero più vicino a sua scelta.\\n\\nLa descrizione di un effetto di teletrasporto indica se è necessario che il personaggio veda la destinazione del teletrasporto.","page":217},"rule.difficult-terrain":{"name":"Terreno difficile","description":"Se uno spazio è terreno difficile, ogni 30 centimetri di movimento in quello spazio costano 30 centimetri extra. Per esempio, spostarsi di 1,5 metri su terreno difficile costa 3 metri di movimento. Il terreno difficile non è cumulativo: o uno spazio è terreno difficile o non lo è.\\n\\nUno spazio è terreno difficile se contiene uno dei seguenti elementi o qualcosa di simile:\\n\\n- Una creatura che non sia minuscola o una creatura alleata\\n- Mobili a misura di creature di taglia pari o superiore a quella del personaggio\\n- Neve alta, ghiaccio, detriti o sottobosco\\n- Liquido a livello degli stinchi o fino alla vita\\n- Un'apertura stretta adatta a una creatura di una taglia inferiore a quella del personaggio\\n- Una pendenza di 20 gradi o più","page":217},"rule.damage-and-healing.damage-types":{"name":"Tipi di danno","description":"Gli attacchi e altri effetti dannosi infliggono vari tipi di danno. I tipi di danno non seguono regole particolari; tuttavia, altre regole, come quelle riguardanti la resistenza, possono farvi riferimento. La tabella \\"Tipi di danno\\" fornisce degli esempi per aiutare il GM ad assegnare un tipo di danno a un determinato effetto.\\n\\n**Tipi di danno**\\n\\n|Tipo|Esempi|\\n|---|---|\\n|Acido|Liquidi corrosivi, enzimi digestivi|\\n|Contundente|Oggetti contundenti, stritolamento, caduta|\\n|Forza|Pura energia magica|\\n|Freddo|Acqua gelata, getti ghiacciati|\\n|Fulmine|Elettricità|\\n|Fuoco|Fiamme, calore insopportabile|\\n|Necrotico|Energia in grado di risucchiare la vita|\\n|Perforante|Zanne, oggetti perforanti|\\n|Psichico|Energia in grado di spezzare la mente|\\n|Radioso|Energia sacra, radiazione incandescente|\\n|Tagliente|Artigli, oggetti taglienti|\\n|Tuono|Suono concussivo|\\n|Veleno|Gas tossico, veleno|","page":217},"rule.damage-type.acid":{"name":"Acido","description":"Liquidi corrosivi, enzimi digestivi","page":217},"rule.damage-type.bludgeoning":{"name":"Contundente","description":"Oggetti contundenti, stritolamento, caduta","page":217},"rule.damage-type.force":{"name":"Forza","description":"Pura energia magica","page":217},"rule.damage-type.cold":{"name":"Freddo","description":"Acqua gelata, getti ghiacciati","page":217},"rule.damage-type.lightning":{"name":"Fulmine","description":"Elettricità","page":217},"rule.damage-type.fire":{"name":"Fuoco","description":"Fiamme, calore insopportabile","page":217},"rule.damage-type.necrotic":{"name":"Necrotico","description":"Energia in grado di risucchiare la vita","page":217},"rule.damage-type.piercing":{"name":"Perforante","description":"Zanne, oggetti perforanti","page":217},"rule.damage-type.psychic":{"name":"Psichico","description":"Energia in grado di spezzare la mente","page":217},"rule.damage-type.radiant":{"name":"Radioso","description":"Energia sacra, radiazione incandescente","page":217},"rule.damage-type.slashing":{"name":"Tagliente","description":"Artigli, oggetti taglienti","page":217},"rule.damage-type.thunder":{"name":"Tuono","description":"Suono concussivo","page":217},"rule.damage-type.poison":{"name":"Veleno","description":"Gas tossico, veleno","page":217},"rule.creature-type":{"name":"Tipo di creatura","description":"Le regole relative a ogni creatura, inclusi i personaggi giocanti, presentano un descrittore che identifica il tipo di creatura. La maggior parte dei personaggi giocanti è di tipo umanoide. Di seguito sono elencati i tipi di creature presenti nel gioco:\\n\\n|Aberrazione|Elementale|Mostruosità|\\n|---|---|---|\\n|Bestia|Folletto|Non morto|\\n|Celestiale|Gigante|Umanoide|\\n|Costrutto|Immondo|Vegetale|\\n|Drago|Melma||\\n\\nI vari tipi di creature non hanno regole proprie, ma alcune regole del gioco influenzano certi tipi di creature in modo diverso.","page":218},"rule.attack-roll":{"name":"Tiro per colpire","description":"Un tiro per colpire è una prova con d20 che rappresenta un attacco con un'arma, con un colpo senz'armi o con un incantesimo. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\").","page":218},"rule.damage-and-healing.damage-rolls":{"name":"Tiro per i danni","description":"Un tiro per i danni è un tiro di dado (regolato dall'aggiunta dei modificatori applicabili) che infligge danni a un bersaglio. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":218},"rule.saving-throw":{"name":"Tiro salvezza","description":"Un tiro salvezza rappresenta il tentativo di evitare o di resistere a una minaccia. Solitamente, effettui un tiro salvezza solo quando una regola lo richiede, ma puoi anche decidere di fallire il tiro senza tirare il dado. Il risultato di un tiro salvezza è descritto nell'effetto che l'ha reso necessario. Se un bersaglio è costretto a effettuare un tiro salvezza e non possiede il punteggio di caratteristica utilizzato dal tiro, fallisce automaticamente. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\").","page":218},"rule.death-saving-throw":{"name":"Tiro salvezza contro morte","description":"Un personaggio giocante deve effettuare un tiro salvezza contro morte se inizia il proprio turno con 0 punti ferita. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":218},"rule.damage-and-healing.knocking-out-a-creature":{"name":"Tramortire una creatura","description":"Quando il personaggio sta per ridurre una creatura a 0 punti ferita con un attacco in mischia, può invece ridurla a 1 punto ferita. La creatura diventa quindi priva di sensi e inizia un riposo breve.\\n\\nLa creatura rimane priva di sensi fino a quando non riacquista punti ferita o fino a quando qualcuno non usa un'azione per somministrarle cure di pronto soccorso, il che richiede superare una prova di Saggezza (Medicina) con CD 10.","page":218},"rule.cantrip":{"name":"Trucchetto","description":"Un trucchetto è un incantesimo di livello 0 che si lancia senza slot incantesimo. *Vedi anche* \\"Incantesimi\\".","page":218},"rule.action.utilize":{"name":"Utilizzo [azione]","description":"Di norma un personaggio interagisce con un oggetto mentre fa qualcos'altro, come per esempio quando sfodera una spada come parte dell'azione di Attacco. Quando l'utilizzo di un oggetto richiede un'azione, il personaggio effettua l'azione di Utilizzo.","page":218},"rule.d20-tests.advantage-disadvantage":{"name":"Vantaggio","description":"Se il tuo personaggio dispone di vantaggio a una prova con d20, tira due d20 e scegli il risultato più alto. Un tiro non può essere influenzato da più di un vantaggio; inoltre, vantaggio e svantaggio sullo stesso tiro si annullano a vicenda. *Vedi anche* \\"Come si gioca\\" (\\"Prove con d20\\").","page":218},"rule.speed":{"name":"Velocità","description":"Ogni creatura ha la propria velocità, che è la distanza in metri che la creatura può percorrere quando si muove nel suo turno. *Vedi anche* \\"Nuotare\\", \\"Saltare\\", \\"Scalare\\", \\"Strisciare\\", \\"Volare\\" e \\"Come si gioca\\" (\\"Combattimento\\").\\n\\n***Velocità speciali.*** Alcune creature hanno velocità speciali, come la velocità di nuoto, la velocità di scalata, la velocità di scavo o la velocità di volo (ognuna di esse è descritta nel glossario). Se il personaggio ha più di una velocità, sceglie quale utilizzare per muoversi; quando si muove, può passare da un tipo di velocità all'altra. Ogni volta che il personaggio cambia velocità, sottrai la distanza di cui si è già mosso dalla nuova velocità: il risultato determina la distanza di cui può ancora muoversi. Se il risultato è pari o inferiore a 0, il personaggio non può usare la nuova velocità durante il movimento in corso. Per esempio, se il personaggio possiede una velocità di 9 metri e una velocità in volo di 18 metri, può volare per 6 metri, poi camminare per 3 metri e poi volare di nuovo per altri 9 metri.\\n\\n***Modifiche alle velocità.*** Se un effetto aumenta o diminuisce la velocità del personaggio per un certo periodo di tempo, anche le sue velocità speciali (se presenti) aumentano o diminuiscono della stessa quantità e per la stessa durata. Per esempio, se la velocità del personaggio scende a 0 e il personaggio ha anche una velocità di scalata, anche la sua velocità di scalata scende a 0. Allo stesso modo, se la sua velocità è dimezzata e il personaggio ha anche una velocità di volo, anche la sua velocità di volo è dimezzata.","page":218},"rule.swim-speed":{"name":"Velocità di nuoto","description":"La velocità di nuoto può essere usata per nuotare senza spendere movimento extra normalmente associato al nuoto. *Vedi anche* \\"Nuotare\\" e \\"Velocità\\".","page":219},"rule.climb-speed":{"name":"Velocità di scalata","description":"La velocità di scalata può essere usata al posto della velocità per arrampicarsi su una superficie verticale, senza spendere movimento extra normalmente associato alla scalata. *Vedi anche* \\"Scalare\\" e \\"Velocità\\".","page":219},"rule.burrow-speed":{"name":"Velocità di scavo","description":"Una creatura dotata di velocità di scavo può usare tale velocità per muoversi attraverso la sabbia, la terra, il fango o il ghiaccio. Non può scavare nella roccia solida, a meno che non abbia un tratto che le consenta di farlo. *Vedi anche* \\"Velocità\\".","page":219},"rule.fly-speed":{"name":"Velocità di volo","description":"La velocità di volo può essere usata per spostarsi in aria. Fin quando il personaggio ha la velocità di volo, può rimanere sospeso in aria fino a che non atterra, cade o muore. *Vedi anche* \\"Volare\\" e \\"Velocità\\".","page":219},"rule.blindsight":{"name":"Vista cieca","description":"Un personaggio con vista cieca è in grado di vedere entro un raggio specifico, senza fare affidamento sul senso della vista. Entro quel raggio, il personaggio è in grado di vedere qualsiasi cosa che non si trovi dietro copertura totale, anche se è accecato o circondato da oscurità. Inoltre, entro quel raggio, il personaggio riesce a vedere tutto ciò che è invisibile.","page":219},"rule.truesight":{"name":"Vista pura","description":"Se un personaggio ha vista pura, la sua vista entro un raggio specifico è migliorata. Entro quel raggio, grazie alla sua vista, il personaggio riesce a vedere attraverso:\\n\\n**Oscurità.** Il personaggio è in grado di vedere nell'oscurità magica e non.\\n\\n**Invisibilità.** Il personaggio è in grado di vedere creature e oggetti invisibili.\\n\\n**Illusioni visive.** Le illusioni visive appaiono trasparenti al personaggio, il quale supera automaticamente i tiri salvezza contro di esse.\\n\\n**Trasformazioni.** Il personaggio discerne la vera forma di tutte le creature e degli oggetti che vede e che sono stati alterati dalla magia.\\n\\n**Piano Etereo.** Il personaggio è in grado di vedere nel Piano Etereo.","page":219},"rule.flying":{"name":"Volare","description":"Esistono vari effetti che consentono a una creatura di volare. Mentre il tuo personaggio vola, cade al suolo se è incapacitato o prono, o se la sua velocità di volo scende a 0. In queste circostanze, il personaggio può rimanere sospeso in aria se è in grado di fluttuare. *Vedi anche* \\"Caduta\\" e \\"Velocità di volo\\".","page":219},"rule.vulnerability":{"name":"Vulnerabilità","description":"Se un personaggio è vulnerabile a un tipo di danno, i danni di quel tipo che subisce sono raddoppiati. La vulnerabilità si applica una sola volta per ogni istanza di danno ricevuta. *Vedi anche* \\"Come si gioca\\" (\\"Danni e guarigione\\").","page":219},"species.gnome":{"name":"Gnomo","description":"In quanto gnomo, il personaggio ha i seguenti tratti speciali.","page":95},"lineage.gnome.forest-gnome":{"name":"Gnomo delle foreste","description":"Il personaggio conosce il trucchetto illusione minore. Inoltre, l'incantesimo parlare con gli animali è sempre considerato come preparato. Può lanciarlo senza consumare uno slot incantesimo un numero di volte pari al suo bonus di competenza e riacquista tutti gli usi spesi al termine di un riposo lungo. Può anche lanciare l'incantesimo usando uno qualsiasi degli slot incantesimo a sua disposizione.","page":95},"lineage.gnome.rock-gnome":{"name":"Gnomo delle rocce","description":"Conosce i trucchetti riparare e prestidigitazione. Inoltre, può impiegare 10 minuti di lancio di prestidigitazione per creare un piccolo dispositivo meccanico (CA 5, 1 PF), come un giocattolo, un accendifuoco o un carillon. Una volta creato, puoi determinare il suo effetto scegliendolo fra quelli di prestidigitazione. Il dispositivo lo produrrà ogni volta che il personaggio o un'altra creatura utilizza un'azione bonus per attivarlo a contatto. Se l'effetto selezionato presenta ulteriori opzioni, puoi sceglierne una al momento della creazione del congegno. Per esempio, puoi selezionare l'effetto di accensione o spegnimento e decidere quale dei due applicare. Il dispositivo creato non può eseguirli entrambi. Il personaggio può avere in contemporanea fino a tre oggetti del genere. Ciascuno si smantella 8 ore dopo la sua creazione o finché non lo fa il personaggio stesso con un'azione di Contatto o Utilizzo.","page":95},"feature.gnome.gnomish-cunning":{"name":"Astuzia gnomesca","description":"Dispone di vantaggio a i tiri salvezza su Intelligenza, Saggezza e Carisma.","page":95},"feature.gnome.gnomish-lineage":{"name":"Lignaggio gnomesco","description":"Come parte di un lignaggio, è dotato di abilità soprannaturali. Scegli una delle opzioni seguenti. A prescindere da quella selezionata, la caratteristica da incantatore del personaggio può essere Intelligenza, Saggezza o Carisma per gli incantesimi lanciati con questo tratto (decidi l'abilità quando scegli il lignaggio):\\n\\n- **Gnomo delle foreste.** Il personaggio conosce il trucchetto illusione minore. Inoltre, l'incantesimo parlare con gli animali è sempre considerato come preparato. Può lanciarlo senza consumare uno slot incantesimo un numero di volte pari al suo bonus di competenza e riacquista tutti gli usi spesi al termine di un riposo lungo. Può anche lanciare l'incantesimo usando uno qualsiasi degli slot incantesimo a sua disposizione.\\n- **Gnomo delle rocce.** Conosce i trucchetti riparare e prestidigitazione. Inoltre, può impiegare 10 minuti di lancio di prestidigitazione per creare un piccolo dispositivo meccanico (CA 5, 1 PF), come un giocattolo, un accendifuoco o un carillon. Una volta creato, puoi determinare il suo effetto scegliendolo fra quelli di prestidigitazione. Il dispositivo lo produrrà ogni volta che il personaggio o un'altra creatura utilizza un'azione bonus per attivarlo a contatto. Se l'effetto selezionato presenta ulteriori opzioni, puoi sceglierne una al momento della creazione del congegno. Per esempio, puoi selezionare l'effetto di accensione o spegnimento e decidere quale dei due applicare. Il dispositivo creato non può eseguirli entrambi. Il personaggio può avere in contemporanea fino a tre oggetti del genere. Ciascuno si smantella 8 ore dopo la sua creazione o finché non lo fa il personaggio stesso con un'azione di Contatto o Utilizzo.","page":95},"feature.gnome.darkvision":{"name":"Scurovisione","description":"Il personaggio ha scurovisione fino a un raggio di 18 metri.","page":95},"species.halfling":{"name":"Halfling","description":"In quanto halfling, il personaggio ha i seguenti tratti speciali.","page":96},"feature.halfling.halfling-nimbleness":{"name":"Agilità halfling","description":"Può attraversare lo spazio occupato da qualsiasi creatura più grande di lui, ma non può soffermarcisi.","page":96},"feature.halfling.brave":{"name":"Coraggioso","description":"Dispone di vantaggio ai tiri salvezza eseguiti per evitare o terminare la condizione spaventato su se stesso.","page":96},"feature.halfling.luck":{"name":"Fortuna","description":"Quando effettui una prova con d20 e ottieni 1, puoi ritirare il dado e devi utilizzare il nuovo risultato.","page":96},"feature.halfling.naturally-stealthy":{"name":"Furtività innata","description":"Può effettuare l'azione di Nascondersi anche se è oscurato solo da una singola creatura, purché questa sia più grande di lui di almeno una taglia.","page":96},"species.dragonborn":{"name":"Dragonide","description":"In quanto dragonide, il personaggio ha i seguenti tratti speciali.","page":94},"feature.dragonborn.draconic-flight":{"name":"Volo draconico","description":"Quando il personaggio raggiunge il 5º livello, può incanalare dell'energia draconica per volare temporaneamente. Come azione bonus, può far spuntare delle ali spettrali dalla sua schiena che durano per 10 minuti, fino al momento in cui decide di farle scomparire (nessuna azione richiesta) o finché non diventa incapacitato. Durante quel periodo, è dotato di una velocità di volo pari alla sua velocità. L'aspetto delle ali varia in base al tipo di energia del Soffio. Dopo aver usato questo tratto, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.","page":94},"feature.dragonborn.draconic-ancestry":{"name":"Discendenza draconica","description":"Il personaggio discende da un progenitore draconico. Scegli la tipologia dalla tabella Antenati draconici. La tua decisione definisce il tipo di soffio e il tratto di resistenza ai danni, ma anche l'aspetto del personaggio.\\n\\n**Antenati draconici**\\n\\n|Drago|Tipo di danni|Drago|Tipo di danni|\\n|---|---|---|---|\\n|Argento|Freddo|Oro|Fuoco|\\n|Bianco|Freddo|Ottone|Fuoco|\\n|Blu|Fulmine|Rame|Acido|\\n|Bronzo|Fulmine|Rosso|Fuoco|\\n|Nero|Acido|Verde|Veleno|","page":94},"feature.dragonborn.damage-resistance":{"name":"Resistenza ai danni","description":"Il personaggio dispone di resistenza ai danni del tipo determinato dal tratto Discendenza draconica.","page":94},"feature.dragonborn.darkvision":{"name":"Scurovisione","description":"Il personaggio ha scurovisione fino a un raggio di 18 metri.","page":94},"feature.dragonborn.breath-weapon":{"name":"Soffio","description":"Quando il personaggio esegue l'azione di Attacco durante il turno, può sostituire uno dei suoi attacchi con un'esalazione di energia magica in un cono di 4,5 metri o in una linea lunga 9 metri e larga 1,5 (puoi scegliere la forma a ogni utilizzo). Ogni creatura nell'area deve effettuare un tiro salvezza su Destrezza (CD 8 più il modificatore di Costituzione e il bonus di competenza del personaggio). In caso di fallimento, vengono inflitti 1d10 danni del tipo determinato dal tratto Discendenza draconica. In caso di successo, subisce soltanto la metà di quei danni. I danni aumentano di 1d10 quando il personaggio raggiunge il 5º livello (2d10), l'11º livello (3d10) e il 17º livello (4d10).\\n\\nIl personaggio può utilizzare il Soffio un numero di volte pari al valore del suo bonus di competenza e recuperare tutti gli utilizzi spesi quando completa un riposo lungo.","page":94},"species.goliath":{"name":"Goliath","description":"In quanto goliath, il personaggio ha i seguenti tratti speciali.","page":95},"feature.goliath.large-form":{"name":"Forma Grande","description":"A partire dal 5º livello, come azione bonus può diventare di taglia Grande se si trova in uno spazio abbastanza ampio. La trasformazione dura per 10 minuti o finché non la interrompe (nessuna azione richiesta). Per tutta la sua durata, ottiene vantaggio alle prove di Forza e la sua velocità aumenta di 3 metri. Dopo aver usato questo tratto, il personaggio non può riutilizzarlo prima di aver completato un riposo lungo.","page":96},"feature.goliath.powerful-build":{"name":"Costituzione robusta","description":"Ha vantaggio a qualsiasi prova di caratteristica effettuata per non essere afferrato. Inoltre, la capacità di trasporto del personaggio è quella di una taglia superiore.","page":95},"feature.goliath.giant-ancestry":{"name":"Discendenza gigantica","description":"Il personaggio discende dai giganti. Sceglie uno dei seguenti doni soprannaturali derivati dal suo retaggio. Il personaggio può utilizzare il beneficio un numero di volte pari al valore del suo bonus di competenza e recupera tutti gli utilizzi spesi quando completa un riposo lungo:\\n\\n- **Brivido gelante (gigante del gelo).** Quando colpisce un bersaglio con un tiro per colpire e gli infligge dei danni, può anche infliggergli 1d6 danni da freddo e ridurre la sua velocità di 3 metri fino all'inizio del proprio turno successivo.\\n- **Forza della collina (gigante delle colline).** Quando colpisce una creatura di taglia Grande o inferiore con un tiro per colpire e le infligge dei danni, quest'ultima può cadere prona.\\n- **Fuoco bruciante (gigante del fuoco).** Quando colpisce un bersaglio con un tiro per colpire e gli infligge dei danni, può anche infliggergli 1d10 danni da fuoco.\\n- **Resistenza della pietra (gigante delle pietre).** Quando subisce danni, può usare una reazione per tirare 1d12. Aggiungi il suo modificatore di Costituzione al numero ottenuto e sottrai il totale ai danni subiti.\\n- **Salta-nuvole (gigante delle nuvole).** Come azione bonus, può teletrasportarsi magicamente di un massimo di 9 metri fino a uno spazio libero che è in grado di vedere.\\n- **Tuono tempestoso (gigante delle tempeste).** Quando subisce danni da una creatura entro 18 metri da sé, può usare una reazione per infliggerle 1d8 danni da tuono.","page":95},"species.tiefling":{"name":"Tiefling","description":"In quanto tiefling, il personaggio ha i seguenti tratti speciali.","page":96},"feature.tiefling.otherworldly-presence":{"name":"Presenza ultraterrena","description":"Conosce il trucchetto taumaturgia. Quando lo lancia sfruttando questo tratto, l'incantesimo utilizza la stessa caratteristica da incantatore del tratto Retaggio immondo.","page":96},"feature.tiefling.darkvision":{"name":"Scurovisione","description":"Ha scurovisione fino a un raggio di 18 metri.","page":97},"feature.tiefling.fiendish-legacy":{"name":"Retaggio immondo","description":"Grazie alla sua discendenza è dotato di abilità soprannaturali. Scegli un retaggio dalla tabella Retaggi immondi. Dopodiché, il personaggio otterrà il beneficio di 1º livello del retaggio selezionato.\\n\\nQuando raggiunge i livelli 3 e 5, apprenderà un incantesimo di livello superiore, come mostrato nella tabella. Tale incantesimo è sempre considerato come preparato. Può lanciarlo una volta senza consumare uno slot incantesimo e ne recupera l'utilizzo in questo modo dopo aver completato un riposo lungo. Può anche lanciarlo usando gli slot incantesimo a sua disposizione del livello appropriato.\\n\\nLa caratteristica da incantatore del personaggio può essere Intelligenza, Saggezza o Carisma per gli incantesimi lanciati con questo tratto (decidi l'abilità quando scegli il retaggio).\\n\\n**Retaggi immondi**\\n\\n|Retaggio|Livello 1|Livello 3|Livello 5|\\n|---|---|---|---|\\n|Abissale|Possiede resistenza ai danni da veleno. Inoltre, conosce il trucchetto spruzzo velenoso.|Raggio di infermità|Blocca persone|\\n|Ctonio|Possiede resistenza ai danni necrotici. Inoltre, conosce il trucchetto tocco gelido.|Vita falsata|Raggio di affaticamento|\\n|Infernale|Possiede resistenza ai danni da fuoco. Inoltre, conosce il trucchetto dardo di fuoco.|Intimorire infernale|Oscurità|","page":96},"species.orc":{"name":"Orco","description":"In quanto orco, il personaggio ha i seguenti tratti speciali.\\n\\nIl personaggio può usare questo tratto un numero di volte pari al valore del suo bonus di competenza e recupera tutti gli utilizzi spesi quando completa un riposo breve o lungo.","page":96},"feature.orc.adrenaline-rush":{"name":"Scarica di adrenalina","description":"L'orco può utilizzare l'azione di Scatto come azione bonus. Ogni volta che lo fa, ottiene un numero di punti ferita temporanei pari al suo bonus di competenza.\\n\\nIl personaggio può usare questo tratto un numero di volte pari al valore del suo bonus di competenza e recupera tutti gli utilizzi spesi quando completa un riposo breve o lungo.","page":96},"feature.orc.darkvision":{"name":"Scurovisione","description":"Ha scurovisione fino a un raggio di 36 metri.","page":96},"feature.orc.relentless-endurance":{"name":"Resistenza implacabile","description":"Quando scende a 0 punti ferita ma non viene ucciso sul colpo, può decidere di rimanere a 1 punto ferita. Dopo averlo usato, non può riutilizzare questo tratto prima di aver completato un riposo lungo.","page":96},"species.elf":{"name":"Elfo","description":"Taglia: Media (altezza di circa 150-180 centimetri)\\n\\nVelocità: 9 metri\\n\\nIn quanto elfo, il personaggio ha i seguenti tratti speciali.","page":94},"feature.elf.trance":{"name":"Trance","description":"Non ha bisogno di dormire e la magia non può farlo addormentare. Può completare un riposo lungo in 4 ore rimanendo in uno stato di trance meditativa, durante il quale resta cosciente.","page":95},"feature.elf.keen-senses":{"name":"Sensi acuti","description":"Ha competenza nelle abilità Intuizione, Percezione o Sopravvivenza.","page":95},"feature.elf.darkvision":{"name":"Scurovisione","description":"Il personaggio ha scurovisione fino a un raggio di 18 metri.","page":94},"feature.elf.elven-lineage":{"name":"Lignaggio elfico","description":"Come parte di un lignaggio, è dotato di abilità soprannaturali. Scegli un lignaggio dalla tabella Lignaggi elfici. Il personaggio otterrà il beneficio di 1º livello di quel determinato lignaggio.\\n\\nQuando raggiunge i livelli 3 e 5, apprenderà un incantesimo di livello superiore, come mostrato nella tabella. Tale incantesimo è sempre considerato come preparato. Può lanciarlo una volta senza consumare uno slot incantesimo e ne recupera l'utilizzo in questo modo dopo aver completato un riposo lungo. Può anche lanciarlo usando gli slot incantesimo a sua disposizione del livello appropriato.\\n\\nLa caratteristica da incantatore del personaggio può essere Intelligenza, Saggezza o Carisma per gli incantesimi lanciati con questo tratto (decidi l'abilità quando scegli il lignaggio).\\n\\n**Lignaggi elfici**\\n\\n|Lignaggio|Livello 1|Livello 3|Livello 5|\\n|---|---|---|---|\\n|Drow|La portata di scurovisione aumenta fino a 36 metri. Inoltre, il personaggio conosce il trucchetto luci danzanti.|Luminescenza|Oscurità|\\n|Elfo alto|Il personaggio impara il trucchetto prestidigitazione. Ogni volta che completa un riposo lungo, può sostituirlo con un altro trucchetto dalla lista degli incantesimi del mago.|Individuazione del magico|Passo velato|\\n|Elfo dei boschi|La velocità del personaggio aumenta a 10,5 metri. Inoltre, conosce il trucchetto artificio druidico.|Passo veloce|Passare senza tracce|","page":94},"feature.elf.fey-ancestry":{"name":"Retaggio fatato","description":"Dispone di vantaggio ai tiri salvezza eseguiti per evitare o terminare la condizione affascinato su se stesso.","page":95},"species.dwarf":{"name":"Nano","description":"In quanto nano, il personaggio ha i seguenti tratti speciali.","page":96},"feature.dwarf.dwarven-resilience":{"name":"Resilienza nanica","description":"Ha resistenza ai danni da veleno. Dispone di vantaggio sui tiri salvezza eseguiti per evitare o terminare la condizione avvelenato su se stesso.","page":96},"feature.dwarf.darkvision":{"name":"Scurovisione","description":"Ha scurovisione fino a un raggio di 36 metri.","page":96},"feature.dwarf.stonecunning":{"name":"Esperto minatore","description":"Come azione bonus, il personaggio ottiene percezione tellurica con un raggio di 18 metri per 10 minuti. Per poterla utilizzare, deve trovarsi su una superficie di pietra o toccarla. La pietra deve essere naturale o lavorata.\\n\\nIl personaggio può utilizzare questa azione bonus un numero di volte pari al valore del suo bonus di competenza, recuperando tutti gli utilizzi spesi quando completa un riposo lungo.","page":96},"feature.dwarf.dwarven-toughness":{"name":"Robustezza nanica","description":"I punti ferita massimi di un nano aumentano di 1 e aumentano di nuovo di 1 ogni volta che acquisisce un livello.","page":96},"species.human":{"name":"Umano","description":"In quanto umano, il personaggio ha i seguenti tratti speciali.","page":97},"feature.human.versatile":{"name":"Versatile","description":"Ottiene un talento Origini a sua scelta (vedi capitolo \\"Talenti\\"). È consigliato il talento Abile.","page":97},"feature.human.resourceful":{"name":"Intraprendente","description":"Ottiene Ispirazione eroica ogni volta che completa un riposo lungo.","page":97},"feature.human.skillful":{"name":"Pluriabilità","description":"Acquisisce competenza in un'abilità a sua scelta.","page":97},"lineage.elf.drow":{"name":"Drow","description":"La portata di scurovisione aumenta fino a 36 metri. Inoltre, il personaggio conosce il trucchetto luci danzanti.","page":95},"lineage.elf.high-elf":{"name":"Elfo alto","description":"Il personaggio impara il trucchetto prestidigitazione. Ogni volta che completa un riposo lungo, può sostituirlo con un altro trucchetto dalla lista degli incantesimi del mago.","page":95},"lineage.elf.wood-elf":{"name":"Elfo dei boschi","description":"La velocità del personaggio aumenta a 10,5 metri. Inoltre, conosce il trucchetto artificio druidico.","page":95},"lineage.tiefling.abyssal":{"name":"Abissale","description":"Possiede resistenza ai danni da veleno. Inoltre, conosce il trucchetto spruzzo velenoso.","page":97},"lineage.tiefling.chthonic":{"name":"Ctonio","description":"Possiede resistenza ai danni necrotici. Inoltre, conosce il trucchetto tocco gelido.","page":97},"lineage.tiefling.infernal":{"name":"Infernale","description":"Possiede resistenza ai danni da fuoco. Inoltre, conosce il trucchetto dardo di fuoco.","page":97},"feature.elf.drow":{"name":"Drow","description":"La portata di scurovisione aumenta fino a 36 metri. Inoltre, il personaggio conosce il trucchetto luci danzanti.","page":95},"feature.elf.high-elf":{"name":"Elfo alto","description":"Il personaggio impara il trucchetto prestidigitazione. Ogni volta che completa un riposo lungo, può sostituirlo con un altro trucchetto dalla lista degli incantesimi del mago.","page":95},"feature.elf.wood-elf":{"name":"Elfo dei boschi","description":"La velocità del personaggio aumenta a 10,5 metri. Inoltre, conosce il trucchetto artificio druidico.","page":95},"feature.gnome.forest-gnome":{"name":"Gnomo delle foreste","description":"Il personaggio conosce il trucchetto illusione minore. Inoltre, l'incantesimo parlare con gli animali è sempre considerato come preparato. Può lanciarlo senza consumare uno slot incantesimo un numero di volte pari al suo bonus di competenza e riacquista tutti gli usi spesi al termine di un riposo lungo. Può anche lanciare l'incantesimo usando uno qualsiasi degli slot incantesimo a sua disposizione.","page":95},"feature.gnome.rock-gnome":{"name":"Gnomo delle rocce","description":"Conosce i trucchetti riparare e prestidigitazione. Inoltre, può impiegare 10 minuti di lancio di prestidigitazione per creare un piccolo dispositivo meccanico (CA 5, 1 PF), come un giocattolo, un accendifuoco o un carillon. Una volta creato, puoi determinare il suo effetto scegliendolo fra quelli di prestidigitazione. Il dispositivo lo produrrà ogni volta che il personaggio o un'altra creatura utilizza un'azione bonus per attivarlo a contatto. Se l'effetto selezionato presenta ulteriori opzioni, puoi sceglierne una al momento della creazione del congegno. Per esempio, puoi selezionare l'effetto di accensione o spegnimento e decidere quale dei due applicare. Il dispositivo creato non può eseguirli entrambi. Il personaggio può avere in contemporanea fino a tre oggetti del genere. Ciascuno si smantella 8 ore dopo la sua creazione o finché non lo fa il personaggio stesso con un'azione di Contatto o Utilizzo.","page":95},"feature.tiefling.abyssal":{"name":"Abissale","description":"Possiede resistenza ai danni da veleno. Inoltre, conosce il trucchetto spruzzo velenoso.","page":97},"feature.tiefling.chthonic":{"name":"Ctonio","description":"Possiede resistenza ai danni necrotici. Inoltre, conosce il trucchetto tocco gelido.","page":97},"feature.tiefling.infernal":{"name":"Infernale","description":"Possiede resistenza ai danni da fuoco. Inoltre, conosce il trucchetto dardo di fuoco.","page":97},"feature.goliath.giant-ancestry.clouds-jaunt":{"name":"Salta-nuvole (gigante delle nuvole)","description":"Come azione bonus, può teletrasportarsi magicamente di un massimo di 9 metri fino a uno spazio libero che è in grado di vedere.","page":96},"feature.goliath.giant-ancestry.fires-burn":{"name":"Fuoco bruciante (gigante del fuoco)","description":"Quando colpisce un bersaglio con un tiro per colpire e gli infligge dei danni, può anche infliggergli 1d10 danni da fuoco.","page":96},"feature.goliath.giant-ancestry.frosts-chill":{"name":"Brivido gelante (gigante del gelo)","description":"Quando colpisce un bersaglio con un tiro per colpire e gli infligge dei danni, può anche infliggergli 1d6 danni da freddo e ridurre la sua velocità di 3 metri fino all'inizio del proprio turno successivo.","page":95},"feature.goliath.giant-ancestry.hills-tumble":{"name":"Forza della collina (gigante delle colline)","description":"Quando colpisce una creatura di taglia Grande o inferiore con un tiro per colpire e le infligge dei danni, quest'ultima può cadere prona.","page":95},"feature.goliath.giant-ancestry.stones-endurance":{"name":"Resistenza della pietra (gigante delle pietre)","description":"Quando subisce danni, può usare una reazione per tirare 1d12. Aggiungi il suo modificatore di Costituzione al numero ottenuto e sottrai il totale ai danni subiti.","page":96},"feature.goliath.giant-ancestry.storms-thunder":{"name":"Tuono tempestoso (gigante delle tempeste)","description":"Quando subisce danni da una creatura entro 18 metri da sé, può usare una reazione per infliggerle 1d8 danni da tuono.","page":96},"spell.illusory-script":{"name":"Scritto illusorio","description":"L'incantatore scrive su una pergamena, un foglio o un altro materiale adatto e infonde nello scritto un'illusione che permane per la durata dell'incantesimo. All'incantatore e a qualsiasi creatura indicata da lui al momento del lancio, lo scritto appare normale, sembra essere stilato nella calligrafia dell'incantatore e trasmette il significato inteso nel momento in cui è stato scritto. Agli occhi di tutti gli altri, il messaggio appare scritto in una lingua magica o ignota che risulta per loro incomprensibile. In alternativa, l'illusione può alterare il significato, la calligrafia e la lingua del testo, ma questa deve essere una lingua conosciuta dall'incantatore.\\n\\nSe l'incantesimo viene dissolto, il messaggio originale e l'illusione scompaiono.\\n\\nUna creatura con vista pura può leggere il messaggio nascosto.","material":"inchiostro del valore di 10 mo o più, che l'incantesimo consuma","page":185},"spell.produce-flame":{"name":"Produrre fiamma","description":"Una fiamma tremolante compare nella mano dell'incantatore e permane per la durata dell'incantesimo. La fiamma non emette calore e non può incendiare nulla; emana luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri. L'incantesimo termina se l'incantatore lo lancia di nuovo.\\n\\nFino al termine dell'incantesimo, l'incantatore può effettuare un'azione di Magia per scagliare la fiamma contro una creatura o un oggetto a 18 metri da lui, effettuando un attacco a distanza con incantesimo. Se il colpo va a segno, il bersaglio subisce 1d8 danni da fuoco.","higherLevels":"I danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).","page":175},"spell.teleportation-circle":{"name":"Cerchio di teletrasporto","description":"Quando lancia l'incantesimo, l'incantatore traccia un cerchio del diametro di 1,5 metri sul terreno dotato di sigilli che collegano il luogo in cui si trova a un cerchio di teletrasporto permanente a sua scelta, di cui conosce la sequenza di sigilli e che si trova sul suo stesso piano di esistenza. All'interno del cerchio tracciato si apre un portale scintillante che rimane aperto fino al termine del suo turno successivo. Qualsiasi creatura che entra nel portale appare immediatamente entro 1,5 metri dal cerchio di destinazione o nello spazio libero più vicino se tale spazio è occupato.\\n\\nNella maggior parte dei casi, templi e palazzi delle gilde più grandi, oltre ad altri luoghi importanti, sono dotati di cerchi di teletrasporto permanenti. Ognuno di essi include una sequenza di sigilli unica: una serie di rune disposte secondo uno schema particolare.\\n\\nQuando l'incantatore ottiene per la prima volta la capacità di lanciare questo incantesimo, apprende la sequenza di sigilli abbinata a due destinazioni situate sul Piano Materiale, determinate dal GM. Nel corso delle sue avventure può apprendere ulteriori sequenze di sigilli, imparando a memoria ciascuna di esse dopo 1 minuto di studio.\\n\\nL'incantatore può creare un cerchio di teletrasporto permanente lanciando questo incantesimo nello stesso luogo ogni giorno per 365 giorni.","material":"inchiostri rari dal valore di 50 mo o più, che l'incantesimo consuma","page":131},"spell.guidance":{"name":"Guida","description":"L'incantatore tocca una creatura consenziente e sceglie un'abilità. Fino al termine dell'incantesimo, la creatura aggiunge 1d4 a qualsiasi prova di caratteristica effettuata utilizzando l'abilità scelta.","page":153},"spell.imprisonment":{"name":"Imprigionare","description":"L'incantatore crea una costrizione magica per trattenere una creatura entro gittata che egli è in grado di vedere. Il bersaglio deve effettuare un tiro salvezza su Saggezza. In caso di successo, il bersaglio non viene influenzato ed è immune a questo incantesimo per le 24 ore successive. In caso di fallimento, il bersaglio è imprigionato. Mentre è imprigionato, il bersaglio non ha bisogno di respirare, mangiare o bere, e non invecchia. Gli incantesimi di divinazione non possono localizzare il bersaglio imprigionato e questo non può teletrasportarsi.\\n\\nInoltre, fino al termine dell'incantesimo, il bersaglio subisce uno dei seguenti effetti a scelta dell'incantatore:\\n\\n- **Ceppi.** Il bersaglio è bloccato da una serie di catene saldamente ancorate al terreno. Il bersaglio è trattenuto e non può essere spostato in alcun modo.\\n- **Prigione protetta.** Il bersaglio è intrappolato in un semipiano protetto da teletrasporto e viaggi planari. Il semipiano può essere un labirinto, una gabbia, una torre o una struttura simile, a scelta dell'incantatore.\\n- **Prigionia ridotta.** Il bersaglio viene rimpicciolito fino all'altezza di 2,5 centimetri ed è intrappolato in una gemma indistruttibile o un oggetto simile. La luce passa attraverso la gemma (permettendo al bersaglio di guardare all'esterno e alle altre creature di guardare all'interno), ma nient'altro può attraversarla in alcun modo.\\n- **Sepoltura.** Il bersaglio viene sepolto nelle viscere della terra in un globo di forza magica sufficientemente ampio da contenerlo. Nulla può entrare o uscire dal globo.\\n- **Sonno.** Il bersaglio è privo di sensi e non può essere risvegliato.\\n\\n**Porre fine all'incantesimo.** Quando lancia l'incantesimo, l'incantatore specifica un innesco che porrà fine all'incantesimo. L'innesco può essere tanto semplice quanto complesso, in base alla scelta dell'incantatore, ma il GM deve ritenere che abbia una certa probabilità di verificarsi entro i dieci anni successivi. L'innesco deve essere un'azione osservabile, ad esempio: una persona che fa un'offerta particolare al tempio della divinità dell'incantatore, il salvataggio del vero amore dell'incantatore, o la sconfitta di un mostro specifico.\\n\\nDissolvi magie può porre fine a questo incantesimo solo se viene lanciato con uno slot incantesimo di 9º livello, bersagliando la prigione o la componente usata per crearla.","material":"una statuetta del bersaglio del valore di 5.000 mo o più","page":155},"spell.hunters-mark":{"name":"Marchio del cacciatore","description":"L'incantatore marchia magicamente come sua preda una creatura entro gittata che egli è in grado di vedere. Fino al termine dell'incantesimo, l'incantatore infligge 1d6 danni da forza extra al bersaglio ogni volta che lo colpisce con un tiro per colpire. Inoltre, l'incantatore dispone di vantaggio a qualsiasi prova di Saggezza (Percezione o Sopravvivenza) che effettua per trovare il bersaglio.\\n\\nSe il bersaglio scende a 0 punti ferita prima del termine dell'incantesimo, l'incantatore può effettuare un'azione bonus per spostare il marchio su un'altra creatura entro gittata che egli è in grado di vedere.","higherLevels":"La concentrazione dell'incantatore può durare di più utilizzando uno slot incantesimo di 3º o 4º livello (fino a 8 ore) o di 5º livello o superiore (fino a 24 ore).","page":164},"spell.spiritual-weapon":{"name":"Arma spirituale","description":"L'incantatore crea una forza spettrale e fluttuante che ha la forma di un'arma a sua scelta e permane per la durata dell'incantesimo. L'arma appare entro gittata in un luogo a scelta dell'incantatore, il quale può subito effettuare un attacco in mischia con incantesimo contro una creatura entro 1,5 metri dall'arma. Se il colpo va a segno, il bersaglio subisce 1d8 danni da forza + il modificatore di caratteristica da incantatore dell'incantatore.\\n\\nCome azione bonus nei suoi turni successivi, l'incantatore può muovere l'arma spirituale di un massimo di 6 metri e ripetere l'attacco contro una creatura situata entro 1,5 metri da essa.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 2º.","page":125},"spell.project-image":{"name":"Immagine proiettata","description":"L'incantatore crea una copia illusoria di se stesso che permane per la durata dell'incantesimo. La copia può apparire in qualsiasi luogo entro gittata che l'incantatore abbia visto in precedenza, a prescindere dalla presenza di ostacoli. L'illusione assomiglia in tutto e per tutto all'incantatore, ma è intangibile. Inoltre, se subisce danni, scompare e l'incantesimo termina.\\n\\nL'incantatore può vedere e sentire attraverso gli occhi e le orecchie dell'illusione, come se si trovasse nel suo spazio. Come azione di Magia, l'incantatore può muovere l'illusione fino a 18 metri e farla gesticolare, parlare e comportare nel modo che ritiene più opportuno. L'illusione imita i modi di fare dell'incantatore alla perfezione.\\n\\nL'illusione può essere rivelata da un'interazione fisica, poiché gli oggetti possono attraversarla. Una creatura che effettua l'azione di Studio per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine e gli eventuali suoni che emette si attenuano alle sue orecchie.","material":"una statuetta dell'incantatore del valore di 5 mo o più","page":154},"spell.phantom-steed":{"name":"Destriero fantomatico","description":"Una creatura di taglia Grande, simile a un cavallo quasi reale, compare sul terreno in uno spazio libero entro gittata a scelta dell'incantatore. L'incantatore sceglie l'aspetto della creatura, che è dotata di sella, morso e briglie. Qualsiasi equipaggiamento creato dall'incantesimo svanisce in uno sbuffo di fumo se trasportato a più di 3 metri dal destriero.\\n\\nPer la durata dell'incantesimo, l'incantatore o una creatura a sua scelta può cavalcare il destriero, che usa la scheda delle statistiche del cavallo da galoppo (vedi \\"Mostri\\"), ma ha una velocità di 30 metri e può percorrere 20 chilometri in un'ora. Al termine dell'incantesimo, la cavalcatura svanisce gradualmente, dando al suo cavaliere 1 minuto per smontare. L'incantesimo termina in anticipo se la cavalcatura subisce danni.","page":141},"spell.spirit-guardians":{"name":"Guardiani spirituali","areaDimensions":"Emanazione di 4,5 metri","description":"Degli spiriti protettori fluttuano attorno al personaggio in un'emanazione di 4,5 metri per la durata dell'incantesimo. Se l'incantatore è buono o neutrale, la loro forma spettrale appare angelica o fatata (a scelta dell'incantatore). Se è malvagio, appaiono con sembianze demoniache.\\n\\nQuando l'incantatore lancia questo incantesimo, può indicare le creature che non ne saranno influenzate. All'interno dell'emanazione, la velocità di ogni altra creatura è dimezzata e, ogni volta che una creatura entra nel suo spazio e viceversa, o ogni volta che vi termina lì il turno, dovrà effettuare un tiro salvezza su Saggezza. Se lo fallisce, subisce 3d8 danni radiosi (se l'incantatore è buono o neutrale) o 3d8 danni necrotici (se è malvagio), mentre se lo supera subisce soltanto la metà di quei danni. Una creatura effettua questo tiro salvezza solo una volta per turno.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 3º.","material":"una pergamena con una preghiera","page":152},"spell.programmed-illusion":{"name":"Illusione programmata","areaDimensions":"Cubo con spigolo di 9 metri","description":"L'incantatore crea un'illusione di un oggetto, una creatura o qualche altro fenomeno visibile entro gittata che si attiva al verificarsi di un innesco specifico. Fino ad allora, l'illusione è impercettibile. Inoltre, essa non può essere più grande di un cubo con spigolo di 9 metri ed è l'incantatore, al momento del lancio, a decidere come si comporta e quali suoni emette. Questa esibizione programmata può durare un massimo di 5 minuti.\\n\\nQuando l'innesco specificato si verifica, l'illusione si materializza e si comporta nella maniera descritta dall'incantatore. Al termine della sua esibizione, l'illusione scompare e rimane latente per 10 minuti, dopo i quali può essere attivata nuovamente.\\n\\nL'innesco può essere sia generale che dettagliato, ma deve essere basato su fenomeni visibili o udibili che si verificano entro 9 metri dall'area. Per esempio, l'incantatore potrebbe creare un'illusione di se stesso per avvertire coloro che tentano di aprire una porta protetta da una trappola.\\n\\nL'illusione può essere rivelata da un'interazione fisica, poiché gli oggetti possono attraversarla. Una creatura che effettua l'azione di Studio per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine e gli eventuali suoni che emette si attenuano alle sue orecchie.","material":"polvere di giada del valore di 25 mo o più","page":154},"spell.mage-hand":{"name":"Mano magica","description":"Una mano spettrale fluttuante compare in un punto a scelta dell'incantatore situato entro gittata. La mano permane per la durata dell'incantesimo e svanisce se si trova a più di 9 metri dall'incantatore o se quest'ultimo lancia nuovamente l'incantesimo.\\n\\nQuando lancia l'incantesimo, l'incantatore può usare la mano per maneggiare un oggetto, aprire una porta o un contenitore che non siano chiusi a chiave, riporre o estrarre un oggetto da un contenitore aperto o versare il contenuto di una fiala.\\n\\nCome azione di Magia nei tuoi turni successivi, puoi controllare nuovamente la mano. Come parte di quell'azione, puoi muoverla fino a 9 metri.\\n\\nLa mano non può attaccare, attivare oggetti magici o trasportare più di 5 chilogrammi.","page":164},"spell.true-strike":{"name":"Colpo accurato","description":"Guidato da un lampo di intuizione magica, l'incantatore effettua un attacco con l'arma utilizzata per lanciare l'incantesimo. Per determinare il tiro per colpire e il tiro per i danni, l'incantatore utilizza la sua caratteristica da incantatore invece che la Forza o la Destrezza. Se l'attacco infligge danni, possono essere danni radiosi o danni normali inflitti dall'arma (a scelta dell'incantatore).","higherLevels":"A prescindere dal tipo di danni che l'incantatore sceglie (danni radiosi o danni normali dell'arma), l'attacco infligge danni radiosi extra quando l'incantatore raggiunge il 5º livello (1d6), l'11º livello (2d6) e il 17º livello (3d6).","material":"un'arma nel cui uso l'incantatore ha competenza e ha un valore di 1 mr o più","page":133},"spell.contagion":{"name":"Contagio","description":"Il tocco dell'incantatore trasmette un contagio magico. Il bersaglio deve superare un tiro salvezza su Costituzione, altrimenti subirà 11d8 danni necrotici e sarà avvelenato. Inoltre, quando l'incantatore lancia l'incantesimo, sceglie una caratteristica. Mentre è avvelenato, il bersaglio subisce svantaggio ai tiri salvezza effettuati con la caratteristica scelta.\\n\\nIl bersaglio deve ripetere il tiro salvezza alla fine di ogni suo turno finché non raggiunge tre tiri superati o falliti. Se il bersaglio supera tre tiri salvezza, si libera dall'effetto dell'incantesimo. Se il bersaglio fallisce tre tiri salvezza, subisce l'incantesimo per 7 giorni.\\n\\nOgni volta che il bersaglio avvelenato riceve un effetto che porrebbe fine all'avvelenamento, deve riuscire a superare un tiro salvezza su Costituzione, altrimenti l'avvelenamento permane.","page":135},"spell.mirage-arcane":{"name":"Miraggio arcano","areaDimensions":"Area quadrata con lato fino a 1,5 chilometri","description":"L'incantatore fa in modo che il terreno in un'area quadrata con lato fino a 1,5 chilometri appaia, suoni, odori e perfino risulti al tatto come un altro tipo di terreno. Un campo aperto o una strada potrebbe così sembrare una palude, una collina, un crepaccio o qualche altro tipo di terreno impervio e invalicabile. Allo stesso modo, uno stagno potrebbe apparire come un prato erboso, un precipizio come un dolce pendio o un fosso irto di rocce come una strada ampia e accogliente.\\n\\nL'incantatore può similmente modificare l'aspetto di strutture o aggiungerne altre dove non sono presenti. Tuttavia, l'incantesimo non può camuffare, occultare o aggiungere creature.\\n\\nL'illusione include elementi uditivi, visivi, tattili e olfattivi, quindi può trasformare un terreno libero in un terreno difficile (o viceversa), oppure ostacolare in altri modi i movimenti all'interno dell'area. Ogni frammento di terreno illusorio (come una roccia o un bastone) che viene rimosso dall'area dell'incantesimo scompare immediatamente.\\n\\nLe creature con vista pura sono in grado di vedere la vera forma del terreno attraverso l'illusione; tuttavia, permangono tutti gli altri elementi dell'illusione, quindi, nonostante la creatura sia consapevole della sua presenza, può continuare a interagire fisicamente con essa.","page":165},"spell.resistance":{"name":"Resistenza","description":"L'incantatore tocca una creatura consenziente e sceglie un tipo di danno: acido, contundente, freddo, fulmine, fuoco, necrotico, perforante, radioso, tagliente, tuono, veleno. Quando una creatura subisce danni del tipo scelto prima del termine dell'incantesimo, riduce il totale dei danni subiti di 1d4. Una creatura può beneficiare di questo incantesimo solo una volta per turno.","page":179},"spell.resurrection":{"name":"Resurrezione","description":"L'incantatore tocca e resuscita una creatura morta da non più di un secolo, che non sia morta di vecchiaia e che non fosse un non morto al momento della morte.\\n\\nLa creatura torna in vita con tutti i suoi punti ferita. Inoltre, questo incantesimo neutralizza qualsiasi veleno che influenzava la creatura al momento della morte, richiude tutte le ferite mortali e ripristina le eventuali parti del corpo mancanti.\\n\\nIl ritorno dalla morte è un vero e proprio travaglio. Il bersaglio subisce una penalità di −4 alle prove con d20. Ogni volta che completa un riposo lungo, questa penalità viene ridotta di 1 finché non arriva a 0.\\n\\nLanciare questo incantesimo per riportare in vita una creatura morta da 365 giorni o più risulta logorante per l'incantatore. Finché non completa un riposo lungo, non può lanciare di nuovo incantesimi e subisce svantaggio alle prove con d20.","material":"un diamante del valore di 1.000 mo o più, che l'incantesimo consuma","page":179},"spell.ray-of-enfeeblement":{"name":"Raggio di affaticamento","description":"Un raggio di energia logorante scaturisce dall'incantatore verso una creatura entro gittata. Il bersaglio deve effettuare un tiro salvezza su Costituzione. In caso di successo, fino all'inizio del turno successivo dell'incantatore, il bersaglio subisce svantaggio al suo tiro per colpire successivo.\\n\\nIn caso di fallimento, il bersaglio subisce svantaggio alle prove con d20 basate sulla Forza per la durata dell'incantesimo. Durante questo periodo, sottrae anche 1d8 da tutti i suoi tiri per i danni. Alla fine di ogni suo turno, il bersaglio ripete il tiro salvezza e, se lo supera, termina l'incantesimo.","page":177},"spell.irresistible-dance":{"name":"Danza irresistibile","description":"Una creatura entro gittata che l'incantatore è in grado di vedere deve effettuare un tiro salvezza su Saggezza. In caso di successo, il bersaglio danza comicamente fino al termine del proprio turno successivo, durante il quale deve spendere tutto il suo movimento danzando sul posto.\\n\\nSe il bersaglio fallisce il tiro, diventa affascinato per la durata dell'incantesimo. Mentre è affascinato, il bersaglio danza comicamente, deve spendere tutto il suo movimento danzando sul posto, subisce svantaggio ai tiri salvezza su Destrezza e ai tiri per colpire, e le altre creature dispongono di vantaggio ai tiri per colpire contro di esso. In ognuno dei suoi turni, il bersaglio può effettuare un'azione per riprendere il controllo di sé e ripetere il tiro salvezza. Se lo supera, l'incantesimo termina.","page":139},"spell.finger-of-death":{"name":"Dito della morte","description":"L'incantatore scatena un'ondata di energia negativa contro una creatura entro gittata che egli è in grado di vedere. Il bersaglio effettua un tiro salvezza su Costituzione, subendo 7d8 + 30 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nAll'inizio del turno successivo dell'incantatore, un umanoide ucciso da questo incantesimo si rianima come uno zombi (vedi \\"Mostri\\") che segue gli ordini verbali dell'incantatore.","page":143},"spell.animal-shapes":{"name":"Forme animali","description":"L'incantatore sceglie un qualsiasi numero di creature consenzienti entro gittata che egli è in grado di vedere. Ogni bersaglio muta forma in una bestia Grande o Piccola a scelta, con un grado di sfida pari o inferiore a 4. L'incantatore può scegliere una forma differente per ogni bersaglio e, nei turni successivi, può effettuare un'azione di Magia per trasformare nuovamente i bersagli.\\n\\nLe statistiche della bestia scelta sostituiscono le statistiche di gioco del bersaglio, il cui tipo di creatura non cambia. Inoltre, il bersaglio conserva i punti ferita, i dadi vita, il proprio allineamento, l'abilità di comunicare e i punteggi di Intelligenza, Saggezza e Carisma. Le azioni del bersaglio sono limitate dalla forma anatomica della bestia scelta, che non può lanciare incantesimi. L'equipaggiamento del bersaglio si fonde nella nuova forma e non può essere utilizzato finché non viene assunta di nuovo la forma originale.\\n\\nIl bersaglio guadagna un numero di punti ferita temporanei pari ai punti ferita della prima forma in cui viene mutato. Al termine dell'incantesimo, il bersaglio perde tutti i punti ferita temporanei rimasti. La trasformazione permane per la durata dell'incantesimo o finché il bersaglio non la termina come azione bonus.","page":149},"spell.dimension-door":{"name":"Porta dimensionale","description":"L'incantatore si teletrasporta in un punto entro gittata arrivando precisamente nel luogo desiderato, che può essere un punto che è in grado di vedere, che riesce a visualizzare o che è in grado di descrivere dichiarandone la distanza e la direzione, come per esempio \\"60 metri in linea retta verso il basso\\" o \\"90 metri verso nord-ovest, a un'angolazione ascendente di 45 gradi\\".\\n\\nL'incantatore può anche teletrasportare una creatura consenziente. Prima che si teletrasporti, la creatura deve trovarsi entro 1,5 metri dall'incantatore, per poi teletrasportarsi in uno spazio entro 1,5 metri dalla destinazione dell'incantatore.\\n\\nSe l'incantatore, l'altra creatura o entrambi arrivano in uno spazio occupato da una creatura o riempito completamente da uno o più oggetti, l'incantatore e qualsiasi creatura che viaggia con lui subiscono 4d6 danni da forza e il teletrasporto fallisce.","page":174},"spell.mass-suggestion":{"name":"Suggestione di massa","description":"L'incantatore suggerisce un corso d'azione da intraprendere (descritto con non più di 25 parole) a fino a dodici creature entro gittata che egli è in grado di vedere. Le creature devono essere in grado di comprendere l'incantatore. Il suggerimento deve apparire realizzabile e non deve comportare nulla che infligga palesemente danni ai bersagli o ai loro alleati. Ad esempio, l'incantatore potrebbe dire: \\"Cammina fino al villaggio in fondo alla strada e aiuta gli abitanti a raccogliere le colture fino al tramonto\\". Oppure potrebbe dire: \\"Non è il momento della violenza. Getta le armi e balla! Fermati tra un'ora\\".\\n\\nOgni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti rimane affascinato per la durata dell'incantesimo o finché l'incantatore o i suoi alleati non gli infliggono danni. Ogni bersaglio affascinato segue il suggerimento al meglio delle sue capacità. L'attività suggerita può continuare per l'intera durata, ma se può essere completata in un tempo più breve, l'incantesimo termina e non ha più effetto sul bersaglio che completa l'attività.","higherLevels":"La durata aumenta con uno slot incantesimo di 7º livello (10 giorni), 8º livello (30 giorni) o 9º livello (366 giorni).","material":"una lingua di serpente","page":193},"spell.hex":{"name":"Sortilegio","description":"L'incantatore scaglia una maledizione su una creatura entro gittata che egli è in grado di vedere. Fino al termine dell'incantesimo, l'incantatore infligge 1d6 danni necrotici extra al bersaglio ogni volta che lo colpisce con un tiro per colpire. Inoltre, quando l'incantatore lancia l'incantesimo, sceglie una caratteristica. Il bersaglio subisce svantaggio alle prove di caratteristica effettuate con la caratteristica scelta.\\n\\nSe il bersaglio scende a 0 punti ferita prima del termine dell'incantesimo, l'incantatore può effettuare un'azione bonus in un suo turno successivo per maledire un'altra creatura.","higherLevels":"La concentrazione dell'incantatore può durare di più utilizzando uno slot incantesimo di 2º livello (fino a 4 ore), di 3º o 4º livello (fino a 8 ore) o di 5º livello o superiore (24 ore).","material":"l'occhio pietrificato di un tritone","page":191},"spell.geas":{"name":"Costrizione","description":"L'incantatore impartisce un comando verbale a una creatura entro gittata che egli è in grado di vedere, ordinandole di compiere un servizio di qualche tipo o ad astenersi dal compiere un'azione o un'attività, come da lui stabilito. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti rimane affascinato per la durata dell'incantesimo. Il bersaglio supera automaticamente il tiro se non è in grado di comprendere il comando dell'incantatore.\\n\\nMentre è affascinata, la creatura subisce 5d10 danni psichici se agisce in maniera direttamente contraria al comando dell'incantatore, subendo questi danni non più di una volta al giorno.\\n\\nL'incantatore può impartire al bersaglio un comando a sua scelta, a eccezione di un'attività che ne provocherebbe la morte certa: se impartisce un comando suicida, l'incantesimo termina.\\n\\nUn incantesimo desiderio, rimuovi maledizione o ristorare superiore è in grado di porre fine all'incantesimo.","higherLevels":"Se l'incantatore usa uno slot incantesimo di 7º o 8º livello, la durata diventa 365 giorni. Se l'incantatore usa uno slot incantesimo di 9º livello, l'incantesimo dura finché uno degli incantesimi menzionati sopra non vi pone fine.","page":137},"spell.divine-favor":{"name":"Favore divino","description":"Fino al termine dell'incantesimo, i suoi attacchi con le armi infliggono 1d4 danni radiosi extra se il colpo va a segno.","page":147},"spell.identify":{"name":"Identificare","description":"L'incantatore tocca un oggetto per la durata del lancio dell'incantesimo. Se si tratta di un oggetto magico o di un altro oggetto infuso di magia, apprende le sue proprietà e come usarlo, se richiede sintonia e quante cariche contiene, se ce ne sono. Apprende anche se l'oggetto è influenzato da eventuali incantesimi in corso e di quali si tratta. Se l'oggetto è stato creato da un incantesimo, l'incantatore apprende il nome di quell'incantesimo.\\n\\nSe invece durante il lancio dell'incantesimo l'incantatore tocca una creatura, apprende quali incantesimi in corso la stanno influenzando, se ce ne sono.","material":"una perla del valore di 100 mo o più","page":153},"spell.divine-word":{"name":"Parola divina","description":"L'incantatore pronuncia una parola pervasa di potere dei Piani Superiori. Ogni creatura a sua scelta situata entro gittata effettua un tiro salvezza su Carisma. In caso di fallimento, un bersaglio che ha 50 punti ferita o meno subisce un effetto basato sui suoi punti ferita attuali, come indicato nella tabella Effetti della parola divina. Indipendentemente dai suoi punti ferita, un bersaglio celestiale, elementale, folletto o immondo che fallisce il suo tiro salvezza viene respinto sul suo piano d'origine (se non vi si trova già) e non può ritornare sul piano attuale per 24 ore in alcun modo se non tramite un incantesimo desiderio.\\n\\n**Tabella: Effetti della parola divina**\\n\\n|Punti ferita|Effetto|\\n|---|---|\\n|0–20|Il bersaglio muore.|\\n|21–30|Il bersaglio è accecato, assordato e stordito per 1 ora.|\\n|31–40|Il bersaglio è accecato e assordato per 10 minuti.|\\n|41–50|Il bersaglio è assordato per 1 minuto.|","page":172},"spell.earthquake":{"name":"Terremoto","areaDimensions":"Raggio di 30 metri","description":"L'incantatore sceglie un punto del terreno entro gittata che egli è in grado di vedere. Per la durata dell'incantesimo, una scossa intensa sconquassa il terreno in un raggio di 30 metri centrato su quel punto, rendendolo terreno difficile.\\n\\nQuando l'incantatore lancia questo incantesimo, e alla fine di ogni suo turno per tutta la durata, ogni creatura sul terreno nell'area effettua un tiro salvezza su Destrezza. In caso di fallimento, la creatura cade prona e la sua concentrazione viene interrotta.\\n\\nL'incantatore può anche causare i seguenti effetti.\\n\\n**Crepe.** Un totale di 1d6 crepe si apre nell'area dell'incantesimo alla fine del turno in cui viene lanciato. L'incantatore sceglie i punti in cui si aprono le crepe, che non possono trovarsi al di sotto di strutture. Ognuna di esse è profonda 1d10 × 3 metri, ampia 3 metri e si estende da un lato all'altro dell'area dell'incantesimo. Se una creatura si trova nel punto in cui si apre una crepa, deve superare un tiro salvezza su Destrezza o vi cade dentro. Una creatura che supera il tiro salvezza riesce a spostarsi insieme al bordo della crepa mentre si apre.\\n\\n**Strutture.** La scossa infligge 50 danni contundenti a una qualsiasi struttura a contatto con il terreno nell'area in cui è stato lanciato l'incantesimo e alla fine di ogni turno dell'incantatore fino al termine dell'incantesimo. Se la struttura scende a 0 punti ferita, crolla.\\n\\nUna creatura situata entro una distanza da una struttura in disfacimento pari alla metà dell'altezza della struttura stessa effettua un tiro salvezza su Destrezza. Se fallisce, subisce 12d6 danni contundenti, viene buttata a terra prona e rimane sepolta sotto le macerie; per liberarsi con un'azione deve effettuare una prova di Forza (Atletica) con CD 20. In caso di successo, subisce soltanto la metà di quei danni.","material":"una roccia fratturata","page":196},"spell.animal-messenger":{"name":"Animale messaggero","description":"Una bestia Minuscola a scelta entro gittata che l'incantatore è in grado di vedere deve superare un tiro salvezza su Carisma, altrimenti deve cercare di consegnare un messaggio da parte dell'incantatore (se il grado di sfida del bersaglio non è 0, la prova viene superata automaticamente). L'incantatore specifica il luogo di consegna, che ha già visitato, e un destinatario che corrisponda a una descrizione generica, come \\"una persona che indossa l'uniforme della guardia cittadina\\" o \\"un nano dai capelli rossi che indossa un cappello a punta\\". Inoltre, l'incantatore comunica un messaggio composto da un massimo di venticinque parole. La bestia bersaglio viaggia per la durata dell'incantesimo verso il luogo specificato, percorrendo circa 37,5 chilometri in 24 ore o 75 chilometri se è una bestia volante.\\n\\nQuando la bestia arriva a destinazione, trasmette il messaggio alla creatura descritta, imitando il modo di comunicare dell'incantatore. Se la bestia non raggiunge la sua destinazione prima della fine dell'incantesimo, il messaggio viene perso e la bestia torna nel luogo dove l'incantatore ha lanciato l'incantesimo.","higherLevels":"La durata dell'incantesimo aumenta di 48 ore per ogni slot di livello superiore al 2º.","material":"un boccone di cibo","page":123},"spell.blade-barrier":{"name":"Barriera di lame","description":"L'incantatore crea un muro di lame turbinanti composte da energia magica. Il muro compare entro gittata e permane per la durata dell'incantesimo. L'incantatore crea un muro lineare lungo fino a 30 metri, alto 6 metri e spesso 1,5 metri, oppure un muro circolare del diametro massimo di 18 metri, alto 6 metri e spesso 1,5 metri. Il muro garantisce tre quarti di copertura e il suo spazio è un terreno difficile.\\n\\nQualsiasi creatura situata nello spazio del muro deve effettuare un tiro salvezza su Destrezza, subendo 6d10 danni forza in caso di fallimento, o la metà dei danni in caso di successo. Una creatura effettua il tiro salvezza anche se entra nello spazio del muro o vi termina il suo turno. Il tiro salvezza può essere effettuato solo una volta per turno.","page":127},"spell.magic-circle":{"name":"Cerchio magico","areaDimensions":"Cilindro di 3 metri di raggio e 6 metri di altezza","description":"L'incantatore crea un cilindro di energia magica di 3 metri di raggio e 6 metri di altezza, centrato su un punto del terreno entro gittata che egli è in grado di vedere. Rune luminose appaiono nei punti in cui il cilindro si interseca con il pavimento o altre superfici.\\n\\nL'incantatore sceglie uno o più tra i tipi di creature seguenti: celestiali, elementali, folletti, immondi o non morti. Il cerchio influenza una creatura del tipo scelto nei seguenti modi:\\n\\n- La creatura non può entrare volontariamente nel cilindro tramite mezzi non magici. Se prova a utilizzare il teletrasporto o il viaggio interplanare, deve prima superare un tiro salvezza su Carisma.\\n- La creatura subisce svantaggio ai tiri per colpire contro i bersagli all'interno del cilindro.\\n- I bersagli all'interno del cilindro non possono essere posseduti, affascinati o spaventati dalla creatura.\\n\\nOgni volta che lancia questo incantesimo, l'incantatore può far funzionare la sua magia nella direzione inversa, impedendo cioè a una creatura di un tipo specifico di uscire dal cilindro e proteggendo i bersagli all'esterno.","higherLevels":"La durata aumenta di 1 ora per ogni slot di livello superiore al 3º.","material":"sale e polvere d'argento del valore di 100 mo o più, che l'incantesimo consuma","page":132},"spell.clone":{"name":"Clone","description":"L'incantatore tocca una creatura o un cubo della sua carne di almeno 2,5 cm per lato. Un duplicato inerme di quella creatura si sviluppa all'interno del contenitore utilizzato per lanciare l'incantesimo e finisce di crescere dopo 120 giorni; l'incantatore sceglie se il clone sviluppato ha la stessa età della creatura o è più giovane. Il clone rimane inerte e permane per un tempo indeterminato, fintantoché il suo involucro rimane indisturbato.\\n\\nDopo che il clone ha raggiunto la maturazione, se la creatura originale muore, la sua anima viene trasferita al clone, purché essa sia libera e disposta a tornare. Il clone è fisicamente identico all'originale e possiede la sua personalità, i suoi ricordi e le sue abilità, ma non il suo equipaggiamento. I resti della creatura originale, se ancora esistono, diventano inerti e non possono più essere riportati in vita, in quanto l'anima della creatura è altrove.","material":"un diamante del valore di 1.000 mo o più, che l'incantesimo consuma, e un contenitore sigillabile del valore di 2.000 mo o più, abbastanza grande da contenere la creatura da clonare","page":133},"spell.create-food-and-water":{"name":"Creare cibo e acqua","description":"L'incantatore crea 22,5 chili di cibo e 120 litri d'acqua fresca sul terreno o all'interno di un contenitore entro gittata, utili per tenere lontani i rischi di malnutrizione e disidratazione. Il cibo è insipido ma nutriente e assomiglia a un alimento a scelta dell'incantatore; l'acqua è pulita. Il cibo marcisce dopo 24 ore se non viene consumato.","page":138},"spell.wish":{"name":"Desiderio","description":"Desiderio è l'incantesimo più potente che un mortale sia in grado di lanciare. Gli basta parlare a voce alta per alterare l'essenza stessa della realtà.\\n\\nL'uso base di questo incantesimo è riprodurre un qualsiasi altro incantesimo di livello pari o inferiore all'8º. Utilizzandolo in questo modo, non è necessario soddisfare particolari requisiti per lanciarlo e non servono costose componenti: l'incantesimo ha semplicemente effetto.\\n\\nIn alternativa, l'incantatore può creare uno dei seguenti effetti a sua scelta:\\n\\n- **Creazione di un oggetto.** L'incantatore crea un oggetto del valore massimo di 25.000 mo che non sia un oggetto magico e che non misuri più di 90 metri in ogni dimensione. L'oggetto si materializza a terra in uno spazio libero che l'incantatore è in grado di vedere.\\n- **Salute istantanea.** L'incantatore consente a sé e un massimo di venti creature che egli è in grado di vedere di recuperare tutti i punti ferita e pone fine a tutti gli effetti su di loro come descritto nell'incantesimo ristorare superiore.\\n- **Resistenza.** L'incantatore conferisce a un massimo di dieci creature che egli è in grado di vedere resistenza a un tipo di danno a sua scelta. La resistenza conferita è permanente.\\n- **Immunità a un incantesimo.** L'incantatore conferisce a un massimo di dieci creature che egli è in grado di vedere immunità a un singolo incantesimo o un altro effetto magico per 8 ore.\\n- **Apprendimento improvviso.** L'incantatore sostituisce uno dei suoi talenti con un altro di cui soddisfa i requisiti, perdendo tutti i benefici di quello precedente e ottenendo quelli del nuovo talento. Non è possibile sostituirne uno che è un prerequisito per altri talenti o caratteristiche del personaggio.\\n- **Ripetizione del tiro.** L'incantatore annulla un singolo evento recente imponendo la ripetizione di un qualsiasi tiro effettuato entro l'ultimo round (incluso il suo ultimo turno). La realtà viene rimodellata e si adatta al nuovo risultato. Per esempio, un incantesimo desiderio potrebbe annullare un tiro salvezza fallito da un alleato o il colpo critico inferto da un avversario. L'incantatore può imporre che il tiro ripetuto sia effettuato con vantaggio o svantaggio e poi può scegliere se usare il tiro ripetuto o il tiro originale.\\n- **Riplasmazione della realtà.** L'incantatore potrebbe desiderare qualcosa che non è incluso negli altri effetti elencati. Per farlo, deve dichiarare il suo desiderio al GM nel modo più preciso possibile. Il GM ha la massima libertà di decidere cosa accade in questi casi: più potente è il desiderio, maggiori sono le probabilità che qualcosa vada storto. L'incantesimo potrebbe semplicemente fallire, l'effetto desiderato potrebbe avverarsi solo in parte o l'incantatore potrebbe subire conseguenze inaspettate come risultato della formulazione del desiderio. Per esempio, se desidera che un suo nemico sia morto, potrebbe essere trascinato nel futuro fino al momento in cui quel nemico non è più in vita, venendo a tutti gli effetti rimosso dal gioco. Analogamente, se desidera un manufatto o un oggetto magico leggendario, potrebbe essere trasportato istantaneamente in presenza del suo attuale proprietario. Se il desiderio viene esaudito e i suoi effetti hanno conseguenze per un'intera comunità, regione o per tutto il mondo, l'incantatore potrebbe attirare l'attenzione di potenti nemici. Se invece potrebbe avere effetti su una divinità, i suoi servi divini potrebbero intervenire all'istante per impedirlo o incoraggiare l'incantatore a formularlo in un modo preciso. Se dovesse disfare il multiverso stesso, il desiderio fallisce.\\n\\nLa tensione provocata dal lancio di desiderio per produrre un qualsiasi effetto diverso dalla duplicazione di un altro incantesimo debilita l'incantatore. Dopo aver sopportato quella tensione, ogni volta che l'incantatore lancia un incantesimo prima di avere completato un riposo lungo, subisce 1d10 danni necrotici per livello di quell'incantesimo. Questi danni non possono essere ridotti o prevenuti in alcun modo. Inoltre, il punteggio di Forza dell'incantatore scende a 3 per 2d4 giorni. Per ognuno di quei giorni trascorso a riposare e a non fare nulla fuorché attività poco impegnative, il tempo di recupero rimanente diminuisce di 2 giorni. Esiste infine una probabilità del 33% che l'incantatore non sia più in grado di lanciare desiderio, se non riesce a reggere la tensione.","page":140},"spell.globe-of-invulnerability":{"name":"Globo di invulnerabilità","areaDimensions":"Emanazione di 3 metri","description":"Una barriera scintillante e immobile si materializza in un'emanazione di 3 metri attorno all'incantatore e permane per la durata dell'incantesimo.\\n\\nQualsiasi incantesimo di 5º livello o inferiore lanciato dall'esterno della barriera non può influenzare niente che si trovi al suo interno. Questo tipo di incantesimo può essere rivolto contro le creature e gli oggetti all'interno della barriera, senza tuttavia avere effetti su di loro. Allo stesso modo, l'area all'interno della barriera è esclusa dalle aree di effetto create da questo tipo di incantesimi.","higherLevels":"La barriera blocca incantesimi superiori di 1 livello per ogni slot di livello superiore al 6º.","material":"una perla di vetro","page":152},"spell.incendiary-cloud":{"name":"Nube incendiaria","areaDimensions":"Sfera del raggio di 6 metri","description":"Una nube turbinante di fumo e tizzoni incandescenti appare in una sfera del raggio di 6 metri centrata su un punto entro gittata. L'area coperta dalla nuvola è pesantemente oscurata. La nube permane per la durata dell'incantesimo o finché un vento forte (come quello creato da folata di vento) non la disperde.\\n\\nQuando essa compare, ogni creatura al suo interno effettua un tiro salvezza su Destrezza, subendo 10d8 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo. Una creatura deve effettuare questo tiro salvezza anche quando la sfera si muove nel suo spazio e quando la creatura entra nella sfera o vi termina il suo turno. Una creatura effettua questo tiro salvezza solo una volta per turno.\\n\\nLa nube si allontana di 3 metri dall'incantatore in una direzione scelta da quest'ultimo all'inizio di ogni suo turno.","page":169},"spell.shillelagh":{"name":"Randello incantato","description":"Un randello o un bastone ferrato impugnato dall'incantatore è pervaso dal potere della natura. Per la durata dell'incantesimo, l'incantatore usa la propria caratteristica da incantatore anziché la Forza per i tiri per i danni e i tiri per colpire effettuati negli attacchi in mischia usando quell'arma: inoltre, i danni dell'arma sono calcolati con un d8. Se l'attacco infligge danni, possono essere danni da forza o danni normali inflitti dall'arma (a scelta dell'incantatore).\\n\\nL'incantesimo termina se l'incantatore lo lancia di nuovo o se lascia andare l'arma.","higherLevels":"I danni sono calcolati con un dado diverso quando l'incantatore raggiunge il 5º livello (d10), l'11º livello (d12) e il 17º livello (2d6).","material":"vischio","page":178},"spell.tsunami":{"name":"Tsunami","areaDimensions":"Muro fino a 90 metri di lunghezza, 90 metri di altezza e 15 metri di spessore","description":"Un muro di acqua si materializza in un punto a scelta dell'incantatore entro gittata. Il muro può avere dimensioni massime di 90 metri di lunghezza, 90 metri di altezza e 15 metri di spessore Il muro permane per tutta la durata dell'incantesimo.\\n\\nQuando appare, ogni creatura nell'area effettua un tiro salvezza su Forza, subendo 6d10 danni contundenti in caso di fallimento o la metà dei danni in caso di successo.\\n\\nAll'inizio di ogni turno dell'incantatore, dopo l'apparizione del muro, esso si sposta di 15 metri (insieme alle creature che contiene) allontanandosi dall'incantatore. Qualsiasi creatura di taglia Enorme o inferiore all'interno del muro e qualsiasi creatura in uno spazio in cui il muro entra quando si sposta, deve superare un tiro salvezza su Forza, altrimenti subisce 5d10 danni contundenti. Una creatura può subire questi danni solo una volta per round. Alla fine del turno, l'altezza del muro si riduce di 15 metri e i danni che infligge nei round successivi sono ridotti di 1d10. Quando il muro raggiunge 0 metri di altezza, l'incantesimo termina.\\n\\nUna creatura immersa nel muro può muoversi nuotando. Tuttavia, a causa della forza dell'onda, per potersi effettivamente muovere deve superare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo. Se fallisce la prova, non può muoversi. Una creatura che, muovendosi, esce dal muro, cade a terra.","page":199},"spell.antipathysympathy":{"name":"Antipatia/simpatia","description":"Quando l'incantatore lancia l'incantesimo, decide se creare antipatia o simpatia e sceglie come bersaglio una creatura o un oggetto di taglia Enorme o inferiore. Dopodiché, specifica un tipo di creatura, come per esempio draghi rossi, goblin o vampiri. Una creatura del tipo scelto effettua un tiro salvezza su Saggezza quando si trova entro 36 metri dal bersaglio. La scelta dell'incantatore tra gli effetti di antipatia e simpatia determina cosa accade a una creatura quando questa fallisce il tiro salvezza.\\n\\n- **Antipatia.** La creatura è spaventata e deve usare il movimento nel suo turno per allontanarsi il più possibile dal bersaglio, muovendosi per la via più sicura.\\n- **Simpatia.** La creatura è affascinata e deve usare il movimento nel suo turno per avvicinarsi il più possibile al bersaglio, muovendosi per la via più sicura. Se la creatura si trova entro 1,5 metri dal bersaglio, non può allontanarsi volontariamente. Se il bersaglio infligge danni alla creatura affascinata, questa può effettuare un tiro salvezza su Saggezza per porre fine all'effetto, come descritto di seguito.\\n\\n**Porre fine all'effetto.** Se la creatura spaventata o affascinata termina il suo turno a più di 36 metri di distanza dal bersaglio, effettua un tiro salvezza su Saggezza. In caso di successo, la creatura non è più sotto l'influenza del bersaglio. Una creatura che supera un tiro salvezza contro l'effetto ne è immune per 1 minuto, al termine del quale può esserne influenzata di nuovo.","material":"una miscela di aceto e miele","page":125},"spell.hallucinatory-terrain":{"name":"Terreno illusorio","areaDimensions":"Cubo con spigolo di 45 metri","description":"L'incantatore fa in modo che un terreno naturale in un cubo con spigolo di 45 metri entro gittata abbia l'aspetto, i suoni e gli odori di un altro tipo di terreno naturale. Un campo aperto o una strada potrebbe così sembrare una palude, una collina, un crepaccio o qualche altro tipo di terreno difficile e invalicabile. Allo stesso modo, uno stagno potrebbe apparire come un prato erboso, un precipizio come un dolce pendio o un fosso irto di rocce come una strada ampia e accogliente. Tuttavia, le strutture artificiali, l'equipaggiamento e le creature all'interno dell'area non cambiano.\\n\\nInoltre, le caratteristiche tattili del terreno rimangono invariate, quindi le creature che entrano nell'area hanno buone probabilità di accorgersi dell'illusione. Se la differenza non è ovvia al tatto, una creatura che esamina l'illusione può effettuare l'azione di Studio per effettuare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo per non essere tratta in inganno. Se una creatura si accorge che il terreno è illusorio, vede un'immagine indistinta sovrapposta al terreno reale.","material":"un fungo","page":196},"spell.astral-projection":{"name":"Proiezione astrale","description":"L'incantatore e un massimo di otto creature consenzienti entro gittata proiettano i loro corpi astrali sul Piano Astrale (l'incantesimo termina immediatamente se l'incantatore si trova già su quel piano). Il corpo di ogni bersaglio cade in uno stato di animazione sospesa; ha la condizione privo di sensi, non ha bisogno di cibo o aria e non invecchia.\\n\\nLa forma astrale di un bersaglio assomiglia in tutto e per tutto al suo corpo, replicando le sue statistiche di gioco e le sue proprietà. La differenza principale consiste nell'aggiunta di un cordone argentato che si snoda tra le scapole della forma astrale, diventando invisibile dopo 30 cm. Se il cordone viene reciso, cosa che può accadere solo quando un effetto lo specifica chiaramente, il corpo e la forma astrale del bersaglio muoiono entrambi.\\n\\nLa forma astrale di un bersaglio può viaggiare sul Piano Astrale. Nel momento in cui una forma astrale lascia questo piano, il corpo e le proprietà del bersaglio vengono trasportati lungo il cordone argentato, permettendogli di rientrare nel suo corpo nel momento in cui accede al nuovo piano.\\n\\nQualsiasi danno o altro effetto che si applichi a una forma astrale non ha effetto sul corpo del bersaglio e viceversa. Inoltre, l'incantesimo termina se il corpo originale o la forma astrale di un bersaglio scende a 0 punti ferita. L'incantesimo termina per tutti i bersagli se l'incantatore effettua un'azione di Magia per interromperlo.\\n\\nQuando l'incantesimo termina per un bersaglio che non è morto, il bersaglio riappare nel suo corpo ed esce dallo stato di animazione sospesa.","material":"per ogni bersaglio dell'incantesimo, l'incantatore deve possedere un giacinto del valore di 1.000 mo o più e un lingotto d'argento del valore di 100 mo o più; l'incantesimo consuma entrambi","page":176},"spell.gentle-repose":{"name":"Riposo inviolato","description":"L'incantatore tocca un cadavere o altri resti. Per la durata dell'incantesimo, il bersaglio è protetto dalla decomposizione e non può diventare un non morto.\\n\\nInoltre, l'incantesimo estende il limite di tempo entro cui rianimare il bersaglio dalla morte, in quanto i giorni trascorsi sotto l'influenza di questo incantesimo non contano al fine di determinare il limite di tempo di incantesimi come rianimare morti.","material":"2 monete di rame, che l'incantesimo consuma","page":181},"spell.vicious-mockery":{"name":"Beffa crudele","description":"L'incantatore pronuncia una sequenza di insulti mescolati a impercettibili ammaliamenti contro una creatura entro gittata che egli è in grado di vedere o di sentire. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti subisce 1d6 danni psichici e svantaggio al tiro per colpire successivo che effettua prima della fine del suo turno successivo.","higherLevels":"I danni aumentano di 1d6 quando l'incantatore raggiunge il 5º livello (2d6), l'11º livello (3d6) e il 17º livello (4d6).","page":128},"spell.wind-walk":{"name":"Camminare nel vento","description":"L'incantatore e un massimo di dieci creature consenzienti a sua scelta entro gittata assumono una forma gassosa per la durata dell'incantesimo, apparendo come sbuffi di nuvole. Finché il bersaglio ha queste sembianze, ha una velocità di volo di 90 metri e può fluttuare. Inoltre, è immune alla condizione prono e resistente ai danni contundenti, perforanti e taglienti. Le uniche azioni che può effettuare in questa forma sono l'azione Scatto, un'azione di Magia o riassumere la propria forma normale. Quest'ultima opzione richiede 1 minuto, durante il quale il bersaglio è stordito. Fino al termine dell'incantesimo, il bersaglio può assumere nuovamente la forma di nuvola usando un'azione di Magia seguita da 1 minuto di trasformazione.\\n\\nSe una creatura è in forma gassosa e sta volando quando l'effetto termina, scende di 18 metri per round per 1 minuto finché non atterra, senza subire danni. Se tuttavia non riesce ad atterrare in 1 minuto, cade per la distanza rimanente.","material":"una candela","page":129},"spell.ensnaring-strike":{"name":"Colpo intrappolante","castingTimeCondition":"che l'incantatore effettua subito dopo aver colpito una creatura con un'arma","description":"Quando l'incantatore colpisce il bersaglio, su di esso appare un groviglio di rampicanti. Il bersaglio effettua un tiro salvezza su Forza, disponendo di vantaggio a questo tiro se è una creatura di taglia Grande o superiore. Se lo fallisce, il bersaglio è trattenuto fino al termine dell'incantesimo. Se lo supera, i rampicanti si ritraggono e avvizziscono, ponendo fine all'incantesimo.\\n\\nFinché è trattenuto, il bersaglio subisce 1d6 danni perforanti all'inizio di ogni suo turno. Il bersaglio o una creatura alla sua portata può usare un'azione per effettuare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo. In caso di successo, l'incantesimo termina.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 1º.","page":133},"spell.control-weather":{"name":"Controllare tempo atmosferico","description":"L'incantatore assume il controllo del tempo atmosferico entro 7,5 chilometri per la durata dell'incantesimo, che dev'essere lanciato in un luogo all'aperto. L'incantesimo termina anticipatamente se l'incantatore si sposta in un luogo chiuso.\\n\\nQuando lancia un incantesimo, l'incantatore cambia le condizioni atmosferiche attuali determinate dal GM. L'incantatore può modificare le precipitazioni, la temperatura e il vento. Occorrono 1d4 × 10 minuti perché le nuove condizioni abbiano effetto. Quando questo accade, l'incantatore le può cambiare di nuovo. Al termine dell'incantesimo, il tempo atmosferico torna alla normalità.\\n\\nQuando l'incantatore modifica le condizioni atmosferiche, trova la condizione attuale nelle tabelle seguenti e la modifica di un grado, verso l'alto o verso il basso. Quando l'incantatore cambia il vento, può modificarne anche la direzione.\\n\\nPrecipitazioni\\n\\nGrado Condizione 1 Sereno 2 Poco nuvoloso 3 Nuvoloso o nebbia 4 Pioggia, grandine o neve 5 Pioggia torrenziale, grandinata violenta o tormenta\\n\\nTemperatura\\n\\nGrado Condizione 1 Torrido 2 Caldo 3 Temperato 4 Fresco 5 Freddo 6 Gelido\\n\\nVento\\n\\nGrado Condizione 1 Calmo 2 Vento moderato 3 Vento forte 4 Burrasca 5 Tempesta","material":"incenso bruciato","page":137},"spell.sunburst":{"name":"Esplosione solare","areaDimensions":"Sfera del raggio di 18 metri","description":"Una radiosa luce solare splende in una sfera del raggio di 18 metri, centrata su un punto entro gittata a scelta dell'incantatore. Ogni creatura al suo interno deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 12d6 danni radiosi e rimane accecata per 1 minuto, mentre se lo supera subisce solo la metà dei danni.\\n\\nUna creatura accecata da questo incantesimo effettua un altro tiro salvezza su Costituzione al termine di ogni suo turno, facendone svanire l'effetto in caso di successo.\\n\\nQuesto incantesimo dissolve qualsiasi oscurità nell'area creata da un incantesimo.","material":"un frammento di pietra di sole","page":145},"spell.weird":{"name":"Fatale","areaDimensions":"Sfera con raggio di 9 metri","description":"L'incantatore tenta di creare orrori illusori nella mente degli avversari. Ogni creatura a sua scelta all'interno di una sfera con raggio di 9 metri, centrata su un punto entro gittata, effettua un tiro salvezza su Saggezza. In caso di fallimento, il bersaglio subisce 10d10 danni psichici ed è spaventato per la durata dell'incantesimo. Se invece lo supera, subisce soltanto la metà di quei danni.\\n\\nUn bersaglio spaventato effettua un tiro salvezza su Saggezza alla fine di ogni suo turno. In caso di fallimento, subisce 5d10 danni psichici, mentre in caso di successo l'incantesimo termina.","page":147},"spell.heal":{"name":"Guarigione","description":"L'incantatore sceglie una creatura entro gittata che egli è in grado di vedere. Un flusso di energia positiva investe il bersaglio, facendogli recuperare 70 punti ferita. Inoltre, questo incantesimo termina le condizioni accecato, assordato e avvelenato che affliggono il bersaglio.","higherLevels":"La guarigione aumenta di 10 per ogni slot di livello superiore al 6º.","page":153},"spell.blight":{"name":"Inaridire","description":"Una creatura entro gittata che l'incantatore è in grado di vedere effettua un tiro salvezza su Costituzione, subendo 8d8 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo. Una creatura vegetale fallisce automaticamente il tiro salvezza.\\n\\nIn alternativa, l'incantatore bersaglia un vegetale non magico che non sia una creatura, come un albero o un arbusto. Il vegetale non effettua il tiro salvezza, semplicemente appassisce e muore.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 4º.","page":156},"spell.wind-wall":{"name":"Muro di vento","areaDimensions":"Muro lungo fino a 15 metri, alto 4,5 metri e spesso 30 cm","description":"Un muro di vento forte si solleva dal terreno in un punto a scelta dell'incantatore situato entro gittata.\\n\\nIl muro può essere lungo fino a 15 metri, alto 4,5 metri e spesso 30 cm. L'incantatore può modellarlo nel modo che preferisce, purché formi un percorso continuo lungo il terreno. Il muro permane per tutta la durata dell'incantesimo.\\n\\nQuando appare, ogni creatura nell'area effettua un tiro salvezza su Forza, subendo 4d8 danni contundenti in caso di fallimento o la metà dei danni in caso di successo.\\n\\nIl vento forte tiene lontani fumo, nebbia e altri gas. Le creature o gli oggetti volanti di taglia Piccola o inferiore non possono passare attraverso il muro e i materiali leggeri, non fissati in qualche modo, volano verso l'alto una volta portati al suo interno. Frecce, quadrelli e altri proiettili ordinari lanciati contro bersagli dietro il muro vengono deviati verso l'alto e mancano automaticamente il bersaglio (i macigni scagliati dai giganti o dalle macchine d'assedio e altri proiettili simili non sono influenzati dal muro). Inoltre, le creature in forma gassosa non possono attraversarlo.","material":"un ventaglio e una piuma","page":168},"spell.mass-healing-word":{"name":"Parola guaritrice di massa","description":"Fino a sei creature a scelta dall'incantatore entro gittata e che egli è in grado di vedere recuperano un ammontare di punti ferita pari a 2d4 più il modificatore di caratteristica da incantatore dell'incantatore.","higherLevels":"La guarigione aumenta di 1d4 per ogni slot di livello superiore al 3º.","page":173},"spell.passwall":{"name":"Passapareti","description":"L'incantatore sceglie un punto entro gittata e che egli è in grado di vedere su una superficie di legno, pietra o intonaco (come una parete, un soffitto o un pavimento), dove si apre un passaggio che permane per la durata dell'incantesimo. L'incantatore sceglie inoltre le dimensioni dell'apertura, che non possono superare una larghezza di 1,5 metri, un'altezza di 2,4 metri e una profondità di 6 metri. Il passaggio non crea alcuna instabilità nella struttura che lo circonda.\\n\\nQuando l'apertura scompare, qualsiasi creatura o oggetto all'interno del passaggio creato dall'incantesimo viene espulso senza subire danni nello spazio libero più vicino alla superficie su cui l'incantesimo è stato lanciato.","material":"un pizzico di semi di sesamo","page":173},"spell.forbiddance":{"name":"Proibizione","areaDimensions":"Area quadrata con lato di 60 metri e un'altezza di massimo 9 metri","description":"L'incantatore crea una difesa contro i viaggi magici che protegge un'area quadrata di terreno con lato di 60 metri e un'altezza di massimo 9 metri. Per la durata dell'incantesimo, per entrare in tale area le creature non possono utilizzare teletrasporto o portali, come quelli creati dall'incantesimo portale. L'incantesimo protegge l'area dai viaggi planari, impedendo perciò alle creature di accedervi tramite il Piano Astrale, il Piano Etereo, la Selva Fatata, la Coltre Oscura e l'incantesimo spostamento planare.\\n\\nInoltre, infligge danni a uno o più tipi di creature indicati dall'incantatore al momento del lancio, scelti tra i seguenti: aberrazioni, celestiali, elementali, folletti, immondi e non morti. Quando una creatura del tipo scelto entra nell'area dell'incantesimo per la prima volta in un turno o termina il suo turno qui, subisce 5d10 danni necrotici o radiosi (a scelta dell'incantatore al momento del lancio).\\n\\nQuando lancia l'incantesimo, l'incantatore può indicare una parola d'ordine: una creatura che la pronuncia accedendo all'area non subisce danni.\\n\\nL'area di questo incantesimo non può sovrapporsi all'area di un altro incantesimo proibizione. Se l'incantatore lancia proibizione ogni giorno nello stesso luogo per 30 giorni, l'incantesimo permane finché non viene dissolto e le componenti materiali vengono consumate al momento dell'ultimo lancio.","material":"polvere di rubino del valore di 1.000 mo o più","page":176},"spell.magnificent-mansion":{"name":"Reggia meravigliosa","description":"L'incantatore evoca una porta scintillante entro gittata che permane per la durata dell'incantesimo. La porta, larga 1,5 metri e alta 3 metri, conduce a una dimora extradimensionale. L'incantatore e una qualsiasi creatura da lui scelta al momento del lancio possono entrare nella dimora extradimensionale fintantoché la porta rimane aperta. L'incantatore può aprire o chiudere la porta (nessuna azione richiesta) se si trova entro 9 metri da essa; quando è chiusa, la porta è impercettibile.\\n\\nOltre la porta si trova un atrio sfarzoso su cui si aprono numerose stanze. L'atmosfera della dimora è pulita, fresca e accogliente.\\n\\nL'incantatore può definire la planimetria della dimora come preferisce, ma le sue dimensioni non devono superare quelle di 50 cubi contigui con spigolo di 3 metri. Inoltre, la dimora è ammobiliata e decorata come l'incantatore preferisce e contiene cibo a sufficienza per servire un banchetto di nove portate per un massimo di 100 persone. Arredi e altri oggetti creati da questo incantesimo si dissolvono in fumo quando vengono rimossi dalla dimora.\\n\\nA provvedere a ogni bisogno degli ospiti è presente una schiera di 100 servitori semitrasparenti. L'incantatore decide l'aspetto e la tenuta di questi servitori, che sono invulnerabili e obbediscono ai suoi ordini. Ogni servitore può eseguire qualsiasi compito che un umano sarebbe in grado di eseguire, ma non può attaccare o effettuare azioni che ferirebbero in modo diretto un'altra creatura. I servitori possono perciò trasportare oggetti, pulire, riparare, piegare abiti, accendere fuochi, servire cibo, versare vino e così via. Tuttavia, non possono lasciare la dimora.\\n\\nAl termine dell'incantesimo, tutte le creature e gli oggetti rimasti all'interno dello spazio extradimensionale vengono espulsi negli spazi liberi più vicini all'entrata.","material":"una miniatura di una porta del valore di 15 mo o più","page":178},"spell.find-the-path":{"name":"Scopri il percorso","description":"L'incantatore percepisce magicamente il percorso fisico più diretto verso una destinazione di cui nomina il nome e che gli sia nota. Se nomina una destinazione su un altro piano di esistenza, una destinazione in movimento (come una fortezza mobile) o una destinazione poco specifica (come \\"la tana di un drago verde\\"), l'incantesimo non ha effetto.\\n\\nPer la durata dell'incantesimo, finché l'incantatore si trova sullo stesso piano di esistenza della destinazione, sa quanto è lontana e in che direzione si trova. Ogni volta che l'incantatore si trova a scegliere tra più percorsi, sa qual è il più diretto.","material":"un set di strumenti di divinazione, come carte o rune, del valore di 100 mo o più","page":184},"spell.silence":{"name":"Silenzio","areaDimensions":"Sfera del raggio di 6 metri","description":"L'incantatore genera una sfera del raggio di 6 metri centrata su un punto a sua scelta situato entro gittata e, per la durata dell'incantesimo, nessun suono può essere creato all'interno di quella sfera o attraversarla. Ogni creatura o oggetto interamente all'interno della sfera è immune ai danni da tuono e ogni creatura interamente all'interno della sfera è assordata. All'interno dell'area è impossibile lanciare un incantesimo che includa una componente verbale.","page":189},"spell.symbol":{"name":"Simbolo","areaDimensions":"Sfera del raggio di 18 metri","description":"L'incantatore traccia un glifo nocivo su una superficie (come una sezione di pavimento o una parete) o all'interno di un oggetto che può essere chiuso (come un libro o un forziere). Il glifo può coprire un'area massima del diametro di 3 metri. Se l'incantatore sceglie un oggetto, questo non deve essere spostato; se ciò avviene, una volta che l'oggetto si allontana di più di 3 metri dal luogo in cui è stato lanciato l'incantesimo, il glifo si infrange e l'incantesimo termina senza essere innescato.\\n\\nIl glifo è quasi impercettibile e, per notarlo, è necessario superare una prova di Saggezza (Percezione) contro la CD del tiro salvezza sull'incantesimo.\\n\\nQuando viene tracciato, l'incantatore sceglie l'innesco, oltre all'effetto che scatenerà: morte, discordia, paura, dolore, sonno o stordimento. Ciascuno di essi è spiegato di seguito.\\n\\n**Programmare l'innesco.** Quando questo incantesimo viene lanciato, l'incantatore decide cosa innesca il glifo. Nel caso di glifi tracciati su una superficie, gli inneschi più comuni includono: toccare o camminare su di essi, rimuovere un altro oggetto che li copre o avvicinarsi a una certa distanza da loro. Nel caso di glifi tracciati all'interno di un oggetto, gli inneschi più comuni includono aprire quell'oggetto o vedere il glifo.\\n\\nL'incantatore può perfezionare l'innesco in modo che venga attivato solo da un certo tipo di creature (ad esempio, il glifo potrebbe essere programmato per influenzare le aberrazioni). Può inoltre impostare delle condizioni per evitare di innescare il glifo, come pronunciare una specifica parola d'ordine.\\n\\nUna volta attivato, il glifo brilla, proiettando luce fioca in una sfera del raggio di 18 metri per 10 minuti, dopodiché l'incantesimo termina. Ogni creatura all'interno della sfera quando il glifo si attiva, oppure che entra nella sfera per la prima volta in un turno o termina il suo turno qui, ne subisce l'effetto.\\n\\nUna creatura può essere presa di mira una sola volta per turno.\\n\\n**Discordia.** Ogni bersaglio effettua un tiro salvezza su Saggezza. Se lo fallisce, inizia a litigare con le altre creature per 1 minuto, durante il quale non è in grado di comunicare in modo significativo e subisce svantaggio ai tiri per colpire e alle prove di caratteristica.\\n\\n**Dolore.** Ogni bersaglio deve superare un tiro salvezza su Costituzione, altrimenti sarà incapacitato per 1 minuto.\\n\\n**Morte.** Ogni bersaglio effettua un tiro salvezza su Costituzione, subendo 10d10 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**Paura.** Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà spaventato per 1 minuto. Mentre è spaventato, il bersaglio deve allontanarsi di almeno 9 metri dal glifo in ogni suo turno, se ne è in grado.\\n\\n**Sonno.** Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti cade privo di sensi per 10 minuti. Una creatura si risveglia se subisce danni o se qualcuno usa un'azione per scuoterla.\\n\\n**Stordimento.** Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà stordito per 1 minuto.","material":"polvere di diamante del valore di 1.000 mo o più, che l'incantesimo consuma","page":189},"spell.true-seeing":{"name":"Visione del vero","description":"Per la durata dell'incantesimo, una creatura consenziente toccata dall'incantatore è dotata di vista pura fino a 36 metri.","material":"polvere di funghi del valore di 25 mo o più, che l'incantesimo consuma","page":201},"spell.insect-plague":{"name":"Piaga degli insetti","areaDimensions":"Sfera del raggio di 6 metri","description":"Uno sciame di locuste riempie una sfera del raggio di 6 metri centrata su un punto a scelta dell'incantatore situato entro gittata. La sfera permane per la durata dell'incantesimo, la sua area è leggermente oscurata e lo spazio al suo interno è considerato terreno difficile.\\n\\nQuando lo sciame compare, ogni creatura al suo interno effettua un tiro salvezza su Costituzione, subendo 4d10 danni perforanti in caso di fallimento, o la metà dei danni in caso di successo. Inoltre, una creatura effettua questo tiro salvezza anche quando entra nell'area dell'incantesimo per la prima volta in un turno o quando vi termina il suo turno. Una creatura effettua questo tiro salvezza solo una volta per turno.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 5º.","material":"una locusta","page":174},"spell.mass-cure-wounds":{"name":"Cura ferite di massa","areaDimensions":"Sfera di 9 metri di raggio","description":"Un'ondata di energia curativa si sprigiona da un punto entro gittata che l'incantatore è in grado di vedere. L'incantatore sceglie fino a sei creature in una sfera di 9 metri di raggio centrata su quel punto: ogni bersaglio recupera una quantità di punti ferita pari a 5d8 più il modificatore di caratteristica da incantatore dell'incantatore.","higherLevels":"La guarigione aumenta di 1d8 per ogni slot di livello superiore al 5º.","page":139},"spell.conjure-celestial":{"name":"Evoca celestiale","areaDimensions":"Cilindro del raggio di 3 metri e dell'altezza di 12 metri","description":"L'incantatore evoca uno spirito dai Piani Superiori, che si manifesta come un pilastro di luce in un cilindro del raggio di 3 metri e dell'altezza di 12 metri centrato in un punto entro gittata. Per ogni creatura che l'incantatore è in grado di vedere nel cilindro, sceglie quale di queste luci brilla su di essa:\\n\\n- **Luce curatrice.** Il bersaglio recupera una quantità di punti ferita pari a 4d12 più il modificatore di caratteristica da incantatore dell'incantatore.\\n- **Luce ustionante.** Il bersaglio effettua un tiro salvezza su Destrezza, subendo 6d12 danni radiosi in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nFino al termine dell'incantesimo, una luce intensa riempie il cilindro e, quando l'incantatore si muove nel suo turno, può spostare anche il cilindro fino a 9 metri.\\n\\nOgni volta che il cilindro si muove nello spazio di una creatura che l'incantatore è in grado di vedere e ogni volta che una creatura che l'incantatore è in grado di vedere entra nel cilindro o vi termina il suo turno, l'incantatore può immergerla in una di queste luci. Una creatura può essere influenzata da questo incantesimo solo una volta per turno.","higherLevels":"I danni e la guarigione aumentano di 1d12 per ogni slot di livello superiore al 7º.","page":145},"spell.magic-mouth":{"name":"Bocca magica","description":"L'incantatore imprime un messaggio all'interno di un oggetto entro gittata, che viene pronunciato quando si verifica una condizione di innesco. L'incantatore sceglie un oggetto che egli è in grado di vedere e che non è indossato o trasportato da un'altra creatura. Quindi pronuncia il messaggio, che non deve essere più lungo di 25 parole, ma può essere enunciato nell'arco di 10 minuti. Infine, determina la circostanza che innesca l'incantesimo e l'emissione del messaggio.\\n\\nQuando quell'innesco si verifica, sull'oggetto appare una bocca magica che recita il messaggio con il tono e il volume di voce dell'incantatore. Se l'oggetto scelto presenta già una bocca o qualcosa di simile (per esempio, la bocca di una statua), la bocca magica appare in modo che le parole sembrino pronunciate dalla bocca dell'oggetto. Quando lancia questo incantesimo, l'incantatore può fare in modo che esso termini una volta consegnato il messaggio o che rimanga attivo ripetendo il messaggio ogniqualvolta si verifica la circostanza di innesco.\\n\\nL'innesco può essere sia generale che dettagliato, ma deve essere basato su condizioni visibili o udibili che si verificano entro 9 metri dall'oggetto. Per esempio, l'incantatore potrebbe ordinare alla bocca di parlare quando, entro 9 metri dall'oggetto, una qualsiasi creatura si muove, oppure un campana d'argento suona.","material":"polvere di giada del valore di 10 mo o più, che l'incantesimo consuma","page":128},"spell.hellish-rebuke":{"name":"Intimorire infernale","castingTimeCondition":"che l'incantatore effettua quando subisce danni da una creatura che egli è in grado di vedere entro 18 metri da sé","description":"La creatura che ha inflitto danni all'incantatore viene temporaneamente avviluppata da fiamme verdi. La creatura effettua un tiro salvezza su Destrezza, subendo 2d10 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 1º.","page":158},"spell.telepathic-bond":{"name":"Legame telepatico","description":"L'incantatore stringe un legame telepatico con un massimo di otto creature consenzienti a sua scelta entro gittata, collegando mentalmente ogni creatura a tutte le altre per la durata dell'incantesimo. Le creature che non sono in grado di comunicare in nessuna lingua, non sono influenzate da questo incantesimo.\\n\\nFino al termine dell'incantesimo, i bersagli possono comunicare telepaticamente attraverso il legame, a prescindere dal fatto che condividano la stessa lingua. La comunicazione è possibile attraverso qualsiasi distanza, ma non può estendersi ad altri piani di esistenza.","material":"due uova","page":160},"spell.misty-step":{"name":"Passo velato","description":"L'incantatore è avvolto per un istante da una foschia argentata e si teletrasporta di un massimo di 9 metri fino a uno spazio libero che è in grado di vedere.","page":173},"spell.regenerate":{"name":"Rigenerazione","description":"Una creatura toccata dall'incantatore recupera 4d8 + 15 punti ferita. Per la durata dell'incantesimo, il bersaglio recupera 1 punto ferita all'inizio di ogni suo turno e qualsiasi parte del corpo sia stata recisa, ricresce dopo 2 minuti.","material":"un ruota della preghiera","page":181},"spell.teleport":{"name":"Teletrasporto","description":"Questo incantesimo teletrasporta immediatamente l'incantatore e un solo oggetto o un massimo di otto creature consenzienti, che si trovano entro gittata e che egli è in grado di vedere, fino a una destinazione a sua scelta. Se il bersaglio è un oggetto, deve essere di taglia Grande o inferiore e non può essere impugnato o trasportato da una creatura non consenziente.\\n\\nLa destinazione scelta deve essere nota all'incantatore e deve trovarsi sul suo stesso piano di esistenza. La sua familiarità con la destinazione determina il successo del teletrasporto. Il GM tira 1d100 e consulta la tabella Risultato del teletrasporto e le spiegazioni successive.\\n\\n**Tabella: Risultato del teletrasporto**\\n\\n|Familiarità|Errore|Area simile|Fuori bersaglio|Sul bersaglio|\\n|---|---|---|---|---|\\n|Cerchio permanente|—|—|—|01–00|\\n|Oggetto collegato|—|—|—|01–00|\\n|Molto familiare|01–05|06–13|14–24|25–00|\\n|Visto occasionalmente|01–33|34–43|44–53|54–00|\\n|Visto una volta o descritto|01–43|44–53|54–73|74–00|\\n|Falsa destinazione|01–50|51–00|—|—|\\n\\n**Familiarità.** Di seguito vengono spiegati i significati dei termini presenti nella colonna Familiarità:\\n\\n- \\"Cerchio permanente\\" indica un cerchio di teletrasporto permanente di cui l'incantatore conosce la sequenza di sigilli.\\n- \\"Oggetto collegato\\" indica un oggetto in possesso dell'incantatore prelevato dalla destinazione desiderata negli ultimi sei mesi, come un libro della biblioteca di un mago.\\n- \\"Molto familiare\\" indica un luogo che l'incantatore ha visitato spesso, un luogo che ha studiato con attenzione o un luogo che è in grado di vedere quando lancia l'incantesimo.\\n- \\"Visto occasionalmente\\" indica un luogo che l'incantatore ha visto più di una volta, ma che non gli è troppo familiare.\\n- \\"Visto una volta o descritto\\" indica un luogo che l'incantatore ha visto una volta, magari usando la magia, o un luogo noto attraverso la descrizione di un'altra persona o una mappa.\\n- \\"Falsa destinazione\\" è un luogo inesistente. Per esempio, l'incantatore ha cercato di scrutare il rifugio segreto di un nemico ma ha visto invece un'illusione, oppure tenta di teletrasportarsi in un luogo che non esiste più.\\n\\n**Errore.** La magia imprevedibile dell'incantesimo rende difficile il viaggio. Ogni creatura che si teletrasporta (o l'oggetto bersaglio) subisce 3d10 danni da forza e il GM lancia di nuovo sulla tabella per determinare dove arriverà (potrebbero verificarsi vari errori, nel qual caso i danni verranno inflitti ogni volta).\\n\\n**Area simile.** L'incantatore e il suo gruppo (o l'oggetto bersaglio) arrivano in un'area diversa che è visivamente o tematicamente simile all'area bersaglio, oltre a essere nelle sue immediate vicinanze. Per esempio, se l'incantatore vuole dirigersi al suo laboratorio personale, potrebbe comparire in quello di un'altra persona nella stessa città.\\n\\n**Fuori bersaglio.** L'incantatore e il suo gruppo (o l'oggetto bersaglio) compaiono a una distanza di 2d12 chilometri dalla destinazione in una direzione casuale. Tira 1d8 per la direzione: 1, est; 2, sud-est; 3, sud; 4, sud-ovest; 5, ovest; 6, nord-ovest; 7, nord; oppure 8, nord-est.\\n\\n**Sul bersaglio.** L'incantatore e il suo gruppo (o l'oggetto bersaglio) compaiono nel luogo designato.","page":194},"spell.find-steed":{"name":"Trova cavalcatura","description":"L'incantatore evoca un essere ultraterreno che appare come una cavalcatura forte e fedele in uno spazio libero a scelta dell'incantatore entro gittata. Questa creatura usa la scheda delle statistiche della cavalcatura ultraterrena. Se l'incantatore possiede già una cavalcatura evocata con questo incantesimo, essa viene sostituita da quella nuova.\\n\\nLa cavalcatura ha l'aspetto di un animale di taglia Grande a scelta dell'incantatore, per esempio un cavallo, un cammello, un lupo feroce o un alce. Ogni volta che l'incantatore lancia l'incantesimo, sceglie il tipo di creatura della cavalcatura (celestiale, folletto o immondo) e questa scelta determina i tratti e la scheda delle statistiche della creatura.\\n\\n**Combattimento.** La cavalcatura diventa un alleato per l'incantatore e i suoi alleati. In combattimento, ha lo stesso punteggio di iniziativa dell'incantatore, il quale può salirci in sella e guidarla come se fosse una cavalcatura controllata (come descritto nelle regole riguardanti il combattimento in sella). Se l'incantatore è incapacitato, la cavalcatura inizia il suo turno subito dopo quello dell'incantatore: la creatura è indipendente e si concentra sul proteggere l'incantatore.\\n\\n**Scomparsa della cavalcatura.** La cavalcatura scompare quando scende a 0 punti ferita o se l'incantatore muore. Quando scompare, nello spazio che occupava in precedenza lascia qualsiasi oggetto stesse indossando o trasportando. Lanciando nuovamente l'incantesimo, l'incantatore può scegliere se evocare la cavalcatura scomparsa o una diversa.\\n\\n### Cavalcatura ultraterrena\\n\\n*Celestiale Grande, folletto o immondo (a scelta dell'incantatore), neutrale*\\n\\n**CA** 10 + 1 per livello dell'incantesimo  \\n**PF** 5 + 10 per livello dell'incantesimo (la cavalcatura ha un numero di Dadi Vita [d10] pari al livello dell'incantesimo)  \\n**Velocità** 18 metri, volo 18 metri (richiede incantesimo di 4º livello o superiore)\\n\\n| | | MOD | SALV | | | MOD | SALV | | | MOD | SALV |\\n|---|---|---|---|---|---|---|---|---|---|---|---|\\n|For|18|+4|+4|Des|12|+1|+1|Cos|14|+2|+2|\\n|Int|6|−2|−2|Sag|12|+1|+1|Car|8|−1|−1|\\n\\n**Sensi** Percezione passiva 11  \\n**Lingue** telepatia 1,5 km (funziona solo con l'incantatore)  \\n**GS** nessuno (PE 0; BC pari al bonus di competenza del personaggio)\\n\\n#### Tratti\\n\\n**Legame vitale.** Quando l'incantatore recupera punti ferita grazie a un incantesimo di 1º livello o superiore, la cavalcatura recupera la stessa quantità di punti ferita se l'incantatore si trova entro 1,5 metri da essa.\\n\\n#### Azioni\\n\\n**Schianto ultraterreno.** Tiro per colpire in mischia: il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, portata di 1,5 m. Colpito: 1d8 più il livello dell'incantesimo danni radiosi (celestiale), danni psichici (folletto) o danni necrotici (immondo).\\n\\n#### Azioni bonus\\n\\n**Passo fatato (solo folletto; ricarica dopo un riposo lungo).** La cavalcatura si teletrasporta, insieme al suo cavaliere, in uno spazio libero a scelta del personaggio situato a 18 metri da sé.\\n\\n**Sguardo letale (solo immondo; ricarica dopo un riposo lungo).** Tiro salvezza su Saggezza: la CD è pari alla CD del tiro salvezza sull'incantesimo, una creatura entro 18 metri che la cavalcatura è in grado di vedere. Fallimento: il bersaglio è spaventato fino al termine del turno successivo dell'incantantore.\\n\\n**Tocco guaritore (solo celestiale; ricarica dopo un riposo lungo).** Una creatura entro 1,5 metri dalla cavalcatura recupera un numero di punti ferita pari a 2d8 più il livello dell'incantesimo.","higherLevels":"Usa il livello dello slot incantesimo relativo al livello dell'incantesimo nella scheda delle statistiche.","page":198},"spell.prismatic-spray":{"name":"Spruzzo prismatico","areaDimensions":"Cono di 18 metri","description":"Otto raggi di luce si sprigionano dall'incantatore in un cono di 18 metri. Ogni creatura presente nel cono effettua un tiro salvezza su Destrezza. Per ogni bersaglio, si tira 1d8 per determinare da quale raggio viene influenzato, consultando la tabella Raggi prismatici.\\n\\n**Tabella: Raggi prismatici**\\n\\n|1d8|Raggio|\\n|---|---|\\n|1|**Rosso.** *Tiro salvezza fallito:* 12d6 danni da fuoco. *Tiro salvezza superato:* la metà dei danni.|\\n|2|**Arancione.** *Tiro salvezza fallito:* 12d6 danni da acido. *Tiro salvezza superato:* la metà dei danni.|\\n|3|**Giallo.** *Tiro salvezza fallito:* 12d6 danni da fulmine. *Tiro salvezza superato:* la metà dei danni.|\\n|4|**Verde.** *Tiro salvezza fallito:* 12d6 danni da veleno. *Tiro salvezza superato:* la metà dei danni.|\\n|5|**Blu.** *Tiro salvezza fallito:* 12d6 danni da freddo. *Tiro salvezza superato:* la metà dei danni.|\\n|6|**Indaco.** *Tiro salvezza fallito:* il bersaglio è trattenuto ed effettua un tiro salvezza su Costituzione alla fine di ogni suo turno. Se lo supera per tre volte, pone fine alla condizione. Se fallisce per tre volte, resta pietrificato finché non viene liberato da un effetto come quello dell'incantesimo ristorare superiore. Non è necessario che i tiri superati o falliti siano consecutivi: si tiene semplicemente il conto di entrambi finché il bersaglio non ne accumula tre di un certo tipo.|\\n|7|**Viola.** *Tiro salvezza fallito:* il bersaglio è accecato ed effettua un tiro salvezza su Saggezza all'inizio del turno successivo dell'incantatore. Se lo supera, non è più accecato. Se lo fallisce, non è più accecato e viene teletrasportato su un altro piano di esistenza (a scelta del GM).|\\n|8|**Speciale.** Il bersaglio viene colpito da due raggi. Si tira altre due volte, rilanciando i dadi se il risultato ottenuto è 8.|","page":192},"spell.confusion":{"name":"Confusione","areaDimensions":"Sfera del raggio di 3 metri","description":"Ogni creatura all'interno di una sfera del raggio di 3 metri centrata su un punto entro gittata a scelta dell'incantatore deve superare un tiro salvezza su Saggezza, altrimenti non può effettuare azioni bonus o reazioni e deve tirare 1d10 all'inizio di ogni suo turno per determinare il suo comportamento durante quel turno, consultando la tabella sottostante. 1d10 Comportamento per il turno 1 Il bersaglio non effettua alcuna azione e usa tutto il suo movimento per muoversi, tirando 1d4 per la direzione: 1, nord; 2, est; 3, sud; o 4, ovest. 2–6 Il bersaglio non si muove e non effettua azioni. 7–8 Il bersaglio non si muove ed effettua l'azione di Attacco per eseguire un attacco in mischia contro una creatura casuale entro portata. Se nessuna creatura si trova entro la sua portata, il bersaglio non effettua azioni. 9–10 Il bersaglio sceglie il comportamento.\\n\\nAlla fine di ogni suo turno, un bersaglio influenzato ripete il tiro salvezza e, se lo supera, termina l'incantesimo su di sé.","higherLevels":"Il raggio della sfera aumenta di 1,5 metri per ogni slot di livello superiore al 4º.","material":"tre gusci di noce","page":135},"spell.daylight":{"name":"Luce diurna","description":"Per la durata dell'incantesimo, un fascio di luce solare si sprigiona da un punto entro gittata e riempie una sfera del raggio di 18 metri. L'area della luce solare emette luce intensa e poi luce fioca per ulteriori 18 metri.\\n\\nIn alternativa, l'incantatore lancia l'incantesimo su un oggetto che non sia indossato o trasportato, facendo sì che la luce solare riempia un'emanazione di 18 metri di cui l'oggetto è il punto di origine. Coprire l'oggetto con qualcosa di opaco, come una ciotola o un elmo, blocca la luce solare.\\n\\nSe una parte dell'area di questo incantesimo si sovrappone a un'area di oscurità creata da un incantesimo di 3º livello o inferiore, l'incantesimo che ha creato la luce viene dissolto.","page":162},"spell.creation":{"name":"Creazione","areaDimensions":"Cubo con spigolo di 1,5 metri","description":"L'incantatore attrae a sé dei filamenti di sostanza d'ombra dalla Coltre Oscura per creare un oggetto entro gittata. L'oggetto può essere di materia vegetale (tessuti, corda, legno o materiali simili) o di materia minerale (pietra, cristallo, metallo o materiali simili). L'oggetto non dev'essere più grande di un cubo con spigolo di 1,5 metri e deve avere una forma ed essere un materiale che l'incantatore ha già visto.\\n\\nLa durata dell'incantesimo dipende dal materiale dell'oggetto, come indicato nella tabella Materiali. se l'oggetto è composto da vari materiali, si usa la durata più breve. Usare un qualsiasi oggetto creato da questo incantesimo come componente materiale di un altro incantesimo ne provoca il fallimento.\\n\\nMateriali\\n\\nMateriale Materia vegetale Pietra o cristallo Metalli preziosi Gemme Adamantio o mithral\\n\\nDurata 24 ore 12 ore 1 ora 10 minuti 1 minuto","higherLevels":"Il cubo aumenta di 1,5 metri per spigolo per ogni slot di livello superiore al 5º.","material":"un pennello","page":138},"spell.message":{"name":"Messaggio","description":"L'incantatore indica una creatura entro gittata e sussurra un messaggio. Solo il bersaglio sente il messaggio e può sussurrare una risposta che unicamente l'incantatore può sentire.\\n\\nL'incantatore può lanciare questo incantesimo attraverso oggetti solidi se il bersaglio gli è noto e sa che si trova oltre la barriera. Tuttavia, l'incantesimo viene bloccato da silenzio magico, una sottile lamina di piombo o 30 centimetri di pietra, metallo o legno.","material":"un filo di rame","page":164},"spell.cure-wounds":{"name":"Cura ferite","description":"Una creatura toccata dall'incantatore recupera un numero di punti ferita pari a 2d8 più il modificatore di caratteristica da incantatore dell'incantatore.","higherLevels":"La guarigione aumenta di 2d8 per ogni slot di livello superiore al 1º.","page":139},"spell.charm-person":{"name":"Charme su persone","description":"Un umanoide entro gittata che l'incantatore è in grado di vedere effettua un tiro salvezza su Saggezza, disponendo di vantaggio se l'incantatore o i suoi alleati stanno combattendo contro di essa. In caso di fallimento, il bersaglio è affascinato fino al termine dell'incantesimo o finché non gli vengono inflitti danni dall'incantatore o i suoi alleati. La creatura affascinata è amichevole nei confronti dell'incantatore. Al termine dell'incantesimo, il bersaglio capirà di essere stato affascinato dall'incantatore.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","page":132},"spell.alarm":{"name":"Allarme","areaDimensions":"Cubo con spigolo di 6 metri","description":"L'incantatore predispone un allarme che segnala un'intrusione. Sceglie una porta, una finestra o un'area entro gittata che non sia più ampia di un cubo con spigolo di 6 metri. Fino al termine dell'incantesimo, un allarme avverte l'incantatore tutte le volte che una creatura tocca o entra nell'area protetta. Al momento del lancio dell'incantesimo, l'incantatore designa quali creature non faranno scattare l'allarme. Inoltre, sceglie se l'allarme è acustico o mentale.\\n\\n- **Allarme acustico.** L'allarme produce il suono di una campanella per 10 secondi entro 18 metri dall'area protetta.\\n- **Allarme mentale.** Un suono nella mente avverte l'incantatore se questi si trova entro 1,5 chilometri dall'area protetta. Il suono sveglia l'incantatore se sta dormendo.","material":"una campanella e un filo d'argento","page":122},"spell.reverse-gravity":{"name":"Inversione della gravità","areaDimensions":"Cilindro del raggio di 15 metri e dell'altezza di 30 metri","description":"Questo incantesimo inverte la gravità all'interno di un cilindro del raggio di 15 metri e dell'altezza di 30 metri centrato su un punto entro gittata. Tutte le creature e gli oggetti presenti nell'area che non sono ancorati al terreno vengono trascinati verso l'alto e raggiungono la parte superiore del cilindro. Una creatura può effettuare un tiro salvezza su Destrezza per afferrare un oggetto ancorato entro portata, evitando così di essere trascinata verso l'alto.\\n\\nSe un soffitto o un oggetto ancorato viene urtato durante questa caduta, gli oggetti e le creature subiscono un impatto identico a quello che subirebbero durante una normale caduta verso il basso. Se una creatura o un oggetto influenzato arriva in cima al cilindro senza colpire niente, rimane lì a fluttuare per la durata dell'incantesimo. Al termine dell'incantesimo, le creature e gli oggetti influenzati cadono verso il basso.","material":"una calamita e limatura di ferro","page":159},"spell.meteor-swarm":{"name":"Sciame di meteore","areaDimensions":"Sfera del raggio di 12 metri","description":"Globi infuocati precipitano sul terreno in quattro punti differenti entro gittata che l'incantatore è in grado di vedere. Ogni creatura situata in una sfera del raggio di 12 metri centrata su ognuno di quei punti effettua un tiro salvezza su Destrezza. Una creatura subisce 20d6 danni da fuoco e 20d6 danni contundenti in caso di fallimento, o la metà dei danni in caso di successo. Una creatura in un'area con più sfere infuocate subisce l'effetto soltanto una volta.\\n\\nAnche un oggetto non magico che non sia indossato o trasportato subisce i danni se si trova entro l'area dell'incantesimo, e inizia a bruciare se è infiammabile.","page":184},"spell.seeming":{"name":"Sembrare","description":"L'incantatore assegna un aspetto illusorio a ogni creatura a sua scelta entro gittata che egli è in grado di vedere. Un bersaglio non consenziente può effettuare un tiro salvezza su Carisma e, se lo supera, non ne viene influenzato.\\n\\nL'incantatore può assegnare lo stesso aspetto o aspetti diversi ai bersagli. L'incantesimo consente di modificare l'aspetto fisico e l'equipaggiamento dei bersagli. Ogni creatura può apparire 30 centimetri più alta o più bassa, più grassa o più magra. Il nuovo aspetto del bersaglio deve usare la stessa disposizione basilare degli arti del bersaglio. Entro questi limiti, la natura dell'illusione dipende dall'incantatore. L'incantesimo permane per tutta la sua durata.\\n\\nI cambiamenti apportati da questo incantesimo non passano il vaglio di un'ispezione fisica. Per esempio, se l'incantatore usa questo incantesimo per aggiungere un cappello all'abbigliamento della creatura, gli oggetti sono in grado di attraversarlo.\\n\\nUna creatura che effettua l'azione di Studio per esaminare un bersaglio può effettuare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se la supera, capisce che il bersaglio è camuffato.","page":187},"spell.dragons-breath":{"name":"Soffio del drago","areaDimensions":"Cono di 4,5 metri","description":"L'incantatore tocca una creatura consenziente e sceglie acido, freddo, fulmine, fuoco, o veleno. Fino al termine dell'incantesimo, il bersaglio può usare la sua azione di Magia per esalare un cono di 4,5 metri. Ogni creatura nell'area effettua un tiro salvezza su Destrezza; se lo fallisce, subisce 3d6 danni del tipo scelto, mentre se lo supera subisce la metà di quei danni.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 2º.","material":"un peperoncino","page":190},"spell.suggestion":{"name":"Suggestione","description":"L'incantatore suggerisce un corso d'azione da intraprendere (descritto con non più di 25 parole) a una creatura entro gittata che egli è in grado di vedere. Le creature devono essere in grado di comprendere l'incantatore. Il suggerimento deve apparire realizzabile e non deve comportare nulla che infligga palesemente danni al bersaglio o ai suoi alleati. Per esempio, l'incantatore potrebbe dire \\"Prendi la chiave per il caveau del tesoro della setta e portamela\\". Oppure \\"Smetti di combattere, esci dalla biblioteca pacificamente e non tornare mai più\\".\\n\\nIl bersaglio deve superare un tiro salvezza su Saggezza, altrimenti rimane affascinato per la durata dell'incantesimo o finché l'incantatore o i suoi alleati non gli infliggono danni. Il bersaglio affascinato segue il suggerimento al meglio delle sue capacità. L'attività suggerita può continuare per l'intera durata, ma se può essere completata in un tempo più breve, l'incantesimo termina e non ha più effetto sul bersaglio una volta portata a termine.","material":"una goccia di miele","page":192},"spell.mind-blank":{"name":"Vuoto mentale","description":"Fino al termine dell'incantesimo, l'incantatore tocca una creatura consenziente rendendola immune ai danni psichici e alla condizione affascinato. Inoltre, il bersaglio non è influenzato da nulla che sia in grado di percepire le sue emozioni o allineamento, leggere i suoi pensieri o individuare magicamente la sua posizione. Nessun incantesimo, nemmeno l'incantesimo desiderio, può raccogliere informazioni sul bersaglio, osservarlo a distanza, o controllarne la mente.","page":201},"spell.planar-binding":{"name":"Legame planare","description":"L'incantatore tenta di vincolare un celestiale, un elementale, un folletto o un immondo al suo servizio. La creatura deve trovarsi entro gittata per l'intera durata del lancio dell'incantesimo (in genere, la creatura viene prima evocata al centro di una versione invertita dell'incantesimo cerchio magico per tenerla intrappolata mentre questo incantesimo viene lanciato). Completato il lancio dell'incantesimo, il bersaglio deve superare un tiro salvezza su Carisma, altrimenti è obbligato a servire l'incantatore per la durata dell'incantesimo. Se la creatura è stata evocata o creata da un altro incantesimo, la durata di quell'incantesimo viene estesa per corrispondere alla durata di questo.\\n\\nUna creatura vincolata deve eseguire gli ordini al meglio delle sue capacità. L'incantatore potrebbe ordinarle di accompagnarlo in un'avventura, di proteggere un luogo o di consegnare un messaggio. Se la creatura è ostile, cercherà in tutti i modi di distorcere gli ordini dell'incantatore per perseguire i suoi obiettivi personali. Se la creatura porta a termine gli ordini dell'incantatore prima del termine dell'incantesimo, si reca da lui per riferirglielo, ma solo se si trovano sullo stesso piano di esistenza. Se l'incantatore si trova su un piano diverso, la creatura ritorna nel luogo in cui è stata vincolata e vi rimane fino al termine dell'incantesimo.","higherLevels":"La durata aumenta con uno slot incantesimo di 6º livello (10 giorni), di 7º livello (30 giorni), di 8º livello (180 giorni) e di 9º livello (366 giorni).","material":"un gioiello del valore di 1.000 mo o più, che l'incantesimo consuma","page":160},"spell.minor-illusion":{"name":"Illusione minore","description":"L'incantatore crea un suono o un'immagine di un oggetto entro gittata che permane per la durata dell'incantesimo. Di seguito sono descritti gli effetti di ciascuno di essi. L'illusione termina se l'incantatore lancia nuovamente l'incantesimo.\\n\\nSe una creatura effettua l'azione di Studio per esaminare il suono o l'immagine, può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, l'illusione risulta attenuata per quella creatura.\\n\\n**Suono.** Se l'incantatore crea un suono, la sua intensità può variare da quella di un sussurro a quella di un urlo. Può trattarsi della voce dell'incantatore o di altri, del ruggito di un leone, di un rullo di tamburi o di un qualsiasi altro suono a sua scelta. Il suono può echeggiare ininterrottamente per tutta la durata dell'incantesimo, oppure l'incantatore può emettere dei suoni separati in momenti diversi prima che l'incantesimo termini.\\n\\n**Immagine.** Se l'incantatore crea l'immagine di un oggetto (come per esempio una sedia, una serie di impronte nel fango o uno scrigno), quell'oggetto non deve essere più grande di un cubo con spigolo di 1,5 metri. L'illusione non può emettere suoni, luci, odori o qualsiasi altro effetto sensoriale L'illusione può essere rivelata da un'interazione fisica, poiché gli oggetti possono attraversarla.","material":"un ciuffo di lana","page":153},"spell.true-resurrection":{"name":"Resurrezione pura","description":"L'incantatore tocca una creatura morta da non più di 200 anni a causa di un qualsiasi motivo fuorché la vecchiaia. Il bersaglio viene rianimato con tutti i propri punti ferita.\\n\\nQuesto incantesimo chiude tutte le ferite, neutralizza ogni veleno, cura tutti i contagi magici e annulla ogni maledizione che affiggeva la creatura al momento della morte. Inoltre, ripristina gli eventuali organi e arti danneggiati o mancanti. Se la creatura era un non morto, viene riportata alla forma originaria che aveva in vita.\\n\\nL'incantesimo può fornire al bersaglio un nuovo corpo se l'originale non esiste più, nel qual caso l'incantatore deve pronunciare il nome della creatura, che appare in uno spazio libero a scelta dell'incantatore entro 3 metri da lui.","material":"diamanti del valore di 25.000 mo o più, che vengono consumati dall'incantesimo","page":180},"spell.dream":{"name":"Sogno","description":"L'incantatore bersaglia una creatura che conosce sullo stesso piano di esistenza. L'incantatore o una creatura consenziente da lui toccata entra in uno stato di trance, assumendo il ruolo di messaggero onirico. Durante la trance, il messaggero è incapacitato e la sua velocità è pari a 0.\\n\\nSe il bersaglio dorme, il messaggero gli appare in sogno e può conversare con lui finché rimane addormentato e l'incantesimo non termina. Il messaggero può anche modellare l'ambiente del sogno, creando paesaggi, oggetti e altre immagini. Il messaggero può uscire dalla trance in ogni momento, terminando l'incantesimo. Al suo risveglio, il bersaglio ricorda il sogno perfettamente.\\n\\nSe il bersaglio è sveglio quando l'incantatore lancia l'incantesimo, il messaggero ne è consapevole e può terminare la trance (e l'incantesimo) o aspettare che il bersaglio si addormenti e così apparire nei suoi sogni.\\n\\nL'incantatore può fare in modo che il messaggero appaia terrificante al bersaglio. In questo caso, il messaggero può trasmettere un messaggio di massimo dieci parole e poi il bersaglio effettua un tiro salvezza su Saggezza. In caso di fallimento, il bersaglio non ottiene alcun beneficio dal suo riposo e subisce 3d6 danni psichici al risveglio.","material":"una manciata di sabbia","page":190},"spell.alter-self":{"name":"Alterare se stesso","description":"L'incantatore altera la propria forma fisica scegliendo tra le opzioni seguenti. Gli effetti permangono per la sua durata, durante la quale l'incantatore può effettuare un'azione di Magia per sostituire l'opzione scelta con una diversa.\\n\\n**Adattamento acquatico.** L'incantatore sviluppa le branchie e una membrana tra le dita. Inoltre, può respirare sott'acqua e ottenere una velocità di nuoto pari alla sua velocità.\\n\\n**Armi naturali.** L'incantatore sviluppa artigli (taglienti), zanne (perforanti), corna (perforanti) o zoccoli (contundenti). Quando usa il suo colpo senz'armi per infliggere danni con l'arma naturale creata, infligge 1d6 danni (del tipo indicato tra parentesi) invece di infliggere i danni normali del colpo senz'armi, usando il modificatore di caratteristica da incantatore per i tiri per colpire e per i tiri per i danni anziché quello di Forza.\\n\\n**Cambiare aspetto.** L'incantatore altera il suo aspetto: decide come apparire e definisce altezza, peso, lineamenti facciali, tono della voce, lunghezza dei capelli, carnagione e altri tratti distintivi. Può scegliere di assomigliare a un membro di un'altra specie, ma le sue statistiche non subiscono modifiche. Non può apparire come una creatura di taglia diversa e la sua forma base rimane la stessa; per esempio, se è bipede, non può usare l'incantesimo per diventare quadrupede. Per la durata dell'incantesimo, può effettuare un'azione di Magia per cambiare di nuovo il suo aspetto.","page":123},"spell.sunbeam":{"name":"Bagliore solare","areaDimensions":"Linea larga 1,5 metri e lunga 18 metri","description":"L'incantatore lancia un bagliore solare in una linea larga 1,5 metri e lunga 18 metri. Ogni creatura nella sua traiettoria effettua un tiro salvezza su Costituzione e, se lo fallisce, subisce 6d8 danni radiosi e rimane accecata fino all'inizio del turno successivo dell'incantatore. Se lo supera, invece, subisce solo la metà dei danni.\\n\\nFino al termine dell'incantesimo, l'incantatore può effettuare un'azione di Magia per creare una nuova linea radiosa.\\n\\nPer la durata dell'incantesimo, una scintilla di luce radiosa risplende nella sua mano ed emana luce intensa in un raggio di 9 metri e luce fioca per ulteriori 9 metri. Questa luce è considerata luce solare.","material":"una lente d'ingrandimento","page":127},"spell.create-undead":{"name":"Creare non morti","description":"L'incantatore può lanciare questo incantesimo solo di notte, scegliendo fino a tre cadaveri umanoidi di taglia Media o Piccola entro gittata. Ognuno di loro diventa un ghoul sotto il controllo dell'incantatore (vedi il \\"Mostri\\" per la scheda delle statistiche).\\n\\nCome azione bonus a ogni suo turno, l'incantatore può comandare mentalmente qualsiasi creatura animata con questo incantesimo, a patto che la creatura si trovi entro 36 metri da lui (se controlla varie creature, l'incantatore può comandarne più di una allo stesso momento, impartendo lo stesso comando a ciascuna di loro). L'incantatore decide quale azione effettuerà la creatura e dove si muoverà nel suo turno successivo, oppure può impartirle un comando generale, come restare a guardia di un determinato luogo. Se invece non impartisce alcun comando, la creatura effettua l'azione Schivata e si sposta solo per evitare di subire danni. Una volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito.\\n\\nLa creatura rimane sotto il controllo dell'incantatore per 24 ore, passate le quali smette di obbedire a qualsiasi comando ulteriore. Per mantenere il controllo sulla creatura per altre 24 ore, l'incantatore deve lanciare questo incantesimo su di essa prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo gli permette di ristabilire il controllo su un massimo di tre creature da lui animate tramite questo incantesimo, anziché animarne di nuove.","higherLevels":"Se l'incantatore usa uno slot incantesimo di 7º livello, può animare o ristabilire il controllo su quattro ghoul. Se l'incantatore usa uno slot incantesimo di 8º livello, può animare o ristabilire il controllo su cinque ghoul, o due ghast o wight. Se l'incantatore usa uno slot incantesimo di 9º livello, può animare o ristabilire il controllo su sei ghoul, tre ghast o wight, o due mummie. Vedi \\"Mostri\\" per le relative schede delle statistiche.","material":"una pietra onice nera del valore di 150 mo o più per ogni cadavere","page":138},"spell.instant-summons":{"name":"Evocazioni istantanee","description":"L'incantatore tocca lo zaffiro utilizzato per lanciare l'incantesimo e un oggetto del peso pari o inferiore a 5 kg e la cui dimensione più lunga sia pari o inferiore a 1,8 metri. L'incantesimo imprime un marchio invisibile su quell'oggetto e traccia in modo invisibile il nome dell'oggetto sullo zaffiro. Ogni volta che l'incantatore lancia questo incantesimo, deve utilizzare uno zaffiro diverso.\\n\\nSuccessivamente, l'incantatore può effettuare un'azione di Magia per pronunciare il nome dell'oggetto e distruggere lo zaffiro. L'oggetto appare immediatamente nella mano dell'incantatore, a prescindere dalle distanze fisiche o planari e l'incantesimo termina.\\n\\nSe un'altra creatura impugna o trasporta l'oggetto, la distruzione dello zaffiro non comporta l'apparizione dell'oggetto, ma l'incantatore apprende invece chi è la creatura in suo possesso e l'ubicazione attuale.","material":"uno zaffiro del valore di 1.000 mo o più","page":146},"spell.harm":{"name":"Ferire","description":"L'incantatore scatena una malattia virulenta su una creatura entro gittata che egli è in grado di vedere. Il bersaglio effettua un tiro salvezza su Costituzione. Se lo fallisce, subisce 14d6 danni necrotici, e i suoi punti ferita massimi vengono ridotti di una quantità pari ai danni necrotici subiti, mentre se lo supera, subisce solo la metà dei danni. Questo incantesimo non può ridurre i punti ferita massimi del bersaglio a meno di 1.","page":147},"spell.meld-into-stone":{"name":"Fondersi nella pietra","description":"L'incantatore entra in un oggetto o in una superficie di pietra sufficientemente grande da contenere il suo corpo, fondendosi con esso insieme al suo l'equipaggiamento per la durata dell'incantesimo. Per farlo, l'incantatore deve toccare la pietra, e nulla della sua presenza rimane visibile o individuabile da qualsiasi senso non magico.\\n\\nMentre è fuso nella pietra, l'incantatore non può vedere ciò che accade al di fuori e subisce svantaggio in qualsiasi prova di Saggezza (Percezione) effettuata per udire i suoni all'esterno. Rimane tuttavia cosciente del passare del tempo e può lanciare incantesimi su di sé. L'incantatore può usare 1,5 metri del suo movimento per uscire dalla pietra nel punto in cui è entrato, ponendo fine all'incantesimo; altrimenti, non può muoversi.\\n\\nEventuali danni fisici minori inflitti alla pietra non danneggiano l'incantatore, ma una distruzione parziale o un'alterazione nella forma (al punto da non contenerne più il corpo) provoca l'espulsione dell'incantatore, infliggendogli 6d6 danni da forza. La completa distruzione della pietra (o la sua trasmutazione in una sostanza differente) provoca l'espulsione dell'incantatore e gli infligge 50 danni da forza. Se l'incantatore viene espulso, cade a terra prono nello spazio libero più vicino al punto in cui era entrato.","page":148},"spell.mislead":{"name":"Fuorviare","description":"L'incantatore diventa invisibile nello stesso momento in cui un suo sosia illusorio appare nel punto in cui si trova. Il sosia permane per la durata dell'incantesimo, ma l'invisibilità termina se non appena l'incantatore effettua un tiro per colpire, infligge danni o lancia un incantesimo.\\n\\nCome azione di Magia, l'incantatore può muovere il sosia illusorio fino al doppio della sua velocità e farlo gesticolare, parlare e comportare nel modo che ritiene più opportuno. Il sosia è intangibile e invulnerabile.\\n\\nInoltre, l'incantatore può vedere e sentire attraverso il sosia, come se si trovasse nello stesso punto.","page":150},"spell.magic-jar":{"name":"Giara magica","description":"Il corpo dell'incantatore cade in uno stato catatonico e la sua anima lo abbandona entrando nel contenitore utilizzato come componente materiale dell'incantesimo. Mentre la sua anima si trova all'interno del contenitore, l'incantatore è consapevole di ciò che accade intorno a lui come se si trovasse nello spazio del contenitore. L'incantatore non può muoversi o effettuare reazioni, l'unica azione che può effettuare è proiettare la propria anima fino a 30 metri fuori dal contenitore, tornando nel suo corpo (e così terminando l'incantesimo) o provando a prendere possesso di un corpo di un umanoide.\\n\\nL'incantatore può tentare di possedere un qualsiasi umanoide entro 30 metri da lui che egli è in grado di vedere (tranne le creature protette da un incantesimo protezione dal bene e dal male o cerchio magico). Il bersaglio effettua un tiro salvezza su Carisma. In caso di fallimento, l'anima dell'incantatore entra nel corpo del bersaglio, la cui anima viene intrappolata nel contenitore. In caso di successo, il bersaglio resiste agli sforzi dell'incantatore di possederlo e quest'ultimo non può riprovare per le 24 ore successive.\\n\\nQuando l'incantatore prende possesso del corpo di una creatura, ne ha il pieno controllo. I suoi punti ferita, Dadi Vita, Forza, Destrezza, Costituzione, Velocità e sensi vengono sostituiti da quelli della creatura. Altrimenti, l'incantatore conserva le proprie statistiche di gioco.\\n\\nNel frattempo, l'anima della creatura posseduta può percepire ciò che accade intorno al contenitore utilizzando i propri sensi, ma non può muoversi ed è incapacitata.\\n\\nMentre è in possesso di un corpo, l'incantatore può effettuare la sua azione di Magia per tornare nel contenitore se si trova entro 30 metri da lui, riportando l'anima della creatura ospite nel suo corpo. Se il corpo ospite muore mentre l'incantatore si trova al suo interno, anche la creatura muore e l'incantatore effettua un tiro salvezza su Carisma contro la CD del suo stesso incantesimo. In caso di successo, l'incantatore torna nel contenitore, che deve tuttavia trovarsi entro 30 metri da lui; altrimenti muore.\\n\\nSe il contenitore viene distrutto o l'incantesimo termina, l'anima dell'incantatore torna nel suo corpo. Tuttavia, se il suo corpo si trova a più di 30 metri da lui o se è morto, anche l'incantatore muore. Se l'anima di un'altra creatura si trova all'interno del contenitore quando viene distrutto, questa ritorna nel suo corpo, a patto che sia vivo e si trovi entro 30 metri; altrimenti, la creatura muore.\\n\\nAl termine dell'incantesimo, il contenitore viene distrutto.","material":"una gemma, un cristallo o un reliquiario del valore di 500 mo o più","page":151},"spell.antilife-shell":{"name":"Guscio anti-vita","areaDimensions":"Emanazione di 3 metri","description":"Un'aura si estende dall'incantatore in un'emanazione di 3 metri e permane per la durata dell'incantesimo, impedendo a tutte le creature che non siano non morti e costrutti di attraversarla o protendersi oltre essa. Una creatura influenzata può lanciare incantesimi o effettuare attacchi utilizzando armi a distanza o con portata attraverso la barriera.\\n\\nSe l'incantatore si muove in modo che una creatura influenzata sia costretta ad attraversare la barriera, l'incantesimo termina.","page":153},"spell.inflict-wounds":{"name":"Infliggi ferite","description":"Una creatura toccata dall'incantatore effettua un tiro salvezza su Costituzione, subendo 2d10 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 1º.","page":157},"spell.faerie-fire":{"name":"Luminescenza","areaDimensions":"Cubo con spigolo di 6 metri","description":"Gli oggetti contenuti in un cubo con spigolo di 6 metri entro gittata vengono evidenziati da un alone di luce blu, verde o viola (a scelta dell'incantatore). Ogni creatura presente nel cubo viene a sua volta evidenziata se fallisce un tiro salvezza su Destrezza. Per la durata dell'incantesimo, gli oggetti e le creature influenzate proiettano luce fioca entro un raggio di 3 metri e non possono beneficiare della condizione di invisibilità.\\n\\nI tiri per colpire contro una creatura influenzata o un oggetto influenzato dispongono di vantaggio se l'attaccante è in grado di vederli.","page":163},"spell.prismatic-wall":{"name":"Muro prismatico","description":"Un piano scintillante di luce multicolore forma un muro opaco verticale (che può misurare fino a 27 metri di lunghezza, 9 metri di altezza e 2,5 centimetri di spessore), centrato su un punto entro gittata. In alternativa, l'incantatore modella il muro in un globo del diametro massimo di 9 metri centrato su un punto entro gittata. Il muro permane per tutta la durata dell'incantesimo. Se l'incantatore posiziona il muro in uno spazio occupato da una creatura, l'incantesimo termina immediatamente, senza alcun effetto.\\n\\nIl muro emana luce intensa entro 30 metri e luce fioca per ulteriori 30 metri. L'incantatore e le creature da lui scelte al momento del lancio dell'incantesimo possono passare attraverso il muro o rimanervi accanto senza subire danni. Se un'altra creatura in grado di vedere il muro giunge entro 6 metri da esso o comincia lì il proprio turno, deve superare un tiro salvezza su Costituzione, altrimenti è accecata per 1 minuto.\\n\\nIl muro è composto da sette strati, ognuno di un colore diverso. Quando una creatura si protende oltre il muro o ci passa attraverso, lo fa attraversando uno strato alla volta. Ogni strato costringe la creatura a effettuare un tiro salvezza su Destrezza, altrimenti viene influenzata dalle proprietà di quello strato, come descritto nella tabella degli strati prismatici.\\n\\nIl muro, che ha una CA pari a 10, può essere distrutto uno strato alla volta e in ordine dal rosso al viola, in un modo specifico per ogni strato. Se uno strato viene distrutto, resta distrutto per la durata dell'incantesimo. L'incantesimo campo anti-magia non ha alcun effetto sul muro e l'incantesimo dissolvi magie può influenzare solo lo strato viola.\\n\\n**Tabella: Strati prismatici**\\n\\n|Ordine|Effetti|\\n|---|---|\\n|1|**Rosso.** *Tiro salvezza fallito:* 12d6 danni da fuoco. *Tiro salvezza superato:* la metà dei danni. *Effetti aggiuntivi:* gli attacchi a distanza non magici non possono attraversare questo strato, che viene distrutto se subisce almeno 25 danni da freddo.|\\n|2|**Arancione.** *Tiro salvezza fallito:* 12d6 danni da acido. *Tiro salvezza superato:* la metà dei danni. *Effetti aggiuntivi:* gli attacchi a distanza magici non possono attraversare questo strato, che viene distrutto da un vento forte (come quello creato da folata di vento).|\\n|3|**Giallo.** *Tiro salvezza fallito:* 12d6 danni da fulmine. *Tiro salvezza superato:* la metà dei danni. *Effetti aggiuntivi:* questo strato viene distrutto se subisce almeno 60 danni da forza.|\\n|4|**Verde.** *Tiro salvezza fallito:* 12d6 danni da veleno. *Tiro salvezza superato:* la metà dei danni. *Effetti aggiuntivi:* un incantesimo passapareti o un altro incantesimo di livello pari o superiore che è in grado di aprire un portale su una superficie solida, distrugge questo strato.|\\n|5|**Blu.** *Tiro salvezza fallito:* 12d6 danni da freddo. *Tiro salvezza superato:* la metà dei danni. *Effetti aggiuntivi:* questo strato viene distrutto se subisce almeno 25 danni da fuoco.|\\n|6|**Indaco.** *Tiro salvezza fallito:* il bersaglio è trattenuto ed effettua un tiro salvezza su Costituzione alla fine di ogni suo turno. Se lo supera per tre volte, pone fine alla condizione. Se fallisce per tre volte, resta pietrificato finché non viene liberato da un effetto come quello dell'incantesimo ristorare superiore. Non è necessario che i tiri superati o falliti siano consecutivi: si tiene semplicemente il conto di entrambi finché il bersaglio non ne accumula tre di un certo tipo. *Effetti aggiuntivi:* non è possibile lanciare incantesimi attraverso questo strato, che viene distrutto dalla luce intensa emanata dall'incantesimo luce diurna.|\\n|7|**Viola.** *Tiro salvezza fallito:* il bersaglio è accecato ed effettua un tiro salvezza su Saggezza all'inizio del turno successivo dell'incantatore. Se lo supera, non è più accecato. Se lo fallisce, non è più accecato e viene teletrasportato su un altro piano di esistenza (a scelta del GM). *Effetti aggiuntivi:* questo strato viene distrutto da dissolvi magie.|","page":168},"spell.pass-without-trace":{"name":"Passare senza tracce","areaDimensions":"Emanazione di 9 metri","description":"L'incantatore irradia un'aura occultante in un'emanazione di 9 metri per la durata dell'incantesimo. Finché si trovano nell'aura, l'incantatore e ogni creatura a sua scelta ricevono un bonus di +10 alle prove di Destrezza (Furtività) e non lasciano tracce.","material":"ceneri di vischio bruciato","page":173},"spell.foresight":{"name":"Previsione","description":"L'incantatore tocca una creatura consenziente e le conferisce una capacità limitata di vedere nell'immediato futuro. Per la durata dell'incantesimo, il bersaglio dispone di vantaggio alle prove con d20. Inoltre, le altre creature subiscono svantaggio ai tiri per colpire contro di esso. L'incantesimo termina in anticipo se l'incantatore lo lancia di nuovo.","material":"una piuma di colibrì","page":175},"spell.shield":{"name":"Scudo","castingTimeCondition":"che l'incantatore effettua quando è colpito da un tiro per colpire o bersagliato dall'incantesimo dardo incantato","description":"Una barriera impercettibile di forza magica protegge l'incantatore. Fino all'inizio del suo turno successivo, l'incantatore ottiene un bonus di +5 alla CA da applicare anche all'attacco innescante e non subisce danni da dardo incantato.","page":186},"spell.simulacrum":{"name":"Simulacro","description":"Il personaggio crea un simulacro di una bestia o un umanoide entro 3 metri da sé per l'intera durata del lancio dell'incantesimo. Il lancio termina toccando sia il bersaglio che un cumulo di ghiaccio o neve della sua stessa taglia. Quest'ultimo diventa il simulacro, il quale è una creatura che utilizza le statistiche di gioco della controparte originale al momento del lancio, tranne per il fatto che è un costrutto, per cui ha la metà dei punti ferita massimi e non può lanciare questo incantesimo.\\n\\nIl simulacro è amichevole nei confronti dell'incantatore e delle creature da lui indicate. Inoltre, obbedisce ai comandi che gli impartisce durante il suo turno in combattimento. Il simulacro non può né ottenere livelli né compiere riposi brevi o lunghi.\\n\\nSe subisce dei danni, l'unico modo che il personaggio ha di ripristinare i suoi punti ferita è ripararlo mentre compie un riposo lungo, durante il quale consuma componenti del valore di 100 mo per ogni punto ferita ripristinato. Per poter eseguire la riparazione, il simulacro deve essere entro 1,5 metri dal personaggio.\\n\\nIl simulacro permane finché non scende a 0 punti ferita, nel qual caso si ritrasforma in neve e si scioglie. Se l'incantatore lancia di nuovo questo incantesimo, il simulacro da lui creato in precedenza viene istantaneamente distrutto.","material":"polvere di rubino del valore di 1.500 mo o più, che l'incantesimo consuma","page":190},"spell.find-familiar":{"name":"Trova famiglio","description":"L'incantatore ottiene i servigi di un famiglio, uno spirito che assume la forma di un animale a sua scelta: pipistrello, gatto, rana, falco, lucertola, piovra, gufo, ratto, corvo, ragno, faina o un'altra bestia che abbia un grado di sfida pari a 0. Il famiglio appare in uno spazio libero entro gittata, ha le statistiche della forma scelta (vedi \\"Mostri\\"), anche se si tratta di un celestiale, un folletto o un immondo (a scelta dell'incantatore) invece di una bestia. Il famiglio è indipendente dall'incantatore, ma obbedisce ai suoi comandi.\\n\\n**Connessione telepatica.** Finché il famiglio si trova a 30 metri dall'incantatore, quest'ultimo può comunicare con lui telepaticamente. Inoltre, come azione bonus, l'incantatore è in grado di vedere attraverso gli occhi del famiglio e sentire ciò che sente fino all'inizio del suo turno successivo, ottenendo i benefici di eventuali sensi speciali posseduti dal famiglio.\\n\\nInfine, quando l'incantatore lancia un incantesimo con gittata a contatto, il suo famiglio può trasmettere il tocco. Il famiglio deve trovarsi entro 30 metri dall'incantatore e usare la sua reazione per trasmettere il tocco quando l'incantesimo viene lanciato.\\n\\n**Combattimento.** Il famiglio diventa un alleato per l'incantatore e i suoi alleati. Tira per la propria iniziativa e agisce nel proprio turno. Un famiglio non può attaccare, ma può effettuare altre azioni normalmente.\\n\\n**Scomparsa del famiglio.** Quando un famiglio scende a 0 punti ferita, scompare e riappare quando l'incantatore lancia nuovamente questo incantesimo. Come azione di Magia, l'incantatore può temporaneamente congedare il famiglio, che scompare in una sacca dimensionale. In alternativa, l'incantatore può farlo sparire per sempre. Come azione di Magia, finché il famiglio è congedato temporaneamente, l'incantatore può farlo ricomparire in uno spazio libero entro 9 metri da sé. Ogni volta che il famiglio scende a 0 punti ferita o scompare in una sacca dimensionale, nello spazio che occupava in precedenza lascia qualsiasi oggetto stesse indossando o trasportando.\\n\\n**Un solo famiglio.** Un incantatore non può avere più di un famiglio alla volta. Se lancia questo incantesimo mentre è già presente un famiglio, l'incantatore gli impartisce un'altra forma possibile.","material":"incenso bruciato del valore di 10 mo o più, che l'incantesimo consuma","page":198},"spell.guards-and-wards":{"name":"Vigilanza e interdizione","areaDimensions":"Area di massimo 225 metri quadrati","description":"L'incantatore crea una difesa che protegge un'area di terreno di massimo 225 metri quadrati. L'area protetta può essere alta fino a 6 metri e l'incantatore può darle una delle seguenti forme: un quadrato con lato di 15 metri, cento quadrati contigui con lato di 1,5 metri o venticinque quadrati contigui con lato di 3 metri.\\n\\nQuando lancia questo incantesimo, l'incantatore può specificare quali individui non saranno influenzati dagli effetti dell'incantesimo. Può anche specificare una parola d'ordine che, una volta pronunciata a voce alta entro 1,5 metri dall'area protetta, renderà chi la pronuncia immune a questi effetti.\\n\\nL'incantesimo crea gli effetti illustrati di seguito all'interno dell'area protetta. Dissolvi magie non ha effetti su vigilanza e interdizione, ma ciascuno dei seguenti effetti può essere dissolto. Se tutti e quattro vengono dissolti, vigilanza e interdizione termina. Se l'incantatore lancia l'incantesimo ogni giorno per 365 giorni sulla stessa area, esso permane finché tutti i suoi effetti non vengono dissolti.\\n\\n**Corridoi.** Tutti i corridoi protetti si riempiono di nebbia e diventano pesantemente oscurati. Inoltre, a ogni incrocio o diramazione che richieda di scegliere una direzione, una creatura diversa dall'incantatore ha una probabilità del 50% di credere di andare in una direzione differente da quella che ha scelto.\\n\\n**Porte.** Tutte le porte nell'area protetta vengono chiuse a chiave magicamente, come sigillate dall'incantesimo serratura arcana. Inoltre, l'incantatore può coprire fino a dieci porte con un'illusione per farle apparire come normali sezioni di parete.\\n\\n**Scale.** Tutte le scale nell'area protetta si riempiono da cima a fondo di ragnatele, come succederebbe lanciando l'incantesimo ragnatela. Per la durata dell'incantesimo vigilanza e interdizione, i fili di queste ragnatele si riformano in 10 minuti se queste vengono distrutte.\\n\\n**Altri effetti dell'incantesimo.** L'incantatore posiziona uno dei seguenti effetti magici all'interno dell'area protetta:\\n\\n- Luci danzanti in quattro corridoi, specificando anche un semplice schema che le luci ripetono per la durata di vigilanza e interdizione.\\n- Bocca magica in due luoghi.\\n- Nube maleodorante in due luoghi (il vapore riappare nel giro di 10 minuti se disperso fintantoché vigilanza e interdizione permane).\\n- Folata di vento in un corridoio o una stanza (il vento soffia ininterrottamente per la durata dell'incantesimo).\\n- Suggestione in un'area quadrata con lato di 1,5 metri. Qualsiasi creatura che entri nell'area riceve mentalmente la suggestione.","material":"una verga d'argento del valore di 10 mo o più","page":200},"spell.feather-fall":{"name":"Caduta morbida","castingTimeCondition":"che l'incantatore può effettuare quando egli stesso o una creatura entro 18 metri da lui che egli è in grado di vedere cade","description":"L'incantatore sceglie fino a cinque creature in caduta entro gittata. La velocità di discesa di una creatura in caduta rallenta fino a 18 metri per round finché l'incantesimo non termina. Se una creatura cade prima del termine dell'incantesimo, non subisce alcun danno da caduta e interrompe l'effetto dell'incantesimo.","material":"una piccola piuma","page":129},"spell.prestidigitation":{"name":"Prestidigitazione","description":"L'incantatore crea un effetto magico entro gittata, scegliendolo tra quelli illustrati di seguito. Se l'incantatore lancia questo incantesimo più volte, può tenere attivi fino a tre dei suoi effetti non istantanei contemporaneamente.\\n\\n**Effetto sensoriale.** L'incantatore crea un effetto sensoriale innocuo e istantaneo, come una pioggia di scintille, una folata di vento, una tenue melodia musicale o uno strano odore.\\n\\n**Trucchetto col fuoco.** L'incantatore accende o spegne istantaneamente una candela, una torcia o un piccolo fuoco da campo.\\n\\n**Pulire o sporcare.** L'incantatore pulisce o sporca istantaneamente un oggetto non più grande di un cubo con spigolo di 30 centimetri.\\n\\n**Lieve sensazione.** L'incantatore riscalda, raffredda o condisce materiale non vivente del volume massimo di un cubo con spigolo di 30 centimetri per 1 ora.\\n\\n**Segno magico.** L'incantatore fa comparire un colore, un piccolo segno o un simbolo su un oggetto o una superficie per 1 ora.\\n\\n**Creazione minore.** L'incantatore crea un monile non magico o un'immagine illusoria che può stare nel palmo della sua mano e che permane fino al termine del suo turno successivo. Un monile non può infliggere danni e non ha valore monetario.","page":175},"spell.arcanists-magic-aura":{"name":"Aura magica dell'arcanista","description":"L'incantatore tocca una creatura consenziente o un oggetto che non sia indossato o trasportato e vi pone un'illusione. Una creatura riceve l'effetto Maschera, mentre un oggetto riceve l'effetto Falsa aura. Entrambi gli effetti, descritti di seguito, permangono per tutta la durata dell'incantesimo. Se l'incantatore lancia l'incantesimo sullo stesso bersaglio ogni giorno per 30 giorni, l'illusione permane finché non viene dissolta.\\n\\n**Maschera (creatura).** L'incantatore sceglie un tipo di creatura diverso da quello del bersaglio. Gli incantesimi e altri effetti magici considerano il bersaglio come se fosse una creatura del tipo scelto dall'incantatore.\\n\\n**Falsa aura (oggetto).** L'incantatore modifica il modo in cui il bersaglio appare agli incantesimi e agli effetti magici che individuano le aure magiche, come per esempio individuazione del magico. L'incantatore può fare in modo che un oggetto non magico appaia come magico e viceversa, oppure può cambiare l'aura di un oggetto in modo che sembri appartenere a una scuola di magia a sua scelta.","material":"un piccolo pezzo quadrato di seta","page":126},"spell.wall-of-ice":{"name":"Muro di ghiaccio","description":"L'incantatore crea un muro di ghiaccio su una superficie solida entro gittata, modellandolo in una cupola semisferica o in una sfera del raggio massimo di 3 metri, oppure in una superficie piatta composta da dieci pannelli quadrati con lato di 3 metri. Ogni pannello dev'essere contiguo a un altro pannello. In qualsiasi forma, il muro ha uno spessore di 30 centimetri e permane per la durata dell'incantesimo.\\n\\nSe il muro invade lo spazio di una creatura alla sua apparizione, quest'ultima viene spinta verso un lato del muro (a scelta dell'incantatore) ed effettua un tiro salvezza su Destrezza, subendo 10d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nIl muro è un oggetto che può essere danneggiato e quindi sfondato, con CA 12 e 30 punti ferita per ogni sezione di 3 metri. Inoltre, è immune ai danni da freddo, da veleno e psichici e vulnerabile ai danni da fuoco. Una sezione di 3 metri viene distrutta se scende a 0 punti ferita e, nello spazio che occupava in precedenza, permane una cortina d'aria gelida.\\n\\nUna creatura che attraversa tale cortina d'aria gelida per la per la prima volta in un turno effettua un tiro salvezza su Costituzione, subendo 5d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.","higherLevels":"I danni inflitti dal muro quando compare aumentano di 2d6 e quelli subiti da chi passa attraverso la cortina d'aria gelida aumentano di 1d6 per ogni slot incantesimo di livello superiore al 6º.","material":"un pezzo di quarzo","page":167},"spell.healing-word":{"name":"Parola guaritrice","description":"Una creatura scelta dall'incantatore entro gittata e che egli è in grado di vedere recupera un ammontare di punti ferita pari a 2d4 più il modificatore di caratteristica da incantatore dell'incantatore.","higherLevels":"La guarigione aumenta di 2d4 per ogni slot di livello superiore al 1º.","page":173},"spell.shining-smite":{"name":"Punizione splendente","castingTimeCondition":"che l'incantatore effettua subito dopo aver colpito una creatura con un'arma da mischia o con un colpo senz'armi","description":"L'attacco infligge 2d6 danni radiosi extra al bersaglio. Fino al termine dell'incantesimo, il bersaglio proietta luce intensa in un raggio di 1,5 metri, non può beneficiare della condizione di invisibilità e i tiri per colpire contro di esso dispongono di vantaggio.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 2º.","page":177},"spell.eyebite":{"name":"Sguardo penetrante","description":"Per la durata dell'incantesimo, gli occhi dell'incantatore diventano neri e vacui. Una creatura a scelta dell'incantatore entro 18 metri da lui e che l'incantatore è in grado di vedere deve superare un tiro salvezza su Saggezza o essere influenzata da uno dei seguenti effetti a sua scelta per la durata dell'incantesimo.\\n\\nIn ogni suo turno fino al termine dell'incantesimo, l'incantatore può usare un'azione di Magia per bersagliare un'altra creatura, non potendo tuttavia bersagliare di nuovo una creatura che abbia superato un tiro salvezza contro questo lancio dell'incantesimo.\\n\\n**Addormentato.** Il bersaglio cade privo di sensi e si risveglia se subisce danni o se un'altra creatura usa un'azione per svegliarla scuotendola.\\n\\n**In preda al panico.** Il bersaglio è spaventato. In ogni suo turno, il bersaglio spaventato deve effettuare l'azione Scatto e muoversi per allontanarsi dall'incantatore lungo il percorso più sicuro e rapido possibile. Se il bersaglio si muove in un punto a più di 18 metri dall'incantatore dove non è più in grado di vederlo, l'effetto termina.\\n\\n**Nauseato.** Il bersaglio viene avvelenato.","page":189},"spell.protection-from-energy":{"name":"Protezione dall'energia","description":"Per la durata dell'incantesimo, una creatura consenziente toccata dall'incantatore dispone di resistenza a un tipo di danni a scelta di quest'ultimo: acido, freddo, fulmine, fuoco o tuono.","page":177},"spell.phantasmal-force":{"name":"Allucinazione di forza","areaDimensions":"Cubo con spigolo di 3 metri","description":"L'incantatore tenta di creare un'illusione nella mente di una creatura entro gittata che egli è in grado di vedere. Il bersaglio effettua un tiro salvezza su Intelligenza. Se lo fallisce, l'incantatore crea l'illusione di un oggetto, una creatura o un fenomeno di altra natura, che non sia più grande di un cubo con spigolo di 3 metri e che sia percepibile soltanto dal bersaglio per la durata dell'incantesimo. L'allucinazione include suoni, temperature e altri stimoli analoghi.\\n\\nIl bersaglio può effettuare un'azione di Studio per esaminare l'allucinazione con una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se supera la prova, il bersaglio capisce che l'allucinazione è un'illusione e l'incantesimo termina.\\n\\nFinché il bersaglio è influenzato dall'incantesimo, considera l'allucinazione come se fosse reale e razionalizza qualsiasi esito illogico prodotto dalle sue interazioni con essa. Ad esempio, se il bersaglio cammina attraverso un ponte illusorio e sopravvive alla caduta, crederà comunque che il ponte esista e che sia stato qualcos'altro a causare la caduta.\\n\\nUn bersaglio influenzato può perfino subire danni dall'illusione se l'allucinazione rappresenta una creatura pericolosa o un pericolo. In ogni turno dell'incantatore, l'allucinazione può infliggere 2d8 danni psichici al bersaglio se questo si trova nell'area dell'allucinazione o entro 1,5 metri da essa. Il bersaglio percepisce i danni come se fossero del tipo appropriato per l'illusione.","material":"un ciuffo di lana","page":122},"spell.aura-of-life":{"name":"Aura di vita","areaDimensions":"Emanazione di 9 metri","description":"L'incantatore irradia un'aura in un'emanazione di 9 metri da sé che permane per la durata dell'incantesimo. Mentre sono nell'aura, l'incantatore e i suoi alleati ottengono resistenza ai danni necrotici e i loro punti ferita massimi non possono essere ridotti. Se un alleato con 0 punti ferita inizia il suo turno nell'aura, ne recupera 1.","page":126},"spell.circle-of-death":{"name":"Cerchio di morte","areaDimensions":"Sfera del raggio di 18 metri","description":"Un flusso di energia negativa si espande in una sfera del raggio di 18 metri da un punto a scelta dell'incantatore situato entro gittata. Ogni creatura nell'area effettua un tiro salvezza su Costituzione, subendo 8d8 danni necrotici in caso di fallimento, o la metà dei danni in caso di successo.","higherLevels":"I danni aumentano di 2d8 per ogni slot di livello superiore al 6º.","material":"polvere ricavata da una perla nera frantumata, del valore di 500 mo o più","page":131},"spell.commune-with-nature":{"name":"Comunione con la natura","description":"L'incantatore entra in comunione con gli spiriti della natura e acquisisce conoscenza dell'area circostante. All'aperto, l'incantesimo fornisce all'incantatore la conoscenza dell'area entro un raggio di 4,5 chilometri. Nelle caverne e in altri ambienti naturali sotterranei, il raggio è limitato a 90 metri. L'incantesimo non funziona nei luoghi in cui la natura è stata sostituita da costruzioni, come castelli e insediamenti.\\n\\nScegli tre dei seguenti fatti; l'incantatore apprende i fatti che riguardano l'area dell'incantesimo:\\n\\n- Luoghi di insediamento\\n- Ubicazione dei portali che conducono verso altri piani di esistenza\\n- Ubicazione di una creatura con grado di sfida pari o superiore a 10 (a scelta del GM) che sia un celestiale, un elementale, un folletto, un immondo o un non morto\\n- Il tipo di pianta, minerale o bestia più diffuso (l'incantatore sceglie quale apprendere)\\n- Ubicazione di distese d'acqua\\n\\nAd esempio, l'incantatore può determinare l'ubicazione di un potente mostro situato in quell'area, l'ubicazione delle distese d'acqua e l'ubicazione di eventuali cittadine.","page":134},"spell.control-water":{"name":"Controllare acqua","areaDimensions":"Cubo con spigolo di 30 metri","description":"Fino al termine dell'incantesimo, l'incantatore controlla una massa d'acqua all'interno di un'area a sua scelta, con un volume massimo pari a un cubo con spigolo di 30 metri, usando uno dei seguenti effetti. Come azione di Magia durante i suoi turni successivi, può ripetere il medesimo effetto o sceglierne uno differente.\\n\\n**Deviare la corrente.** L'incantatore fa in modo che l'acqua corrente nell'area si muova in una direzione scelta da lui, anche se l'acqua deve risalire ostacoli e pareti o scorrere in altre direzioni inverosimili. L'acqua nell'area si muove secondo le indicazioni dell'incantatore, ma una volta superata l'area dell'incantesimo, riprende il suo corso in base al terreno. L'acqua continua a scorrere nella direzione scelta fino al termine dell'incantesimo o finché l'incantatore non sceglie un effetto diverso.\\n\\n**Gorgo.** L'incantatore crea un gorgo al centro dell'area, che deve essere di almeno 15 metri per lato e 7,5 metri di profondità. Il gorgo permane finché l'incantatore non sceglie un effetto diverso o fino al termine dell'incantesimo. Il gorgo è alto 7,5 metri e ampio 1,5 metri alla base e fino a 15 metri alla sommità. Qualsiasi creatura nell'acqua ed entro 7,5 metri dal gorgo viene trascinata per 3 metri verso di esso. Quando una creatura viene trascinata nel gorgo per la prima volta in un turno o vi finisce il suo turno, effettua un tiro salvezza su Forza. In caso di fallimento, la creatura subisce 2d8 danni contundenti, mentre se lo supera, subisce soltanto la metà di quei danni. Una creatura può nuotare via dal gorgo solo se prima effettua un'azione per allontanarsi e supera una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo dell'incantatore.\\n\\nIl livello dell'acqua rimane elevato fino al termine dell'incantesimo o finché l'incantatore non sceglie un effetto diverso. Se questo effetto produce un'onda, questa si ripete all'inizio del turno successivo dell'incantatore finché l'effetto di inondazione permane.\\n\\n**Inondazione.** L'incantatore fa in modo che il livello di tutta l'acqua ferma dell'area si alzi di un massimo di 6 metri. Se l'incantatore sceglie un'area all'interno di un grande specchio d'acqua, genera invece un'onda alta 6 metri che da una parte dell'area si infrange sull'altra. Qualsiasi veicolo di taglia Enorme o inferiore sul percorso dell'onda viene trascinato dall'altra parte dell'area e ha una probabilità del 25% di capovolgersi.\\n\\n**Separare le acque.** L'incantatore fa in modo che l'acqua presente nell'area si separi, creando un canale che si estende per tutta l'area dell'incantesimo; le acque divise formano un muro su entrambi i lati. Il canale permane fino al termine dell'incantesimo o finché l'incantatore non sceglie un effetto diverso. L'acqua poi riempie lentamente il canale nel corso del round successivo, finché il livello normale dell'acqua non viene ripristinato.","material":"una miscela di acqua e polvere","page":136},"spell.spike-growth":{"name":"Crescita di spine","areaDimensions":"Sfera del raggio di 6 metri","description":"Spine e spuntoni nascono dal terreno in una sfera del raggio di 6 metri, centrata su un punto entro gittata. Per la durata dell'incantesimo, l'area diventa terreno difficile. Quando una creatura entra nell'area o si muove al suo interno, subisce 2d4 danni perforanti ogni 1,5 metri di movimento.\\n\\nLa trasformazione del terreno è mimetizzata in modo da sembrare naturale. Qualsiasi creatura che non stesse osservando l'area al momento del lancio dell'incantesimo deve effettuare un'azione di Ricerca e superare una prova di Saggezza (Percezione o Sopravvivenza) contro la CD del tiro salvezza sull'incantesimo per riconoscere la pericolosità del terreno prima di entrarvi.","material":"sette spine","page":139},"spell.dispel-evil-and-good":{"name":"Dissolvi il bene e il male","description":"Per la durata dell'incantesimo, celestiali, elementali, folletti, immondi e non morti subiscono svantaggio ai tiri per colpire effettuati contro l'incantatore. L'incantatore può terminare prematuramente l'incantesimo usando una delle funzioni speciali seguenti.\\n\\n**Congedo.** Come azione di Magia, l'incantatore bersaglia una creatura che egli è in grado di vedere situata entro 1,5 metri da sé dei tipi sopraindicati. Il bersaglio deve superare un tiro salvezza su Carisma, altrimenti viene cacciata sul suo piano d'origine (se non vi si trova già). Se non si trovano già sul loro piano d'origine, i non morti vengono respinti nella Coltre Oscura e i folletti nella Selva Fatata.\\n\\n**Spezzare ammaliamento.** Come azione di Magia, l'incantatore tocca una creatura affascinata, spaventata o posseduta da una o più creature dei tipi sopraindicati. Il bersaglio non è più posseduto, affascinato o spaventato da quelle creature.","material":"polvere d'argento e ferro","page":142},"spell.time-stop":{"name":"Fermare il tempo","description":"L'incantatore interrompe brevemente lo scorrere nel tempo per tutti tranne che per se stesso.\\n\\nPer le altre creature il tempo non passa, mentre l'incantatore effettua 1d4 + 1 turni consecutivamente, nel corso dei quali può usare azioni e muoversi normalmente.\\n\\nQuesto incantesimo termina se una delle azioni usate o qualsiasi effetto creato dall'incantatore nel corso della sua durata influenza una creatura diversa da lui o un oggetto indossato o trasportato da qualcuno diverso da lui. Termina inoltre se l'incantatore si muove in un luogo a più di 300 metri dal punto in cui ha lanciato l'incantesimo.","page":147},"spell.glyph-of-warding":{"name":"Glifo di interdizione","description":"L'incantatore traccia un glifo da cui, in seguito, si sprigionerà un effetto magico. Il glifo può essere tracciato su una superficie (come un tavolo o una sezione di pavimento) o, al fine di nasconderlo, all'interno di un oggetto che può essere chiuso (come un libro o un forziere). Il glifo può coprire un'area massima del diametro di 3 metri. Se la superficie o l'oggetto viene spostato per più di 3 metri dal punto in cui l'incantatore ha lanciato questo incantesimo, il glifo si infrange e l'incantesimo termina senza essere innescato.\\n\\nIl glifo è quasi impercettibile e, per notarlo, è necessario superare una prova di Saggezza (Percezione) contro la CD del tiro salvezza sull'incantesimo.\\n\\nQuando l'incantatore traccia il glifo, ne programma l'innesco e sceglie se si tratta di una runa esplosiva o di un glifo magico, come illustrato di seguito.\\n\\n**Programmare l'innesco.** Quando questo incantesimo viene lanciato, l'incantatore decide cosa innesca il glifo. Nel caso di glifi tracciati su una superficie, gli inneschi più comuni includono: toccare o camminare su di essi, rimuovere un altro oggetto che li copre o avvicinarsi a una certa distanza da loro. Nel caso di glifi tracciati all'interno di un oggetto, gli inneschi più comuni includono aprire quell'oggetto o vedere il glifo. Una volta che un glifo viene innescato, l'incantesimo termina.\\n\\nL'incantatore può perfezionare l'innesco in modo che venga attivato solo da un certo tipo di creature (ad esempio, il glifo potrebbe essere programmato per influenzare le aberrazioni). L'incantatore può inoltre impostare delle condizioni per evitare di innescare il glifo, come pronunciare una specifica parola d'ordine.\\n\\n**Runa esplosiva.** Quando attivato, il glifo esplode in una sfera di energia magica con raggio di 6 metri centrata su di esso. Ogni creatura presente nell'area effettua un tiro salvezza su Destrezza. In caso di fallimento, subisce 5d8 danni da acido, freddo, fulmine, fuoco o tuono (a scelta dell'incantatore al momento della creazione del glifo), o la metà dei danni in caso di successo.\\n\\n**Glifo magico.** L'incantatore può custodire un incantesimo preparato di 3º livello o inferiore all'interno del glifo lanciandolo come parte del suo processo di creazione. L'incantesimo deve avere come bersaglio una sola creatura o un'area. In questo modo, l'incantesimo custodito non ha effetto immediato, ma ha effetto quando il glifo si attiva. Se l'incantesimo ha un bersaglio, risulterà essere la creatura che ha attivato il glifo, mentre se influenza un'area, tale area sarà centrata su quella creatura. Se l'incantesimo evoca creature ostili oppure crea oggetti o trappole dannose, ciò che viene evocato o creato appare nel punto più vicino possibile all'intruso e lo attacca. Se l'incantesimo richiede concentrazione, permane per tutta la sua durata.","higherLevels":"I danni di una runa esplosiva aumentano di 1d8 per ogni slot di livello superiore al 3º. Se l'incantatore crea un glifo magico, può custodirvi qualsiasi incantesimo di livello pari o inferiore a quello dello slot incantesimo usato per il glifo di interdizione.","material":"polvere di diamante del valore di 200 mo o più, che l'incantesimo consuma","page":151},"spell.silent-image":{"name":"Immagine silenziosa","areaDimensions":"Cubo con spigolo di 4,5 metri","description":"L'incantatore crea l'immagine di un oggetto, una creatura o qualche altro fenomeno visibile che non sia più grande di un cubo con spigolo di 4,5 metri. L'immagine compare in un punto situato entro gittata e permane per la durata dell'incantesimo. L'immagine è puramente visiva: non è accompagnata da suoni, odori o altri effetti sensoriali.\\n\\nCome azione di Magia, il personaggio può far muovere l'immagine verso qualunque posizione entro gittata. Mentre l'immagine è in movimento, l'incantatore può alterarne l'aspetto in modo che i movimenti risultino naturali. Ad esempio, se l'incantatore crea l'immagine di una creatura e decide di farla muovere, può modificarla per simulare il fatto che sta camminando.\\n\\nL'illusione può essere rivelata da un'interazione fisica, poiché gli oggetti possono attraversarla. Una creatura che effettua l'azione di Studio per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine.","material":"un ciuffo di lana","page":155},"spell.flame-blade":{"name":"Lama infuocata","description":"L'incantatore evoca una lama infuocata nella sua mano libera. La lama ha forma e dimensioni simili a una scimitarra e permane per la durata dell'incantesimo. Se l'incantatore la lascia cadere, la lama scompare, ma può essere evocata di nuovo come azione bonus.\\n\\nCome azione di Magia, l'incantatore può effettuare un attacco in mischia con la lama infuocata. Se il colpo va a segno, il bersaglio subisce 3d6 danni da fuoco più il modificatore di caratteristica da incantatore dell'incantatore.\\n\\nLa lama infuocata emana luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 2º.","material":"una foglia di sommacco","page":160},"spell.locate-creature":{"name":"Localizza creatura","description":"L'incantatore descrive o nomina una creatura a lui familiare, percependo la direzione della sua ubicazione se la creatura si trova entro 300 metri da lui. Se la creatura è in movimento, l'incantatore apprende verso quale direzione si sta dirigendo.\\n\\nL'incantesimo può localizzare una creatura specifica nota all'incantatore o una creatura di un tipo specifico più vicina (come un umano o un unicorno), purché l'incantatore abbia visto tale creatura da vicino (entro 9 metri) almeno una volta. Se la creatura descritta o nominata ha una forma diversa, per esempio se si trova sotto l'effetto di un incantesimo carne in pietra o metamorfosi, questo incantesimo non riesce a localizzarla.\\n\\nQuesto incantesimo non può localizzare una creatura se uno strato di piombo blocca il percorso diretto tra essa e l'incantatore.","material":"un ciuffo di peli di un segugio","page":162},"spell.sanctuary":{"name":"Santuario","description":"L'incantatore protegge una creatura situata entro gittata. Fino al termine dell'incantesimo, ogni creatura che bersaglia la creatura protetta con un tiro per colpire o con un incantesimo dannoso deve prima superare un tiro salvezza su Saggezza, altrimenti deve scegliere un bersaglio diverso o perdere l'attacco o l'incantesimo. Questo incantesimo non protegge la creatura protetta dalle aree di effetto. L'incantesimo termina se la creatura protetta effettua un tiro per colpire, lancia un incantesimo o infligge danni.","material":"un frammento di vetro di uno specchio","page":183},"spell.plane-shift":{"name":"Spostamento planare","description":"L'incantatore e un massimo di otto creature consenzienti, che si tengono per mano formando un cerchio, vengono trasportati su un piano di esistenza diverso. L'incantatore può specificare la destinazione in termini generici, come una città specifica sul Piano Elementale del Fuoco o palazzo sul secondo livello dei Nove Inferi, apparendo in quella destinazione o nelle sue immediate vicinanze, in base alla scelta del GM.\\n\\nIn alternativa, se l'incantatore conosce la sequenza di sigilli di un cerchio di teletrasporto su un altro piano di esistenza, questo incantesimo può portarlo fino a quel cerchio. Se il cerchio di teletrasporto è troppo piccolo per contenere tutte le creature trasportate dall'incantatore, esse appariranno negli spazi liberi più vicini.","material":"una verga di metallo biforcuta del valore di 250 mo o più e in sintonia con un piano di esistenza","page":191},"spell.telekinesis":{"name":"Telecinesi","description":"L'incantatore ottiene la capacità di spostare o manipolare creature e oggetti con la forza del pensiero. Al lancio e come sua azione di Magia ogni turno successivo prima del termine dell'incantesimo, l'incantatore può esercitare la propria volontà su una creatura o un oggetto entro gittata che egli è in grado di vedere, provocando l'effetto appropriato descritto di seguito. L'incantatore può influenzare lo stesso bersaglio in ogni round o sceglierne uno nuovo in ogni momento. Se cambia bersaglio, quello precedente non risentirà più degli effetti dell'incantesimo.\\n\\n**Creatura.** L'incantatore può provare a spostare una creatura di taglia Enorme o inferiore. Il bersaglio deve superare un tiro salvezza su Forza, altrimenti verrà spostato dall'incantatore di massimo 9 metri in una direzione entro la gittata dell'incantesimo. Fino alla fine del suo turno successivo, la creatura è trattenuta e, se alzata a mezz'aria, rimarrà sospesa lì. Cadrà al termine del turno successivo dell'incantatore, a meno che non utilizzi di nuovo questa opzione su di essa e fallisca il tiro salvezza.\\n\\n**Oggetto.** L'incantatore può provare a spostare un oggetto di taglia Enorme o inferiore. Se esso non è indossato o trasportato, lo sposta automaticamente fino a 9 metri in qualsiasi direzione entro la gittata dell'incantesimo.\\n\\nSe l'oggetto è indossato o trasportato da una creatura, quest'ultima deve superare un tiro salvezza su Forza, altrimenti l'incantatore lo tirerà via e lo sposterà fino a 9 metri in qualsiasi direzione entro la gittata dell'incantesimo.\\n\\nCon la sua presa telecinetica, l'incantatore può esercitare un controllo più preciso sugli oggetti, come manipolare uno strumento semplice.","page":193},"spell.black-tentacles":{"name":"Tentacoli neri","areaDimensions":"Quadrato con lato di 6 metri","description":"Una massa di tentacoli brulicanti color ebano riempie un quadrato con lato di 6 metri situato sul terreno entro gittata e che l'incantatore è in grado di vedere. Per la durata dell'incantesimo, questi tentacoli trasformano quell'area in un terreno difficile.\\n\\nOgni creatura nell'area effettua un tiro salvezza su Forza. In caso di fallimento, subisce 3d6 danni contundenti ed è trattenuta fino al termine dell'incantesimo. Una creatura effettua il tiro salvezza anche se entra nell'area o vi termina il suo turno. Il tiro salvezza può essere effettuato solo una volta per turno.\\n\\nUna creatura trattenuta può usare un'azione per effettuare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo, ponendo fine alla sua condizione \\"trattenuta\\" in caso di successo.","material":"un tentacolo","page":195},"spell.vampiric-touch":{"name":"Tocco del vampiro","description":"Il tocco della mano dell'incantatore, avviluppata in una cortina d'ombra, può risucchiare l'energia vitale delle altre creature per curare le proprie ferite. Effettua un attacco con incantesimo in mischia contro una creatura a portata. Se il colpo va a segno, il bersaglio subisce 3d6 danni necrotici e l'incantatore recupera una quantità di punti ferita pari alla metà dei danni necrotici inflitti.\\n\\nFino al termine dell'incantesimo, come azione di Magia, l'incantatore può effettuare di nuovo l'attacco a ogni suo turno, prendendo di mira la stessa creatura o un'altra.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 3º.","page":196},"spell.animate-objects":{"name":"Animare oggetti","description":"Gli oggetti si animano su ordine dell'incantatore. L'incantatore sceglie un numero di oggetti non magici entro gittata che non siano indossati o trasportati, fissati su una superficie o di dimensioni Mastodontiche. Il numero massimo di oggetti è uguale al suo modificatore di caratteristica da incantatore; per questo numero, un bersaglio di taglia Media o inferiore conta come un oggetto, un bersaglio di taglia Grande conta come due e un bersaglio Enorme conta come tre.\\n\\nOgni bersaglio si anima e diventa un costrutto provvisto di gambe che utilizza la scheda delle statistiche dell'oggetto animato; questa creatura è sotto il controllo dell'incantatore fino al termine dell'incantesimo o finché non viene ridotta a 0 punti ferita. Ogni creatura creata con questo incantesimo diventa un alleato per l'incantatore e i suoi alleati. In combattimento, la creatura ha lo stesso punteggio di iniziativa dell'incantatore, ma inizia il turno immediatamente dopo il suo.\\n\\nFino al termine dell'incantesimo, come azione bonus, l'incantatore può comandare mentalmente qualsiasi creatura creata con questo incantesimo, a patto che si trovi entro 150 metri da sé (se controlla varie creature, l'incantatore può comandarne più di una allo stesso momento, impartendo lo stesso comando a ciascuna di loro). Se invece non impartisce alcun comando, la creatura effettua l'azione Schivata e si sposta solo per evitare di subire danni. Quando la creatura scende a 0 punti ferita, riassume la sua forma di oggetto, a cui vengono trasferiti eventuali danni rimanenti.","higherLevels":"I danni da Schianto della creatura aumentano di 1d4 (taglia Media o inferiore), 1d6 (taglia Grande) o 1d12 (taglia Enorme) per ogni slot di livello superiore al 5º.","page":124},"spell.sending":{"name":"Inviare","description":"L'incantatore invia un breve messaggio di un massimo di 25 parole a una creatura che ha incontrato o a una creatura che gli è stata descritta da qualcuno che ha conosciuto. Il bersaglio sente il messaggio nella sua mente, riconosce l'incantatore come colui che l'ha inviato e può rispondere immediatamente allo stesso modo. L'incantesimo consente ai bersagli di comprendere il significato del messaggio dell'incantatore.\\n\\nL'incantatore può inviare il messaggio a qualsiasi distanza e perfino ad altri piani di esistenza, ma se il bersaglio si trova su un piano di esistenza diverso dal suo, c'è una probabilità del 5% che il messaggio non arrivi. Se l'invio del messaggio fallisce, l'incantatore se ne rende conto.\\n\\nQuando riceve il messaggio, una creatura può bloccare la capacità dell'incantatore di contattarla nuovamente tramite questo incantesimo per 8 ore. Se l'incantatore cerca di inviare un altro messaggio durante quel periodo, capisce di essere stato bloccato e l'incantesimo fallisce.","material":"un filo di rame","page":159},"spell.tongues":{"name":"Linguaggi","description":"Questo incantesimo concede alla creatura toccata dall'incantatore l'abilità di comprendere qualsiasi lingua (parlata o non) che sente o vede. Inoltre, quando comunica con parole o gesti, qualsiasi creatura che conosce almeno una lingua può comprenderla se è in grado di sentire ciò che dice o vedere i suoi gesti.","material":"una ziggurat in miniatura","page":161},"spell.mending":{"name":"Riparare","description":"Questo incantesimo ripara una singola crepa o uno squarcio in un oggetto toccato dall'incantatore, come l'anello spezzato di una catena, due metà di una chiave spezzata, un mantello strappato o un otre forato. Se le dimensioni della crepa o dello squarcio non superano i 30 centimetri, l'incantatore ripara l'oggetto senza lasciare traccia del danno precedente.\\n\\nQuesto incantesimo può riparare un oggetto magico solo fisicamente, senza ripristinare la magia in esso contenuta.","material":"due calamite","page":181},"spell.mind-spike":{"name":"Aculeo mentale","description":"L'incantatore guida un flusso di energia psionica nella mente di una creatura entro gittata che egli è in grado di vedere. Il bersaglio effettua un tiro salvezza su Saggezza, subendo 3d8 danni psichici in caso di fallimento, o la metà dei danni in caso di successo. Se fallisce il tiro, l'incantatore sa sempre dove si trova il bersaglio fino al termine dell'incantesimo, ma solo se entrambi si trovano sullo stesso piano di esistenza. Finché l'incantatore è in possesso di queste conoscenze, il bersaglio non può nascondersi da lui e, se è invisibile, non ottiene alcun beneficio da questa condizione contro di lui.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 2º.","page":121},"spell.animate-dead":{"name":"Animare morti","description":"L'incantatore sceglie una pila di ossa o un cadavere umanoide di taglia Media o Piccola entro gittata, animandolo come creatura non morta. Il bersaglio si trasforma in uno scheletro se l'incantatore sceglie la pila di ossa, o in uno zombi se l'incantatore sceglie un cadavere (vedi \\"Mostri\\" per le schede delle statistiche).\\n\\nA ogni suo turno, l'incantatore può effettuare un'azione bonus per comandare mentalmente qualsiasi creatura creata con questo incantesimo, a patto che si trovi entro 18 metri da lui (se controlla varie creature, l'incantatore può comandarne più di una allo stesso momento, impartendo lo stesso comando a ciascuna di loro). L'incantatore decide quale azione effettuerà la creatura e dove si muoverà nel suo turno successivo, oppure può impartirle un comando generale, come restare a guardia di una stanza o un di corridoio. Se invece non impartisce alcun comando, la creatura effettua l'azione Schivata e si sposta solo per evitare di subire danni. Una volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito.\\n\\nLa creatura rimane sotto il controllo dell'incantatore per 24 ore, passate le quali smette di obbedire a qualsiasi comando ulteriore. Per mantenere il controllo sulla creatura per altre 24 ore, l'incantatore deve lanciare di nuovo questo incantesimo su di essa prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo gli permette di ristabilire il controllo su un massimo di quattro creature da lui animate tramite questo incantesimo, anziché animarne una nuova.","higherLevels":"L'incantatore anima due creature non morte aggiuntive o ristabilisce il controllo su di esse per ogni slot incantesimo di livello superiore al 3º. Ognuna delle creature deve provenire da un diverso cadavere o mucchio d'ossa.","material":"una goccia di sangue, un pezzo di carne e un pizzico di polvere d'osso","page":124},"spell.mage-armor":{"name":"Armatura magica","description":"L'incantatore tocca una creatura consenziente che non indossa un'armatura. Fino al termine dell'incantesimo, la CA base del bersaglio diventa 13 più il suo modificatore di Destrezza. L'incantesimo termina in anticipo se il bersaglio indossa un'armatura.","material":"un pezzo di cuoio trattato","page":126},"spell.heroes-feast":{"name":"Banchetto degli eroi","areaDimensions":"Cubo con spigolo di 3 metri","description":"L'incantatore evoca accanto a sé un banchetto che appare su una superficie all'interno di un cubo libero con spigolo di 3 metri. Consumare il banchetto richiede 1 ora, solo al termine della quale il convivio scompare e i suoi effetti benefici vengono applicati. Fino a un massimo di dodici creature possono partecipare al banchetto.\\n\\nUna creatura che partecipa al banchetto ottiene numerosi benefici che durano 24 ore. La creatura diventa resistente ai danni da veleno e immune alle condizioni avvelenato e spaventato. Inoltre, i suoi punti ferita massimi aumentano di 2d10 e ottiene lo stesso numero di punti ferita.","material":"una ciotola tempestata di gemme del valore di 1.000 mo o più, che l'incantesimo consuma","page":127},"spell.tiny-hut":{"name":"Capanna","areaDimensions":"Emanazione di 3 metri","description":"Un'emanazione di 3 metri si materializza attorno all'incantatore e permane stazionaria per la durata dell'incantesimo. L'incantesimo fallisce quando l'incantatore lo lancia ma l'emanazione non è abbastanza grande da poter inglobare totalmente tutte le creature all'interno della sua area.\\n\\nLe creature e gli oggetti all'interno dell'emanazione al momento del lancio dell'incantesimo possono attraversarla liberamente, mentre a tutte le altre creature e oggetti è proibito. Non è possibile lanciare incantesimi di 3º livello o inferiore attraverso l'emanazione, e gli effetti di tali incantesimi non si estendono al suo interno.\\n\\nL'atmosfera all'interno dell'emanazione è gradevole e asciutta, a prescindere dal tempo atmosferico all'esterno. Fino al termine dell'incantesimo, l'incantatore può decidere che all'interno dell'emanazione ci sia luce fioca o oscurità (nessuna azione richiesta). Dall'esterno, l'emanazione appare opaca e di un qualsiasi colore a scelta dell'incantatore, ma dall'interno risulta trasparente.\\n\\nL'incantesimo termina in anticipo se l'incantatore lo lancia di nuovo o se esce dall'area dell'emanazione.","material":"una perla di cristallo","page":130},"spell.cone-of-cold":{"name":"Cono di freddo","areaDimensions":"Cono di 18 metri","description":"Un getto d'aria gelida si propaga dall'incantatore. Ogni creatura entro un cono di 18 metri che ha origine dall'incantatore effettua un tiro salvezza su Costituzione, subendo 8d8 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo. Una creatura uccisa da questo incantesimo si tramuta in una statua di ghiaccio finché non si scioglie.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 5º.","material":"un piccolo cono di cristallo o vetro","page":135},"spell.contact-other-plane":{"name":"Contattare altri piani","description":"L'incantatore contatta mentalmente un semidio, lo spirito di un sapiente defunto da tempo o qualche altra entità saggia appartenente a un altro piano. Contattare questa intelligenza ultraterrena può sconvolgere la sua mente: quando l'incantatore lancia questo incantesimo, deve effettuare un tiro salvezza su Intelligenza con CD 15. In caso di successo, l'incantatore può porre all'entità un massimo di cinque domande prima del termine dell'incantesimo. Il GM risponde a ogni domanda con una parola, come per esempio \\"sì\\", \\"no\\", \\"forse\\", \\"mai\\", \\"irrilevante\\" o \\"ignoto\\" (se l'entità non conosce la risposta alla domanda). Nel caso in cui una risposta di una parola sola possa rivelarsi fuorviante, il GM può fornire come risposta una breve frase.\\n\\nIn caso di fallimento, l'incantatore subisce 6d6 danni psichici ed è incapacitato finché non completa un riposo lungo. Un incantesimo ristorare superiore fa svanire questo effetto.","page":136},"spell.fabricate":{"name":"Fabbricare","description":"L'incantatore converte materie prime in prodotti dello stesso materiale. Per esempio, può fabbricare un ponte di legno da una catasta di tronchi, una corda da un groviglio di canapa o abiti da lino o lana.\\n\\nL'incantatore sceglie materie prime entro gittata che egli è in grado di vedere e, qualora ne possegga una quantità sufficiente, può fabbricare un oggetto di taglia Grande o inferiore (contenuto in un cubo con spigolo di 3 metri o in otto cubi con spigolo di 1,5 metri collegati tra loro). Tuttavia, se l'incantatore lavora con metallo, pietra o un'altra sostanza minerale, l'oggetto fabbricato potrà essere al massimo di taglia Media (contenuto in un cubo con spigolo di 1,5 metri). La qualità degli oggetti realizzati è basata sulla qualità delle materie prime.\\n\\nQuesto incantesimo non può creare creature o oggetti magici. Inoltre, l'incantatore non può utilizzarlo per creare oggetti che richiedono un alto grado di precisione, come armi o armature, a meno che non possegga competenza con il tipo di strumenti da artigiano usati per realizzare tali oggetti.","page":147},"spell.etherealness":{"name":"Forma eterea","description":"L'incantatore mette piede nelle regioni di confine in cui il Piano Etereo si sovrappone al suo piano attuale. Rimane nel Confine Etereo per la durata dell'incantesimo. Durante questo periodo, l'incantatore può muoversi in ogni direzione. Muovendosi su o giù, ogni 30 cm di movimento gli costano 30 cm extra. L'incantatore può percepire il piano da cui proviene, che appare in scala di grigi ed è visibile solo fino a una distanza di 18 metri.\\n\\nMentre si trova sul Piano Etereo, l'incantatore può influenzare ed essere influenzato solo dalle creature, gli oggetti e gli effetti che si trovano su quel piano. Le creature che non sono presenti sul Piano Etereo non possono percepire o interagire con l'incantatore, a meno che un privilegio non dia loro la capacità per farlo.\\n\\nAl termine dell'incantesimo, l'incantatore torna sul piano da cui proviene, sul punto che corrisponde al suo spazio nel Confine Etereo. Se l'incantatore appare in uno spazio occupato, viene sbalzato nello spazio libero più vicino e subisce una quantità di danni da forza pari al doppio del numero di metri di cui si è mosso.\\n\\nQuesto incantesimo termina all'istante se l'incantatore lo lancia mentre si trova sul Piano Etereo o su un piano non confinante, come uno dei Piani Esterni.","higherLevels":"L'incantatore può bersagliare fino a un massimo di tre creature consenzienti (incluso se stesso) per ogni slot di livello superiore al 7º. Al momento del lancio dell'incantesimo, le creature non devono trovarsi a più di 3 metri dall'incantatore.","page":149},"spell.acid-arrow":{"name":"Freccia acida","description":"Una freccia verde scintillante sfreccia verso un bersaglio entro gittata ed esplode in uno spruzzo di acido. L'incantatore effettua un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 4d4 danni da acido e 2d4 danni da acido alla fine del suo turno successivo. Se il colpo manca, la freccia schizza acido sul bersaglio, infliggendo solo la metà dei danni iniziali.","higherLevels":"I danni (sia iniziali che successivi) aumentano di 1d4 per ogni slot di livello superiore al 2º.","material":"foglia di rabarbaro in polvere","page":150},"spell.forcecage":{"name":"Gabbia di forza","description":"Una prigione cubica di forza magica invisibile e immobile si materializza intorno a un'area entro gittata scelta dall'incantatore. La prigione può essere una gabbia o una struttura solida a sua scelta.\\n\\nUna prigione a forma di gabbia può misurare fino a 6 metri per lato ed essere composta da sbarre di 1,25 centimetri di diametro disposte a 1,25 centimetri di distanza. Una prigione a forma di scatola chiusa può misurare fino a 3 metri per lato e crea una barriera compatta che impedisce a ogni tipo di materia di passarle attraverso e blocca qualsiasi incantesimo lanciato verso l'interno o l'esterno dell'area.\\n\\nAl momento del lancio dell'incantesimo, ogni creatura completamente all'interno dell'area della gabbia è intrappolata. Le creature situate solo parzialmente all'interno dell'area o quelle di dimensioni troppo grandi per essere contenute al suo interno sono spinte lontano dal centro dell'area finché non ne fuoriescono completamente.\\n\\nUna creatura all'interno della gabbia non può uscirne tramite mezzi non magici. Se la creatura prova a utilizzare il teletrasporto o il viaggio interplanare, deve prima effettuare un tiro salvezza su Carisma. Se lo supera, la creatura può usare quella magia per uscire dalla gabbia, mentre se lo fallisce, non può uscire dalla gabbia e spreca un uso di quell'incantesimo o effetto. La gabbia si estende anche sul Piano Etereo, bloccando i viaggi eterei.\\n\\nQuesto incantesimo non può essere dissolto con dissolvi magie.","material":"polvere di rubino del valore di 1.500 mo o più, che l'incantesimo consuma","page":150},"spell.awaken":{"name":"Risveglio","description":"L'incantatore trascorre il tempo di lancio tracciando percorsi magici su una pietra preziosa, poi tocca il bersaglio. Il bersaglio deve essere una bestia o una creatura vegetale con Intelligenza pari o inferiore a 3 o una pianta naturale che non sia una creatura. Il bersaglio acquisisce Intelligenza pari a 10 e la capacità di parlare una lingua conosciuta dall'incantatore. Se il bersaglio è una pianta naturale, diventa una creatura vegetale e ottiene l'abilità di muovere i suoi rami, radici, liane, rampicanti e così via e sviluppa sensi simili a quelli umani. Il GM sceglie le statistiche appropriate per il vegetale risvegliato, come per esempio nel caso di un cespuglio risvegliato o di un albero risvegliato, in \\"Mostri\\".\\n\\nIl bersaglio risvegliato rimane affascinato per 30 giorni o finché l'incantatore o i suoi alleati non gli infliggono danni. Quando l'effetto di tale condizione svanisce, la creatura risvegliata sceglie il suo atteggiamento nei confronti dell'incantatore.","material":"un'agata del valore di 1.000 mo o più, che l'incantesimo consuma","page":182},"spell.private-sanctum":{"name":"Santuario privato","areaDimensions":"Cubo da un minimo di 1,5 metri per spigolo a un massimo di 30 metri per spigolo","description":"L'incantatore rende magicamente sicura un'area entro gittata: un cubo le cui dimensioni possono variare da un minimo di 1,5 metri per spigolo a un massimo di 30 metri per spigolo. L'incantesimo permane per tutta la sua durata.\\n\\nQuando lancia l'incantesimo, l'incantatore decide che tipo di sicurezza esso fornisce, scegliendo una o più tra le proprietà seguenti:\\n\\n- I suoni non possono attraversare la barriera ai confini dell'area protetta.\\n- La barriera nell'area protetta appare oscura e nebulosa, rendendo impossibile vedere oltre (anche utilizzando scurovisione).\\n- I sensori creati dagli incantesimi di divinazione non possono apparire all'interno dell'area protetta né oltrepassarne il perimetro.\\n- Le creature nell'area non possono essere bersaglio di incantesimi di divinazione.\\n- Nulla può teletrasportarsi dentro o fuori dall'area protetta.\\n- I viaggi planari sono bloccati all'interno dell'area protetta.\\n\\nLanciando questo incantesimo nello stesso punto ogni giorno per 365 giorni, l'incantesimo dura finché non viene dissolto.","higherLevels":"L'incantatore può aumentare le dimensioni del cubo di 30 metri per spigolo per ogni slot di livello superiore al 4º.","material":"una sottile lamina di piombo","page":183},"spell.find-traps":{"name":"Scopri trappole","description":"L'incantatore percepisce qualsiasi trappola piazzata entro gittata e nel suo campo visivo. Ai fini di questo incantesimo, per trappola si intende qualsiasi oggetto o meccanismo creato per provocare danni o altri pericoli. Pertanto, l'incantesimo è in grado di percepire gli incantesimi allarme o glifo di interdizione, o una fossa meccanica nascosta, ma non di rivelare un cedimento naturale del pavimento, un soffitto instabile o una voragine nascosta.\\n\\nQuesto incantesimo rivela la presenza di una trappola ma non la sua ubicazione. L'incantatore scopre solo la natura generale del pericolo che la trappola pone.","page":185},"spell.arcane-sword":{"name":"Spada arcana","description":"L'incantatore crea una spada spettrale che fluttua entro gittata e permane per tutta la durata dell'incantesimo.\\n\\nQuando la spada appare, l'incantatore può effettuare un attacco in mischia con questo incantesimo contro un bersaglio che si trova entro 1,5 metri dalla spada. Se il colpo va a segno, il bersaglio subisce 4d12 danni da forza più il modificatore di caratteristica da incantatore dell'incantatore.\\n\\nNei suoi turni successivi, l'incantatore può effettuare un'azione bonus per spostare la spada fino a 9 metri in un punto che è in grado di vedere e ripetere l'attacco contro lo stesso bersaglio o uno diverso.","material":"una spada in miniatura del valore di 250 mo o più","page":191},"spell.freedom-of-movement":{"name":"Libertà di movimento","description":"L'incantatore tocca una creatura consenziente. Per la durata dell'incantesimo, il movimento del bersaglio non è influenzato dal terreno difficile, inoltre incantesimi e altri effetti magici non possono né ridurne la velocità né trattenerlo o renderlo paralizzato. Il bersaglio dispone anche di una velocità di nuoto pari alla sua velocità.\\n\\nInoltre, il bersaglio può usare 1,5 metri di movimento per sfuggire automaticamente alle restrizioni non magiche, come un paio di manette o la presa di una creatura che lo afferra.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º.","material":"una cinghia di cuoio","page":161},"spell.conjure-elemental":{"name":"Evoca elementale","description":"L'incantatore può evocare uno spirito intangibile di taglia Grande dai Piani Elementali che appare in uno spazio libero entro gittata. L'incantatore sceglie l'elemento dello spirito, che ne determina il tipo di danno: aria (fulmine), terra (tuono), fuoco (fuoco) o acqua (freddo). Lo spirito permane per la durata dell'incantesimo.\\n\\nOgni volta che una creatura che l'incantatore è in grado di vedere entra nello spazio dello spirito o inizia il suo turno entro un raggio di 1,5 metri da esso, l'incantatore può costringerla a effettuare un tiro salvezza su Destrezza, a patto che lo spirito non stia trattenendo una creatura. In caso di fallimento, il bersaglio subisce 8d8 danni del tipo dello spirito, e il bersaglio è trattenuto fino al termine dell'incantesimo. All'inizio di ogni suo turno, il bersaglio trattenuto ripete il tiro. In caso di fallimento, il bersaglio subisce 4d8 danni del tipo determinato dallo spirito. In caso di successo, il bersaglio non è più trattenuto dallo spirito.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 4º.","page":146},"spell.prayer-of-healing":{"name":"Preghiera di guarigione","description":"Fino a cinque creature a scelta dell'incantatore, situate entro gittata per l'intera durata del lancio dell'incantesimo, ottengono i benefici di un riposo breve e recuperano 2d8 punti ferita. Una creatura non può essere nuovamente influenzata da questo incantesimo fino a che non completa un riposo lungo.","higherLevels":"La guarigione aumenta di 1d8 per ogni slot di livello superiore al 2º.","page":174},"spell.sequester":{"name":"Celare","description":"Con un tocco, l'incantatore cela magicamente un oggetto o una creatura consenziente. Per la durata dell'incantesimo, il bersaglio è invisibile e non può essere bersagliato da incantesimi di divinazione, individuato dalla magia o osservato a distanza con la magia.\\n\\nSe il bersaglio è una creatura, entra in uno stato di animazione sospesa, è priva di sensi, non invecchia e non necessita di cibo, acqua o aria.\\n\\nPer terminare prematuramente l'incantesimo, l'incantatore può stabilire una condizione, che può essere qualsiasi cosa a sua scelta che, tuttavia, debba verificarsi o essere visibile entro 1,5 chilometri dal bersaglio. Per esempio, \\"dopo 1.000 anni\\" o \\"al risveglio del tarrasque\\". Questo incantesimo termina inoltre se il bersaglio subisce danni.","material":"polvere di gemme del valore di 5.000 mo o più, che l'incantesimo consuma","page":131},"spell.comprehend-languages":{"name":"Comprensione dei linguaggi","description":"Per la durata dell'incantesimo, l'incantatore comprende il significato letterale di qualsiasi linguaggio che è in grado di sentire o vedere tramite segni. Comprende inoltre ogni linguaggio scritto che è in grado di vedere, ma deve toccare la superficie su cui sono scritte le parole. È necessario circa 1 minuto per leggere una pagina di testo. Questo incantesimo non decodifica simboli o messaggi segreti.","material":"un pizzico di fuliggine e di sale","page":134},"spell.counterspell":{"name":"Controincantesimo","castingTimeCondition":"che l'incantatore può effettuare quando vede una creatura entro 18 metri da lui lanciare un incantesimo con componenti verbali, somatiche o materiali","description":"L'incantatore tenta di interrompere una creatura nell'atto di lanciare un incantesimo. La creatura effettua un tiro salvezza su Costituzione. Se lo fallisce, l'incantesimo si dissolve senza alcun effetto e l'azione, azione bonus o reazione utilizzata per lanciarlo viene sprecata. Se l'incantesimo è stato lanciato usando uno slot incantesimo, lo slot non viene consumato.","page":136},"spell.create-or-destroy-water":{"name":"Creare o distruggere acqua","description":"L'incantatore esegue una delle seguenti azioni:\\n\\n- **Creare acqua.** L'incantatore crea fino a 40 litri d'acqua pulita in un contenitore aperto entro gittata. In alternativa, l'acqua cade sotto forma di pioggia in un cubo con spigolo di 9 metri entro gittata, estinguendo le fiamme presenti nell'area.\\n- **Distruggere acqua.** L'incantatore distrugge fino a 40 litri d'acqua in un contenitore aperto entro gittata. In alternativa, distrugge la nebbia presente in un cubo con spigolo di 9 metri entro gittata.","higherLevels":"L'incantatore crea o distrugge 40 litri aggiuntivi d'acqua, oppure la grandezza del cubo aumenta di 1,5 metri per spigolo, per ogni slot di livello superiore al 1º.","material":"una miscela di acqua e sabbia","page":138},"spell.disintegrate":{"name":"Disintegrazione","description":"L'incantatore lancia un raggio verde verso un bersaglio entro gittata che egli è in grado di vedere. Il bersaglio può essere una creatura, un oggetto non magico o una creazione di forza magica, come un muro creato da muro di forza.\\n\\nUna creatura bersagliata da questo incantesimo effettua un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d6 + 40 danni da forza. Se tali danni riducono i punti ferita del bersaglio a 0, la creatura, insieme a qualsiasi oggetto non magico indossi o trasporti, viene disintegrata in polvere grigia. Il bersaglio può essere rianimato solo da un incantesimo desiderio o resurrezione pura.\\n\\nQuesto incantesimo disintegra automaticamente un oggetto non magico di taglia Grande o inferiore, oppure una creazione di forza magica. Se il bersaglio è Enorme o superiore, questo incantesimo ne disintegra una parte pari a un cubo con spigolo di 3 metri.","higherLevels":"I danni aumentano di 3d6 per ogni slot di livello superiore al 6º.","material":"una calamita e della polvere","page":142},"spell.levitate":{"name":"Levitazione","description":"Una creatura o un oggetto a scelta dell'incantatore, situato entro gittata e che egli è in grado di vedere, si solleva verticalmente fino a 6 metri rimanendo sospeso per la durata dell'incantesimo. L'incantesimo può far levitare un oggetto che pesa fino a 250 kg. Una creatura non consenziente che supera un tiro salvezza su Costituzione non subisce l'effetto dell'incantesimo.\\n\\nIl bersaglio può muoversi soltanto spingendosi o aggrappandosi a un oggetto fisso o a una superficie entro portata (come per esempio una parete o un soffitto), che gli permetta di muoversi come se ne stesse scalando la superficie. Nel proprio turno, l'incantatore può variare l'altitudine del bersaglio per un massimo di 6 metri in ogni direzione. Se il bersaglio è l'incantatore stesso, può muoversi verso l'alto o verso il basso come parte del suo movimento. Altrimenti, l'incantatore può usare la sua azione di Magia per muovere il bersaglio, che deve rimanere entro gittata.\\n\\nIl bersaglio, se è ancora sospeso, al termine dell'incantesimo fluttua dolcemente fino a terra.","material":"una molla in metallo","page":161},"spell.gate":{"name":"Portale","description":"L'incantatore evoca un portale che collega uno spazio libero entro gittata che egli è in grado di vedere a un luogo preciso su un piano di esistenza differente. Il portale è un'apertura circolare, del diametro variabile tra 1,5 e 6 metri a scelta dell'incantatore e può essere orientato in qualsiasi direzione. Il portale permane per la durata dell'incantesimo e la sua destinazione è visibile attraverso di esso.\\n\\nIl portale ha un lato anteriore e un lato posteriore su ogni piano dove appare e i viaggi sono possibili solo attraversandolo dalla parte anteriore. Tutto ciò che lo attraversa è trasportato immediatamente sull'altro piano, apparendo nello spazio libero più vicino al portale.\\n\\nDivinità e altri sovrani planari possono impedire che i portali creati tramite questo incantesimo si aprano in loro presenza o nei loro domini.\\n\\nQuando lancia questo incantesimo, l'incantatore può pronunciare il nome di una creatura specifica (pseudonimi, titoli o soprannomi non funzionano). Se la creatura nominata si trova su un piano diverso da quello in cui si trova l'incantatore, il portale si apre nelle immediate vicinanze della creatura, trasportandola fino allo spazio libero più vicino sul lato del portale in cui si trova l'incantatore. L'incantatore non ottiene alcun potere speciale sulla creatura, che è libera di agire come il GM ritiene più appropriato: potrebbe andarsene, attaccarlo o aiutarlo.","material":"un diamante del valore di 5.000 mo o più","page":174},"spell.purify-food-and-drink":{"name":"Purificare cibo e bevande","areaDimensions":"Sfera del raggio di 1,5 metri","description":"L'incantatore rimuove veleno e marciume da cibi e bevande non magici situati in una sfera del raggio di 1,5 metri centrata su un punto entro gittata.","page":177},"spell.summon-dragon":{"name":"Richiama drago","description":"L'incantatore invoca uno spirito di drago, che si manifesta in uno spazio libero entro gittata che egli sia in grado di vedere e utilizza la scheda delle statistiche dello spirito draconico. La creatura scompare quando scende a 0 punti ferita o quando l'incantesimo termina ed è un alleato per il personaggio e i suoi alleati. In combattimento, la creatura ha lo stesso punteggio di iniziativa dell'incantatore, ma inizia il turno immediatamente dopo il suo, obbedendo ai suoi comandi verbali (nessuna azione richiesta da parte dell'incantatore). Se l'incantatore non pronuncia comandi verbali, la creatura compie l'azione di Schivata e usa il suo movimento per sottrarsi al pericolo.","higherLevels":"Usa il livello dello slot incantesimo relativo al livello dell'incantesimo nella scheda delle statistiche.","material":"un oggetto su cui è incisa l'immagine di un drago, del valore di 500 mo o più","page":180},"spell.heat-metal":{"name":"Riscaldare il metallo","description":"L'incantatore sceglie un oggetto lavorato in metallo, come un'arma in metallo o un'armatura di metallo media o pesante entro gittata che egli è in grado di vedere e la rende incandescente. Qualsiasi creatura a contatto fisico con l'oggetto subisce 2d8 danni da fuoco al momento del lancio dell'incantesimo. Fino al termine dell'incantesimo, l'incantatore può effettuare un'azione bonus in ognuno dei suoi turni successivi per infliggere di nuovo i danni se l'oggetto si trova entro gittata.\\n\\nSe una creatura sta stringendo o indossando l'oggetto e ne subisce i danni, deve superare un tiro salvezza su Costituzione o, se possibile, lasciar cadere l'oggetto. Se non lascia cadere l'oggetto, il bersaglio subisce svantaggio ai tiri per colpire e alle prove di caratteristica effettuati prima dell'inizio del turno successivo dell'incantatore.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 2º.","material":"un pezzo di ferro e una fiamma","page":181},"spell.storm-of-vengeance":{"name":"Tempesta di vendetta","areaDimensions":"Raggio di 90 metri","description":"Per la durata dell'incantesimo, l'incantatore genera una minacciosa nube temporalesca che si espande fino a una raggio di 90 metri centrata su un punto entro gittata. Ogni creatura che si trova sotto alla nube quando appare deve superare un tiro salvezza su Costituzione, altrimenti subirà 2d6 danni da tuono e sarà assordata per la durata dell'incantesimo.\\n\\nAll'inizio di ciascun turno successivo, la tempesta produce effetti diversi, come indicato sotto.\\n\\n**2º turno.** Cade della pioggia acida. Ogni creatura e ogni oggetto sotto la nube subisce 4d6 danni da acido.\\n\\n**3º turno.** L'incantatore invoca sei fulmini che scendono dalla nube e colpiscono sei creature o oggetti situati sotto di essa. Ogni bersaglio effettua un tiro salvezza su Destrezza, subendo 10d6 danni da fulmine in caso di fallimento, o la metà dei danni in caso di successo.\\n\\n**4º turno.** Cade della grandine. Ogni creatura sotto la nube subisce 2d6 danni contundenti.\\n\\n**Dal 5º al 10º turno.** L'area sotto la nube è attraversata da raffiche di vento e pioggia gelida, ogni creatura sotto di essa subisce 1d6 danni da freddo. Fino al termine dell'incantesimo, quest'area è considerata terreno difficile ed è pesantemente oscurata. È sferzata da forti venti e al suo interno è impossibile eseguire attacchi a distanza.","page":195},"spell.tree-stride":{"name":"Traslazione arborea","description":"L'incantatore ottiene la capacità di entrare in un albero e muoversi al suo interno fino ad arrivare a un altro albero dello stesso tipo posto entro 150 metri. Entrambi gli alberi devono essere vivi e di taglia pari o superiore a quella dell'incantatore, che deve usare 1,5 metri di movimento per entrare in uno di essi. L'incantatore apprende immediatamente l'ubicazione di tutti gli altri alberi dello stesso tipo entro 150 metri e, come parte del movimento usato per entrare nell'albero, può scegliere se passare in uno di quegli alberi o riemergere da quello in cui si trova. L'incantatore ricompare in un punto a sua scelta entro 1,5 metri dall'albero di destinazione, usando ulteriori 1,5 metri di movimento. Se non gli rimane più alcun movimento, ricompare entro 1,5 metri dall'albero in cui è entrato.\\n\\nQuest'abilità di trasporto è utilizzabile una sola volta per turno. Inoltre, l'incantatore deve concludere ogni suo turno fuori dall'albero.","page":197},"spell.beacon-of-hope":{"name":"Faro di speranza","description":"L'incantatore sceglie un qualsiasi numero di creature entro gittata. Per la durata dell'incantesimo, ogni bersaglio dispone di vantaggio ai tiri salvezza su Saggezza, ai tiri salvezza contro morte e recupera il numero massimo di punti ferita possibile da qualsiasi guarigione.","page":147},"spell.revivify":{"name":"Rinascita","description":"L'incantatore tocca una creatura morta nell'ultimo minuto, la quale ritorna in vita con 1 punto ferita. Questo incantesimo non può riportare in vita una creatura morta di vecchiaia e non ripristina le eventuali parti del corpo mancanti.","material":"un diamante del valore di 300 mo o più, che l'incantesimo consuma","page":181},"spell.continual-flame":{"name":"Fiamma perenne","description":"Una fiamma si sprigiona da un oggetto toccato dall'incantatore. L'effetto proietta luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri. L'effetto è quello di una fiamma comune, ma non genera calore e non utilizza combustibile. La fiamma può essere coperta o nascosta, ma non soffocata o estinta.","material":"polvere di rubino del valore di 50 mo o più, che l'incantesimo consuma","page":148},"spell.befuddlement":{"name":"Disorientare","description":"L'incantatore assale la mente di una creatura entro gittata che egli è in grado di vedere. Il bersaglio effettua un tiro salvezza su Intelligenza.\\n\\nSe lo fallisce, il bersaglio subisce 10d12 danni psichici e non può lanciare incantesimi o eseguire l'azione di Magia. Alla fine di ogni 30 giorni, il bersaglio ripete il tiro salvezza e, se lo supera, l'effetto svanisce. L'effetto può essere dissolto anche tramite gli incantesimi ristorare superiore, guarigione o desiderio.\\n\\nIn caso di successo, subisce soltanto la metà di quei danni.","material":"un portachiavi senza chiavi","page":142},"spell.conjure-animals":{"name":"Evoca animali","description":"L'incantatore evoca degli spiriti della natura che appaiono come un branco Grande di animali spettrali e intangibili in uno spazio libero entro gittata che l'incantatore è in grado di vedere. Il branco permane per la durata dell'incantesimo e l'incantatore può scegliere la forma animale assunta dagli spiriti, per esempio lupi, serpenti o uccelli.\\n\\nMentre si trova entro 1,5 metri dal branco, l'incantatore dispone di vantaggio ai tiri salvezza su Forza e, quando si muove nel suo turno, può spostare anche il branco fino a 9 metri in uno spazio libero che è in grado di vedere.\\n\\nOgni volta che il branco si muove entro 3 metri da una creatura che l'incantatore è in grado di vedere e ogni volta che una creatura che l'incantatore è in grado di vedere entra in uno spazio entro 3 metri dal branco o vi termina il suo turno, l'incantatore può costringerla a effettuare un tiro salvezza su Destrezza. In caso di fallimento, subisce 3d10 danni taglienti. Una creatura effettua questo tiro salvezza solo una volta per turno.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 3º.","page":145},"spell.ice-knife":{"name":"Coltello di ghiaccio","description":"L'incantatore crea un frammento di ghiaccio e lo scaglia contro una creatura entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d10 danni perforanti. Che colpisca o manchi il bersaglio, il frammento poi esplode.\\n\\nIl bersaglio e ogni creatura entro 1,5 metri dal punto in cui il ghiaccio è esploso devono superare un tiro salvezza su Destrezza, altrimenti subiscono 2d6 danni da freddo.","higherLevels":"I danni da freddo aumentano di 1d6 per ogni slot di livello superiore al 1º.","material":"una goccia d'acqua o un frammento di ghiaccio","page":133},"spell.guiding-bolt":{"name":"Dardo tracciante","description":"L'incantatore scaglia un lampo di luce verso una creatura entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, esso subisce 4d6 danni radiosi, e il successivo tiro per colpire effettuato contro il bersaglio prima del termine del turno successivo dell'incantatore dispone di vantaggio.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 1º.","page":140},"spell.dispel-magic":{"name":"Dissolvi magie","description":"L'incantatore sceglie una creatura, un oggetto o un effetto magico situato entro gittata. Ogni incantesimo di 3º livello o inferiore presente sul bersaglio termina. Per ogni incantesimo di 4º livello o superiore presente sul bersaglio, l'incantatore effettua una prova di caratteristica usando la propria caratteristica da incantatore (CD 10 più il livello di quell'incantesimo). Se la prova viene superata, l'incantesimo termina.","higherLevels":"L'incantatore termina automaticamente un incantesimo sul bersaglio se il livello di quell'incantesimo è pari o inferiore al livello dello slot incantesimo usato dall'incantatore.","page":142},"spell.dominate-beast":{"name":"Dominare bestie","description":"Una bestia entro gittata e che l'incantatore è in grado di vedere deve superare un tiro salvezza su Saggezza, altrimenti diventa affascinata per la durata dell'incantesimo. Il bersaglio dispone di vantaggio al tiro salvezza se l'incantatore o i suoi alleati stanno combattendo contro di essa. Ogni volta che il bersaglio subisce danni, ripete il tiro salvezza; se lo supera, l'effetto svanisce.\\n\\nL'incantatore ha un legame telepatico con il bersaglio affascinato mentre i due si trovano sullo stesso piano di esistenza. Nel proprio turno, l'incantatore può utilizzare questo legame per impartire comandi al bersaglio (nessuna azione richiesta), come ad esempio \\"attacca quella creatura\\", \\"spostati lì\\", o \\"recupera quell'oggetto\\". Il bersaglio fa del suo meglio per obbedire nel suo turno. Se porta a termine un ordine e non riceve ulteriori istruzioni dall'incantatore, agisce e si muove a suo piacimento, concentrandosi sulla propria incolumità.\\n\\nL'incantatore può comandare al bersaglio di effettuare una reazione, ma per farlo dovrà utilizzare la propria reazione.","higherLevels":"La concentrazione dell'incantatore può durare più a lungo utilizzando uno slot incantesimo di 5º livello (fino a 10 minuti), di 6º livello (fino a 1 ora) o di 7º livello o superiore (fino a 8 ore).","page":143},"spell.dominate-person":{"name":"Dominare persone","description":"Un umanoide entro gittata e che l'incantatore è in grado di vedere deve superare un tiro salvezza su Saggezza, altrimenti diventa affascinato per la durata dell'incantesimo. Il bersaglio dispone di vantaggio al tiro salvezza se l'incantatore o i suoi alleati stanno combattendo contro di essa. Ogni volta che il bersaglio subisce danni, ripete il tiro salvezza; se lo supera, l'effetto svanisce.\\n\\nL'incantatore ha un legame telepatico con il bersaglio affascinato mentre i due si trovano sullo stesso piano di esistenza. Nel proprio turno, l'incantatore può utilizzare questo legame per impartire comandi al bersaglio (nessuna azione richiesta), come ad esempio \\"attacca quella creatura\\", \\"spostati lì\\", o \\"recupera quell'oggetto\\". Il bersaglio fa del suo meglio per obbedire nel suo turno. Se porta a termine un ordine e non riceve ulteriori istruzioni dall'incantatore, agisce e si muove a suo piacimento, concentrandosi sulla propria incolumità.\\n\\nL'incantatore può comandare al bersaglio di effettuare una reazione, ma per farlo dovrà utilizzare la propria reazione.","higherLevels":"La concentrazione dell'incantatore può durare più a lungo utilizzando uno slot incantesimo di 6º livello (fino a 10 minuti), di 7º livello (fino a 1 ora) o di 8º livello o superiore (fino a 8 ore).","page":143},"spell.mass-heal":{"name":"Guarigione di massa","description":"Un'ondata di energia curativa si sprigiona dall'incantatore, investendo le creature intorno a lui. In questo modo, ripristina fino a 700 punti ferita, ripartendoli come desidera tra un qualsiasi numero di creature entro gittata che egli è in grado di vedere. Le creature guarite da questo incantesimo vengono inoltre curate dalle condizioni accecato, assordato e avvelenato.","page":153},"spell.arcane-hand":{"name":"Mano arcana","description":"L'incantatore crea una mano Grande di energia magica luccicante in uno spazio libero entro gittata che è in grado di vedere. La mano permane per la durata dell'incantesimo e si muove al comando dell'incantatore, imitando i movimenti della sua mano.\\n\\nLa mano è un oggetto che possiede CA 20 e una quantità di punti ferita pari ai punti ferita massimi dell'incantatore; se scende a 0 punti ferita, l'incantesimo termina. La mano non occupa spazio.\\n\\nQuando l'incantatore lancia l'incantesimo come azione bonus nei suoi turni successivi, può muovere la mano per un massimo di 18 metri e causare uno dei seguenti effetti:\\n\\n- **Mano interposta.** La mano conferisce all'incantatore mezza copertura contro gli attacchi e altri effetti che hanno origine dal suo spazio o che la attraversano. Inoltre, il suo spazio conta come terreno difficile per i nemici.\\n- **Mano possente.** La mano tenta di spingere una creatura di taglia Enorme o inferiore situata entro 1,5 metri da essa: Il bersaglio deve superare un tiro salvezza su Forza, altrimenti viene spinto dalla mano fino a una distanza pari a 1,5 metri, più un numero di metri pari a cinque volte il modificatore di caratteristica da incantatore. La mano si muove insieme al bersaglio, rimanendo entro 1,5 metri da esso.\\n- **Mano stritolatrice.** La mano tenta di afferrare una creatura di taglia Enorme o inferiore situata entro 1,5 metri da essa. Il bersaglio deve superare un tiro salvezza su Destrezza, altrimenti viene afferrato; la CD per sfuggire alla presa è pari alla CD del tiro salvezza sull'incantesimo dell'incantatore. Mentre la mano afferra il bersaglio, l'incantatore può effettuare un'azione bonus per ordinarle di stritolarlo, infliggendogli danni contundenti pari a 4d6 più il modificatore di caratteristica da incantatore dell'incantatore.\\n- **Pugno serrato.** La mano colpisce un bersaglio che si trova entro 1,5 metri da essa. L'incantatore effettua un attacco con incantesimo in mischia. Se il colpo va a segno, il bersaglio subisce 5d8 danni da forza.","higherLevels":"I danni del pugno serrato aumentano di 2d8 e quelli della mano stritolatrice di 2d6 per ogni slot di livello superiore al 5º.","material":"un guscio d'uovo e un guanto","page":163},"spell.modify-memory":{"name":"Modificare memoria","description":"L'incantatore tenta di alterare i ricordi di un'altra creatura entro gittata che egli è in grado di vedere, la quale effettua un tiro salvezza su Saggezza. Se l'incantatore sta combattendo contro la creatura, essa dispone di vantaggio al tiro salvezza. Se il bersaglio fallisce il tiro, diventa affascinato per la durata dell'incantesimo. Mentre è affascinato, il bersaglio è anche incapacitato e inconsapevole di ciò che gli accade intorno, ma può ancora udire l'incantatore. Se subisce danni o è bersagliato da un altro incantesimo, questo incantesimo termina e nessun ricordo viene modificato.\\n\\nFinché questo ammaliamento permane, l'incantatore può alterare il ricordo che il bersaglio ha di un evento avvenuto entro le 24 ore precedenti e della durata massima di 10 minuti. Può eliminare permanentemente tutti i ricordi dell'evento, consentire al bersaglio di ricordarlo con estrema chiarezza, alterare il ricordo di alcuni dettagli o creare il ricordo di un evento diverso.\\n\\nPer descrivere in che modo i ricordi vengono alterati, l'incantatore deve parlare con il bersaglio, che deve quindi comprendere il linguaggio usato affinché i ricordi modificati si radichino nella sua mente. La sua mente poi riempie le eventuali lacune presenti nella descrizione dell'incantatore. Se l'incantesimo termina prima che l'incantatore abbia finito di descrivere i ricordi modificati, la memoria della creatura non subisce alcuna alterazione. In caso contrario, i ricordi modificati si radicano nella sua mente e l'incantesimo termina.\\n\\nUn ricordo modificato non influenza necessariamente il comportamento di una creatura, in particolare se contraddice le sue inclinazioni naturali, il suo allineamento o le sue convinzioni. Un ricordo modificato illogicamente, come per esempio il falso ricordo di quanto la creatura ami nuotare nell'acido, viene ignorato e considerato come un brutto sogno. Il GM potrebbe ritenere che un ricordo modificato sia troppo insensato per influenzare la creatura.\\n\\nUn incantesimo rimuovi maledizione o ristorare superiore lanciato su un bersaglio ripristina i veri ricordi della creatura.","higherLevels":"L'incantatore può alterare i ricordi del bersaglio relativi a un evento risalente fino a 7 giorni prima (slot incantesimo di 6º livello), 30 giorni prima (slot incantesimo di 7º livello), 365 giorni prima (slot incantesimo di 8º livello) o a un qualsiasi momento del suo passato (slot incantesimo di 9º livello).","page":165},"spell.protection-from-evil-and-good":{"name":"Protezione dal bene e dal male","description":"Fino al termine dell'incantesimo, una creatura consenziente toccata dall'incantatore è protetta da certi tipi di creature: aberrazioni, celestiali, elementali, folletti, immondi o non morti. La protezione garantisce diversi vantaggi. Le creature contro cui è attiva subiscono svantaggio ai tiri per colpire indirizzati contro il bersaglio; inoltre, il bersaglio non può essere affascinato, spaventato o posseduto da creature analoghe. Se il bersaglio è già affascinato, spaventato o posseduto da una tale creatura, dispone di vantaggio a qualsiasi nuovo tiro salvezza contro il relativo effetto.","material":"un'ampolla di acqua santa del valore di 25 mo o più, che l'incantesimo consuma","page":176},"spell.scorching-ray":{"name":"Raggio rovente","description":"L'incantatore lancia tre raggi di fuoco contro uno o più bersagli entro gittata. Con questo incantesimo, l'incantatore effettua un attacco a distanza per ogni raggio. Se il colpo va a segno, il bersaglio subisce 2d6 danni da fuoco.","higherLevels":"L'incantatore crea un raggio aggiuntivo per ogni slot di livello superiore al 2º.","page":178},"spell.arcane-lock":{"name":"Serratura arcana","description":"Toccando una porta, una finestra, un cancello, un contenitore o una botola, l'oggetto viene sigillato magicamente per la durata dell'incantesimo. L'oggetto non può essere aperto tramite mezzi non magici. L'incantatore e le creature da lui designate al momento del lancio dell'incantesimo possono aprire e chiudere l'oggetto nonostante la serratura. L'incantatore può anche stabilire una parola d'ordine che, una volta pronunciata entro 1,5 metri dall'oggetto, lo mantiene aperto per 1 minuto.","material":"polvere d'oro del valore di 25 mo o più, che viene consumata dall'incantesimo","page":187},"spell.thaumaturgy":{"name":"Taumaturgia","description":"L'incantatore genera una meraviglia minore entro gittata, oltre a uno degli effetti elencati di seguito. Se l'incantatore lancia questo incantesimo più volte, può tenere attivi contemporaneamente fino a tre dei suoi effetti dalla durata di 1 minuto.\\n\\n**Mano invisibile.** L'incantatore fa in modo che una porta o una finestra non chiusa a chiave si spalanchi o si chiuda di colpo da sola.\\n\\n**Occhi alterati.** L'incantatore altera l'aspetto dei suoi occhi per 1 minuto.\\n\\n**Suono spettrale.** L'incantatore crea un suono improvviso che ha origine da un punto entro gittata a sua scelta, come un rombo di tuono, il verso di un corvo o un mormorio sinistro.\\n\\n**Tremiti.** L'incantatore genera un tremito innocuo sul terreno per 1 minuto.\\n\\n**Trucchetto col fuoco.** L'incantatore fa in modo che una fiamma tremi, si intensifichi, si affievolisca o cambi colore per 1 minuto.\\n\\n**Voce tonante.** La voce dell'incantatore rimbomba con potenza tre volte superiore rispetto al normale per 1 minuto. Per la durata dell'incantesimo, dispone di vantaggio alle prove di Carisma (Intimidire).","page":193},"spell.false-life":{"name":"Vita falsata","description":"L'incantatore ottiene 2d4 + 4 punti ferita temporanei.","higherLevels":"L'incantatore ottiene 5 punti ferita temporanei aggiuntivi per ogni slot di livello superiore al 1º.","material":"una goccia di alcol","page":201},"spell.animal-friendship":{"name":"Amicizia con gli animali","description":"L'incantatore sceglie come bersaglio una bestia entro gittata che egli è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti rimane affascinato per la durata dell'incantesimo. Se l'incantatore o uno dei suoi alleati infligge danni al bersaglio, l'incantesimo termina.","higherLevels":"L'incantatore può scegliere come bersaglio una bestia aggiuntiva per ogni slot di livello superiore al 1º.","material":"un boccone di cibo","page":123},"spell.charm-monster":{"name":"Charme sui mostri","description":"Una creatura entro gittata che l'incantatore è in grado di vedere effettua un tiro salvezza su Saggezza, disponendo di vantaggio se l'incantatore o i suoi alleati stanno combattendo contro di essa. In caso di fallimento, il bersaglio è affascinato fino al termine dell'incantesimo o finché non gli vengono inflitti danni dall'incantatore o i suoi alleati. La creatura affascinata è amichevole nei confronti dell'incantatore. Al termine dell'incantesimo, il bersaglio capirà di essere stato affascinato dall'incantatore.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º.","page":132},"spell.compulsion":{"name":"Compulsione","description":"Ogni creatura a scelta dell'incantatore, entro gittata e che egli è in grado di vedere, deve superare un tiro salvezza su Saggezza, altrimenti diventa affascinata fino al termine dell'incantesimo.\\n\\nPer la durata dell'incantesimo, l'incantatore può effettuare un'azione bonus per scegliere una direzione orizzontale rispetto a lui. Ogni bersaglio affascinato deve usare la maggior parte possibile del suo movimento per muoversi in quella direzione nel suo turno successivo, percorrendo la via più sicura. Dopo essersi mosso in questo modo, un bersaglio ripete il tiro salvezza e, se lo supera, termina l'incantesimo su di sé.","page":134},"spell.aid":{"name":"Aiuto","description":"L'incantatore sceglie fino a tre creature entro gittata. I punti ferita massimi e i punti ferita attuali di ogni bersaglio aumentano di 5 per la durata dell'incantesimo.","higherLevels":"I punti ferita di ciascun bersaglio aumentano di 5 per ogni slot incantesimo di livello superiore al 2º.","material":"una striscia di tessuto bianco","page":121},"spell.shield-of-faith":{"name":"Scudo della fede","description":"Un campo di energia scintillante avvolge una creatura scelta dall'incantatore entro gittata, conferendole un bonus di +2 alla CA per la durata dell'incantesimo.","material":"una pergamena con una preghiera","page":186},"spell.conjure-minor-elementals":{"name":"Evoca elementali minori","areaDimensions":"Emanazione di 4,5 metri","description":"L'incantatore evoca degli spiriti dai Piani Elementali che gli fluttuano attorno in un'emanazione di 4,5 metri per la durata dell'incantesimo. Fino al termine dell'incantesimo, ogni attacco effettuato dall'incantatore infligge 2d8 danni extra quando colpisce una creatura nell'emanazione. I danni inflitti sono da acido, freddo, fuoco o fulmine (a scelta dell'incantatore quando effettua l'attacco).\\n\\nInoltre, il terreno all'interno dell'emanazione diventa terreno difficile per i nemici.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 4º.","page":146},"spell.invisibility":{"name":"Invisibilità","description":"Una creatura toccata dall'incantatore diventa invisibile fino al termine dell'incantesimo. L'incantesimo termina immediatamente quando il bersaglio effettua un tiro per colpire, infligge danni o lancia un incantesimo.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 2º.","material":"un ciglio in uno strato di resina","page":159},"spell.dancing-lights":{"name":"Luci danzanti","description":"L'incantatore crea fino a quattro luci delle dimensioni di una torcia, facendole apparire come lanterne, torce o globi luminosi che fluttuano per la durata dell'incantesimo entro la sua gittata. In alternativa, l'incantatore può fondere le quattro luci in un'unica forma luminosa di taglia Media di aspetto simile a quello umano. Qualunque sia la forma scelta, ogni luce proietta luce fioca entro un raggio di 3 metri.\\n\\nCome azione bonus, l'incantatore può muovere le luci per un massimo di 18 metri fino a un punto entro gittata. Ogni luce deve trovarsi entro 6 metri da un'altra luce creata da questo incantesimo. Se una delle luci supera la gittata dell'incantesimo, svanisce.","material":"un frammento di fosforo","page":163},"spell.nondetection":{"name":"Anti-individuazione","description":"Per la durata dell'incantesimo, l'incantatore nasconde agli incantesimi di divinazione un bersaglio da lui toccato. Il bersaglio può essere una creatura consenziente, oppure un luogo o un oggetto non più grande di 3 metri in qualsiasi dimensione. Il bersaglio non può essere preso di mira da alcun incantesimo di divinazione né percepito da sensori di scrutamento magico.","material":"un pizzico di polvere di diamante del valore di 25 mo o più, che l'incantesimo consuma","page":125},"spell.goodberry":{"name":"Bacche benefiche","description":"Per la durata dell'incantesimo, nella mano dell'incantatore appaiono dieci bacche infuse di magia. Una creatura può effettuare un'azione bonus per mangiare una bacca, recuperando così 1 punto ferita e ottenendo nutrimento sufficiente per una giornata intera.\\n\\nLe bacche non mangiate scompaiono al termine dell'incantesimo.","material":"un rametto di vischio","page":127},"spell.commune":{"name":"Comunione","description":"L'incantatore entra in contatto con una divinità o un emissario divino e, prima della fine dell'incantesimo, pone fino a tre domande a cui è possibile rispondere con sì o no. L'incantatore riceve una risposta corretta per ogni domanda.\\n\\nGli esseri divini non sono necessariamente onniscienti, quindi l'incantatore potrebbe ricevere \\"ignoto\\" come risposta se una domanda riguarda informazioni che vanno oltre le loro conoscenze. Nel caso in cui una risposta di una parola sola possa rivelarsi fuorviante o contraria agli interessi della divinità, il GM può fornire come risposta una breve frase.\\n\\nSe l'incantatore lancia l'incantesimo più volte prima di completare un riposo lungo, esiste una probabilità cumulativa del 25% di non ottenere risposta per ogni lancio dopo il primo.","material":"incenso","page":134},"spell.divination":{"name":"Divinazione","description":"Questo incantesimo mette in contatto l'incantatore con una divinità o con un servitore della divinità. L'incantatore pone una sola domanda relativa a uno specifico obiettivo, evento o attività che si verificherà entro 7 giorni. Il GM fornisce una risposta onesta, che può essere una breve frase o una rima enigmatica. L'incantesimo non tiene conto delle circostanze che potrebbero modificare la risposta, come il lancio di altri incantesimi.\\n\\nSe l'incantatore lancia l'incantesimo più volte prima di completare un riposo lungo, esiste una probabilità cumulativa del 25% di non ottenere risposta per ogni lancio dopo il primo.","material":"incenso del valore di 25 mo o più, che l'incantesimo consuma","page":143},"spell.guardian-of-faith":{"name":"Guardiano della fede","description":"Per la durata dell'incantesimo, un guardiano spettrale di taglia Grande compare e fluttua in uno spazio libero entro gittata che l'incantatore è in grado di vedere. Il guardiano occupa quello spazio ed è invulnerabile: assume inoltre una forma appropriata alla divinità o al pantheon dell'incantatore.\\n\\nQualsiasi nemico si muova in uno spazio entro 3 metri dal guardiano per la prima volta in un turno o che inizi il proprio turno lì, effettua un tiro salvezza su Destrezza. In caso di fallimento, subisce 20 danni radiosi o la metà dei danni in caso di successo. Il guardiano svanisce quando ha inflitto un totale di 60 danni.","page":153},"spell.entangle":{"name":"Intralciare","areaDimensions":"Quadrato di 6 metri per lato","description":"Dei vegetali afferranti spuntano dal terreno in un quadrato di 6 metri per lato in un punto situato entro gittata. Per la durata dell'incantesimo, i vegetali trasformano quell'area in un terreno difficile. I vegetali scompaiono al termine dell'incantesimo.\\n\\nQuando viene lanciato l'incantesimo, ogni creatura diversa dall'incantatore all'interno dell'area deve superare un tiro salvezza su Forza, altrimenti è trattenuta fino al termine dell'incantesimo. Le creature trattenute possono usare un'azione per effettuare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo. In caso di successo, si liberano dai vegetali afferranti e non sono più trattenute.","page":158},"spell.maze":{"name":"Labirinto","description":"L'incantatore bandisce una creatura entro gittata che egli è in grado di vedere in un semipiano labirintico. Il bersaglio rimane laggiù per la durata dell'incantesimo o finché non fugge dal labirinto.\\n\\nIl bersaglio può effettuare un'azione di Studio per provare a fuggire. Quando questo avviene, effettua una prova di Intelligenza (Indagare) con CD 20. In caso di successo, il bersaglio fugge e l'incantesimo termina.\\n\\nAl termine dell'incantesimo, il bersaglio riappare nello spazio in cui si trovava prima del lancio o, se è occupato, nello spazio libero più vicino.","page":160},"spell.locate-animals-or-plants":{"name":"Localizza animali o vegetali","description":"L'incantatore descrive o nomina un tipo specifico di bestia o creatura vegetale, oppure un vegetale non magico. Apprende la direzione e la distanza fino alla creatura o al vegetale di quel tipo più vicino entro 7,5 chilometri, se ne è presente almeno uno.","material":"un ciuffo di peli di un segugio","page":161},"spell.wall-of-fire":{"name":"Muro di fuoco","description":"L'incantatore crea un muro di fuoco su una superficie solida entro gittata. Il muro può essere lungo fino a 18 metri, alto 6 metri e spesso 30 cm, oppure essere un muro circolare del diametro massimo di 6 metri, alto 6 metri e spesso 30 cm. Il muro è opaco e permane per la durata dell'incantesimo.\\n\\nQuando compare, ogni creatura al suo interno effettua un tiro salvezza su Destrezza, subendo 5d8 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nUn lato del muro, scelto dall'incantatore al momento del lancio dell'incantesimo, infligge 5d8 danni da fuoco a ogni creatura che termina il proprio turno entro 3 metri da quel lato o all'interno del muro. Una creatura subisce gli stessi danni quando lo attraversa per la prima volta in un turno o vi termina il suo turno. L'altro lato del muro non infligge danni.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 4º.","material":"un pezzo di carbone","page":167},"spell.fog-cloud":{"name":"Nube di nebbia","areaDimensions":"Sfera del raggio di 6 metri","description":"L'incantatore genera una sfera di nebbia del raggio di 6 metri centrata su un punto entro gittata. La sfera è pesantemente oscurata e permane la durata dell'incantesimo o finché un vento forte (come quello creato da folata di vento) non la disperde.","higherLevels":"Il raggio della sfera di nebbia aumenta di 6 metri per ogni slot di livello superiore al 1º.","page":169},"spell.arcane-eye":{"name":"Occhio arcano","description":"L'incantatore crea un occhio invisibile e invulnerabile che fluttua per la durata dell'incantesimo entro la sua gittata. L'incantatore riceve informazioni visive dall'occhio, che può vedere in ogni direzione e che è inoltre dotato di scurovisione fino a 9 metri.\\n\\nCome azione bonus, l'incantatore può muovere l'occhio per un massimo di 9 metri in ogni direzione. Una barriera solida blocca il movimento dell'occhio, che tuttavia può passare attraverso un'apertura dal diametro minimo di 2,5 centimetri.","material":"un ciuffo di peli di pipistrello","page":170},"spell.darkness":{"name":"Oscurità","description":"Per la durata dell'incantesimo, un'oscurità magica si estende da un punto entro gittata e riempie una sfera del raggio di 4,5 metri. Una creatura dotata di scurovisione non è in grado di vedere attraverso di essa e la luce non magica non può illuminarla.\\n\\nIn alternativa, l'incantatore lancia l'incantesimo su un oggetto che non sia indossato o trasportato, facendo sì che l'oscurità riempia un'emanazione di 4,5 metri di cui l'oggetto è il punto di origine. Coprire l'oggetto con qualcosa di opaco, come una ciotola o un elmo, blocca l'oscurità.\\n\\nSe una parte dell'area di questo incantesimo si sovrappone a un'area di luce intensa o luce fioca creata da un incantesimo di 2º livello o inferiore, l'incantesimo che ha creato la luce viene dissolto.","material":"pelo di pipistrello e un pezzo di carbone","page":170},"spell.demiplane":{"name":"Semipiano","description":"L'incantatore crea una porta d'ombra di taglia Media su una superficie piatta e solida entro gittata che egli è in grado di vedere. La porta può essere aperta e chiusa, e conduce verso un semipiano che appare come una stanza vuota di legno o pietra (a scelta dell'incantatore) ampia 9 metri in ogni dimensione.\\n\\nAl termine dell'incantesimo, la porta scompare e gli oggetti al suo interno rimangono nel semipiano. Ciò si applica anche alle creature, a meno che non scelgano di venire spinte attraverso la porta mentre questa svanisce, atterrando prone sugli spazi liberi più vicini allo spazio occupato precedentemente dalla porta.\\n\\nOgni volta che lancia questo incantesimo, l'incantatore può creare un nuovo semipiano o collegare la porta d'ombra a un semipiano da lui creato con un lancio precedente di questo incantesimo. Inoltre, se l'incantatore conosce la natura e i contenuti di un semipiano creato da un'altra creatura lanciando questo incantesimo, può fare invece in modo che la porta d'ombra si colleghi a quel semipiano.","page":187},"spell.color-spray":{"name":"Spruzzo colorato","areaDimensions":"Cono di 4,5 metri","description":"L'incantatore lancia un lampo abbagliante di luce multicolore. Ogni creatura entro un cono di 4,5 metri originato dall'incantatore deve superare un tiro salvezza su Costituzione, altrimenti è accecata fino al termine del turno successivo dell'incantatore.","material":"un pizzico di sabbia colorata","page":191},"spell.transport-via-plants":{"name":"Trasporto vegetale","description":"Questo incantesimo crea un legame magico tra un vegetale inanimato di taglia Grande o superiore situato entro gittata e un altro vegetale, situato a qualsiasi distanza sullo stesso piano di esistenza. L'incantatore deve aver visto o toccato il vegetale di destinazione almeno una volta in precedenza. Per la durata dell'incantesimo, qualsiasi creatura può entrare nel vegetale bersaglio e uscire da quello di destinazione usando 1,5 metri di movimento.","page":197},"spell.death-ward":{"name":"Interdizione alla morte","description":"L'incantatore tocca una creatura e le concede una misura di protezione dalla morte. La prima volta che il bersaglio scende a 0 punti ferita prima del termine dell'incantesimo, scende invece a 1 punto ferita e l'incantesimo termina.\\n\\nSe l'incantesimo è ancora attivo quando il bersaglio è soggetto a un effetto che ne provocherebbe la morte istantanea senza infliggere danni, quell'effetto viene annullato e l'incantesimo termina.","page":158},"spell.bestow-curse":{"name":"Scagliare maledizione","description":"L'incantatore tocca una creatura che deve superare un tiro salvezza su Saggezza, altrimenti verrà maledetta per la durata dell'incantesimo. Finché la maledizione non svanisce, il bersaglio subisce uno dei seguenti effetti a scelta:\\n\\n- L'incantatore sceglie una caratteristica. Il bersaglio subisce svantaggio alle prove di caratteristica e ai tiri salvezza effettuati con quella caratteristica.\\n- Il bersaglio subisce svantaggio ai tiri per colpire contro l'incantatore.\\n- In combattimento, il bersaglio deve superare un tiro salvezza su Saggezza all'inizio di ogni suo turno, altrimenti in quel turno è costretto a effettuare l'azione Schivata.\\n- Se l'incantatore infligge danni al bersaglio con un tiro per colpire o un incantesimo, il bersaglio subisce 1d8 danni necrotici extra.","higherLevels":"Se l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4º livello, può mantenere la concentrazione su di esso fino a un massimo di 10 minuti. Se usa uno slot incantesimo di 5º livello o superiore, l'incantesimo non richiede concentrazione e la durata diventa di 8 ore (slot di 5º e 6º livello) o 24 ore (slot di 7º o 8º livello). Se usa uno slot incantesimo di 9º livello, l'incantesimo dura finché non viene dissolto.","page":184},"spell.fire-storm":{"name":"Tempesta di fuoco","areaDimensions":"Dieci cubi con spigolo di 3 metri","description":"Una tempesta di fuoco compare in un luogo entro gittata. L'area della tempesta è composta da dieci cubi con spigolo di 3 metri, che l'incantatore può disporre come desidera. Ogni cubo deve essere contiguo ad almeno un altro cubo. Ogni creatura nell'area effettua un tiro salvezza su Destrezza; se lo fallisce, subisce 7d10 danni da fuoco, mentre se lo supera subisce la metà dei danni.\\n\\nGli oggetti infiammabili nell'area che non sono indossati o trasportati iniziano a bruciare.","page":195},"spell.moonbeam":{"name":"Bagliore lunare","areaDimensions":"Cilindro del raggio di 1,5 metri e dell'altezza di 12 metri","description":"Un bagliore argentato di luce pallida forma un cilindro del raggio di 1,5 metri e dell'altezza di 12 metri centrato su un punto entro gittata. Fino al termine dell'incantesimo, il cilindro è pervaso da luce fioca e l'incantatore può effettuare un'azione di Magia nei turni successivi per spostare il cilindro fino a 18 metri.\\n\\nQuando appare il cilindro, ogni creatura al suo interno effettua un tiro salvezza su Costituzione. In caso di fallimento, una creatura subisce 2d10 danni radiosi e, se la creatura è in forma mutata (ad esempio, come conseguenza all'incantesimo metamorfosi), torna alla sua forma naturale e non può trasformarsi finché non esce dal cilindro. In caso di successo, subisce soltanto la metà di quei danni. Una creatura effettua questo tiro salvezza anche quando l'area dell'incantesimo si muove nel suo spazio e quando la creatura entra nell'area dell'incantesimo o vi termina il suo turno. Una creatura effettua questo tiro salvezza solo una volta per turno.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 2º.","material":"una foglia di un vitigno legnoso","page":127},"spell.heroism":{"name":"Eroismo","description":"Una creatura consenziente toccata dall'incantatore è animata da grande coraggio. Fino al termine dell'incantesimo, la creatura è immune alla condizione spaventato e all'inizio di ogni suo turno ottiene una quantità di punti ferita temporanei pari al modificatore di caratteristica da incantatore dell'incantatore.","page":144,"higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º."},"spell.poison-spray":{"name":"Spruzzo velenoso","description":"L'incantatore spruzza una nebbia tossica contro una creatura entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d12 danni da veleno.","higherLevels":"I danni aumentano di 1d12 quando l'incantatore raggiunge il 5º livello (2d12), l'11º livello (3d12) e il 17º livello (4d12).","page":192},"spell.longstrider":{"name":"Passo veloce","description":"L'incantatore tocca una creatura, la cui velocità aumenta di 3 metri fino al termine dell'incantesimo.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","material":"un pizzico di terriccio","page":173},"spell.jump":{"name":"Salto","description":"L'incantatore tocca una creatura consenziente. La creatura, in ogni suo turno fino al termine dell'incantesimo, può saltare fino a 9 metri, usando 3 metri di movimento.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","material":"la zampa posteriore di una cavalletta","page":182},"spell.contingency":{"name":"Contingenza","description":"L'incantatore sceglie un incantesimo di livello pari o inferiore a 5 che sia in grado di lanciare, che abbia un tempo di lancio di un'azione e che possa avere come bersaglio l'incantatore stesso. Lancia l'incantesimo, chiamato incantesimo contingente, come parte del lancio di contingenza, consumando gli slot incantesimo per entrambi. L'incantesimo contingente, tuttavia, non ha effetto finché non si verificano determinati inneschi che l'incantatore descrive nel momento in cui lancia i due incantesimi. Per esempio, un lancio di contingenza con respirare sott'acqua potrebbe stabilire che respirare sott'acqua avrà effetto quando l'incantatore sarà sommerso nell'acqua o in un liquido simile.\\n\\nChe l'incantatore lo desideri o meno, l'incantesimo contingente ha effetto nel momento in cui gli inneschi vengono soddisfatti per la prima volta, poi contingenza termina.\\n\\nL'incantesimo contingente ha effetto solamente sull'incantatore, nonostante normalmente possa essere lanciato su altri bersagli. L'incantatore può utilizzare un solo incantesimo contingenza alla volta. Se l'incantatore lancia nuovamente questo incantesimo, l'effetto di un altro incantesimo contingenza su di sé termina. Inoltre, contingenza termina qualora la sua componente materiale non si trovi sulla persona dell'incantatore.","material":"una statuetta dell'incantatore tempestata di gemme, del valore di 1.500 mo o più","page":136},"spell.shatter":{"name":"Frantumare","areaDimensions":"Sfera di 3 metri di raggio","description":"Un rumore assordante esplode da un punto a scelta dell'incantatore entro gittata. Ogni creatura all'interno di una sfera di 3 metri di raggio centrata su quel punto effettua un tiro salvezza su Costituzione. In caso di fallimento, subisce 3d8 danni da tuono o la metà dei danni in caso di successo. Un costrutto subisce svantaggio al tiro salvezza.\\n\\nAnche un oggetto non magico che non sia indossato o trasportato subisce i danni se si trova entro l'area dell'incantesimo.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 2º.","material":"un frammento di mica","page":150},"spell.glibness":{"name":"Loquacità","description":"Fino al termine dell'incantesimo, quando l'incantatore effettua una prova di Carisma, può sostituire il risultato del tiro con un 15. Inoltre, a prescindere da ciò che dice, le magie in grado di determinare se un bersaglio stia dicendo o meno la verità indicano che l'incantatore è sincero.","page":162},"spell.light":{"name":"Luce","description":"L'incantatore tocca un oggetto di taglia Grande o inferiore che non sia stato indossato o trasportato da altri. Fino al termine dell'incantesimo, l'oggetto proietta luce intensa entro un raggio di 6 metri e luce fioca per altri 6 metri. L'incantatore può scegliere il colore di luce che desidera.\\n\\nCoprire l'oggetto con qualcosa di opaco blocca la luce. L'incantesimo termina se l'incantatore lo lancia di nuovo.","material":"una lucciola o del muschio fosforescente","page":162},"spell.delayed-blast-fireball":{"name":"Palla di fuoco ritardata","areaDimensions":"Sfera del raggio di 6 metri","description":"Un raggio di luce gialla si sprigiona dall'incantatore per poi condensarsi in un punto a sua scelta entro gittata, formando una sfera scintillante che permane per la durata dell'incantesimo. Al termine dell'incantesimo, la sfera esplode e ogni creatura all'interno di una sfera del raggio di 6 metri centrata su quel punto effettua un tiro salvezza su Destrezza. In caso di fallimento, la creatura subisce una quantità di danni da fuoco pari al totale dei danni accumulati, o la metà dei danni in caso di successo.\\n\\nI danni base dell'incantesimo sono pari a 12d6 e aumentano di 1d6 ogni volta che termina il turno dell'incantatore e l'incantesimo è ancora attivo.\\n\\nSe una creatura tocca la sfera scintillante prima del termine dell'incantesimo, effettua un tiro salvezza su Destrezza. In caso di fallimento, l'incantesimo termina, causando l'esplosione della sfera. In caso di successo, la creatura può lanciare la sfera fino a una distanza di 12 metri: se entra nello spazio di una creatura o si scontra con un oggetto solido, l'incantesimo termina, facendo esplodere la sfera.\\n\\nQuando la sfera esplode, gli oggetti infiammabili all'interno dell'esplosione che non sono indossati o trasportati iniziano a bruciare.","higherLevels":"I danni base aumentano di 1d6 per ogni slot di livello superiore al 7º.","material":"una pallina di guano di pipistrello e zolfo","page":171},"spell.speak-with-dead":{"name":"Parlare con i morti","description":"L'incantatore conferisce una parvenza di vita a un cadavere a sua scelta situato entro gittata, permettendogli di rispondere alle domande che gli vengono poste. Il cadavere deve avere la bocca e, se la creatura deceduta era un non morto al momento del trapasso, l'incantesimo fallisce. Fallisce allo stesso modo se il cadavere è già stato il bersaglio di questo incantesimo negli ultimi 10 giorni.\\n\\nFino al termine dell'incantesimo, l'incantatore può porre al cadavere un massimo di cinque domande. Il cadavere conosce solo quello che sapeva in vita, incluse le lingue. Generalmente, le risposte sono brevi, criptiche o ripetitive e il cadavere non è obbligato a offrirne una sincera se l'incantatore gli è ostile o se il cadavere lo riconosce come nemico. Questo incantesimo non riporta l'anima della creatura nel suo corpo, solamente lo spirito animante. Perciò il cadavere non può apprendere nuove informazioni, non conosce nulla di ciò che è accaduto dopo la sua morte e non può speculare sugli eventi futuri.","material":"incenso bruciato","page":171},"spell.word-of-recall":{"name":"Parola del ritiro","description":"L'incantatore e un massimo di cinque creature consenzienti entro 1,5 metri da lui si teletrasportano immediatamente in un santuario indicato in precedenza. L'incantatore e le creature che si teletrasportano con lui appaiono nello spazio libero più vicino al punto indicato dall'incantatore quando ha preparato il suo santuario (vedi di seguito). Se lancia questo incantesimo senza prima preparare un santuario, l'incantesimo non ha effetto.\\n\\nDeve designare un luogo (come un tempio o un santuario) lanciando lì l'incantesimo.","page":172},"spell.expeditious-retreat":{"name":"Ritirata rapida","description":"L'incantatore effettua un'azione di Scatto e, fino al termine dell'incantesimo, può effettuarla di nuovo come azione bonus.","page":182},"spell.fire-shield":{"name":"Scudo di fuoco","description":"Per la durata dell'incantesimo, il corpo dell'incantatore è avvolto da fiamme sottili, che proiettano luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri.\\n\\nLe fiamme conferiscono all'incantatore uno scudo ardente o gelido a sua scelta. Lo scudo ardente gli conferisce resistenza ai danni da freddo, mentre lo scudo gelido resistenza ai danni da fuoco.\\n\\nInoltre, ogni volta che una creatura entro 1,5 metri dall'incantatore lo colpisce con un tiro per colpire in mischia, dallo scudo erompono delle fiamme. L'attaccante subisce 2d8 danni da fuoco da uno scudo ardente o 2d8 danni da freddo da uno scudo gelido.","material":"un frammento di fosforo o una lucciola","page":186},"spell.faithful-hound":{"name":"Segugio fedele","description":"L'incantatore evoca un cane da guardia fantasma in uno spazio libero entro gittata che egli è in grado di vedere. Il segugio permane per la durata dell'incantesimo o fino a quando la distanza tra il segugio e l'incantatore non supera i 90 metri di distanza.\\n\\nSolo l'incantatore è in grado di vedere il segugio, che è intangibile e invulnerabile. Quando una creatura di taglia Piccola o inferiore si avvicina entro 9 metri dal segugio senza prima aver pronunciato la parola d'ordine specificata dall'incantatore al momento del lancio dell'incantesimo, il segugio inizia ad abbaiare sonoramente. Il segugio ottiene vista pura con un raggio di 9 metri.\\n\\nAll'inizio di ogni turno dell'incantatore, il segugio tenta di mordere un nemico entro 1,5 metri da sé. Il nemico deve superare un tiro salvezza su Destrezza, altrimenti subisce 4d8 danni da forza.\\n\\nNei turni successivi, l'incantatore può effettuare un'azione di Magia per spostare il segugio fino a 9 metri.","material":"un fischietto d'argento","page":186},"spell.unseen-servant":{"name":"Servitore inosservato","description":"Fino al termine di questo incantesimo, una forza Media invisibile, amorfa e priva di volontà propria svolge dei compiti semplici su ordine dell'incantatore. Il servitore appare sul terreno in uno spazio libero entro gittata, ha CA 10, 1 punto ferita, Forza pari a 2 e non può attaccare. Se scende a 0 punti ferita, l'incantesimo termina.\\n\\nUna volta in ogni suo turno, come azione bonus, l'incantatore può ordinare mentalmente al servitore di spostarsi di un massimo di 4,5 metri e interagire con un oggetto. Esso può eseguire compiti semplici alla stregua di un umano, come portare oggetti, pulire, riparare, ripiegare abiti, accendere fuochi, servire pietanze e versare bevande. Una volta impartito il comando, il servitore svolge il compito al meglio delle sue capacità finché non lo porta a termine, poi attende l'ordine successivo dell'incantatore.\\n\\nSe l'incantatore ordina al servitore di eseguire un compito che lo porta a più di 18 metri da lui, l'incantesimo termina.","material":"un pezzo di spago e di legno","page":187},"spell.cloudkill":{"name":"Nube mortale","areaDimensions":"Sfera del raggio di 6 metri","description":"L'incantatore genera una sfera di nebbia giallo-verdastra del raggio di 6 metri centrata su un punto entro gittata. La nebbia permane la durata dell'incantesimo o finché un vento forte (come quello creato da folata di vento) non la disperde, ponendo fine all'incantesimo. L'area della sfera è pesantemente oscurata.\\n\\nOgni creatura nella sfera effettua un tiro salvezza su Costituzione, subendo 5d8 danni da veleno in caso di fallimento, o la metà dei danni in caso di successo. Una creatura deve effettuare questo tiro salvezza anche quando la sfera si muove nel suo spazio e quando la creatura entra nella sfera o vi termina il suo turno. Una creatura effettua questo tiro salvezza solo una volta per turno.\\n\\nLa sfera si allontana di 3 metri dall'incantatore all'inizio di ogni suo turno.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 4º.","page":170},"spell.blindnessdeafness":{"name":"Cecità/sordità","description":"Una creatura entro gittata che l'incantatore è in grado di vedere deve superare un tiro salvezza su Costituzione, altrimenti viene accecata o assordata (a scelta dell'incantatore) per la durata dell'incantesimo. Alla fine di ogni suo turno, il bersaglio ripete il tiro salvezza e, se lo supera, termina l'incantesimo su di sé.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 2º.","page":131},"spell.legend-lore":{"name":"Conoscenza delle leggende","description":"L'incantatore nomina o descrive una persona, un luogo o un oggetto famosi. L'incantesimo riporta alla mente dell'incantatore un breve riassunto delle conoscenze più significative relative a ciò che ha nominato, come descritto dal GM.\\n\\nQueste conoscenze possono includere dettagli importanti, rivelazioni sorprendenti o persino conoscenze segrete che non sono note ai più. Più informazioni l'incantatore conosce già riguardo a ciò che ha nominato, più precise e dettagliate saranno le informazioni che riceverà. Le informazioni che riceve sono accurate, ma potrebbero essere celate da un linguaggio figurativo o sotto forma di poesia, in base alla scelta del GM.\\n\\nSe l'incantatore nomina qualche cosa che in realtà non è famosa, sente il suono delle tristi note di un trombone, e l'incantesimo fallisce.","material":"incenso del valore di 250 mo o più, che l'incantesimo consuma, e quattro bastoncini d'avorio del valore di 50 mo o più ciascuno","page":135},"spell.greater-restoration":{"name":"Ristorare superiore","description":"L'incantatore tocca una creatura e rimuove magicamente da essa uno dei seguenti effetti:\\n\\n- 1 livello di indebolimento\\n- La condizione affascinato o pietrificato\\n- Una maledizione, inclusa la sintonia del bersaglio con un oggetto magico maledetto\\n- Qualsiasi riduzione di un punteggio di caratteristica del bersaglio\\n- Qualsiasi riduzione dei punti ferita massimi del bersaglio","material":"polvere di diamante del valore di 100 mo o più, che l'incantesimo consuma","page":182},"spell.lesser-restoration":{"name":"Ristorare inferiore","description":"L'incantatore tocca una creatura e pone fine a una delle condizioni che la affligge tra: accecato, assordato, avvelenato o paralizzato.","page":182},"spell.holy-aura":{"name":"Aura sacra","areaDimensions":"Emanazione di 9 metri","description":"Per la durata dell'incantesimo, l'incantatore irradia un'aura in un'emanazione di 9 metri. Le creature scelte dell'incantatore che si trovano all'interno dell'aura dispongono di vantaggio a tutti i tiri salvezza, mentre le altre creature subiscono svantaggio ai tiri per colpire contro le creature scelte. Inoltre, quando un immondo o un non morto colpisce una creatura influenzata con un tiro per colpire in mischia, l'attaccante deve superare un tiro salvezza su Costituzione, altrimenti viene accecato fino al termine del proprio turno successivo.","material":"un reliquiario del valore di 1.000 mo o più","page":126},"spell.antimagic-field":{"name":"Campo anti-magia","areaDimensions":"Emanazione di 3 metri","description":"Un'aura di anti-magia circonda l'incantatore in un'emanazione di 3 metri. Nessuno può lanciare incantesimi, compiere azioni di Magia o creare altri effetti magici all'interno dell'aura, e tali azioni non possono colpire o influenzare in alcun modo nulla al suo interno. Le proprietà degli oggetti magici non funzionano all'interno dell'aura o su qualsiasi cosa al suo interno.\\n\\nLe aree di effetto create da incantesimi o da altre magie non possono estendersi all'interno dell'aura e nessuno può teletrasportarsi all'interno o all'esterno di essa o utilizzare il viaggio planare. I portali si chiudono temporaneamente quando si trovano all'interno dell'aura.\\n\\nGli incantesimi già in corso, tranne quelli lanciati da manufatti o divinità, sono soppressi all'interno dell'area. Mentre un effetto è soppresso non funziona, ma il tempo che trascorre in questo stato conta ai fini della sua durata.\\n\\nDissolvi magie non ha alcun effetto sull'aura, e le aure create da più incantesimi campo anti-magia non si annullano a vicenda.","material":"limatura di ferro","page":129},"spell.flame-strike":{"name":"Colpo infuocato","areaDimensions":"Cilindro del raggio di 3 metri e dell'altezza di 12 metri","description":"Una colonna verticale di fuoco splendente si abbatte dall'alto. Ogni creatura all'interno di un cilindro del raggio di 3 metri e dell'altezza di 12 metri centrato in un punto entro gittata effettua un tiro salvezza su Destrezza; se lo fallisce, subisce 5d6 danni da fuoco e 5d6 danni radiosi, mentre se lo supera subisce soltanto la metà di quei danni.","higherLevels":"I danni da fuoco e i danni radiosi aumentano di 1d6 per ogni slot di livello superiore al 5º.","material":"un pizzico di zolfo","page":133},"spell.floating-disk":{"name":"Disco fluttuante","description":"Questo incantesimo crea un piano circolare e orizzontale di forza del diametro di 90 centimetri e spessore di 2,5 centimetri, che fluttua 90 centimetri sopra il terreno in uno spazio libero a scelta dell'incantatore entro gittata e che egli è in grado di vedere. Questo disco permane per la durata dell'incantesimo e può sostenere fino a 250 kg. Se si aggiunge ulteriore peso, l'incantesimo termina e tutto ciò che si trovava sul disco precipita a terra.\\n\\nIl disco rimane immobile se l'incantatore si trova entro 6 metri da esso. Se l'incantatore si allontana a più di 6 metri, il disco lo segue per rimanere entro 6 metri da lui. Può muoversi sul terreno dissestato, lungo scalinate, pendii e terreni simili, ma non può superare un dislivello pari o superiore a 3 metri. Per esempio, il disco non può attraversare una fossa profonda 3 metri o uscirne se si trovasse sul fondo.\\n\\nL'incantesimo termina se l'incantatore si allontana di più di 30 metri dal disco (normalmente accade perché il disco non può superare un ostacolo per seguirlo).","material":"una goccia di mercurio","page":141},"spell.dominate-monster":{"name":"Dominare mostri","description":"Una creatura entro gittata e che l'incantatore è in grado di vedere deve superare un tiro salvezza su Saggezza, altrimenti diventa affascinato per la durata dell'incantesimo. Il bersaglio dispone di vantaggio al tiro salvezza se l'incantatore o i suoi alleati stanno combattendo contro di essa. Ogni volta che il bersaglio subisce danni, ripete il tiro salvezza; se lo supera, l'effetto svanisce.\\n\\nL'incantatore ha un legame telepatico con il bersaglio affascinato mentre i due si trovano sullo stesso piano di esistenza. Nel proprio turno, l'incantatore può utilizzare questo legame per impartire comandi al bersaglio (nessuna azione richiesta), come ad esempio \\"attacca quella creatura\\", \\"spostati lì\\", o \\"recupera quell'oggetto\\". Il bersaglio fa del suo meglio per obbedire nel suo turno. Se porta a termine un ordine e non riceve ulteriori istruzioni dall'incantatore, agisce e si muove a suo piacimento, concentrandosi sulla propria incolumità.\\n\\nL'incantatore può comandare al bersaglio di effettuare una reazione, ma per farlo dovrà utilizzare la propria reazione.","higherLevels":"La concentrazione dell'incantatore può durare più a lungo usando uno slot incantesimo di 9º livello (fino a 8 ore).","page":143},"spell.enlargereduce":{"name":"Ingrandire/ridurre","description":"Per la durata dell'incantesimo, l'incantatore ingrandisce o riduce una creatura o un oggetto entro gittata che egli è in grado di vedere (vedi di seguito l'effetto scelto). L'oggetto bersaglio non deve essere né indossato né trasportato. Se il bersaglio è una creatura non consenziente, può effettuare un tiro salvezza su Costituzione. Se lo supera, l'incantesimo non sortisce alcun effetto.\\n\\nTutto ciò che la creatura indossa o trasporta cambia di taglia insieme a lei. Se un oggetto cade a terra, torna immediatamente alle sue dimensioni normali. Le armi da lancio e le munizioni tornano alle loro dimensioni normali subito dopo aver colpito o mancato un bersaglio.\\n\\n**Ingrandire.** La taglia del bersaglio aumenta di una categoria (da Media a Grande, per esempio). Il bersaglio dispone anche di vantaggio alle prove di Forza e ai tiri salvezza su Forza. Gli attacchi effettuati dal bersaglio con armi ingrandite o con colpi senz'armi infliggono 1d4 danni extra se il colpo va a segno.\\n\\n**Ridurre.** La taglia del bersaglio diminuisce di una categoria (da Media a Piccola, per esempio). Il bersaglio dispone anche di svantaggio alle prove di Forza e ai tiri salvezza su Forza. Gli attacchi effettuati dal bersaglio con armi ridotte o con colpi senz'armi infliggono 1d4 danni in meno se il colpo va a segno (i danni non possono scendere a meno di 1).","material":"un pizzico di polvere di ferro","page":157},"spell.giant-insect":{"name":"Insetto gigante","description":"L'incantatore evoca un millepiedi gigante, un ragno gigante o una vespa gigante (a sua scelta al momento del lancio). L'insetto si manifesta in uno spazio libero entro gittata che l'incantatore è in grado di vedere e utilizza la scheda delle statistiche dell'insetto gigante. La forma scelta dall'incantatore determina alcuni dettagli della sua scheda delle statistiche. La creatura scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\\n\\nLa creatura è un alleato per il personaggio e i suoi alleati. In combattimento, la creatura ha lo stesso punteggio di iniziativa dell'incantatore, ma inizia il turno immediatamente dopo il suo, obbedendo ai suoi comandi verbali (nessuna azione richiesta da parte dell'incantatore). Se l'incantatore non pronuncia comandi verbali, la creatura compie l'azione di Schivata e usa il suo movimento per sottrarsi al pericolo.","higherLevels":"Usa il livello dello slot incantesimo relativo al livello dell'incantesimo nella scheda delle statistiche.","page":157},"spell.blink":{"name":"Intermittenza","description":"L'incantatore tira 1d6 alla fine di ogni suo turno per la durata dell'incantesimo. Con un risultato di 4–6, l'incantatore svanisce dal piano di esistenza in cui si trova per riapparire sul Piano Etereo (l'incantesimo termina immediatamente se l'incantatore si trova già su quel piano). Mentre si trova sul Piano Etereo, l'incantatore può percepire il piano da cui proviene, che è proiettato in scala di grigi ed è visibile solo fino a una distanza di 18 metri. Può influenzare ed essere influenzato solo dalle creature che si trovano sul Piano Etereo, e le creature che si trovano sull'altro piano non possono percepirlo a meno che non abbiano una capacità speciale che consenta loro di percepire le cose sul Piano Etereo.\\n\\nL'incantatore fa ritorno sull'altro piano all'inizio del suo turno successivo e al termine dell'incantesimo se si trova sul Piano Etereo, tornando in uno spazio libero a propria scelta egli è in grado di vedere entro 3 metri dallo spazio che ha abbandonato. Se nessuno spazio libero è disponibile entro quella distanza, l'incantatore appare nello spazio libero più vicino.","page":158},"spell.greater-invisibility":{"name":"Invisibilità superiore","description":"Una creatura toccata dall'incantatore diventa invisibile fino al termine dell'incantesimo.","page":159},"spell.speak-with-plants":{"name":"Parlare con i vegetali","areaDimensions":"Emanazione di 9 metri","description":"L'incantatore infonde nei vegetali in un'emanazione fissa di 9 metri una parvenza di animazione e volontà, donando loro l'abilità di comunicare con lui e di seguire dei comandi semplici. Può interrogare i vegetali sugli eventi avvenuti nell'area dell'incantesimo nella giornata passata, ottenere informazioni riguardo alle creature transitate al suo interno, al clima e ad altre circostanze.\\n\\nPer la durata dell'incantesimo, l'incantatore può anche trasformare un terreno difficile a causa della crescita vegetale (come per esempio arbusti e sottobosco) in un terreno normale. In alternativa può trasformare un terreno normale dove siano presenti dei vegetali in un terreno difficile.\\n\\nL'incantesimo non consente alle piante di sradicarsi e deambulare, ma permette loro di muovere rami, rampicanti e viticci per l'incantatore.\\n\\nSe una creatura vegetale si trova nell'area, il personaggio può comunicarci come se entrambi condividessero una lingua comune.","page":171},"spell.knock":{"name":"Scassinare","description":"L'incantatore sceglie un oggetto entro gittata che egli è in grado di vedere. Può trattarsi di una porta, uno scrigno, un forziere, un paio di manette, un lucchetto o un altro oggetto dotato di un mezzo normale o magico per la chiusura.\\n\\nUn bersaglio tenuto chiuso da una normale serratura, incastrato o sbarrato, cessa di essere tale. Se l'oggetto è protetto da più serrature, con questo incantesimo se ne sblocca soltanto una.\\n\\nSe il bersaglio è tenuto chiuso da Serratura Arcana, quell'incantesimo è soppresso per 10 minuti, nel corso dei quali l'oggetto può essere aperto e chiuso.\\n\\nQuando l'incantatore lancia l'incantesimo, si percepisce un forte rumore simile al bussare proveniente dal bersaglio, udibile fino a una distanza di 90 metri.","page":184},"spell.magic-weapon":{"name":"Arma magica","description":"L'incantatore tocca un'arma non magica, e, fino al termine dell'incantesimo, quell'arma diventa un'arma magica con un bonus di +1 ai tiri per colpire e ai tiri per i danni. L'incantesimo termina in anticipo se l'incantatore lo lancia di nuovo.","higherLevels":"Il bonus aumenta a +2 con uno slot incantesimo compreso tra il 3º e 5º livello. Il bonus aumenta a +3 con uno slot incantesimo di 6º livello o superiore.","page":125},"spell.scrying":{"name":"Scrutare","description":"L'incantatore può vedere e udire una creatura a sua scelta situata sul suo stesso piano di esistenza. Il bersaglio effettua un tiro salvezza su Saggezza, modificato (vedi le tabelle di seguito) dalla conoscenza e dal tipo di legame fisico che l'incantatore ha nei confronti della creatura. Il bersaglio non sa contro cosa sta effettuando il tiro salvezza, avverte solo una sensazione di disagio.\\n\\n|La conoscenza del bersaglio è…|Modificatore al tiro salvezza|\\n|---|---|\\n|Indiretta (ha sentito parlare del bersaglio)|+5|\\n|Diretta (ha incontrato il bersaglio)|+0|\\n|Approfondita (conosce bene il bersaglio)|−5|\\n\\n|Del bersaglio, l'incantatore possiede…|Modificatore al tiro salvezza|\\n|---|---|\\n|Immagine o altra raffigurazione|−2|\\n|Abito o altro oggetto personale|−4|\\n|Parte del corpo, ciocca di capelli o pezzo di unghia|−10|\\n\\nIn caso di tiro salvezza superato, il bersaglio non viene influenzato dall'incantesimo, che l'incantatore non può lanciare su di esso per 24 ore.\\n\\nIn caso di fallimento, l'incantesimo crea un sensore invisibile e intangibile entro 3 metri dal bersaglio, attraverso cui l'incantatore può vedere e sentire come se si trovasse sul posto. Il sensore si muove insieme al bersaglio, rimanendo entro 3 metri da esso per la durata dell'incantesimo. Se qualcosa è in grado di vedere il sensore, esso appare come un globo luminoso grande all'incirca quanto un pugno umano.\\n\\nInvece di bersagliare una creatura, l'incantatore può bersagliare un luogo che ha già visto. Quando lo fa, il sensore appare in quel luogo e non si muove.","material":"un focus del valore di 1.000 mo o più, come una sfera di cristallo, uno specchio o una fonte d'acqua","page":185},"spell.planar-ally":{"name":"Alleato planare","description":"L'incantatore chiede aiuto a un'entità ultraterrena che deve essergli nota: un dio, un principe dei demoni o qualche altro essere dotato di poteri cosmici. Quell'entità invia in aiuto un celestiale, un elementale o un immondo a lei fedele, che appare in uno spazio libero entro gittata. Se l'incantatore conosce il nome di una creatura specifica, può pronunciarlo quando lancia l'incantesimo per richiedere il suo intervento, ma potrebbe apparire comunque una creatura diversa (a scelta del GM).\\n\\nQuando la creatura appare, non è obbligata a comportarsi in un modo particolare. L'incantatore può chiederle di svolgere per lui un servizio in cambio di pagamento, ma essa non è costretta ad accettare. Il compito richiesto potrebbe essere qualcosa di semplice (\\"portaci in volo oltre il baratro\\" o \\"aiutaci a combattere una battaglia\\") o di complesso (\\"spia i nostri nemici\\" o \\"proteggici durante la nostra incursione nel dungeon\\"). L'incantatore deve essere in grado di comunicare con la creatura per contrattare per i suoi servigi.\\n\\nIl pagamento può avere varie forme: Un celestiale potrebbe richiedere un'ingente donazione in oro o oggetti magici a un tempio alleato, un immondo esigere una creatura vivente in sacrificio o un tesoro in dono. Alcune creature potrebbero scambiare i propri servigi con una missione che l'incantatore deve svolgere.\\n\\nUn compito che può essere misurato in minuti richiede un pagamento del valore di 100 mo al minuto, un compito misurato in ore richiede 1.000 mo all'ora e un compito misurato in giorni (per un massimo di 10 giorni) richiede 10.000 mo al giorno. Il GM può modificare questi pagamenti in base alle circostanze del lancio. Se il compito è in sintonia con l'etica della creatura, il pagamento potrebbe essere dimezzato o addirittura revocato. I compiti non pericolosi richiedono tipicamente solo la metà del pagamento suggerito, mentre quelli particolarmente rischiosi potrebbero richiedere una ricompensa superiore. È raro che una creatura accetti un compito potenzialmente suicida.\\n\\nDopo aver portato a termine il compito o quando la durata pattuita termina, la creatura fa ritorno al suo piano d'origine dopo aver fatto rapporto all'incantatore, se possibile. Se l'incantatore e la creatura non riescono ad accordarsi sul prezzo del suo servizio, quest'ultima ritorna immediatamente sul suo piano d'origine.","page":122},"spell.phantasmal-killer":{"name":"Allucinazione mortale","description":"L'incantatore attinge agli incubi di una creatura entro gittata che egli è in grado di vedere e crea un'illusione delle sue paure più profonde, visibile solo a lei. Il bersaglio effettua un tiro salvezza su Saggezza. In caso di fallimento, subisce 4d10 danni psichici e subisce svantaggio alle prove di caratteristica e ai tiri per colpire per la durata dell'incantesimo. In caso di successo, subisce soltanto la metà di quei danni e l'incantesimo termina.\\n\\nPer la durata dell'incantesimo, il bersaglio effettua un tiro salvezza su Saggezza alla fine di ogni suo turno. In caso di fallimento, subisce nuovamente i danni psichici. In caso di successo, l'incantesimo termina.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 4º.","page":123},"spell.hold-person":{"name":"Blocca persone","description":"L'incantatore sceglie un umanoide entro gittata che egli è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti rimane paralizzato per la durata dell'incantesimo. Alla fine di ogni suo turno, il bersaglio ripete il tiro salvezza e, se lo supera, termina l'incantesimo su di sé.","higherLevels":"L'incantatore può bersagliare un umanoide aggiuntivo per ogni slot di livello superiore al 2º.","material":"una sbarra di ferro","page":128},"spell.conjure-fey":{"name":"Evoca folletto","description":"L'incantatore evoca uno spirito di taglia Media dalla Selva Fatata in uno spazio libero entro gittata che egli è in grado di vedere. Lo spirito permane per la durata dell'incantesimo e ha le sembianze di una creatura fatata a scelta dell'incantatore. Quando lo spirito appare, l'incantatore può effettuare un attacco in mischia con incantesimo contro una creatura entro 1,5 metri dallo spirito. Se il colpo va a segno, il bersaglio subisce danni psichici pari a 3d12 più il modificatore di caratteristica da incantatore dell'incantatore. Inoltre, il bersaglio è spaventato fino all'inizio del turno successivo dell'incantatore, con l'incantatore e lo spirito come fonti della sua paura.\\n\\nCome azione bonus nei suoi turni successivi, l'incantatore può teletrasportare lo spirito in uno spazio libero che è in grado di vedere, a una distanza massima di 9 metri dal punto in cui si trovava prima, ed effettuare l'attacco contro una creatura entro 1,5 metri dallo spirito.","higherLevels":"I danni aumentano di 1d12 per ogni slot di livello superiore al 6º.","page":146},"spell.chromatic-orb":{"name":"Globo cromatico","description":"L'incantatore scaglia un globo di energia contro un bersaglio entro gittata. Può scegliere che tipo di globo creare tra acido, freddo, fulmine, fuoco, tuono o veleno, e poi effettuare un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 3d8 danni del tipo scelto.\\n\\nSe l'incantatore ottiene lo stesso risultato su due o più d8, il globo schizza verso un altro bersaglio a scelta dell'incantatore che si trovi entro 9 metri dal primo bersaglio. L'incantatore effettua un tiro per colpire contro il secondo bersaglio e anche un altro tiro per i danni. Il globo non può più schizzare verso un altro bersaglio, a meno che l'incantatore non lanci l'incantesimo usando uno slot incantesimo di 2º livello o superiore.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 1º. Il globo può schizzare verso un altro bersaglio un numero massimo di volte pari al livello dello slot incantesimo consumato, ed è possibile bersagliare una creatura soltanto una volta per ogni lancio di questo incantesimo.","material":"un diamante del valore di 50 mo o più","page":152},"spell.major-image":{"name":"Immagine maggiore","areaDimensions":"Cubo con spigolo di 6 metri","description":"L'incantatore crea l'immagine di un oggetto, una creatura o qualche altro fenomeno visibile che non sia più grande di un cubo con spigolo di 6 metri. L'immagine, apparendo in un punto situato entro gittata che l'incantatore è in grado di vedere, permane per la durata dell'incantesimo. L'immagine sembra reale e include temperature, suoni e odori appropriati all'elemento raffigurato, ma non può infliggere danni o causare condizioni.\\n\\nSe l'incantatore si trova entro la gittata dell'immagine illusoria, può effettuare la sua azione di Magia per fare in modo che l'immagine si muova fino a un qualsiasi altro punto entro gittata. Mentre l'immagine è in movimento, l'incantatore può alterarne l'aspetto in modo che i movimenti risultino naturali. Ad esempio, se l'incantatore crea l'immagine di una creatura e decide di farla muovere, può alterare l'immagine in modo da simulare che stia camminando. Analogamente, può fare in modo che l'illusione generi suoni diversi in momenti diversi, in modo da, per esempio, farle persino sostenere una conversazione.\\n\\nL'illusione può essere rivelata da un'interazione fisica, poiché è possibile passarle attraverso. Una creatura che effettua l'azione di Studio per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo. Se una creatura riconosce l'illusione per ciò che è, riesce a vedere attraverso l'immagine, di cui si attenuano le altre caratteristiche sensoriali.","higherLevels":"L'incantesimo dura finché non viene dissolto, e non necessita di concentrazione, se viene lanciato con uno slot incantesimo 4º livello o superiore.","material":"un ciuffo di lana","page":154},"spell.mirror-image":{"name":"Immagine speculare","description":"Tre duplicati illusori dell'incantatore appaiono nel suo spazio. Fino al termine dell'incantesimo, i duplicati si muovono con l'incantatore e imitano le sue azioni, cambiando posizione in modo che sia impossibile individuare quale sia l'immagine reale.\\n\\nOgni volta che una creatura colpisce l'incantatore con tiro per colpire nel corso della durata dell'incantesimo, l'incantatore tira un d6 per ognuno dei duplicati rimasti. Se uno qualsiasi dei risultati che ottiene è pari o superiore a 3, uno dei duplicati subisce il colpo al posto dell'incantatore, e poi viene distrutto. Altrimenti, i duplicati ignorano tutti gli altri danni o effetti. L'incantesimo termina quando tutti e i tre duplicati vengono distrutti.\\n\\nUna creatura non è influenzata da questo incantesimo se è accecata o se ha vista cieca o vista pura.","page":155},"spell.call-lightning":{"name":"Invocare il fulmine","areaDimensions":"Cilindro alto 3 metri con un raggio di 18 metri","description":"Una nube di tempesta appare in un punto situato entro gittata che l'incantatore è in grado di vedere sopra di sé. Ha la forma di un cilindro alto 3 metri con un raggio di 18 metri.\\n\\nQuando lancia questo incantesimo, l'incantatore sceglie un punto che è in grado di vedere al di sotto della nube, dove si abbatte un fulmine originato da essa. Ogni creatura entro un raggio di 1,5 metri da quel punto effettua un tiro salvezza su Destrezza; se lo fallisce, subisce 3d10 danni da fulmine, mentre se lo supera subisce la metà di quei danni.\\n\\nFino al termine dell'incantesimo, l'incantatore può effettuare un'azione di Magia per richiamare il fulmine in questo modo, bersagliando lo stesso punto o un punto diverso.\\n\\nSe l'incantatore lancia questo incantesimo mentre si trova all'aperto durante una tempesta, l'incantesimo permette di controllare quella tempesta invece di crearne una nuova. In queste condizioni, i danni provocati dall'incantesimo aumentano di 1d10.","higherLevels":"I danni aumentano di 1d10 per ogni slot di livello superiore al 3º.","page":159},"spell.wall-of-thorns":{"name":"Muro di spine","description":"L'incantatore crea un muro di rovi irto di spine affilate. Il muro appare entro gittata su una superficie solida e permane per tutta la durata dell'incantesimo. L'incantatore può scegliere se creare un muro lungo fino a 18 metri, alto 3 metri e spesso 1,5 metri, oppure un muro circolare del diametro massimo di 6 metri, alto fino a 6 metri e spesso 1,5 metri. Il muro blocca la visuale.\\n\\nQuando compare, ogni creatura al suo interno effettua un tiro salvezza su Destrezza, subendo 7d8 danni perforanti in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nUna creatura può muoversi attraverso il muro, seppur con fatica e dolore: per ogni 30 centimetri di muro che attraversa, deve usare 1,2 metri di movimento. Inoltre, la prima volta che una creatura entra in uno spazio nel muro in un turno o vi termina il proprio turno, effettua un tiro salvezza su Destrezza subendo 7d8 danni taglienti in caso di fallimento, o la metà dei danni in caso di successo. Una creatura effettua questo tiro salvezza solo una volta per turno.","higherLevels":"Entrambi i tipi di danno aumentano di 1d8 per ogni slot incantesimo di livello superiore al 6º.","material":"una manciata di spine","page":168},"spell.divine-smite":{"name":"Punizione divina","castingTimeCondition":"che l'incantatore effettua subito dopo aver colpito un bersaglio con un'arma da mischia o con un colpo senz'armi","description":"Il bersaglio subisce 2d8 danni radiosi extra dall'attacco. I danni aumentano di 1d8 se il bersaglio è un immondo o un non morto.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 1º.","page":177},"spell.ray-of-sickness":{"name":"Raggio di infermità","description":"L'incantatore proietta un raggio di energia verdastra verso una creatura entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 2d8 danni da veleno ed è avvelenato fino al termine del turno successivo dell'incantatore.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 1º.","page":178},"spell.web":{"name":"Ragnatela","areaDimensions":"Cubo con spigolo di 6 metri","description":"L'incantatore evoca un ammasso di ragnatele appiccicose in un punto entro gittata, che riempiono un cubo con spigolo di 6 metri per la durata dell'incantesimo. Le ragnatele contano come terreno difficile e l'area al loro interno e leggermente oscurata.\\n\\nSe le ragnatele non sono ancorate tra due masse solide (per esempio pareti o alberi) o stese su un pavimento, un muro o un soffitto, collassano su se stesse e l'incantesimo termina all'inizio del turno successivo dell'incantatore. Le ragnatele stese su una superficie piatta hanno una profondità di 1,5 metri.\\n\\nLa prima volta che una creatura vi entra in un turno o inizia lì il suo turno, deve superare un tiro salvezza su Destrezza, altrimenti sarà trattenuta finché sarà al loro interno o non si libera.\\n\\nUna creatura trattenuta dalle ragnatele può usare la un'azione per effettuare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo. Se supera la prova, non è più trattenuta.\\n\\nLe ragnatele sono infiammabili. Un cubo di ragnatele con spigolo di 1,5 metri brucia in 1 round, infliggendo 2d4 danni da fuoco a ogni creatura che inizi il suo turno tra le fiamme.","material":"un frammento di ragnatela comune","page":178},"spell.vitriolic-sphere":{"name":"Sfera al vetriolo","areaDimensions":"Sfera del raggio di 6 metri","description":"L'incantatore indica un punto entro gittata e un globo luminescente di acido del diametro di 30 centimetri sfreccia verso quel punto, dove esplode in una sfera del raggio di 6 metri. Ogni creatura nell'area effettua un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d4 danni da acido e altri 5d4 danni da acido alla fine del suo turno successivo. In caso di successo, subisce soltanto la metà dei danni iniziali.","higherLevels":"I danni iniziali aumentano di 2d4 per ogni slot di livello superiore al 4º.","material":"una goccia di bile","page":188},"spell.flaming-sphere":{"name":"Sfera infuocata","areaDimensions":"Sfera del diametro di 1,5 metri","description":"L'incantatore crea una sfera di fuoco del diametro di 1,5 metri in uno spazio libero del terreno entro gittata che permane per la durata dell'incantesimo. Ogni creatura che termina il suo turno entro 1,5 metri dalla sfera effettua un tiro salvezza su Destrezza; se lo fallisce, subisce 2d6 danni da fuoco, mentre se lo supera subisce soltanto la metà di quei danni.\\n\\nCome azione bonus, l'incantatore può muovere la sfera per un massimo di 9 metri, facendola rotolare sul terreno. Se l'incantatore muove la sfera nello spazio di una creatura, quella creatura effettua un tiro salvezza contro la sfera, che smette di muoversi per quel turno.\\n\\nQuando l'incantatore muove la sfera, può dirigerla oltre le barriere alte fino a 1,5 metri e farla saltare oltre le fosse larghe fino a 3 metri. Se tocca oggetti infiammabili che non sono indossati o trasportati, la sfera li incendia proiettando luce intensa entro un raggio di 6 metri e luce fioca per altri 6 metri.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 2º.","material":"una pallina di cera","page":188},"spell.ice-storm":{"name":"Tempesta di ghiaccio","areaDimensions":"Cilindro del raggio di 6 metri e alto 12 metri","description":"Chicchi di grandine cadono in un cilindro del raggio di 6 metri e alto 12 metri, centrato su un punto entro gittata. Ogni creatura presente nel cilindro effettua un tiro salvezza su Destrezza, subendo 2d10 danni contundenti e 4d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nLa grandine trasforma l'area all'interno del cilindro in terreno difficile fino al termine del turno successivo dell'incantatore.","higherLevels":"I danni contundenti aumentano di 1d10 per ogni slot di livello superiore al 4º.","material":"una muffola","page":195},"spell.zone-of-truth":{"name":"Zona di verità","areaDimensions":"Sfera del raggio di 4,5 metri","description":"L'incantatore crea una zona magica che protegge dagli inganni all'interno di una sfera del raggio di 4,5 metri, centrata su un punto entro gittata. Fino al termine dell'incantesimo, una creatura che entra nell'area dell'incantesimo per la prima volta in un turno o che inizia qui il suo turno effettua un tiro salvezza su Carisma. Se lo fallisce, non può mentire deliberatamente mentre si trova nell'area. L'incantatore sa se il bersaglio supera o meno il tiro salvezza.\\n\\nUna creatura influenzata è consapevole dell'incantesimo e può evitare di rispondere alle domande a cui normalmente risponderebbe mentendo. In tal caso, deve essere evasiva, ma sincera.","page":201},"spell.spare-the-dying":{"name":"Salvare i morenti","description":"L'incantatore sceglie una creatura entro gittata con 0 punti ferita ma che è ancora in vita, facendola diventare stabile.","higherLevels":"La gittata raddoppia quando l'incantatore raggiunge il 5º livello (9 metri), l'11º livello (18 metri) e il 17º livello (36 metri).","page":182},"spell.hold-monster":{"name":"Blocca mostri","description":"L'incantatore sceglie una creatura entro gittata che egli è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti rimane paralizzato per la durata dell'incantesimo. Alla fine di ogni suo turno, il bersaglio ripete il tiro salvezza e, se lo supera, termina l'incantesimo su di sé.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 5º.","material":"una sbarra di ferro","page":128},"spell.gust-of-wind":{"name":"Folata di vento","areaDimensions":"Linea lunga 18 metri e ampia 3 metri","description":"Una linea di vento forte lunga 18 metri e ampia 3 metri viene indirizzata dall'incantatore in una direzione a sua scelta per la durata dell'incantesimo. Ogni creatura sulla linea deve superare un tiro salvezza su Forza, altrimenti viene spinta per 4,5 metri lontano dall'incantatore nella direzione della linea. Una creatura che termina il suo turno sulla linea deve effettuare lo stesso tiro salvezza.\\n\\nQualsiasi creatura sulla linea deve usare 60 centimetri di movimento per ogni 30 centimetri percorsi per avvicinarsi all'incantatore.\\n\\nLa folata può disperdere gas o vapore e spegne candele e simili fiamme non protette nell'area. Le fiamme protette, come quelle delle lanterne, tremolano e hanno il 50% di possibilità di spegnersi.\\n\\nCome azione bonus nei suoi turni successivi, l'incantatore può modificare la direzione in cui indirizzare la linea.","material":"un seme di legume","page":148},"spell.chill-touch":{"name":"Tocco gelido","description":"Incanalando un flusso di gelo sepolcrale, l'incantatore effettua un attacco con incantesimo in mischia contro un bersaglio a portata. Se il colpo va a segno, il bersaglio subisce 1d10 danni necrotici e non può recuperare punti ferita fino al termine del turno successivo dell'incantatore.","higherLevels":"I danni aumentano di 1d10 quando l'incantatore raggiunge il 5º livello (2d10), l'11º livello (3d10) e il 17º livello (4d10).","page":197},"spell.grease":{"name":"Unto","areaDimensions":"Area di 3 metri per lato","description":"Una patina di unto non infiammabile ricopre un'area di terreno di 3 metri per lato centrata su un punto entro gittata che diventa terreno difficile per la durata dell'incantesimo.\\n\\nQuando l'unto compare, ogni creatura nell'area deve superare un tiro salvezza su Destrezza, altrimenti cade a terra prona. Anche una creatura che entra nell'area o vi termina il proprio turno deve superare lo stesso tiro salvezza, altrimenti cade prona.","material":"un pezzo di cotenna di maiale o burro","page":199},"spell.calm-emotions":{"name":"Calmare emozioni","areaDimensions":"Sfera del raggio di 6 metri","description":"Ogni umanoide all'interno di una sfera del raggio di 6 metri centrata su un punto scelto dall'incantatore entro gittata deve effettuare un tiro salvezza su Carisma o essere influenzato da uno dei seguenti effetti (a scelta per ogni creatura):\\n\\n- La creatura è immune alle condizioni affascinato e spaventato fino al termine dell'incantesimo. Se la creatura è già affascinata o spaventata, queste condizioni sono soppresse per la durata dell'incantesimo.\\n- La creatura diventa indifferente alle creature (a scelta dell'incantatore) verso cui è ostile. Questa indifferenza termina se il bersaglio subisce danni o se vede uno dei suoi alleati subire danni. Al termine dell'incantesimo, l'atteggiamento della creatura torna alla normalità.","page":129},"spell.gaseous-form":{"name":"Forma gassosa","description":"Una creatura consenziente, toccata dall'incantatore, muta forma, insieme a tutto ciò che indossa o trasporta, trasformandosi in una nube fosca per la durata dell'incantesimo. L'effetto svanisce se il bersaglio scende a 0 punti ferita o se effettua un'azione di Magia per terminare l'incantesimo su di sé.\\n\\nMentre si trova in questa forma, una velocità di volo di 3 metri è l'unico metodo di movimento del bersaglio, che può fluttuare e può entrare nello spazio di un'altra creatura e occuparlo. Il bersaglio è resistente ai danni contundenti, perforanti e taglienti; è immune alla condizione prono; dispone di vantaggio ai tiri salvezza su Forza, Destrezza e Costituzione. Il bersaglio può passare attraverso aperture strette, tuttavia tratta i liquidi come fossero superfici solide.\\n\\nIl bersaglio non può parlare o manipolare oggetti e quelli che trasporta o impugna non possono essere lasciati cadere, usati o manipolati in alcun modo. Infine, il bersaglio non può attaccare o lanciare incantesimi.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 3º.","material":"un pezzo di garza","page":149},"spell.locate-object":{"name":"Localizza oggetto","description":"L'incantatore descrive o nomina un oggetto a lui familiare, percependo la direzione della sua ubicazione se l'oggetto si trova entro 300 metri da lui. Se l'oggetto è in movimento, l'incantatore apprende verso quale direzione si sta dirigendo.\\n\\nL'incantesimo può localizzare un oggetto specifico noto all'incantatore, purché l'abbia visto da vicino (entro 9 metri) almeno una volta. In alternativa, può localizzare l'oggetto di un tipo particolare più vicino, come per esempio un certo tipo di veste, gioiello, mobile, strumento o arma.\\n\\nQuesto incantesimo non può localizzare un oggetto se uno strato di piombo blocca il percorso diretto tra esso e l'incantatore.","material":"un ramoscello biforcuto","page":162},"spell.protection-from-poison":{"name":"Protezione dai veleni","description":"L'incantatore tocca una creatura e pone fine alla condizione avvelenato che la affligge. Per la durata dell'incantesimo, il bersaglio dispone di vantaggio ai tiri salvezza eseguiti per evitare o terminare la condizione avvelenato, ed è resistente ai danni da veleno.","page":176},"spell.reincarnate":{"name":"Reincarnazione","description":"L'incantatore tocca un umanoide defunto o una parte di umanoide defunto. Se la creatura non è morta da più di 10 giorni, l'incantesimo le forma un nuovo corpo e richiama la sua anima all'interno di quel corpo. Si tira 1d10 e si consulta la tabella di seguito per determinare la specie del nuovo corpo, oppure il GM sceglie un'altra specie giocabile.\\n\\n|1d10|Specie|\\n|---|---|\\n|1|Il personaggio tira di nuovo|\\n|2|Dragonide|\\n|3|Elfo|\\n|4|Gnomo|\\n|5|Goliath|\\n|6|Halfling|\\n|7|Nano|\\n|8|Orchesco|\\n|9|Tiefling|\\n|10|Umano|\\n\\nLa creatura reincarnata compie le scelte indicate nella descrizione della specie scelta e ricorda la sua vita precedente. Conserva le capacità che possedeva nella sua forma originale, ad eccezione del fatto che i tratti della sua specie originaria vengono sostituiti dai tratti della nuova specie.","material":"oli rari del valore di 1.000 mo o più, che l'incantesimo consuma","page":179},"spell.secret-chest":{"name":"Scrigno segreto","description":"L'incantatore nasconde uno scrigno e tutti i suoi contenuti sul Piano Etereo. Per farlo, deve toccare lo scrigno e la riproduzione in miniatura che fungono da componenti materiali dell'incantesimo. Il forziere può contenere fino a 12 cubi con spigolo di 30 centimetri di materiale non vivente (90 x 60 x 60 cm).\\n\\nFinché il forziere rimane sul Piano Etereo, l'incantatore può effettuare un'azione di Magia e toccare la riproduzione per richiamare a sé lo scrigno, che appare a terra in uno spazio libero entro 1,5 metri da lui. L'incantatore può inviare nuovamente lo scrigno sul Piano Etereo, effettuando un'azione di Magia per toccare lo scrigno e la riproduzione.\\n\\nDopo 60 giorni, esiste una probabilità cumulativa del 5% al termine di ogni giorno che l'incantesimo termini. L'incantesimo termina anche se l'incantatore lancia nuovamente questo incantesimo o se la riproduzione minuscola dello scrigno viene distrutta. Se l'incantesimo termina e lo scrigno più grande si trova sul Piano Etereo, lo scrigno rimane lì per poter essere ritrovato dall'incantatore o da qualcun altro.","material":"uno scrigno che misura 90 x 60 x 60 centimetri, realizzato con materiali rari del valore di 5.000 mo o più e una riproduzione minuscola dello scrigno fatta degli stessi materiali del valore di 50 mo o più","page":185},"spell.augury":{"name":"Presagio","description":"L'incantatore riceve un presagio da un'entità ultraterrena sui risultati di un corso d'azione che intende effettuare nei prossimi 30 minuti. Il GM sceglie il presagio dalla tabella Presagi.\\n\\n**Presagi**\\n\\n|Presagio|Con risultati...|\\n|---|---|\\n|Ventura|Positivi|\\n|Sventura|Negativi|\\n|Ventura e sventura|Positivi e negativi|\\n|Indifferenza|Né positivi né negativi|\\n\\nL'incantesimo non tiene conto delle circostanze, come altri incantesimi, che potrebbero modificare i risultati.\\n\\nSe l'incantatore lancia l'incantesimo più volte prima di completare un riposo lungo, esiste una probabilità cumulativa del 25% di non ottenere risposta per ogni lancio dopo il primo.","material":"bastoncini, ossa, carte o altri oggetti da divinazione dotati di contrassegni speciali, del valore di 25 mo o più","page":175},"spell.hallow":{"name":"Santificare","areaDimensions":"Area del raggio massimo di 18 metri","description":"L'incantatore tocca un punto e infonde un potere sacro o sacrilego in un'area del raggio massimo di 18 metri intorno a esso. L'incantesimo tuttavia fallisce se il raggio comprende un'area già sotto l'effetto di santificare. L'area influenzata è soggetta ai seguenti effetti:\\n\\n**Protezione consacrata.** L'incantatore sceglie uno dei seguenti tipi di creature: aberrazione, celestiale, elementale, folletto, immondo o non morto. Le creature del tipo scelto non possono entrare volontariamente nell'area, e qualsiasi creatura affascinata, spaventata o posseduta da tali creature non viene affascinata, spaventata o posseduta fintantoché si trova nell'area.\\n\\n**Effetto aggiuntivo.** L'incantatore vincola un effetto aggiuntivo all'area, scegliendolo dalla lista sottostante:\\n\\n- **Coraggio.** Le creature di qualsiasi tipo scelto dall'incantatore non possono essere spaventate finché si trovano nell'area.\\n- **Interferenza extradimensionale.** Le creature di qualsiasi tipo scelte dall'incantatore non possono entrare o uscire dall'area utilizzando il teletrasporto o i viaggi interplanari.\\n- **Linguaggi.** Le creature di qualsiasi tipo scelto dall'incantatore possono comunicare con qualsiasi creatura all'interno dell'area, anche se non condividono la stessa lingua.\\n- **Luce diurna.** L'area è pervasa di luce intensa. L'oscurità magica creata dagli incantesimi di livello inferiore rispetto a questo incantesimo non può sopprimere la luce.\\n- **Oscurità.** L'area si riempie di oscurità. La luce normale, nonché la luce magica creata dagli incantesimi di livello inferiore rispetto a questo incantesimo, non possono illuminare l'area.\\n- **Paura.** Le creature di qualsiasi tipo scelto dall'incantatore non possono essere spaventate finché si trovano nell'area.\\n- **Resistenza.** Le creature di qualsiasi tipo scelto dall'incantatore sono resistenti a un tipo di danno scelto dall'incantatore finché si trovano nell'area.\\n- **Sereno riposo.** I cadaveri sepolti nell'area non possono diventare non morti.\\n- **Silenzio.** L'area è insonorizzata, nessun suono può fuoriuscire o penetrare al suo interno.\\n- **Vulnerabilità.** Le creature di qualsiasi tipo scelto dall'incantatore sono vulnerabili a un tipo di danno scelto dall'incantatore finché si trovano nell'area.","material":"incenso del valore di 1.000 mo o più, che l'incantesimo consuma","page":183},"spell.stone-shape":{"name":"Scolpire pietra","description":"L'incantatore tocca un oggetto di pietra di taglia Media o inferiore, oppure una sezione di pietra non più grande di 1,5 metri in ogni dimensione, modellandola nella forma che desidera. Per esempio, potrebbe trasformare una grossa roccia in un'arma, una statua, un forziere o creare un piccolo sentiero di passaggio attraverso un muro spesso 1,5 metri. L'incantatore può anche modellare una porta di pietra o i suoi stipiti per sigillarla. L'oggetto creato può avere un massimo di due cardini e una chiusura, ma non può essere dotato di meccanismi più raffinati.","material":"argilla morbida","page":184},"spell.true-polymorph":{"name":"Metamorfosi pura","description":"L'incantatore sceglie una creatura o un oggetto non magico entro gittata che egli è in grado di vedere. La prima si trasforma in un'altra creatura o un oggetto non magico, mentre il secondo diventa una creatura (l'oggetto non deve essere né indossato né trasportato). La trasformazione permane per la durata dell'incantesimo, o finché il bersaglio non muore o viene distrutto. Tuttavia, se l'incantatore mantiene la concentrazione per l'intera durata, l'incantesimo ha efficacia finché non viene dissolto o una creatura non consenziente supera un tiro salvezza su Saggezza.\\n\\n**Creatura in creatura.** Se l'incantatore trasforma una creatura in un altro tipo di creatura, la nuova forma può essere di qualsiasi tipo, purché il suo grado di sfida sia pari o inferiore a quello del bersaglio (o al suo livello). Le sue statistiche di gioco sono sostituite dalla scheda delle statistiche della nuova forma, mantenendo punti ferita, Dadi Vita, allineamento e personalità.\\n\\nIl bersaglio guadagna un numero di punti ferita temporanei pari ai punti ferita della nuova forma. Al termine dell'incantesimo, il bersaglio perde tutti i punti ferita temporanei rimasti.\\n\\nIl bersaglio è limitato alle azioni che può effettuare in base alla anatomia della sua nuova forma e non può parlare o lanciare incantesimi.\\n\\nL'attrezzatura del bersaglio si fonde nella sua nuova forma e la creatura non può utilizzare il suo equipaggiamento o beneficiarne in alcun modo.\\n\\n**Oggetto in creatura.** L'incantatore può trasformare un oggetto in un qualsiasi tipo di creatura, purché la sua taglia non sia superiore a quella dell'oggetto e il suo grado di sfida sia pari o inferiore a 9. La creatura è amichevole nei confronti dell'incantatore e dei suoi compagni e, in combattimento, obbedisce ai suoi comandi e svolge il suo turno subito dopo di lui.\\n\\nTuttavia, se l'incantesimo dura per più di un'ora, l'incantatore perde il controllo su di essa. Potrebbe rimanere amichevole o meno nei suoi confronti, in base a come è stata trattata.\\n\\n**Creatura in oggetto.** Se l'incantatore trasforma una creatura in un oggetto, tutto ciò che essa indossa o trasporta si fonde nella nuova forma, purché la taglia dell'oggetto non sia superiore a quella della creatura. Le statistiche della creatura diventano quelle dell'oggetto e, una volta terminato l'incantesimo e tornata nella sua forma normale, essa non ricorderà nulla del tempo trascorso in quella forma.","material":"una goccia di mercurio, una piccola quantità di resina e uno sbuffo di fumo","page":165},"spell.shapechange":{"name":"Trasformazione","description":"L'incantatore assume la forma di una creatura diversa per la durata dell'incantesimo o finché non effettua un'azione di Magia per mutare in un'altra forma possibile. La nuova forma deve essere quella di una creatura con un grado di sfida pari o inferiore al livello o al grado di sfida dell'incantatore. La creatura non può essere un costrutto o un non morto e deve essere un tipo di creatura che l'incantatore abbia già visto.\\n\\nQuando l'incantatore lancia l'incantesimo, ottiene un numero di punti ferita temporanei pari ai punti ferita della prima forma in cui si trasforma.\\n\\nAl termine dell'incantesimo, il bersaglio perde tutti i punti ferita temporanei rimasti.\\n\\nLe statistiche di gioco dell'incantatore vengono sostituite dalla scheda delle statistiche della forma scelta, ma l'incantatore conserva il suo tipo di creatura, allineamento, personalità, punteggi di Intelligenza, Saggezza e Carisma, punti ferita, Dadi Vita, competenze e abilità di comunicare. Se l'incantatore possiede il privilegio Incantesimi, conserva anche quello.\\n\\nQuando si trasforma, l'incantatore sceglie se lasciare a terra il suo equipaggiamento o se cambiarne taglia e aspetto per adattarlo alla sua nuova forma e continuare a indossarlo.","material":"un diadema di giada del valore di 1.500 mo o più","page":197},"spell.flesh-to-stone":{"name":"Carne in pietra","description":"L'incantatore tenta di tramutare in pietra una creatura entro gittata che egli è in grado di vedere. Il bersaglio effettua un tiro salvezza su Costituzione. In caso di fallimento, è trattenuto per la durata dell'incantesimo. In caso di successo, la sua velocità è pari a 0 fino all'inizio del turno successivo dell'incantatore. I costrutti superano automaticamente il tiro salvezza.\\n\\nUn bersaglio trattenuto effettua un altro tiro salvezza su Costituzione al termine di ogni suo turno. L'incantesimo termina se il bersaglio supera per tre volte il tiro salvezza contro questo incantesimo. Mentre se lo fallisce per tre volte, viene tramutato in pietra e diventa pietrificato per la durata dell'incantesimo. Non è necessario che i tiri superati o falliti siano consecutivi: si tiene semplicemente il conto di entrambi finché il bersaglio non ne accumula tre di un certo tipo.\\n\\nSe l'incantatore mantiene la concentrazione su questo incantesimo per l'intera durata possibile, il bersaglio è pietrificato fino a quando non viene posta fine alla condizione con ristorare superiore o un'altra magia simile.","material":"una piuma di coccatrice","page":130},"spell.sacred-flame":{"name":"Fiamma sacra","description":"Un bagliore simile a una fiamma discende su una creatura entro gittata che egli è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d8 danni radiosi. Per questo tiro salvezza, il bersaglio non trae beneficio dalla mezza copertura o dai tre quarti di copertura.","higherLevels":"I danni aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).","page":148},"spell.move-earth":{"name":"Muovere il terreno","areaDimensions":"Area con un lato lungo al massimo 12 metri","description":"L'incantatore sceglie un'area di terreno entro gittata con un lato lungo al massimo 12 metri. Per la durata dell'incantesimo, può rimodellare come desidera l'argilla, il terriccio o la sabbia presente nell'area. L'incantatore può aumentare o ridurre l'elevazione dell'area, creare o riempire una fossa, erigere o spianare una parete, oppure innalzare una colonna. Tuttavia, l'estensione di tali cambiamenti non può superare la metà della dimensione più grande dell'area. Ad esempio, se l'area dell'incantesimo è un quadrato con lato di 12 metri, l'incantatore può creare una colonna alta fino a 6 metri, aumentare o ridurre l'elevazione del terreno di 6 metri, scavare una fossa della profondità massima di 6 metri e così via. Le modifiche verranno completate in 10 minuti. Dal momento che la trasformazione del terreno avviene lentamente, le creature nell'area non restano intrappolate o ferite a causa dei movimenti del suolo.\\n\\nAl termine di ogni 10 minuti trascorsi a concentrarsi sull'incantesimo, l'incantatore può scegliere una nuova area di terreno entro gittata da influenzare.\\n\\nQuesto incantesimo non può manipolare la pietra naturale e le costruzioni realizzate in pietra: le rocce e le strutture si spostano per adattarsi al nuovo terreno. Se il modo in cui l'incantatore modella il terreno rende una struttura instabile, essa potrebbe crollare.\\n\\nAllo stesso modo, questo incantesimo non influenza in modo diretto la crescita vegetale: la terra in movimento trasporta con sé i vegetali presenti.","material":"una pala in miniatura","page":166},"spell.eldritch-blast":{"name":"Deflagrazione occulta","description":"L'incantatore scaglia un raggio di energia crepitante, effettuando un attacco a distanza con incantesimo contro una creatura o un oggetto entro gittata. Se il colpo va a segno, il bersaglio subisce 1d10 danni da forza.","higherLevels":"L'incantesimo crea due raggi al 5º livello, tre raggi all'11º livello e quattro raggi al 17º livello. L'incantatore può indirizzare i raggi contro lo stesso bersaglio o contro bersagli differenti, effettuando un tiro per colpire separato per ogni raggio.","page":140},"spell.command":{"name":"Comando","description":"L'incantatore rivolge una parola di comando a una creatura entro gittata che egli è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti dovrà obbedire al comando nel suo turno successivo. Scegli il comando tra le seguenti opzioni:\\n\\n- **Avvicinati.** Il bersaglio si muove verso l'incantatore seguendo il percorso più breve e diretto, terminando il suo turno se giunge entro 1,5 metri da lui.\\n- **Fermo.** Nel suo turno, il bersaglio non si muove e non effettua alcuna azione o azione bonus.\\n- **Fuggi.** Il bersaglio usa il suo turno per allontanarsi dall'incantatore nel modo più rapido possibile.\\n- **Lascia.** Il bersaglio lascia cadere ciò che stava impugnando, poi termina il suo turno.\\n- **Prostrati.** Il bersaglio cade a terra prono e termina il suo turno.","higherLevels":"L'incantatore può influenzare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","page":134},"spell.stinking-cloud":{"name":"Nube maleodorante","areaDimensions":"Sfera del raggio di 6 metri","description":"L'incantatore genera una sfera di gas nauseante giallastro del raggio di 6 metri centrata su un punto entro gittata. La nube è pesantemente oscurata e rimane attiva per la durata dell'incantesimo o finché un vento forte (come quello creato da folata di vento) non la disperde.\\n\\nOgni creatura che inizi il proprio turno all'interno della sfera deve superare un tiro salvezza su Costituzione, altrimenti sarà avvelenata fino al termine del turno in corso. Finché è avvelenato, il bersaglio non può effettuare né azioni né azioni bonus.","material":"un uovo marcio","page":170},"spell.power-word-stun":{"name":"Parola del potere stordire","description":"L'incantatore sconvolge la mente di una creatura situata entro gittata che egli è in grado di vedere. Se il bersaglio possiede 150 punti ferita o meno, è stordito. Altrimenti, la sua velocità è pari a 0 fino all'inizio del turno successivo dell'incantatore.\\n\\nIl bersaglio stordito effettua un tiro salvezza su Costituzione alla fine di ogni suo turno e, se lo supera, pone fine alla condizione.","page":172},"spell.remove-curse":{"name":"Rimuovi maledizione","description":"Al tocco dell'incantatore, tutte le maledizioni che affliggono una creatura o un oggetto terminano. Nel caso di un oggetto magico maledetto, la sua maledizione permane, ma l'incantesimo spezza la sintonia del suo proprietario, consentendogli di rimuoverlo o di liberarsene.","page":181},"spell.darkvision":{"name":"Scurovisione","description":"Per la durata dell'incantesimo, una creatura consenziente toccata dall'incantatore è dotata di scurovisione fino a 45 metri.","material":"una carota essiccata","page":186},"spell.sleep":{"name":"Sonno","areaDimensions":"Sfera dal raggio di 1,5 metri","description":"Ogni creatura a scelta dell'incantatore in una sfera dal raggio di 1,5 metri in una posizione entro gittata deve superare un tiro salvezza su Saggezza, altrimenti sarà incapacitata fino al termine del proprio turno successivo. A questo punto, dovrà ripetere la prova e, in caso di fallimento, cadrà priva di sensi per la durata dell'incantesimo. L'effetto svanisce se il bersaglio subisce danni o se qualcuno entro 1,5 metri da esso effettua un'azione per scuoterlo e farlo tornare in sé.\\n\\nLe creature che non dormono, come gli elfi, o che sono immuni all'indebolimento superano automaticamente i tiri salvezza contro l'incantesimo.","material":"un pizzico di sabbia o dei petali di rosa","page":191},"spell.sleet-storm":{"name":"Tempesta di nevischio","areaDimensions":"Cilindro alto 12 metri dal raggio di 6 metri","description":"Fino al termine dell'incantesimo cade del nevischio in un cilindro alto 12 metri dal raggio di 6 metri il cui centro è un punto a scelta dell'incantatore entro gittata. L'area è pesantemente oscurata e le fiamme libere al suo interno vengono estinte.\\n\\nLa superficie all'interno del cilindro è un terreno difficile. Quando una creatura entra nell'area del cilindro per la prima volta in un turno o vi inizia il proprio turno, deve superare un tiro salvezza su Destrezza, altrimenti cadrà a terra prona e perderà la concentrazione.","material":"un ombrello in miniatura","page":195},"spell.see-invisibility":{"name":"Vedere invisibilità","description":"Per la durata dell'incantesimo, l'incantatore è in grado di vedere le creature e gli oggetti invisibili e proiettare la sua vista sul Piano Etereo. Le creature e gli oggetti appaiono spettrali.","material":"un pizzico di talco","page":200},"spell.power-word-kill":{"name":"Parola del potere uccidere","description":"L'incantatore costringe una creatura entro gittata che egli è in grado di vedere a morire. Se il bersaglio possiede 100 punti ferita o meno, muore. Altrimenti, subisce 12d12 danni psichici.","page":172},"spell.barkskin":{"name":"Pelle coriacea","description":"L'incantatore tocca una creatura consenziente. Fino al termine dell'incantesimo, la pelle del bersaglio assume l'aspetto della corteccia. Inoltre, il bersaglio ha una Classe Armatura di 17 se la sua CA è inferiore a tale valore.","material":"un pezzo di corteccia","page":173},"spell.clairvoyance":{"name":"Chiaroveggenza","description":"L'incantatore crea un sensore invisibile entro gittata in un luogo a lui familiare (cioè che ha già visitato o visto), oppure in un luogo ovvio a lui non familiare (come per esempio dietro una porta, dietro un angolo o in un boschetto). Questo sensore intangibile e invulnerabile rimane in quella posizione per la durata dell'incantesimo.\\n\\nQuando lancia l'incantesimo, l'incantatore sceglie tra vista e udito, potendo utilizzare il senso scelto attraverso il sensore come se si trovasse nel suo spazio. Come azione bonus, l'incantatore può passare dalla vista all'udito e viceversa.\\n\\nUna creatura che vede il sensore (per esempio una creatura che beneficia di vedere invisibilità o vista pura) scorge una sfera luminosa grande quanto il pugno dell'incantatore.","material":"un focus del valore di 100 mo o più, a scelta tra un cornetto acustico incastonato di gemme o un occhio di vetro per la vista","page":132},"spell.dissonant-whispers":{"name":"Sussurri dissonanti","description":"Una creatura a scelta dell'incantatore, situata entro gittata e che egli è in grado di vedere, sente una melodia dissonante nella sua mente. Il bersaglio effettua un tiro salvezza su Saggezza. Se lo fallisce, subisce 3d6 danni psichici e, se disponibile, deve usare immediatamente la sua reazione per muoversi fin dove la sua velocità glielo consente, percorrendo la via più sicura. In caso di successo, subisce soltanto la metà di quei danni.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 1º.","page":193},"spell.water-walk":{"name":"Camminare sull'acqua","description":"Questo incantesimo conferisce la capacità di muoversi su una qualsiasi superficie liquida, come l'acqua, l'acido, il fango, la neve, le sabbie mobili o la lava, come se si trattasse di un innocuo terreno solido (ma le creature che attraversano un tratto di lava fusa possono comunque subire danni dal calore). Fino a dieci creature consenzienti entro gittata a scelta dell'incantatore ottengono questa capacità per la durata dell'incantesimo.\\n\\nUn bersaglio colpito deve usare un'azione bonus per passare dalla superficie del liquido all'interno del liquido stesso e viceversa, ma se il bersaglio cade dentro di esso passa attraverso la superficie nel liquido sottostante.","material":"un pezzo di sughero","page":129},"spell.polymorph":{"name":"Metamorfosi","description":"L'incantatore tenta di trasformare in bestia una creatura entro gittata che egli è in grado di vedere. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti assume la forma di una bestia per la durata dell'incantesimo. La forma in cui muta può essere quella di qualsiasi bestia, a scelta dell'incantatore, il cui grado di sfida sia pari o inferiore a quello del bersaglio (o al livello del bersaglio, se esso non possiede un grado di sfida). Le statistiche di gioco del bersaglio vengono sostituite dalla scheda delle statistiche della bestia scelta, ma il bersaglio conserva il proprio allineamento, personalità, tipo di creatura, punti ferita e Dadi Vita. Vedi la sezione \\"Animali\\" in \\"Mostri\\" per un esempio di scheda delle statistiche di una bestia.\\n\\nIl bersaglio guadagna un numero di punti ferita temporanei pari ai punti ferita della forma bestiale. Al termine dell'incantesimo, il bersaglio perde tutti i punti ferita temporanei rimasti. L'incantesimo termina in anticipo se il bersaglio non ha punti ferita temporanei rimasti.\\n\\nIl bersaglio è limitato alle azioni che può effettuare in base alla anatomia della sua nuova forma e non può parlare o lanciare incantesimi.\\n\\nL'attrezzatura del bersaglio si fonde nella sua nuova forma e la creatura non può utilizzare il suo equipaggiamento o beneficiarne in alcun modo.","material":"il bozzolo di un bruco","page":164},"spell.stoneskin":{"name":"Pelle di pietra","description":"Fino al termine dell'incantesimo, una creatura consenziente toccata dall'incantatore avrà resistenza a danni contundenti, perforanti e taglienti.","material":"polvere di diamante del valore di 100 mo o più, che l'incantesimo consuma","page":174},"spell.water-breathing":{"name":"Respirare sott'acqua","description":"Questo incantesimo concede a un massimo di dieci creature consenzienti entro gittata (a scelta dell'incantatore) la capacità di respirare sott'acqua per tutta la sua durata. Le creature influenzate conservano inoltre la loro normale modalità di respirazione.","material":"un piccolo giunco","page":179},"spell.druidcraft":{"name":"Artificio druidico","description":"Sussurrando agli spiriti della natura, l'incantatore crea uno degli effetti seguenti entro gittata.\\n\\n**Sensore atmosferico.** L'incantatore crea un Minuscolo e innocuo effetto sensoriale che predice il tempo atmosferico nel luogo in cui si trova per le successive 24 ore. L'effetto potrebbe manifestarsi come una sfera dorata in caso di cieli tersi, una nuvola in caso di pioggia, fiocchi di neve in caso di nevicate e così via. Questo effetto permane per 1 round.\\n\\n**Fioritura.** L'incantatore fa istantaneamente sbocciare un fiore, aprire un baccello o schiudere un germoglio.\\n\\n**Effetto sensoriale.** L'incantatore crea un effetto sensoriale innocuo, come la caduta di foglie, delle fate spettrali danzanti, una brezza leggera, il rumore di un piccolo animale o il debole odore di una puzzola. L'effetto deve poter essere contenuto in un cubo con spigolo di 1,5 metri.\\n\\n**Trucchetto col fuoco.** L'incantatore accende o spegne una candela, una torcia o un fuoco da campo.","page":126},"spell.disguise-self":{"name":"Camuffare se stesso","description":"L'incantatore (compresi i suoi abiti, armatura, armi e altri oggetti personali presenti sulla sua persona) assume un aspetto diverso fino al termine dell'incantesimo. Può apparire 30 centimetri più alto o più basso e apparire più grasso o più magro, adottando una forma che usi la stessa disposizione basilare degli arti. Entro questi limiti, la natura dell'illusione dipende da lui.\\n\\nI cambiamenti apportati da questo incantesimo non passano il vaglio di un'ispezione fisica. Per esempio, se l'incantatore usa questo incantesimo per aggiungere un cappello al suo abbigliamento, gli oggetti attraverserebbero il cappello e chiunque lo toccasse non sentirebbe nulla.\\n\\nPer capire che l'incantatore è camuffato, una creatura può usare la sua azione di Studio per ispezionarne l'aspetto, superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza sull'incantesimo.","page":130},"spell.chain-lightning":{"name":"Catena di fulmini","description":"L'incantatore scaglia un fulmine verso un bersaglio entro gittata e che egli è in grado di vedere. Tre fulmini sfrecciano poi dal bersaglio verso un massimo di altri tre bersagli a scelta dell'incantatore, ognuno dei quali deve trovarsi entro 9 metri dal primo. I bersagli dell'incantesimo possono essere creature o oggetti e possono essere bersagliati soltanto da uno dei fulmini.\\n\\nOgni bersaglio effettua un tiro salvezza su Destrezza, subendo 10d8 danni da fulmine in caso di fallimento, o la metà dei danni in caso di successo.","higherLevels":"Un fulmine aggiuntivo si trasmette dal primo bersaglio a un altro bersaglio per ogni slot di livello superiore al 6º.","material":"tre spilli d'argento","page":131},"spell.magic-missile":{"name":"Dardo incantato","description":"L'incantatore crea tre dardi lucenti di forza magica. Ogni dardo colpisce una creatura a scelta dell'incantatore situata entro gittata che egli è in grado di vedere. Un dardo infligge 1d4 + 1 danni da forza al suo bersaglio. Tutti i dardi colpiscono simultaneamente e l'incantatore può dirigerli per colpire una o più creature.","higherLevels":"L'incantesimo crea un dardo aggiuntivo per ogni slot di livello superiore al 1º.","page":140},"spell.elementalism":{"name":"Elementalismo","description":"L'incantatore esercita il suo controllo sugli elementi, creando uno dei seguenti effetti entro gittata.\\n\\n**Richiamo del fuoco.** Nell'area di un cubo con spigolo di 1,5 metri, l'incantatore crea una piccola nube di braci non incandescenti, colorate e che emettono fumo e un odore particolare. L'incantatore sceglie il colore e l'odore delle braci, che si possono usare per accendere candele, torce o lampade in quell'area. L'odore del fumo permane per 1 minuto.\\n\\n**Richiamo dell'acqua.** L'incantatore crea uno spruzzo d'acqua fresca nebulizzata che inumidisce leggermente le creature e gli oggetti all'interno di un cubo con spigolo di 1,5 metri. In alternativa, crea 1 coppa di acqua pulita da riversare all'interno di un contenitore aperto o su una superficie; l'acqua evapora dopo 1 minuto.\\n\\n**Richiamo dell'aria.** Nell'area di un cubo con spigolo di 1,5 metri, l'incantatore crea una brezza in grado di far svolazzare i tessuti, sollevare la polvere, far oscillare le foglie e chiudere porte e persiane aperte. Se le porte e le persiane sono tenute aperte da qualcuno, l'incantesimo non ha effetto su di esse.\\n\\n**Richiamo della terra.** L'incantatore crea un sottile velo di polvere o sabbia che ricopre le superfici di un'area di 1,5 metri per lato, oppure fa comparire una singola parola scritta nella sua calligrafia su un lembo di terra o un letto di sabbia.\\n\\n**Scolpire elementi.** L'incantatore fa in modo che un elemento a sua scelta tra terra, sabbia, fuoco, fumo, nebbia o acqua (in una quantità tale da poter essere contenuto in un cubo con spigolo di 30 centimetri) assuma una forma rozza (come quella di una creatura) per 1 ora.","page":144},"spell.detect-magic":{"name":"Individuazione del magico","description":"Per la durata dell'incantesimo, l'incantatore percepisce la presenza di effetti magici entro 9 metri da sé. Se percepisce tali effetti, può eseguire un azione di Magia per vedere una debole aura attorno a ogni creatura o oggetto visibile nell'area che contenga magia e apprende di che scuola di magia si tratta, se ne esiste una.\\n\\nL'incantesimo viene bloccato da 30 cm di pietra, terriccio o legno, 2,5 centimetri di metallo o una sottile lamina di piombo.","page":157},"spell.slow":{"name":"Lentezza","areaDimensions":"Cubo con spigolo di 12 metri","description":"L'incantatore altera il tempo intorno a un massimo di sei creature a sua scelta all'interno in un cubo con spigolo di 12 metri entro gittata. Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti è influenzato da questo incantesimo per tutta la sua durata.\\n\\nUn bersaglio influenzato subisce una penalità di −2 alla CA e ai tiri salvezza su Destrezza, non può effettuare reazioni e la sua velocità è dimezzata. Quando è il suo turno, può effettuare un'azione o un'azione bonus, non entrambe. Inoltre, se sceglie di eseguire l'azione di Attacco, può sferrare un solo attacco. Se lancia un incantesimo con una componente somatica, ha una probabilità di fallimento del 25%, poiché l'incantatore effettua troppo lentamente i movimenti necessari al lancio.\\n\\nInoltre, ripeterà il tiro salvezza alla fine di ogni suo turno. Se lo supera, l'incantesimo svanisce.","material":"una goccia di melassa","page":161},"spell.speak-with-animals":{"name":"Parlare con gli animali","description":"Per la durata dell'incantesimo, l'incantatore comprende le bestie e può comunicare verbalmente con loro usando una qualunque abilità dell'azione di Influenza.\\n\\nNella maggior parte dei casi hanno ben poco da dire su temi che esulano dalla sopravvivenza o dallo spirito di squadra, ma almeno possono fornire informazioni su luoghi e mostri nelle vicinanze, oltre a tutto ciò che hanno notato nel corso dell'ultima giornata.","page":171},"spell.fear":{"name":"Paura","areaDimensions":"Cono di 9 metri","description":"Ogni creatura entro un cono di 9 metri deve superare un tiro salvezza su Saggezza, altrimenti lascia cadere ciò che tiene in mano e diventa spaventata per la durata dell'incantesimo.\\n\\nUna creatura spaventata effettua l'azione di Scatto e si muove a ogni suo turno per allontanarsi dall'incantatore lungo il percorso più sicuro possibile, sempre che abbia lo spazio per muoversi. Se la creatura termina il suo turno in uno spazio dove l'incantatore non è in vista, effettua un tiro salvezza su Saggezza. In caso di successo, l'incantesimo termina.","material":"una piuma bianca","page":173},"spell.searing-smite":{"name":"Punizione incandescente","castingTimeCondition":"che l'incantatore effettua subito dopo aver colpito un bersaglio con un'arma da mischia o con un colpo senz'armi","description":"Quando l'incantatore colpisce il bersaglio, esso subisce 1d6 danni da fuoco extra dall'attacco. All'inizio di ogni suo turno fino al termine dell'incantesimo, il bersaglio subisce 1d6 danni da fuoco ed effettua un tiro salvezza su Costituzione. In caso di fallimento, l'incantesimo permane. In caso di successo, l'incantesimo termina.","higherLevels":"Tutti i danni aumentano di 1d6 per ogni slot di livello superiore al 1º.","page":177},"spell.freezing-sphere":{"name":"Sfera congelante","areaDimensions":"Sfera di 18 metri di raggio","description":"Una sfera congelata sfreccia dall'incantatore verso un punto a sua scelta entro gittata, dove esplode in una sfera di 18 metri di raggio. Ogni creatura in quell'area effettua un tiro salvezza su Costituzione, subendo 10d6 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nSe la sfera colpisce uno specchio d'acqua, congela l'acqua fino a una profondità di 15 centimetri su un'area quadrata con lato di 9 metri. Lo strato di ghiaccio dura 1 minuto. Le creature che stavano nuotando sulla superficie dell'acqua ghiacciata rimangono intrappolate nel ghiaccio e sono trattenute. Per liberarsi, possono effettuare un'azione per effettuare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo.\\n\\nUna volta completato il lancio dell'incantesimo, l'incantatore può decidere di non scagliare la sfera. Così facendo, una sfera grande all'incirca quanto un proiettile da fionda, freddo al tatto, compare nella sua mano. In qualsiasi momento, l'incantatore o una creatura a cui l'ha consegnata può lanciare la sfera (entro una gittata di 12 metri) o scagliarla con una fionda (entro la normale gittata della fionda). La sfera si infrange all'impatto, con lo stesso effetto di un lancio normale dell'incantesimo. Tuttavia, l'incantatore può anche appoggiare la sfera a terra senza romperla. Dopo 1 minuto, se non è ancora stata infranta, la sfera esplode.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 6º.","material":"una sfera di cristallo in miniatura","page":188},"spell.blur":{"name":"Sfocatura","description":"Il corpo dell'incantatore diventa sfocato. Per la durata dell'incantesimo, tutte le creature subiscono svantaggio ai tiri per colpire contro l'incantatore. Un attaccante è immune a questo effetto se percepisce l'incantatore con vista cieca o vista pura.","page":189},"spell.hypnotic-pattern":{"name":"Trama ipnotica","areaDimensions":"Cubo con spigolo di 9 metri","description":"All'interno di un cubo con spigolo di 9 metri entro gittata, l'incantatore crea un intreccio di colori serpeggianti che appare per qualche secondo prima di svanire. Ogni creatura all'interno dell'area in grado di vedere l'intreccio deve superare un tiro salvezza su Saggezza, altrimenti rimane affascinata per la durata dell'incantesimo. Finché è affascinata, la creatura è incapacitata e la sua velocità è pari a 0.\\n\\nL'incantesimo su una creatura influenzata termina se questa subisce danni o se qualcuno usa un'azione per scuoterla, destandola dal suo stato confusionale.","material":"una manciata di coriandoli","page":197},"spell.haste":{"name":"Velocità","description":"L'incantatore sceglie una creatura consenziente entro gittata che egli è in grado di vedere. Fino al termine dell'incantesimo, il bersaglio ottiene un bonus di +2 alla Classe Armatura, dispone di vantaggio ai tiri salvezza su Destrezza, la sua velocità raddoppia e ottiene un'azione aggiuntiva per ogni turno. Tale azione può essere utilizzata solo per effettuare un'azione di Attacco (un solo attacco), Scatto, Disimpegno, Nascondersi o Utilizzo.\\n\\nAl termine dell'incantesimo, il bersaglio è incapacitato e ha una velocità pari a 0 fino al termine del proprio turno successivo, essendo sopraffatto da un'ondata di spossatezza.","material":"una scaglia di radice di liquirizia","page":200},"spell.conjure-woodland-beings":{"name":"Evoca creature boschive","areaDimensions":"Emanazione di 3 metri","description":"L'incantatore evoca degli spiriti della natura che gli fluttuano attorno in un'emanazione di 3 metri per la durata dell'incantesimo. Ogni volta che l'emanazione entra nello spazio di una creatura che l'incantatore è in grado di vedere e ogni volta che una creatura che l'incantatore è in grado di vedere entra nell'emanazione o vi termina il suo turno, l'incantatore può costringerla a effettuare un tiro salvezza su Saggezza. In caso di fallimento, subisce 5d8 danni da forza, o la metà dei danni in caso di successo. Una creatura effettua questo tiro salvezza solo una volta per turno.\\n\\nInoltre, per la durata dell'incantesimo, l'incantatore può effettuare l'azione di Disimpegno come azione bonus.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 4º.","page":145},"spell.fire-bolt":{"name":"Dardo di fuoco","description":"L'incantatore scaglia una scintilla di fuoco verso una creatura o un oggetto situato entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d10 danni da fuoco. Un oggetto infiammabile colpito da questo incantesimo prende fuoco se non indossato o trasportato in quel momento.","higherLevels":"I danni aumentano di 1d10 quando l'incantatore raggiunge il 5º livello (2d10), l'11º livello (3d10) e il 17º livello (4d10).","page":140},"spell.detect-poison-and-disease":{"name":"Individuazione delle malattie e dei veleni","description":"Per la durata dell'incantesimo, l'incantatore percepisce l'ubicazione di veleni, creature velenose e contagi magici entro 9 metri da sé. Inoltre, in ciascun caso può identificare il tipo di veleno, di creatura velenosa o di malattia.\\n\\nL'incantesimo viene bloccato da 30 cm di pietra, terriccio o legno, 2,5 centimetri di metallo o una sottile lamina di piombo.","material":"una foglia di tasso","page":156},"spell.burning-hands":{"name":"Mani brucianti","areaDimensions":"Cono di 4,5 metri","description":"Un sottile velo di fiamme si propaga dall'incantatore. Ogni creatura entro un cono di 4,5 metri effettua un tiro salvezza su Destrezza, subendo 3d6 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nGli oggetti infiammabili nel cono che non sono indossati o trasportati iniziano a bruciare.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 1º.","page":163},"spell.wall-of-force":{"name":"Muro di forza","description":"Un muro di forza invisibile si materializza in un punto a scelta dell'incantatore situato entro gittata. Esso appare nell'orientamento che l'incantatore desidera, come barriera orizzontale, verticale o inclinata. Può fluttuare nell'aria o poggiare su una superficie solida. L'incantatore può modellare la barriera in una cupola semisferica o in una sfera del raggio massimo di 3 metri, oppure come una superficie piatta composta da dieci pannelli quadrati con lato di 3 metri. Ogni pannello dev'essere contiguo a un altro pannello. In qualsiasi forma, il muro ha uno spessore di 0,6 centimetri e permane per la durata dell'incantesimo. Se, nel momento in cui appare, il muro passa attraverso lo spazio di una creatura, questa viene spinta verso un lato del muro a scelta dell'incantatore.\\n\\nNulla può fisicamente attraversare il muro, che è immune a tutti i danni e non può essere dissolto con dissolvi magie. Tuttavia, un incantesimo disintegrazione lo distrugge all'istante. Il muro si estende anche sul Piano Etereo e blocca i viaggi eterei che lo attraversano.","material":"un frammento di vetro","page":166},"spell.thunderwave":{"name":"Onda tonante","areaDimensions":"Cubo con spigolo di 4,5 metri","description":"L'incantatore sprigiona un'ondata di energia tonante. Ogni creatura entro un cubo con spigolo di 4,5 metri originato dall'incantatore effettua un tiro salvezza su Costituzione. Se lo fallisce, subisce 2d8 danni da tuono e viene spinta a una distanza di 3 metri dall'incantatore. In caso di successo, subisce soltanto la metà di quei danni.\\n\\nInoltre, gli oggetti non fissati e situati interamente nel cubo vengono spinti a 3 metri dall'incantatore, con un boato tonante entro 90 metri.","higherLevels":"I danni aumentano di 1d8 per ogni slot di livello superiore al 1º.","page":170},"spell.raise-dead":{"name":"Rianimare morti","description":"Con un tocco, l'incantatore riporta in vita una creatura morta, purché non sia deceduta da più di 10 giorni e non fosse un non morto al momento della morte.\\n\\nLa creatura torna in vita con 1 punto ferita. Inoltre, questo incantesimo neutralizza qualsiasi veleno che influenzava la creatura al momento della morte.\\n\\nL'incantesimo richiude tutte le ferite mortali, ma non ripristina le parti del corpo mancanti. Se una creatura è priva di organi o parti del corpo essenziali per la sua sopravvivenza, come per esempio la testa, l'incantesimo fallisce automaticamente.\\n\\nIl ritorno dalla morte è un vero e proprio travaglio. Il bersaglio subisce una penalità di −4 alle prove con d20. Ogni volta che completa un riposo lungo, questa penalità viene ridotta di 1 finché non arriva a 0.","material":"un diamante del valore di 500 mo o più, che l'incantesimo consuma","page":180},"spell.sorcerous-burst":{"name":"Stregoneria esplosiva","description":"L'incantatore proietta energia stregonesca verso una creatura o un oggetto entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d8 danni di un tipo a scelta tra: acido, freddo, fuoco, fulmine, psichici, tuono o veleno.\\n\\nSe l'incantatore ottiene il risultato 8 su un d8, può tirare un altro d8 e aggiungere il risultato ai danni. Quando lancia l'incantesimo, l'incantatore può aggiungere ai danni dell'incantesimo un numero di d8 pari al suo modificatore di caratteristica da incantatore.","higherLevels":"I danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).","page":192},"spell.warding-bond":{"name":"Vincolo di interdizione","description":"L'incantatore tocca un'altra creatura consenziente e crea un collegamento mistico tra sé e il bersaglio fino al termine dell'incantesimo. Finché il bersaglio si trova entro 18 metri dall'incantatore, ottiene un bonus di +1 alla CA e ai tiri salvezza e dispone di resistenza a tutti i danni. Inoltre, ogni volta che subisce danni, l'incantatore ne subisce la stessa quantità.\\n\\nL'incantesimo termina se l'incantatore scende a 0 punti ferita, se lui e il bersaglio si allontanano di più di 18 metri o se l'incantesimo viene lanciato di nuovo su una delle due creature collegate.","material":"un paio di anelli di platino del valore di 50 mo o più, che l'incantatore e il bersaglio devono indossare per la durata dell'incantesimo","page":200},"spell.acid-splash":{"name":"Fiotto acido","areaDimensions":"Sfera del raggio di 1,5 metri","description":"L'incantatore crea una bolla di acido in un punto entro gittata, dove la bolla esplode in una sfera del raggio di 1,5 metri. Ogni creatura all'interno della sfera deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d6 danni da acido.","higherLevels":"I danni aumentano di 1d6 quando l'incantatore raggiunge il 5º livello (2d6), l'11º livello (3d6) e il 17º livello (4d6).","page":148},"spell.starry-wisp":{"name":"Luce splendente","description":"L'incantatore lancia un globo di luce contro una creatura o un oggetto entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d8 danni radiosi e, fino al termine del turno successivo dell'incantatore, emette luce fioca nel raggio di 3 metri e non può beneficiare della condizione di invisibilità.","higherLevels":"I danni aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).","page":162},"spell.power-word-heal":{"name":"Parola del potere guarire","description":"Un'ondata di energia curativa investe una creatura entro gittata che l'incantatore è in grado di vedere. Il bersaglio recupera tutti i suoi punti ferita. Se la creatura è affascinata, avvelenata, paralizzata, spaventata o stordita, questa condizione termina. Se la creatura è prona, può usare la sua reazione per rialzarsi.","page":172},"spell.detect-evil-and-good":{"name":"Individuazione del bene e del male","description":"Per la durata dell'incantesimo, l'incantatore percepisce la posizione di aberrazioni, celestiali, elementali, folletti, immondi o non morti entro 9 metri di distanza da sé. Percepisce inoltre se l'incantesimo santificare è attivo e, se sì, dove.\\n\\nL'incantesimo viene bloccato da 30 cm di pietra, terriccio o legno, 2,5 centimetri di metallo o una sottile lamina di piombo.","page":156},"spell.detect-thoughts":{"name":"Individuazione dei pensieri","description":"L'incantatore attiva uno dei seguenti effetti. Fino al termine dell'incantesimo, può attivare entrambi gli effetti come azione di Magia nei suoi turni successivi.\\n\\n**Pensieri sensoriali.** L'incantatore percepisce la presenza di pensieri entro 9 metri da sé appartenenti a creature che conoscono delle lingue o che comunicano telepaticamente. L'incantatore non legge nel pensiero, ma avverte la presenza di una creatura pensante.\\n\\nL'incantesimo viene bloccato da 30 cm di pietra, terriccio o legno, 2,5 centimetri di metallo o una sottile lamina di piombo.\\n\\n**Lettura del pensiero.** L'incantatore bersaglia una creatura entro 9 metri da sé che egli è in grado di vedere o che ha individuato con l'opzione Pensieri sensoriali e apprende i pensieri superficiali del bersaglio, ciò che sta pensando in quel momento. Se il bersaglio non conosce alcuna lingua e non comunica telepaticamente, l'incantatore non apprende nulla.\\n\\nCome azione di Magia nel suo turno successivo, l'incantatore può provare a scavare più in profondità nella mente della creatura. Nell'ultimo caso, il bersaglio effettua un tiro salvezza su Saggezza. In caso di fallimento, l'incantatore ha accesso ai suoi ragionamenti, al suo stato emotivo e a ciò che principalmente riempie la sua mente (qualcosa di cui si preoccupa, che ama o odia). In caso di successo, l'incantesimo termina. In ogni caso, il bersaglio è consapevole che l'incantatore ha accesso alla sua mente e, se quest'ultimo non distoglie la sua attenzione dalla mente del bersaglio, il bersaglio può usare un'azione nel proprio turno per effettuare una prova di Intelligenza (Arcano) contro la CD del tiro salvezza sull'incantesimo; in caso di successo, l'incantesimo termina.","material":"1 pezzo di rame","page":156},"spell.rope-trick":{"name":"Trucco della corda","description":"L'incantatore tocca una corda: un'estremità fluttua verso l'alto finché la corda non pende perpendicolarmente al terreno oppure raggiunge il soffitto. All'estremità superiore della corda, si apre un portale invisibile (che misura 90 centimetri per 1,5 metri) verso uno spazio extradimensionale che permane fino al termine dell'incantesimo. È possibile raggiungere questo spazio arrampicandosi in cima alla corda, la quale può essere ritratta al suo interno o lasciata cadere fuori di esso.\\n\\nLo spazio può contenere un massimo di otto creature di taglia Media o inferiore. Attacchi, incantesimi e altri effetti non possono attraversare in entrata o in uscita lo spazio, ma le creature al suo interno possono vedere attraverso il portale. Tutto ciò che si trova all'interno dello spazio cade all'esterno al termine dell'incantesimo.","material":"un pezzo di corda","page":199},"spell.banishment":{"name":"Esilio","description":"Una creatura entro gittata che l'incantatore è in grado di vedere deve superare un tiro salvezza su Carisma o essere trasportata in un semipiano sicuro per la durata dell'incantesimo. Mentre si trova lì, il bersaglio è incapacitato. Al termine dell'incantesimo, il bersaglio riappare nello spazio in cui si trovava prima del lancio o, se è occupato, nello spazio libero più vicino.\\n\\nSe l'incantesimo sul bersaglio dura 1 minuto, il bersaglio non fa ritorno se è un'aberrazione, un celestiale, un elementale, un folletto o un immondo. In questo caso, viene trasportato in un luogo casuale di un piano (a scelta del GM) associato al tipo di creatura di cui fa parte.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º.","material":"un pentacolo","page":144},"spell.resilient-sphere":{"name":"Sfera elastica","description":"Una sfera di forza scintillante racchiude una creatura o un oggetto di taglia Grande o inferiore entro gittata. Una creatura non consenziente deve superare un tiro salvezza su Destrezza, altrimenti viene rinchiusa nella sfera per la durata dell'incantesimo.\\n\\nNulla può attraversare la barriera in entrata e in uscita (oggetti fisici, energia o altri effetti magici), ma una creatura all'interno può respirare liberamente. La sfera è immune a tutti i danni e una creatura o un oggetto all'interno non può essere danneggiato dagli attacchi o dagli effetti che provengono dall'esterno; analogamente, non può infliggere danni a qualsiasi cosa si trovi all'esterno.\\n\\nLa sfera non ha peso ed è grande quanto basta da contenere la creatura o l'oggetto al suo interno. Una creatura rinchiusa può effettuare un'azione per spingere le pareti della sfera e farla rotolare a una velocità massima pari alla metà della propria. Analogamente, la sfera può essere sollevata e mossa da altre creature.\\n\\nUn incantesimo disintegrazione distrugge la sfera senza danneggiare ciò che contiene.","material":"una sfera di vetro","page":188},"spell.bane":{"name":"Anatema","description":"L'incantatore sceglie fino a tre creature situate entro gittata che egli è in grado di vedere, ciascuna delle quali deve effettuare un tiro salvezza su Carisma. Se un bersaglio fallisce il tiro, ogni volta che effettua un tiro per colpire o un tiro salvezza prima del termine dell'incantesimo deve sottrarre 1d4 da essi.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","material":"una goccia di sangue","page":123},"spell.bless":{"name":"Benedizione","description":"L'incantatore benedice fino a tre creature entro gittata. Se un bersaglio effettua un tiro per colpire o un tiro salvezza prima del termine dell'incantesimo, il bersaglio aggiunge a essi 1d4.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","material":"un simbolo sacro del valore di 5 mo o più","page":128},"spell.enhance-ability":{"name":"Caratteristica potenziata","description":"L'incantatore tocca una creatura e sceglie Forza, Destrezza, Intelligenza, Saggezza o Carisma. Per la durata dell'incantesimo, il bersaglio dispone di vantaggio sulle prove di caratteristica effettuate utilizzando l'abilità scelta.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 2º. L'incantatore può scegliere una caratteristica differente per ogni bersaglio.","material":"un ciuffo di peli o una piuma","page":130},"spell.spider-climb":{"name":"Movimenti del ragno","description":"Fino al termine dell'incantesimo, una creatura consenziente toccata dall'incantatore ottiene la capacità di muoversi verticalmente e orizzontalmente su pareti e soffitti, mantenendo le mani libere. Il bersaglio ottiene anche una velocità di scalata pari alla sua velocità.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 2º.","material":"una goccia di bitume e un ragno","page":166},"spell.plant-growth":{"name":"Crescita vegetale","description":"Questo incantesimo incanala vitalità nei vegetali. Il tempo di lancio utilizzato dall'incantatore determina l'effetto che ha l'incantesimo tra i due descritti di seguito: Groviglio o Fertilità.\\n\\n**Groviglio.** L'incantatore sceglie un punto entro gittata e tutti i vegetali normali entro una sfera del raggio di 30 metri centrata su quel punto crescono rigogliosamente fino a formare un groviglio. Una creatura che si muove attraverso quell'area deve usare 1,2 metri di movimento per ogni 30 centimetri di cui si muove. L'incantatore può escludere dall'influenza dell'incantesimo una o più aree di qualsiasi dimensione all'interno dell'area scelta.\\n\\n**Fertilità.** Tutti i vegetali entro un raggio di 750 metri centrato in un punto entro gittata cresceranno rigogliosamente per 365 giorni e al momento del raccolto produrranno il doppio del cibo normale. I vegetali possono beneficiare di crescita vegetale solo una volta all'anno.","page":139},"spell.enthrall":{"name":"Estasiare","description":"L'incantatore pronuncia una sequenza di parole disorientante, costringendo le creature da lui scelte entro gittata e che egli è in grado di vedere a effettuare un tiro salvezza su Saggezza. Se l'incantatore o i suoi compagni stanno combattendo contro una creatura, quella supera automaticamente questo tiro salvezza. In caso di fallimento, il bersaglio subisce una penalità di −10 alle prove di Saggezza (Percezione) e alla Percezione passiva fino al termine dell'incantesimo.","page":145},"spell.lightning-bolt":{"name":"Fulmine","areaDimensions":"Linea lunga 30 metri e larga 1,5 metri","description":"Un fulmine parte dall'incantatore in una direzione a sua scelta, formando una linea lunga 30 metri e larga 1,5 metri. Ogni creatura sulla linea effettua un tiro salvezza su Destrezza; se lo fallisce, subisce 8d6 danni da fulmine, mentre se lo supera subisce la metà dei danni.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 3º.","material":"un ciuffo di pelo e una verga di cristallo","page":150},"spell.wall-of-stone":{"name":"Muro di pietra","description":"Un muro non magico di solida pietra si materializza in un punto a scelta dell'incantatore situato entro gittata. Il muro è spesso 15 cm ed è composto da pannelli con lato di 3 metri, Ogni pannello dev'essere contiguo a un altro pannello. In alternativa, l'incantatore può creare pannelli di 3 metri per 6 metri spessi solo 8 centimetri.\\n\\nSe, nel momento in cui appare, il muro passa attraverso lo spazio di una creatura, questa viene spinta verso un lato del muro a scelta dell'incantatore. Se una creatura rischia di trovarsi circondata su tutti i lati dal muro (o dal muro e un'altra superficie solida) può effettuare un tiro salvezza su Destrezza. In caso di successo, può usare la sua reazione per muoversi fino alla sua velocità massima nel tentativo di non rimanere intrappolata dal muro.\\n\\nIl muro può avere la forma desiderata dall'incantatore, ma non può occupare lo stesso spazio di una creatura o un oggetto. Non è necessario che sia verticale o poggi su fondamenta solide, deve tuttavia fondersi ed essere saldamente appoggiato a un blocco di pietra già esistente. È quindi possibile usare questo incantesimo per creare una rampa o realizzare un ponte che attraversi un baratro.\\n\\nSe l'incantatore crea una campata di lunghezza superiore a 6 metri, deve dimezzare le dimensioni di ogni pannello per creare dei sostegni. Può modellare rozzamente il muro per creare parapetti e altri elementi simili.\\n\\nIl muro è un oggetto in pietra che può essere danneggiato e quindi sfondato. Ogni pannello ha CA 15 e 30 punti ferita per ogni 2,5 centimetri di spessore ed è immune ai danni da veleno e psichici. Quando un pannello scende a 0 punti ferita, viene distrutto e potrebbe causare il crollo dei pannelli collegati, a discrezione del GM.\\n\\nSe l'incantatore mantiene la concentrazione su questo incantesimo per l'intera durata, il muro diventa permanente e non può essere rimosso. In caso contrario, il muro scompare al termine dell'incantesimo.","material":"un cubo di granito","page":167},"spell.fireball":{"name":"Palla di fuoco","areaDimensions":"Sfera dal raggio di 6 metri","description":"Una scia di luce brillante parte dall'incantatore e sfreccia fino a un punto a sua scelta entro gittata, provocando un'esplosione infuocata con un profondo boato. Ogni creatura presente in una sfera dal raggio di 6 metri e centrata su quel punto deve effettuare un tiro salvezza su Destrezza, subendo 8d6 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.\\n\\nGli oggetti infiammabili nell'area che non sono indossati o trasportati iniziano a bruciare.","higherLevels":"I danni aumentano di 1d6 per ogni slot di livello superiore al 3º.","material":"una pallina di guano di pipistrello e zolfo","page":171},"spell.hideous-laughter":{"name":"Risata incontenibile","description":"Una creatura a scelta entro gittata che l'incantatore è in grado di vedere effettua un tiro salvezza su Saggezza. Se lo fallisce, cade a terra prona ed è incapacitata per la durata dell'incantesimo. Durante quel periodo di tempo, ride incontrollabilmente (se è in grado di ridere) e non può porre fine alla condizione prono.\\n\\nIl bersaglio effettua un altro tiro salvezza su Saggezza alla fine di ogni suo turno e ogni volta che subisce danni; in quest'ultimo caso, lo effettua con vantaggio. In caso di successo, l'incantesimo termina.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.","material":"una crostata e una piuma","page":181},"spell.shocking-grasp":{"name":"Stretta folgorante","description":"Un fulmine si sprigiona dall'incantatore verso una creatura da lui toccata. Con questo incantesimo, l'incantatore effettua un attacco in mischia contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d8 danni da fulmine e non può effettuare attacchi di opportunità fino all'inizio del proprio turno successivo.","higherLevels":"I danni aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).","page":192},"spell.fly":{"name":"Volare","description":"L'incantatore tocca una creatura consenziente. Per la durata dell'incantesimo, il bersaglio ottiene una velocità di volo di 18 metri e può fluttuare. Al termine dell'incantesimo, il bersaglio ancora sospeso in aria cade, sempre che non abbia modo di impedire la caduta.","higherLevels":"L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 3º.","material":"una piuma","page":201},"spell.ray-of-frost":{"name":"Raggio di gelo","description":"Un raggio gelido di luce bianco-azzurra sfreccia verso una creatura entro gittata, contro cui l'incantatore effettua un attacco a distanza con incantesimo. Se il colpo va a segno, il bersaglio subisce 1d8 danni da freddo e la sua velocità è ridotta di 3 metri fino all'inizio del turno successivo dell'incantatore.","higherLevels":"I danni aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).","page":177}}`),a={kind:e,language:`it`,source:n,translates:r,entries:i};export{a as default,i as entries,e as kind,t as language,n as source,r as translates};